export default {"packs":[{"id":"sharks","icon":"🦈","name":{"en":"Sharks","es":"Tiburones"},"words":{"en":[{"w":"FIN","clue":"Sticks up out of the water on a shark's back","fact":"A shark's dorsal fin helps keep it upright so it does not roll over.","tier":1},{"w":"PUP","clue":"A baby shark is called this","fact":"Many shark pups are born able to swim and find food right away.","tier":1},{"w":"TEETH","clue":"A shark has rows and rows of these in its mouth","fact":"Many sharks grow new ones all their lives, using up thousands.","tier":1},{"w":"GILLS","clue":"Slits on a shark's sides that pull oxygen from water","fact":"Most sharks have five to seven pairs of gill slits.","tier":1},{"w":"SKIN","clue":"Covered in tiny scales, it feels like sandpaper one way","fact":"Shark skin feels smooth rubbed one way and rough rubbed the other.","tier":1},{"w":"MAKO","clue":"Speedy shark that can leap right out of the sea","fact":"Mako sharks are among the fastest sharks in the ocean.","tier":1},{"w":"TIGER","clue":"Shark named after a big striped cat","fact":"Young tiger sharks have dark stripes that fade as they grow up.","tier":1},{"w":"NURSE","clue":"Calm sea-floor shark named for a hospital helper","fact":"Nurse sharks can lie still and pump water over their gills to breathe.","tier":1},{"w":"SHARK","clue":"A fish whose skeleton is bendy, not bony","fact":"There are more than 500 kinds of sharks, from tiny ones to giants as long as a bus.","tier":1},{"w":"WHALE","clue":"The biggest kind of shark is named after this giant sea mammal","fact":"Whale sharks are gentle giants that eat mostly tiny plankton.","tier":1},{"w":"BULL","clue":"Shark named for a strong horned animal; it swims up rivers","fact":"Bull sharks can live in both salty ocean water and fresh river water.","tier":1},{"w":"TAIL","clue":"Swishes side to side to push a shark forward","fact":"Most sharks have a tail whose top part is longer than the bottom part.","tier":1},{"w":"SCALES","clue":"Hard little plates that cover a fish's body","fact":"Shark scales are shaped like tiny teeth and help water flow smoothly past.","tier":2},{"w":"BASKING","clue":"Lounging in warm sunshine; also a gentle giant shark's name","fact":"Basking sharks swim with their mouths open and filter tiny animals from the water.","tier":2},{"w":"GOBLIN","clue":"Pink deep-sea shark with a long flat snout and slingshot jaws","fact":"A goblin shark can fling its jaws forward to snatch food.","tier":2},{"w":"SPINNER","clue":"This shark leaps from the sea and twirls in the air","fact":"Spinner sharks whirl around as they leap before splashing back down.","tier":2},{"w":"DOGFISH","clue":"Small shark named after a barking pet","fact":"Spiny dogfish have a sharp spine in front of each back fin.","tier":2},{"w":"LANTERN","clue":"Tiny deep-sea shark named for a light you can carry","fact":"Some lantern sharks glow in the dark using light made by their own skin.","tier":2},{"w":"MIGRATE","clue":"To travel far each year, the way birds fly south","fact":"Some sharks swim thousands of miles in a single trip across the ocean.","tier":2},{"w":"REMORA","clue":"Sucker-headed fish that hitches rides on sharks","fact":"A remora holds on with a sucker on its head and eats scraps.","tier":2},{"w":"NOSTRIL","clue":"A shark has two of these on its snout, only for smelling","fact":"A shark's nostrils are only for smelling; it breathes through its gills.","tier":2},{"w":"MAMMAL","clue":"Warm-blooded air-breather: a dolphin is one, a shark is not","fact":"Sharks are fish with gills, but dolphins and whales are mammals that breathe air.","tier":2},{"w":"SCHOOL","clue":"A big group of fish swimming together","fact":"Hammerhead sharks sometimes gather in groups of hundreds.","tier":2},{"w":"FOSSIL","clue":"Hardened remains of ancient life found in rock","fact":"Shark teeth are one of the most common fossils because sharks lose so many.","tier":2},{"w":"ANCIENT","clue":"Very, very old, from long before dinosaurs","fact":"Sharks swam in the oceans before dinosaurs, and even before trees grew on land.","tier":2},{"w":"BARBELS","clue":"Whisker-like feelers near a nurse shark's mouth","fact":"Nurse sharks use these feelers to find food on the sandy bottom.","tier":2},{"w":"HAMMERHEAD","clue":"Shark whose head is shaped like a tool for pounding nails","fact":"A hammerhead's wide head has an eye at each end, giving it a super wide view.","tier":3},{"w":"MEGALODON","clue":"A giant shark from long ago, known from huge fossil teeth","fact":"Megalodon teeth were as big as a grown-up's hand.","tier":3},{"w":"THRESHER","clue":"Shark with a super long, whip-like tail","fact":"A thresher shark's tail is almost as long as the rest of its body.","tier":3},{"w":"PLANKTON","clue":"Tiny drifting plants and animals that the biggest sharks eat","fact":"Plankton drifts with the water, and some of the biggest sharks and whales eat it.","tier":3},{"w":"WOBBEGONG","clue":"Fringed, carpet-like shark from Australia that hides on the sea floor","fact":"Wobbegongs lie still and blend in with rocks and coral while waiting for fish.","tier":3},{"w":"PECTORAL","clue":"Wing-like side fins that help a shark steer and rise","fact":"A shark's side fins work a bit like airplane wings to lift it as it swims.","tier":3},{"w":"STREAMLINED","clue":"Smooth, slim shape that slips through water easily","fact":"A shark's body is pointed at both ends so it can glide through water.","tier":3},{"w":"ELECTRIC","clue":"Faint signals, like a battery makes, that sharks sense from hidden fish","fact":"Jelly-filled pores on a shark's snout can feel signals from hidden fish.","tier":3},{"w":"CARTILAGE","clue":"Bendy stuff in your ears and nose; it makes a shark's skeleton","fact":"Your ears and nose have it too, which is why they bend.","tier":3},{"w":"PREDATOR","clue":"An animal that hunts other animals for food","fact":"Sharks help keep the ocean healthy by eating weak and sick animals.","tier":3},{"w":"JAW","clue":"The movable frame that holds a shark's teeth","fact":"A shark's jaw is loosely attached to its skull, so it can swing forward when biting.","tier":1},{"w":"EYE","clue":"Body part you see with; you have two of them","fact":"Hammerhead sharks have their eyes at the far ends of their wide heads.","tier":1},{"w":"FISH","clue":"Animal with fins and gills that spends its whole life in water","fact":"There are more than 500 kinds of sharks, and every one is a fish.","tier":1},{"w":"REEF","clue":"Colorful ridge of coral just under the surface of the sea","fact":"Blacktip reef sharks often swim in water so shallow that their fins poke out.","tier":1},{"w":"SEAL","clue":"Whiskered ocean swimmer that barks and rests on rocks","fact":"Great whites can launch their whole bodies out of the water, and seals are a favorite meal.","tier":1},{"w":"TUNA","clue":"Speedy ocean fish often packed in cans for sandwiches","fact":"Mako sharks and tuna both keep their muscles warmer than the water around them.","tier":1},{"w":"SQUID","clue":"Ocean animal with ten limbs that sprays ink to escape","fact":"Squid can change color in a flash, but many sharks still hunt them.","tier":1},{"w":"KELP","clue":"Giant brown seaweed that grows in underwater forests","fact":"Leopard sharks and horn sharks hide and hunt in California's kelp forests.","tier":1},{"w":"CAGE","clue":"Strong metal bars that protect divers watching big sharks","fact":"Divers inside one can look right at a great white from a safe spot.","tier":1},{"w":"DIVE","clue":"What scuba swimmers do to go down deep underwater","fact":"Great white sharks can dive well over 1,000 feet down.","tier":1},{"w":"SWIM","clue":"Move through water by kicking or sweeping fins","fact":"Some sharks must keep swimming all the time so water flows over their gills.","tier":1},{"w":"DEEP","clue":"Far down below the surface; the opposite of shallow","fact":"Some sharks live in water more than a mile down, where it is dark and cold.","tier":1},{"w":"SALT","clue":"White crystals that make the sea taste yucky","fact":"Bull sharks can live in salty sea water and in fresh river water.","tier":1},{"w":"PREY","clue":"An animal that gets hunted and eaten by another","fact":"Hammerhead sharks use their wide heads to pin down stingrays hiding in sand.","tier":1},{"w":"LEMON","clue":"Sour yellow citrus fruit used in a sweet summer drink","fact":"A shark named for this fruit has yellow-brown skin that blends in with sandy sea floors.","tier":1},{"w":"BLUE","clue":"Color of a clear sky; a slim shark is named for it","fact":"Blue sharks sometimes swim all the way across the Atlantic Ocean.","tier":1},{"w":"SAND","clue":"Tiny grains of rock that cover a beach","fact":"Sand tiger sharks gulp air at the surface so they can float in place.","tier":1},{"w":"TAG","clue":"Scientists clip this onto a shark's fin to follow its travels","fact":"Tagged sharks have been tracked swimming thousands of miles across the ocean.","tier":1},{"w":"ZEBRA","clue":"Black-and-white striped animal of the African grasslands, like a horse","fact":"Zebra sharks have stripes as babies but grow spots as they get older.","tier":1},{"w":"GLOW","clue":"Shine softly in the dark, like a night-light","fact":"Some tiny deep-sea sharks make their own light and glow in the dark.","tier":1},{"w":"SONAR","clue":"Gadget that uses sound echoes to find things underwater","fact":"Sonar works like bat echoes: it sends out sound and listens for what bounces back.","tier":1},{"w":"RAY","clue":"Flat ocean fish that flaps its fins like wings; shark's cousin","fact":"Rays and sharks are cousins, and both have skeletons made of cartilage.","tier":1},{"w":"SNOUT","clue":"Pointy nose of a pig, a dog, or a shark","fact":"A sawshark's long snout has two whisker-like feelers that help it find food in sand.","tier":1},{"w":"LIVER","clue":"Big oily organ inside a shark that helps it float","fact":"Oil is lighter than water, so an oily liver helps keep a shark from sinking.","tier":1},{"w":"BAT","clue":"Wooden stick swung in baseball to hit the ball","fact":"A thresher shark swings its long tail like one to stun small fish.","tier":1},{"w":"DRONE","clue":"Small flying robot with spinning propellers, steered from the ground","fact":"Beach lifeguards and scientists use them to spot sharks from the sky.","tier":1},{"w":"SPEED","clue":"How fast something moves, such as miles per hour","fact":"A shortfin mako can swim faster than 30 miles an hour.","tier":1},{"w":"TIDE","clue":"Daily rise and fall of seawater at the beach","fact":"The Moon's pull makes the ocean rise and fall along the shore.","tier":1},{"w":"LEOPARD","clue":"Spotted big cat of Africa; one small shark wears its pattern","fact":"Leopard sharks swim in big groups in shallow bays, and they are not dangerous to people.","tier":2},{"w":"FRILLED","clue":"Collar-like gill edges give this eel-shaped deep-sea shark its name","fact":"A frilled shark has about 300 tiny three-pointed teeth, and it looks like an eel.","tier":2},{"w":"SANDBAR","clue":"Underwater ridge of loose grains piled up near the shore","fact":"Sandbar sharks have a very tall first fin, and their babies grow up in shallow bays.","tier":2},{"w":"STOMACH","clue":"Bag inside your belly where swallowed food goes","fact":"Some sharks can flip their stomach inside out to clean it.","tier":2},{"w":"SPIRAL","clue":"Shape of a curly staircase or a snail's shell","fact":"Inside a shark's short intestine is a corkscrew twist that gives food more surface to soak into.","tier":2},{"w":"HEARING","clue":"The sense you use your ears for","fact":"Sharks can hear low sounds, like a flapping fish, from very far away.","tier":2},{"w":"CAMERA","clue":"Gadget that snaps photos or video","fact":"Scientists clip tiny ones to sharks to see what a day in their life looks like.","tier":2},{"w":"SPECIES","clue":"One kind of living thing, such as a type of bird","fact":"There are more than 500 species of sharks, and the smallest is shorter than a ruler.","tier":2},{"w":"SALMON","clue":"Pink fish that swims upstream to lay its eggs","fact":"Salmon sharks live in cold northern seas but keep their bodies warmer than the water.","tier":2},{"w":"OCTOPUS","clue":"Sea animal with eight arms that squirts a cloud of ink","fact":"An octopus has three hearts and blue blood.","tier":2},{"w":"LOBSTER","clue":"Hard-shelled sea animal with two big claws, often boiled for dinner","fact":"Nurse sharks can crunch hard-shelled food like lobsters and crabs.","tier":2},{"w":"TURTLE","clue":"Shelled reptile that can swim in the sea","fact":"Tiger sharks have strong jaws that can crack open a sea turtle's shell.","tier":2},{"w":"DOLPHIN","clue":"Playful, smart sea mammal that clicks and whistles","fact":"Dolphins breathe air at the surface, but sharks breathe underwater with gills.","tier":2},{"w":"LAGOON","clue":"Calm, shallow water almost walled in by land or a reef","fact":"Many young reef sharks grow up in the calm, shallow water of lagoons.","tier":2},{"w":"ESTUARY","clue":"Where a river meets the sea and fresh and salt water mix","fact":"Bull sharks can swim into estuaries and even far up rivers.","tier":2},{"w":"NURSERY","clue":"Safe shallow spot where young sharks grow; also a room for babies","fact":"Young sharks stay in calm shallow places where big hungry animals rarely go.","tier":2},{"w":"SNORKEL","clue":"Breathing tube for swimming with your face in the water","fact":"Snorkelers can swim beside whale sharks, which are the biggest fish in the sea.","tier":2},{"w":"SHALLOW","clue":"Not deep; water that barely covers your knees","fact":"Many baby sharks grow up in this kind of water, away from big predators.","tier":2},{"w":"PATTERN","clue":"Repeating design, such as spots or stripes","fact":"Every whale shark has its own spot pattern, like a fingerprint.","tier":2},{"w":"OXYGEN","clue":"Gas in air and water that animals need to breathe","fact":"Water holds far less of it than air does, so gills have to work hard.","tier":2},{"w":"STRIKE","clue":"In baseball, three of these and the batter is out","fact":"A thresher shark's tail can be as long as the rest of its body.","tier":2},{"w":"GENTLE","clue":"Soft and kind, not rough","fact":"Whale sharks and basking sharks are gentle giants that eat tiny food.","tier":2},{"w":"SWIMMER","clue":"Athlete who races in a pool","fact":"Some racing swimsuits were designed to copy the tiny ridges on shark skin.","tier":2},{"w":"BALANCE","clue":"Staying steady without falling over","fact":"Sharks have tiny ear openings behind their eyes that help them hear and keep their balance.","tier":2},{"w":"CARPET","clue":"Soft covering for a living room floor","fact":"Carpet sharks like wobbegongs lie flat on the sea floor and look like rocks.","tier":2},{"w":"MIRROR","clue":"Shiny glass that shows your reflection","fact":"A shark's eye has a mirror-like layer that helps it see in dim water.","tier":2},{"w":"MEMORY","clue":"Your brain's ability to keep things from the past","fact":"Sharks in tests have learned tasks and still remembered them weeks later.","tier":2},{"w":"ARCTIC","clue":"Freezing ocean and ice region around the North Pole","fact":"Greenland sharks swim in near-freezing water and grow very slowly.","tier":2},{"w":"WEIGHT","clue":"How heavy something is, measured on a scale","fact":"A whale shark weighs more than a full-grown elephant.","tier":2},{"w":"NEEDLE","clue":"Thin metal pin used for sewing, with a hole at one end","fact":"A mako's teeth are long and thin like needles, perfect for catching slippery fish.","tier":2},{"w":"SPONGE","clue":"Soft, holey thing for scrubbing, once a sea animal","fact":"A sponge is an animal, even though it never moves from its spot.","tier":2},{"w":"PENGUIN","clue":"Black-and-white bird that cannot fly but swims fast","fact":"Penguins use their wings as flippers to zoom through the water.","tier":2},{"w":"GREENLAND","clue":"Huge icy island near Canada, name of a shark that lives centuries","fact":"Greenland sharks swim slowly in freezing water and may live for hundreds of years.","tier":3},{"w":"BLACKTIP","clue":"Shark whose fin tips look dipped in dark ink","fact":"Blacktip sharks can leap out of the water and spin while hunting fish.","tier":3},{"w":"WHITETIP","clue":"Open-ocean shark with bright pale tips on its fins","fact":"Oceanic whitetip sharks cruise far from land, with long, rounded fins.","tier":3},{"w":"SAWSHARK","clue":"Shark with a toothed snout like a carpenter's tool","fact":"Sawsharks look like sawfish, but they are true sharks and are much smaller.","tier":3},{"w":"DENTICLE","clue":"Tiny tooth-shaped scale; thousands cover a shark's skin","fact":"Denticles point backward, which helps water flow smoothly past a swimming shark.","tier":3},{"w":"SUBMARINE","clue":"Boat that travels deep under the water","fact":"Scientists use small research subs to film deep-sea sharks in the dark.","tier":3},{"w":"SATELLITE","clue":"Machine that circles Earth high above in space","fact":"Some shark tags send signals to one whenever the shark's fin breaks the surface.","tier":3},{"w":"STINGRAY","clue":"Flat sea fish with a whip-like tail that hides in sand","fact":"Stingrays have their eyes on top of their bodies and their mouths underneath.","tier":3},{"w":"MANGROVE","clue":"Tree whose tangled roots grow in salty shallow water","fact":"Baby lemon sharks hide among the roots of these trees to stay safe.","tier":3},{"w":"BONNETHEAD","clue":"Small hammerhead cousin with a rounded, shovel-shaped head","fact":"Unlike most sharks, bonnetheads eat lots of seagrass and can digest part of it.","tier":3},{"w":"SEAGRASS","clue":"Underwater plant that grows in green meadows on the sandy sea floor","fact":"It is a flowering plant that lives underwater, and sea turtles love to eat it.","tier":3},{"w":"AQUARIUM","clue":"Building with big tanks where you can watch fish and sea animals","fact":"Some have glass tunnels where visitors walk right under swimming sharks.","tier":3},{"w":"CAMOUFLAGE","clue":"Colors and patterns that help an animal blend in","fact":"A wobbegong's fringed skin flaps make it nearly invisible on the sea floor.","tier":3},{"w":"DARKNESS","clue":"What you see in a room with all the lights off","fact":"Below about 3,000 feet, sunlight never reaches the ocean, so deep-sea sharks live in the dark.","tier":3},{"w":"PRESSURE","clue":"Squeezing force of deep water on everything in it","fact":"Deep-sea pressure can shrink a foam cup to a tiny size, yet sharks live there.","tier":3},{"w":"SERRATED","clue":"Edged with tiny sharp points, like a steak knife","fact":"Tiger shark and great white teeth are like this, which helps them slice tough food.","tier":3},{"w":"TRIANGLE","clue":"Shape with three straight sides and three corners","fact":"A great white's teeth are shaped like tall triangles with sawlike edges.","tier":3},{"w":"SKELETON","clue":"All the bones in a body, standing together","fact":"Because shark skeletons are made of soft cartilage, mostly their teeth survive as fossils.","tier":3},{"w":"SCIENTIST","clue":"Person who studies nature by asking questions and running experiments","fact":"Scientists can tell the age of some sharks by counting rings in their backbones, like tree rings.","tier":3},{"w":"TROPICAL","clue":"Hot, wet climate near the equator","fact":"Many kinds of sharks prefer warm tropical seas, where lots of fish live.","tier":3},{"w":"JELLYFISH","clue":"Floaty sea animal with stinging tentacles and no brain","fact":"Jellyfish have been drifting in the sea for longer than sharks have.","tier":3},{"w":"SMALLEST","clue":"Least big of all; the opposite of largest","fact":"The dwarf lanternshark is one of the smallest sharks, shorter than a ruler, and it glows.","tier":3},{"w":"SHIPWRECK","clue":"Sunken boat resting on the sea floor","fact":"Sunken ships often become artificial reefs where fish gather, and sharks follow.","tier":3},{"w":"ENDANGERED","clue":"At risk of disappearing forever from the wild","fact":"Many shark kinds are in trouble because they grow slowly and have few pups.","tier":3}],"es":[{"w":"MAR","clue":"Gran extensión de agua salada donde viven los tiburones","fact":"Los tiburones ya nadaban en los mares antes de que existieran los dinosaurios.","tier":1},{"w":"PEZ","clue":"Animal que respira por branquias y nada con aletas","fact":"Todos los tiburones son peces, aunque su esqueleto no es de hueso sino de cartílago.","tier":1},{"w":"ALETA","clue":"Parte del tiburón que sobresale del agua en su lomo","fact":"La aleta dorsal ayuda al tiburón a mantenerse derecho mientras nada.","tier":1},{"w":"CRÍA","clue":"Bebé de un animal; un tiburón recién nacido es una","fact":"Muchas crías de tiburón nacen sabiendo nadar y buscar comida.","tier":1},{"w":"COLA","clue":"Se mueve de lado a lado para empujar al tiburón","fact":"En la mayoría de los tiburones, la parte de arriba de la cola es más larga.","tier":1},{"w":"PIEL","clue":"Cubierta de escamitas, se siente áspera como una lija","fact":"La piel del tiburón es suave de la cabeza a la cola y áspera al revés.","tier":1},{"w":"BOCA","clue":"Donde el tiburón tiene filas y filas de dientes","fact":"Los tiburones tienen varias filas de dientes y los de atrás avanzan cuando se cae uno.","tier":1},{"w":"TORO","clue":"Tiburón con nombre de animal fuerte con cuernos; nada en ríos","fact":"El tiburón toro puede vivir tanto en agua salada como en agua dulce.","tier":1},{"w":"TIGRE","clue":"Tiburón con nombre de felino de rayas","fact":"Los tiburones tigre jóvenes tienen rayas oscuras que se borran al crecer.","tier":1},{"w":"ZORRO","clue":"Tiburón de cola larguísima, con nombre de animal astuto","fact":"La cola del tiburón zorro mide casi tanto como el resto de su cuerpo.","tier":1},{"w":"LIMÓN","clue":"Tiburón con nombre de fruta amarilla y ácida","fact":"Los tiburones limón crían a sus pequeños en aguas poco profundas entre manglares.","tier":1},{"w":"RAYA","clue":"Pariente plana del tiburón que parece volar bajo el agua","fact":"Las rayas y los tiburones son parientes: ninguno tiene huesos duros.","tier":1},{"w":"TIBURÓN","clue":"Pez de mar con filas de dientes y aleta en el lomo","fact":"Hay más de 500 clases de tiburones, desde diminutos hasta enormes.","tier":2},{"w":"BALLENA","clue":"El tiburón más grande lleva el nombre de este gigante del mar","fact":"El tiburón ballena es un pez gigante y manso que come plancton diminuto.","tier":2},{"w":"BLANCO","clue":"Color de la nieve y del tiburón más famoso","fact":"El tiburón blanco tiene la panza clara y el lomo oscuro para confundirse en el agua.","tier":2},{"w":"NODRIZA","clue":"Tiburón tranquilo del fondo del mar, con nombre de cuidadora de bebés","fact":"El tiburón nodriza puede respirar quieto en el fondo bombeando agua por sus agallas.","tier":2},{"w":"DIENTES","clue":"Los tiburones tienen filas de ellos y les salen nuevos","fact":"Un tiburón puede usar miles de dientes a lo largo de su vida.","tier":2},{"w":"AGALLAS","clue":"Ranuras a los lados por donde el tiburón respira","fact":"La mayoría de los tiburones tiene de cinco a siete pares de ranuras de este tipo.","tier":2},{"w":"ESCAMAS","clue":"Pequeñas placas duras que cubren el cuerpo de un pez","fact":"Las escamas del tiburón tienen forma de dientecitos y ayudan a nadar más suave.","tier":2},{"w":"HOCICO","clue":"La parte puntiaguda de adelante de la cara","fact":"Algunos tiburones, como el tiburón duende, tienen un hocico larguísimo y aplanado.","tier":2},{"w":"ANTIGUO","clue":"Muy, muy viejo, de hace muchísimo tiempo","fact":"Los tiburones son tan antiguos que ya existían antes que los árboles.","tier":2},{"w":"MARRAJO","clue":"Tiburón velocísimo que puede saltar fuera del agua","fact":"El marrajo es uno de los tiburones más veloces del océano.","tier":2},{"w":"RÉMORA","clue":"Pez que viaja pegado al tiburón con una ventosa en la cabeza","fact":"La rémora se pega con una ventosa y come los restos de comida del tiburón.","tier":2},{"w":"OLFATO","clue":"Sentido para detectar olores; el del tiburón es muy bueno","fact":"Las fosas nasales del tiburón sirven solo para oler, no para respirar.","tier":2},{"w":"MIGRAR","clue":"Viajar muy lejos cada año, como hacen algunas aves","fact":"Algunos tiburones nadan miles de kilómetros en un solo viaje.","tier":2},{"w":"FÓSILES","clue":"Restos de seres antiguos que quedaron convertidos en piedra","fact":"Los dientes de tiburón son fósiles muy comunes porque son duros y se pierden muchos.","tier":2},{"w":"MARTILLO","clue":"Tiburón de cabeza ancha como una herramienta para clavar clavos","fact":"El tiburón martillo tiene un ojo en cada punta de su cabeza ancha.","tier":3},{"w":"TINTORERA","clue":"Tiburón azul y esbelto que recorre todos los océanos","fact":"Las tintoreras pueden cruzar el océano Atlántico entero en sus viajes.","tier":3},{"w":"PEREGRINO","clue":"Tiburón enorme y manso que nada con la boca bien abierta","fact":"El tiburón peregrino es enorme pero come animalitos diminutos que filtra del agua.","tier":3},{"w":"CARTÍLAGO","clue":"Material flexible de tus orejas que forma el esqueleto del tiburón","fact":"Tus orejas y tu nariz también tienen cartílago, por eso se doblan.","tier":3},{"w":"MEGALODÓN","clue":"Tiburón gigante de hace mucho, conocido por sus dientes fósiles","fact":"Un diente de megalodón era tan grande como la mano de un adulto.","tier":3},{"w":"PLANCTON","clue":"Seres diminutos que flotan en el agua; comen los gigantes del mar","fact":"El plancton es tan pequeño que muchos tipos solo se ven con microscopio.","tier":3},{"w":"ANGELOTE","clue":"Tiburón aplanado que se esconde enterrado en la arena","fact":"El angelote se queda quieto bajo la arena hasta que pasa un pez.","tier":3},{"w":"ELÉCTRICO","clue":"Señales débiles, como las de una pila, que los tiburones detectan","fact":"Los tiburones pueden sentir la electricidad de un pez escondido en la arena.","tier":3},{"w":"CARDUMEN","clue":"Gran grupo de peces que nadan juntos","fact":"Los peces de un cardumen nadan juntos para protegerse mejor.","tier":3},{"w":"DEPREDADOR","clue":"Animal que caza a otros para comer","fact":"Los tiburones ayudan a mantener sano el océano al comer animales débiles o enfermos.","tier":3},{"w":"OJO","clue":"Con esto ves; tienes dos en la cara","fact":"Los tiburones martillo tienen los ojos en los extremos de su cabeza ancha.","tier":1},{"w":"FOCA","clue":"Animal de bigotes que ladra y descansa sobre las rocas","fact":"Los tiburones blancos pueden saltar enteros fuera del agua, y las focas son una de sus comidas favoritas.","tier":1},{"w":"ATÚN","clue":"Pez veloz del mar que se vende en latas","fact":"El tiburón mako y el atún mantienen sus músculos más calientes que el agua que los rodea.","tier":1},{"w":"ALGA","clue":"Planta del mar sin raíces ni flores, verde, café o roja","fact":"Los bosques de algas gigantes son refugio de muchos peces y pequeños tiburones.","tier":1},{"w":"JAULA","clue":"Barras de metal que protegen a los buzos que miran tiburones","fact":"Desde una jaula de metal, los buzos pueden mirar de cerca a un tiburón blanco.","tier":1},{"w":"NADAR","clue":"Moverse en el agua con brazos y piernas o con aletas","fact":"Algunos tiburones deben nadar siempre para que el agua les pase por las agallas.","tier":1},{"w":"SAL","clue":"Cristales blancos que le dan al mar su sabor","fact":"El tiburón toro puede vivir en agua salada y también en ríos de agua dulce.","tier":1},{"w":"PRESA","clue":"Animal al que otro animal caza para comer","fact":"Los tiburones martillo usan su cabeza ancha para sujetar mantarrayas escondidas en la arena.","tier":1},{"w":"AZUL","clue":"Color del cielo despejado; un tiburón delgado lleva ese nombre","fact":"El tiburón azul puede cruzar el océano Atlántico entero en sus viajes.","tier":1},{"w":"ARENA","clue":"Granitos de roca que cubren la playa","fact":"Los tiburones nodriza descansan sobre la arena del fondo del mar.","tier":1},{"w":"CEBRA","clue":"Animal africano de rayas negras y blancas, parecido a un caballo","fact":"Los tiburones cebra nacen con rayas, pero de adultos tienen manchas.","tier":1},{"w":"SONAR","clue":"Aparato que usa ecos de sonido para encontrar cosas bajo el agua","fact":"El sonar funciona como un murciélago: envía sonidos y escucha el eco.","tier":1},{"w":"BATE","clue":"Palo de madera con el que se golpea la pelota de béisbol","fact":"El tiburón zorro agita su larga cola como un bate para aturdir peces pequeños.","tier":1},{"w":"DRON","clue":"Pequeño robot volador con hélices, que se maneja desde lejos","fact":"Los salvavidas y los científicos usan drones para ver tiburones desde el cielo.","tier":1},{"w":"MAREA","clue":"Subida y bajada del agua del mar en la orilla","fact":"La atracción de la Luna hace que el mar suba y baje en la orilla.","tier":1},{"w":"NARIZ","clue":"Parte de la cara con la que hueles y respiras","fact":"Los tiburones tienen fosas nasales, pero solo las usan para oler, no para respirar.","tier":1},{"w":"BUZO","clue":"Persona que explora bajo el agua con un tanque de aire","fact":"Los buzos pueden nadar junto a los tiburones ballena, los peces más grandes del mundo.","tier":1},{"w":"BAHÍA","clue":"Entrada de mar en la costa, de aguas tranquilas","fact":"Muchos bebés tiburón crecen en bahías de aguas poco profundas y tranquilas.","tier":1},{"w":"PULPO","clue":"Animal marino de ocho brazos que suelta tinta","fact":"Un pulpo tiene tres corazones y sangre azul.","tier":1},{"w":"LENTO","clue":"Que se mueve poco a poco, sin prisa","fact":"El tiburón de Groenlandia nada muy despacio, pero puede vivir cientos de años.","tier":1},{"w":"GRIS","clue":"Color de las nubes antes de la lluvia","fact":"Muchos tiburones son grises arriba y blancos abajo, para esconderse mejor en el agua.","tier":1},{"w":"MANTA","clue":"Pariente plano y enorme del tiburón que nada como si volara","fact":"Una manta gigante puede medir más de cinco metros de ancho.","tier":1},{"w":"LUZ","clue":"Lo que dan el Sol y las lámparas y nos deja ver","fact":"La luz del Sol solo ilumina bien los primeros 200 metros del océano.","tier":1},{"w":"BARCO","clue":"Gran vehículo que flota y navega por el mar","fact":"Los científicos viajan en barcos de investigación para marcar y estudiar tiburones.","tier":1},{"w":"OLA","clue":"Montaña de agua que rueda hacia la playa y revienta","fact":"Los tiburones sienten el movimiento del agua con una línea de sensores a lo largo del cuerpo.","tier":1},{"w":"CUEVA","clue":"Hueco grande dentro de una montaña o bajo el mar","fact":"Algunos tiburones descansan quietos en cuevas submarinas mientras el agua les pasa por las agallas.","tier":1},{"w":"RÍO","clue":"Corriente larga de agua dulce que desemboca en el mar","fact":"Algunos tiburones toro nadan río arriba, muy lejos del mar.","tier":1},{"w":"VELOZ","clue":"Muy rápido","fact":"El tiburón mako puede nadar a más de 50 kilómetros por hora.","tier":1},{"w":"CALAMAR","clue":"Animal marino de diez extremidades que suelta tinta para escapar","fact":"Un calamar puede cambiar de color en un instante, aunque muchos tiburones igual lo cazan.","tier":2},{"w":"TORTUGA","clue":"Reptil con caparazón que puede nadar en el mar","fact":"Los tiburones tigre tienen mandíbulas tan fuertes que pueden romper el caparazón de una tortuga marina.","tier":2},{"w":"DELFÍN","clue":"Mamífero marino juguetón e inteligente que chilla y silba","fact":"Los delfines respiran aire en la superficie, pero los tiburones respiran bajo el agua con agallas.","tier":2},{"w":"LAGUNA","clue":"Agua tranquila y poco profunda, rodeada de tierra o de arrecife","fact":"Muchos tiburones jóvenes de arrecife crecen en las aguas tranquilas de las lagunas.","tier":2},{"w":"HÍGADO","clue":"Órgano grande y aceitoso que ayuda al tiburón a flotar","fact":"El aceite pesa menos que el agua, así que un hígado aceitoso evita que el tiburón se hunda.","tier":2},{"w":"OXÍGENO","clue":"Gas del aire y del agua que los animales necesitan para respirar","fact":"El agua tiene mucho menos oxígeno que el aire, así que las agallas deben trabajar duro.","tier":2},{"w":"ESPECIE","clue":"Tipo de ser vivo, como cada clase de tiburón","fact":"Hay más de 500 especies de tiburones, desde mares cálidos hasta aguas heladas.","tier":2},{"w":"SALMÓN","clue":"Pez rosado que nada río arriba para poner sus huevos","fact":"El tiburón salmón vive en mares fríos del norte, pero mantiene su cuerpo más caliente que el agua.","tier":2},{"w":"PEQUEÑO","clue":"De poco tamaño, no grande","fact":"Uno de los tiburones más pequeños, el linterna enano, mide menos que una regla.","tier":2},{"w":"GIGANTE","clue":"Enorme, mucho más grande de lo normal","fact":"El tiburón ballena es un gigante: el pez más grande del mundo, y come cosas diminutas.","tier":2},{"w":"BRILLAR","clue":"Dar luz propia o reflejarla, como una estrella","fact":"Algunos tiburones pequeños brillan en la oscuridad del mar profundo.","tier":2},{"w":"CÁMARA","clue":"Aparato que toma fotos o video","fact":"Los científicos pegan cámaras pequeñas a los tiburones para ver cómo es un día de su vida.","tier":2},{"w":"BUCEAR","clue":"Nadar bajo el agua con un tanque de aire","fact":"Los tiburones blancos pueden bucear a más de 300 metros de profundidad.","tier":2},{"w":"OCÉANO","clue":"Inmensa extensión de agua salada que cubre gran parte del planeta","fact":"Los tiburones viven en casi todos los océanos del mundo, desde aguas tibias hasta muy frías.","tier":2},{"w":"MANGLAR","clue":"Bosque de árboles que crecen con sus raíces en agua salada","fact":"Las crías de tiburón limón se esconden entre las raíces de los manglares.","tier":2},{"w":"CORAZÓN","clue":"Órgano que bombea tu sangre; late dentro de tu pecho","fact":"El corazón de un tiburón tiene forma de S y está cerca de sus agallas.","tier":2},{"w":"CEREBRO","clue":"Órgano dentro de la cabeza con el que piensas","fact":"El cerebro del tiburón dedica una parte grande a procesar los olores.","tier":2},{"w":"CARACOL","clue":"Animal blando con una concha en espiral sobre la espalda","fact":"Algunos tiburones de fondo tienen dientes planos para triturar caracoles y almejas.","tier":2},{"w":"MEDUSA","clue":"Animal marino blando y transparente con tentáculos que pican","fact":"Las medusas flotan en el mar desde antes de que existieran los tiburones.","tier":2},{"w":"ÁRTICO","clue":"Región helada alrededor del Polo Norte","fact":"El tiburón de Groenlandia vive en las aguas casi congeladas del Ártico.","tier":2},{"w":"ESPEJO","clue":"Vidrio brillante donde ves tu reflejo","fact":"Los ojos del tiburón tienen una capa como espejo que le ayuda a ver en agua oscura.","tier":2},{"w":"MEMORIA","clue":"Capacidad del cerebro para guardar lo que ya pasó","fact":"En pruebas, algunos tiburones aprendieron tareas y las recordaron semanas después.","tier":2},{"w":"PATRÓN","clue":"Diseño que se repite, como manchas o rayas","fact":"Cada tiburón ballena tiene un patrón de manchas único, como una huella digital.","tier":2},{"w":"ESPONJA","clue":"Cosa suave con agujeros para tallar; algunas son animales del mar","fact":"Una esponja de mar es un animal, aunque nunca se mueve de su lugar.","tier":2},{"w":"SARDINA","clue":"Pez pequeño y plateado que viaja en enormes grupos","fact":"Cada año, enormes bancos de sardinas viajan por la costa de Sudáfrica y atraen a tiburones y delfines.","tier":2},{"w":"HEMBRA","clue":"Animal que puede tener crías, lo contrario de macho","fact":"Las hembras de muchos tiburones son más grandes que los machos.","tier":2},{"w":"ORILLA","clue":"Borde del mar donde llegan las olas","fact":"Los tiburones punta negra de arrecife nadan en agua tan baja que sus aletas asoman.","tier":2},{"w":"COHETE","clue":"Vehículo que lanza satélites y astronautas al espacio","fact":"Los satélites que reciben señales de las marcas de tiburones viajan al espacio en cohetes.","tier":2},{"w":"PLANETA","clue":"Mundo enorme que gira alrededor de una estrella, como la Tierra","fact":"Más de dos tercios de nuestro planeta están cubiertos por el mar, hogar de los tiburones.","tier":2},{"w":"MORDER","clue":"Cortar o apretar algo con los dientes","fact":"Cuando un tiburón pierde un diente al morder, otro de atrás avanza para ocupar su lugar.","tier":2},{"w":"TAMAÑO","clue":"Qué tan grande o chico es algo","fact":"Los tiburones van desde el tamaño de una regla hasta el de un autobús grande.","tier":2},{"w":"HAMBRE","clue":"Ganas de comer","fact":"Algunos tiburones pueden pasar semanas sin comer después de una comida grande.","tier":2},{"w":"LEOPARDO","clue":"Felino manchado de África y Asia; un tiburón pequeño lleva su diseño","fact":"Los tiburones leopardo nadan en grupos en bahías poco profundas y no son peligrosos para las personas.","tier":3},{"w":"LANGOSTA","clue":"Animal marino de caparazón duro y dos pinzas grandes","fact":"Los tiburones nodriza pueden triturar presas de caparazón duro, como langostas y cangrejos.","tier":3},{"w":"ESTÓMAGO","clue":"Bolsa dentro de tu panza donde llega la comida que tragas","fact":"Algunos tiburones pueden voltear su estómago al revés para limpiarlo.","tier":3},{"w":"PINGÜINO","clue":"Ave blanca y negra que no vuela pero nada muy rápido","fact":"Los pingüinos usan sus alas como aletas para nadar a toda velocidad.","tier":3},{"w":"ESTUARIO","clue":"Donde un río llega al mar, mezclando agua dulce y salada","fact":"En los estuarios crían muchos animales marinos jóvenes, y también entran tiburones toro.","tier":3},{"w":"GUARDERÍA","clue":"Lugar seguro donde cuidan y crecen los bebés","fact":"Muchas crías de tiburón crecen en aguas tranquilas y poco profundas, lejos de los animales grandes.","tier":3},{"w":"LINTERNA","clue":"Aparato portátil con pila que da luz en la oscuridad","fact":"Las luces en la panza de los tiburones linterna quizá los esconden de quien mira desde abajo.","tier":3},{"w":"SUBMARINO","clue":"Barco que viaja bajo el agua","fact":"Los científicos usan submarinos pequeños para filmar tiburones en lo profundo del mar.","tier":3},{"w":"SATÉLITE","clue":"Máquina que gira alrededor de la Tierra, allá arriba en el espacio","fact":"Algunas marcas de tiburón mandan su ubicación a un satélite cuando la aleta sale del agua.","tier":3},{"w":"ARRECIFE","clue":"Cresta de coral cerca de la superficie del mar","fact":"Los arrecifes cubren muy poco del océano, pero en ellos vive muchísima vida marina.","tier":3},{"w":"CANGREJO","clue":"Animal marino de tenazas que camina de lado","fact":"Los cangrejos caminan de lado porque sus patas se doblan hacia los costados.","tier":3},{"w":"NAUFRAGIO","clue":"Restos de un barco hundido en el fondo del mar","fact":"Muchos barcos hundidos se convierten en arrecifes artificiales llenos de peces.","tier":3},{"w":"TROPICAL","clue":"Del clima caliente y húmedo cerca del ecuador","fact":"Muchos tiburones prefieren los mares tropicales, donde hay muchísimos peces.","tier":3},{"w":"CAMUFLAJE","clue":"Colores y dibujos que ayudan a un animal a confundirse","fact":"El tiburón alfombra tiene flecos en la cara que lo hacen parecer algas y rocas.","tier":3},{"w":"PROFUNDO","clue":"Que está muy abajo, muy hondo","fact":"Algunos tiburones viven a más de un kilómetro de profundidad, donde todo es oscuro.","tier":3},{"w":"TRIÁNGULO","clue":"Figura de tres lados rectos y tres esquinas","fact":"Los dientes del gran tiburón blanco tienen forma de triángulos con bordes de sierra.","tier":3},{"w":"CIENTÍFICO","clue":"Persona que estudia la naturaleza haciendo preguntas y experimentos","fact":"Los científicos calculan la edad de algunos tiburones contando los anillos de su columna, como en un árbol.","tier":3},{"w":"AMENAZADO","clue":"En riesgo de desaparecer para siempre","fact":"Muchos tiburones están amenazados porque crecen despacio y tienen pocas crías.","tier":3},{"w":"SUPERFICIE","clue":"La parte de arriba del agua, donde toca el aire","fact":"Algunos tiburones nadan tan cerca de la superficie que su aleta dorsal asoma del agua.","tier":3},{"w":"GUITARRA","clue":"Instrumento musical de seis cuerdas; también un pez plano parecido al tiburón","fact":"El pez guitarra es primo de los tiburones y las rayas, con esqueleto de cartílago.","tier":3},{"w":"ELEFANTE","clue":"Animal terrestre gigante con trompa y colmillos","fact":"Un tiburón ballena adulto pesa más que un elefante.","tier":3},{"w":"ASTRONAUTA","clue":"Persona que viaja al espacio en una nave","fact":"Los astronautas practican caminar en el espacio dentro de enormes piscinas de agua.","tier":3},{"w":"TORMENTA","clue":"Mal tiempo con lluvia, viento y truenos","fact":"Algunos tiburones se van a aguas más profundas antes de que llegue una tormenta fuerte.","tier":3},{"w":"PLATEADO","clue":"De color brillante, como una moneda de plata","fact":"Muchos peces del mar abierto son plateados porque sus escamas reflejan la luz del agua.","tier":3}]}},{"id":"dinosaurs","icon":"🦕","name":{"en":"Dinosaurs","es":"Dinosaurios"},"words":{"en":[{"w":"EGG","clue":"A baby dinosaur starts life inside this","fact":"Dinosaurs laid these, and birds, which are living dinosaurs, still do.","tier":1},{"w":"HORN","clue":"Pointed bony spike on a head, like Triceratops has three","fact":"Triceratops means \"three-horned face.\"","tier":1},{"w":"CLAW","clue":"Sharp curved nail on a toe or finger","fact":"Velociraptor was about the size of a turkey, with a big curved one on each foot.","tier":1},{"w":"SPIKE","clue":"Stegosaurus swung a few of these on its tail","fact":"Stegosaurus had four sharp ones on its tail for protection.","tier":1},{"w":"BEAK","clue":"Hard pointed mouth part, like a bird has","fact":"Many plant-eating dinosaurs had one for snipping leaves.","tier":1},{"w":"NEST","clue":"Dinosaurs made these to hold their eggs","fact":"Maiasaura means \"good mother lizard\" because it cared for its babies in one.","tier":1},{"w":"HERD","clue":"A big group of animals walking together","fact":"Fossil footprints show that some dinosaurs traveled in these.","tier":1},{"w":"TRACK","clue":"A footprint turned to stone is a dinosaur ___","fact":"Some dinosaur footprints in stone show how fast the animal was walking.","tier":1},{"w":"FRILL","clue":"Big bony shield at the back of Triceratops's head","fact":"Scientists think it may have helped dinosaurs recognize each other.","tier":1},{"w":"CREST","clue":"Hollow bony bump on top of Parasaurolophus's head","fact":"Parasaurolophus's hollow one may have worked like a trumpet.","tier":1},{"w":"HIPS","clue":"Scientists sort dinosaurs into two groups by the shape of these","fact":"The two big dinosaur groups are named for how these bones are built.","tier":1},{"w":"AMBER","clue":"Golden tree sap that hardened and sometimes traps ancient bugs","fact":"Amber has trapped insects and even small feathers from the dinosaur age.","tier":1},{"w":"EXTINCT","clue":"No longer living anywhere on Earth","fact":"Most dinosaurs disappeared about 66 million years ago, but birds survived.","tier":2},{"w":"MUSEUM","clue":"Building where you can see big dinosaur skeletons on display","fact":"Many skeletons on display are partly made of copies of the real bones.","tier":2},{"w":"FEATHER","clue":"Light, fluffy covering that birds have and some dinosaurs had","fact":"Many dinosaurs, including Velociraptor, had these.","tier":2},{"w":"LIZARD","clue":"Scaly reptile; \"saurus\" is the old word for it","fact":"\"Dinosaur\" means \"terrible lizard,\" but dinosaurs were not lizards.","tier":2},{"w":"ARMORED","clue":"Covered in hard, bony plates for protection, like Ankylosaurus","fact":"Ankylosaurus had a heavy bony club at the end of its tail.","tier":2},{"w":"PLATES","clue":"Stegosaurus had big, flat, bony ones on its back","fact":"Scientists think they may have helped it control its body heat.","tier":2},{"w":"FOSSIL","clue":"Stone-like remains or prints of ancient life","fact":"Dinosaur fossils have been found on every continent, even Antarctica.","tier":2},{"w":"CRATER","clue":"Giant bowl-shaped hole left when a space rock hits the ground","fact":"A huge one in Mexico marks where an asteroid hit about 66 million years ago.","tier":2},{"w":"EVOLVED","clue":"Changed slowly over millions of years into new kinds of animals","fact":"Birds evolved from small feathered dinosaurs.","tier":2},{"w":"LAYERS","clue":"Rock ones stack like a cake, oldest usually at the bottom","fact":"Deeper rock layers usually hold older fossils.","tier":2},{"w":"PANGAEA","clue":"The giant ancient supercontinent when all the land was joined","fact":"When the first dinosaurs lived, almost all land was joined together.","tier":2},{"w":"REPTILE","clue":"Scaly, cold-blooded animal like a crocodile or turtle","fact":"Crocodiles are reptiles that already lived alongside the dinosaurs.","tier":2},{"w":"CONIFER","clue":"Evergreen tree with cones, like a pine","fact":"Plant-eating dinosaurs munched on conifers and ferns long ago.","tier":2},{"w":"MAMMALS","clue":"Furry, milk-making animals; tiny early ones lived with dinosaurs","fact":"Small furry mammals lived alongside dinosaurs, hiding in burrows and trees.","tier":2},{"w":"TRICERATOPS","clue":"Big plant-eater with a bony neck shield and three face horns","fact":"It had hundreds of tiny teeth that worked like scissors on tough plants.","tier":3},{"w":"STEGOSAURUS","clue":"Plated dinosaur with spikes on its tail","fact":"It walked on four legs, and its back legs were much longer than its front legs.","tier":3},{"w":"DINOSAUR","clue":"A name that means \"terrible lizard\"","fact":"Birds are living dinosaurs, so dinosaurs are still all around us.","tier":3},{"w":"ASTEROID","clue":"Giant space rock that probably ended the dinosaur age","fact":"The asteroid that likely ended the dinosaur age was several miles wide.","tier":3},{"w":"CARNIVORE","clue":"An animal that eats only meat","fact":"Most meat-eating dinosaurs walked on two legs.","tier":3},{"w":"HERBIVORE","clue":"An animal that eats only plants","fact":"Some plant-eating dinosaurs were as long as two school buses lined up.","tier":3},{"w":"PTEROSAUR","clue":"Flying reptile that lived with the dinosaurs but was not one","fact":"Their wings were made of stretched skin, not feathers.","tier":3},{"w":"CRETACEOUS","clue":"The last period of the dinosaur age, when T. rex lived","fact":"T. rex lived closer in time to us than to Stegosaurus.","tier":3},{"w":"GASTROLITH","clue":"Stomach stones some dinosaurs swallowed to grind up their food","fact":"Chickens do the same, swallowing tiny stones to help grind their food.","tier":3},{"w":"PREHISTORIC","clue":"From the time before people wrote anything down","fact":"Dinosaurs lived millions of years before the first people.","tier":3},{"w":"REX","clue":"Latin word for \"king\" in a famous dinosaur's name","fact":"Tyrannosaurus rex means \"tyrant lizard king.\"","tier":1},{"w":"ROAR","clue":"Deep, loud animal sound that a lion makes","fact":"Scientists think dinosaurs may have made deep booming sounds, more like crocodiles and ostriches than movie roars.","tier":1},{"w":"NECK","clue":"Body part between head and shoulders; Brachiosaurus had a very long one","fact":"Long-necked dinosaurs could reach leaves at the tops of tall trees.","tier":1},{"w":"MEAT","clue":"Food from animals, like beef or chicken","fact":"Meat-eating dinosaurs walked on two legs and are called theropods.","tier":1},{"w":"BONE","clue":"Hard white part inside a body that fossil hunters dig up","fact":"Many meat-eating dinosaurs had hollow bones, like birds do, which kept them lighter.","tier":1},{"w":"DIG","clue":"What fossil hunters do with shovels and brushes to find bones","fact":"Paleontologists use tiny brushes and dental picks to uncover fossils without breaking them.","tier":1},{"w":"SKULL","clue":"Bony case that protects the brain","fact":"A Triceratops skull could be longer than a grown-up is tall.","tier":1},{"w":"BIRD","clue":"Modern feathered animal with wings that is a living dinosaur","fact":"Birds are living dinosaurs, descended from small feathered meat-eaters.","tier":1},{"w":"SAIL","clue":"Cloth that catches wind on a boat; Spinosaurus had a bony one","fact":"Spinosaurus had a tall sail on its back and probably hunted fish in rivers.","tier":1},{"w":"LAND","clue":"Dry ground, not the sea; where dinosaurs lived","fact":"Sea reptiles like plesiosaurs lived at the same time, but they were not dinosaurs.","tier":1},{"w":"FERN","clue":"Leafy plant with feathery fronds that grows in shady forests","fact":"Ferns carpeted the ground in dinosaur times, long before grass spread.","tier":1},{"w":"WING","clue":"Body part a pterosaur flapped to fly","fact":"Pterosaur wings were thin skin stretched from one very long finger.","tier":1},{"w":"DIET","clue":"Types of food an animal usually eats","fact":"Tooth shape tells scientists what a dinosaur ate: sharp for meat, flat for plants.","tier":1},{"w":"SPACE","clue":"The huge dark area beyond Earth's air, full of stars","fact":"The asteroid that hit Earth about 66 million years ago was roughly six miles wide.","tier":1},{"w":"GIANT","clue":"Very large being in a fairy tale who says \"fee-fi-fo-fum\"","fact":"Some long-necked dinosaurs may have been longer than a basketball court.","tier":1},{"w":"CHICK","clue":"Fluffy yellow baby that hatches from a hen's egg","fact":"Scientists found that proteins in T. rex bone were most like a chicken's.","tier":1},{"w":"STONE","clue":"Hard rock material that old bones turn into as fossils","fact":"Fossil bones turn to stone as minerals slowly replace them over millions of years.","tier":1},{"w":"MUD","clue":"Wet, sticky dirt that sticks to your boots","fact":"A dinosaur footprint pressed in soft mud can turn into rock if it gets covered quickly.","tier":1},{"w":"SMELL","clue":"Sense you use your nose for","fact":"T. rex had a very large smell center in its brain, so it probably smelled very well.","tier":1},{"w":"DUCK","clue":"Waterbird that says quack; one dinosaur group is named for its bill","fact":"Duck-billed dinosaurs had hundreds of tiny teeth packed together for grinding plants.","tier":1},{"w":"LEAF","clue":"Flat green part of a plant that catches sunlight","fact":"Many dinosaurs ate leaves from ginkgo trees, which still grow today.","tier":1},{"w":"FAST","clue":"Moving at high speed, like a cheetah","fact":"Gallimimus looked like an ostrich and probably ran about as fast as one.","tier":1},{"w":"BITE","clue":"Chomp down with your teeth","fact":"T. rex had one of the strongest bites of any land animal ever.","tier":1},{"w":"SPINE","clue":"Your backbone, or a sharp point on a cactus","fact":"Spinosaurus means \"spine lizard.\"","tier":1},{"w":"TOES","clue":"Five wiggly digits on each of your feet","fact":"Most meat-eating dinosaurs walked on three toes, leaving footprints like a bird's.","tier":1},{"w":"GRASS","clue":"Green blades that cover lawns and baseball fields","fact":"Early dinosaurs had no grass to eat, because grasslands spread much later.","tier":1},{"w":"TINY","clue":"Very, very small","fact":"Some feathered dinosaurs were only about as big as a pigeon.","tier":1},{"w":"LAVA","clue":"Red-hot melted rock that pours from a volcano","fact":"Huge lava eruptions in India happened around the time the dinosaurs died out.","tier":1},{"w":"RAPTOR","clue":"Small, fast, feathered hunter with a curved toe claw","fact":"Real Velociraptors were about as big as turkeys and covered in feathers.","tier":2},{"w":"VOLCANO","clue":"Mountain that can erupt with lava and ash","fact":"Volcanic ash sometimes buried dinosaurs quickly, which helped preserve their bones.","tier":2},{"w":"GINKGO","clue":"Tree with fan-shaped leaves that has barely changed in millions of years","fact":"Ginkgo trees grew in dinosaur times, so they are called living fossils.","tier":2},{"w":"JUNGLE","clue":"Thick, hot, wet forest full of vines","fact":"Dinosaurs even lived in forests near the poles, where winters were dark.","tier":2},{"w":"CLIMATE","clue":"Typical weather of a place over many years","fact":"Earth was much warmer in dinosaur times, with little or no ice at the poles.","tier":2},{"w":"GROWTH","clue":"The process of getting bigger over time","fact":"A teenage T. rex gained roughly five pounds every day.","tier":2},{"w":"SHOVEL","clue":"Digging tool with a flat blade and a long handle","fact":"Fossil hunters use shovels for the top dirt, then switch to tiny tools near the bones.","tier":2},{"w":"HAMMER","clue":"Tool for pounding nails; fossil hunters use small ones with chisels","fact":"Paleontologists tap rock gently with small hammers to free fossils.","tier":2},{"w":"JACKET","clue":"Warm coat for cold weather; also a plaster wrap around a fossil","fact":"Fossil hunters wrap bones in plaster jackets, like a cast on a broken arm.","tier":2},{"w":"DESERT","clue":"Dry, sandy region that gets very little rain","fact":"Many famous dinosaur fossils come from deserts, where wind uncovers old bones.","tier":2},{"w":"CANYON","clue":"Deep valley with steep rock walls","fact":"The rock layers in a canyon are like pages in a book about Earth's past.","tier":2},{"w":"PLANET","clue":"Large world circling a star, like Earth","fact":"Earth is the only planet where dinosaur fossils have ever been found.","tier":2},{"w":"IMPACT","clue":"A hard crash of one thing into another","fact":"The asteroid's impact threw so much dust into the sky that it blocked sunlight.","tier":2},{"w":"FINGER","clue":"One of the five digits on your hand","fact":"T. rex had only two fingers on each tiny arm.","tier":2},{"w":"OSTRICH","clue":"Giant flightless bird with long legs that runs very fast","fact":"Ostriches sprint on two legs, much like many dinosaurs did.","tier":2},{"w":"BEETLE","clue":"Insect with a hard shell-like back, like a ladybug","fact":"Beetles lived alongside dinosaurs, and today there are more kinds of beetles than of any other animal group.","tier":2},{"w":"HEIGHT","clue":"How tall something is, from bottom to top","fact":"Brachiosaurus stood about as tall as a four-story building.","tier":2},{"w":"STRIPES","clue":"Dark bands, like a tiger or a zebra has","fact":"Tiny pigment bits in fossils show that Sinosauropteryx had a striped tail.","tier":2},{"w":"PIGMENT","clue":"Natural coloring in skin, feathers, or fur","fact":"Scientists found tiny pigment structures in fossil feathers and figured out some dinosaurs' colors.","tier":2},{"w":"SCANNER","clue":"Machine that takes pictures of the inside of things","fact":"CT scanners let scientists look inside fossil skulls without breaking them open.","tier":2},{"w":"NESTING","clue":"Building a home for eggs and sitting on them","fact":"Oviraptor fossils have been found sitting on top of their eggs, like birds do.","tier":2},{"w":"EMBRYO","clue":"Tiny baby animal growing inside an egg","fact":"Scientists have found fossil dinosaur eggs with embryos still curled up inside.","tier":2},{"w":"DISPLAY","clue":"To show off for others to admire","fact":"Crests and horns may have been used to show off, like a peacock's tail.","tier":2},{"w":"GLIDER","clue":"Light aircraft with no engine that floats on the wind","fact":"Microraptor had feathers on its arms and legs and may have glided between trees.","tier":2},{"w":"GIRAFFE","clue":"Spotted African animal with a very long neck","fact":"Some long-necked dinosaurs had necks many times longer than a giraffe's.","tier":2},{"w":"DRAGON","clue":"Fire-breathing flying creature from fairy tales","fact":"Long ago, people who found dinosaur bones sometimes thought they were dragon bones.","tier":2},{"w":"FLOWERS","clue":"Colorful blooms on plants that bees visit","fact":"The very first flowers appeared while dinosaurs were alive.","tier":2},{"w":"HISTORY","clue":"Everything that happened in the past","fact":"Dinosaurs ruled Earth for over 160 million years, far longer than humans have existed.","tier":2},{"w":"MILLION","clue":"A thousand thousands","fact":"Dinosaurs died out about 66 million years ago.","tier":2},{"w":"REPLICA","clue":"A copy of the real thing, like a cast of a skull","fact":"Most museum skeletons are copies, because real fossil bones are heavy and fragile.","tier":2},{"w":"PUZZLE","clue":"Game of pieces you fit together","fact":"Fossil hunters often find bones scattered like puzzle pieces and fit them back together.","tier":2},{"w":"THUNDER","clue":"Loud rumble that follows lightning","fact":"Brontosaurus means \"thunder lizard.\"","tier":2},{"w":"WINGSPAN","clue":"Distance from one wingtip to the other","fact":"Quetzalcoatlus had a wingspan about as wide as a small airplane.","tier":3},{"w":"MICROSCOPE","clue":"Tool that makes tiny things look much bigger","fact":"Under a microscope, scientists can see growth rings in dinosaur bones that show how old it was.","tier":3},{"w":"COMPUTER","clue":"Machine with a screen and keyboard that runs programs and games","fact":"Scientists use computers to test how fast a dinosaur could have run, based on its bones.","tier":3},{"w":"HATCHLING","clue":"Newborn animal that has just come out of its egg","fact":"Even giant long-necked dinosaurs hatched from eggs much smaller than a beach ball.","tier":3},{"w":"OMNIVORE","clue":"Animal that eats both plants and meat","fact":"Scientists think some dinosaurs ate both plants and small animals.","tier":3},{"w":"CROCODILE","clue":"Big snouty reptile of African rivers, a living cousin of dinosaurs","fact":"Crocodiles and birds are the closest living relatives of dinosaurs.","tier":3},{"w":"ELEPHANT","clue":"Largest living land animal, with a trunk and tusks","fact":"The biggest long-necked dinosaurs weighed many times more than an elephant.","tier":3},{"w":"CONTINENT","clue":"One of Earth's seven giant land areas","fact":"Dinosaur fossils have been found on every continent, even Antarctica.","tier":3},{"w":"ANTARCTICA","clue":"Icy land at the bottom of the world","fact":"Dinosaurs once lived there, when it was warmer and covered in forests.","tier":3},{"w":"OVIRAPTOR","clue":"Feathered dinosaur whose name wrongly means \"egg thief\"","fact":"Oviraptor was named by mistake; it was really guarding its own nest.","tier":3},{"w":"ALLOSAURUS","clue":"Big meat-eater from the Jurassic, older cousin of T. rex","fact":"Allosaurus lived about 80 million years before T. rex.","tier":3},{"w":"DIPLODOCUS","clue":"Very long plant-eater whose name means \"double beam\"","fact":"Diplodocus was longer than two school buses, but its head was small.","tier":3},{"w":"SPINOSAURUS","clue":"Giant fish-eating dinosaur with a tall sail on its back","fact":"Spinosaurus may have been even longer than T. rex.","tier":3},{"w":"IGUANODON","clue":"Plant-eater with spiky thumbs, one of the first dinosaurs named","fact":"Iguanodon was named about 200 years ago, when people had only just begun finding dinosaurs.","tier":3},{"w":"PLESIOSAUR","clue":"Long-necked sea reptile with four flippers; not a dinosaur","fact":"Plesiosaurs flapped four flippers like wings to fly through the water.","tier":3},{"w":"MOSASAUR","clue":"Giant sea lizard of the late dinosaur age","fact":"Mosasaurs were giant sea reptiles related to today's snakes and lizards.","tier":3},{"w":"PTERANODON","clue":"Flying reptile with a pointed head crest and no teeth","fact":"Pteranodon had no teeth, so it probably swallowed fish whole.","tier":3},{"w":"COPROLITE","clue":"Rock-hard fossil of animal droppings","fact":"Coprolites show scientists what dinosaurs ate, sometimes even including bits of bone.","tier":3},{"w":"EXCAVATION","clue":"Careful digging to uncover things buried long ago","fact":"A big dinosaur dig can take many summers of careful work.","tier":3},{"w":"SEDIMENT","clue":"Sand and mud that settle and pile up in layers","fact":"Bones buried quickly in sediment have the best chance of becoming fossils.","tier":3},{"w":"EXTINCTION","clue":"When a whole kind of animal disappears forever","fact":"About three out of four kinds of living things died out when the dinosaurs did.","tier":3},{"w":"SURVIVOR","clue":"Someone who lives through something dangerous","fact":"Crocodiles, turtles, and birds all survived the event that ended the dinosaur age.","tier":3},{"w":"TRIASSIC","clue":"The first of three periods in the age of dinosaurs","fact":"The first dinosaurs appeared in the Triassic, about 230 million years ago.","tier":3},{"w":"JURASSIC","clue":"The middle period of the age of dinosaurs","fact":"Long-necked giants like Diplodocus lived in the Jurassic, which is named after the Jura Mountains.","tier":3}],"es":[{"w":"HUEVO","clue":"Un bebé dinosaurio empieza su vida dentro de él","fact":"Los dinosaurios ponían huevos, y las aves, que son dinosaurios vivos, todavía lo hacen.","tier":1},{"w":"NIDO","clue":"Los dinosaurios lo hacían para cuidar sus huevos","fact":"Maiasaura significa \"buena madre lagarto\" porque cuidaba a sus crías en el nido.","tier":1},{"w":"GARRA","clue":"Uña larga, curva y afilada de un animal","fact":"Muchos dinosaurios carnívoros tenían tres grandes en cada mano.","tier":1},{"w":"PICO","clue":"Parte dura y puntiaguda de la boca, como la de un pájaro","fact":"Muchos dinosaurios que comían plantas tenían uno para cortar hojas.","tier":1},{"w":"HUESO","clue":"Parte dura de un esqueleto, que los científicos desentierran","fact":"Algunos huesos de dinosaurio se convirtieron en piedra en millones de años.","tier":1},{"w":"ÁMBAR","clue":"Resina dorada de árbol que se endureció y a veces atrapa insectos","fact":"El ámbar ha atrapado insectos y hasta plumas de la época de los dinosaurios.","tier":1},{"w":"PLACA","clue":"El estegosaurio tenía varias grandes y planas en el lomo","fact":"Los científicos creen que las del estegosaurio le ayudaban a regular su temperatura.","tier":1},{"w":"PLUMA","clue":"Cubierta ligera y suave de las aves; algunos dinosaurios la tenían","fact":"Muchos dinosaurios, como el velociraptor, tenían plumas.","tier":1},{"w":"AVE","clue":"Animal con plumas y pico, pariente vivo de los dinosaurios","fact":"Las aves tienen huesos huecos y ligeros, igual que muchos dinosaurios.","tier":1},{"w":"COLA","clue":"La larga parte trasera del dinosaurio le servía de equilibrio","fact":"Muchos dinosaurios usaban la cola para mantener el equilibrio al caminar.","tier":1},{"w":"FÓSIL","clue":"Resto o huella de un ser antiguo convertido en piedra","fact":"Se han encontrado fósiles de dinosaurio en todos los continentes, incluso en la Antártida.","tier":1},{"w":"MUSEO","clue":"Edificio donde puedes ver esqueletos enormes de dinosaurio","fact":"Muchos museos guardan fósiles de dinosaurio que llevan millones de años bajo tierra.","tier":1},{"w":"CUERNO","clue":"Punta dura y larga sobre la cabeza, como las del triceratops","fact":"Triceratops significa \"cara con tres cuernos\".","tier":2},{"w":"MANADA","clue":"Grupo de animales que caminan juntos","fact":"Huellas fósiles muestran que algunos dinosaurios viajaban en manada.","tier":2},{"w":"CRESTA","clue":"Hueso hueco sobre la cabeza del parasaurolofo","fact":"Los científicos creen que la del parasaurolofo sonaba como una trompeta.","tier":2},{"w":"HUELLA","clue":"Marca del pie de un animal, a veces convertida en piedra","fact":"Algunas en piedra muestran a qué velocidad caminaba el dinosaurio.","tier":2},{"w":"CRÁTER","clue":"Agujero enorme que deja un asteroide al chocar","fact":"Un cráter gigante en México marca dónde cayó un asteroide hace unos 66 millones de años.","tier":2},{"w":"EXTINTO","clue":"Que ya no vive en ningún lugar de la Tierra","fact":"La mayoría de los dinosaurios desaparecieron hace unos 66 millones de años, pero las aves no.","tier":2},{"w":"LAGARTO","clue":"Reptil con escamas; \"saurio\" significa esto","fact":"La palabra \"dinosaurio\" significa \"lagarto terrible\", pero no eran lagartos.","tier":2},{"w":"CADERA","clue":"Hueso donde las patas traseras se unen al cuerpo","fact":"Los científicos separan a los dinosaurios en dos grandes grupos según la forma de la cadera.","tier":2},{"w":"REPTIL","clue":"Animal de sangre fría y con escamas, como el cocodrilo","fact":"Los cocodrilos son reptiles que ya vivían junto a los dinosaurios.","tier":2},{"w":"PANGEA","clue":"El supercontinente donde antes estaban unidas casi todas las tierras","fact":"Cuando aparecieron los dinosaurios, casi toda la tierra formaba un solo continente.","tier":2},{"w":"CUELLO","clue":"El braquiosaurio lo tenía larguísimo para alcanzar hojas altas","fact":"El braquiosaurio podía alcanzar las hojas de las copas de árboles muy altos.","tier":2},{"w":"ESPINAS","clue":"Puntas afiladas en la espalda o la cola de algunos dinosaurios","fact":"El estegosaurio tenía cuatro en la cola para protegerse.","tier":2},{"w":"EXCAVAR","clue":"Cavar con cuidado para encontrar fósiles","fact":"Los paleontólogos usan pinceles finos para descubrir huesos sin romperlos.","tier":2},{"w":"CAZADOR","clue":"Animal que persigue a otros para alimentarse","fact":"El velociraptor medía como un pavo y tenía una garra curva en cada pie.","tier":2},{"w":"TRICERÁTOPS","clue":"Dinosaurio vegetariano con tres cuernos y escudo de hueso en la nuca","fact":"Tenía cientos de dientes pequeños que cortaban plantas duras como tijeras.","tier":3},{"w":"DINOSAURIO","clue":"Su nombre significa \"lagarto terrible\"","fact":"Las aves son dinosaurios vivos, así que los dinosaurios siguen entre nosotros.","tier":3},{"w":"ASTEROIDE","clue":"Roca gigante del espacio que probablemente acabó con los dinosaurios","fact":"El que probablemente acabó con los dinosaurios medía varios kilómetros de ancho.","tier":3},{"w":"CARNÍVORO","clue":"Animal que come solo carne","fact":"El tiranosaurio rex era uno, con una mandíbula muy poderosa.","tier":3},{"w":"HERBÍVORO","clue":"Animal que come solo plantas","fact":"Algunos dinosaurios de este tipo eran tan largos como dos autobuses escolares.","tier":3},{"w":"PTEROSAURIO","clue":"Reptil volador que vivió junto a los dinosaurios, pero no era uno","fact":"Sus alas eran de piel estirada, no de plumas.","tier":3},{"w":"CRETÁCICO","clue":"Último período de la era de los dinosaurios; vivió el T. rex","fact":"El T. rex vivió más cerca de nuestra época que de la del estegosaurio.","tier":3},{"w":"ESQUELETO","clue":"Todos los huesos de un cuerpo, armados juntos","fact":"El esqueleto de un ave se parece mucho al de un dinosaurio pequeño.","tier":3},{"w":"GASTROLITO","clue":"Piedra que tragaban algunos dinosaurios para moler la comida en el estómago","fact":"Las gallinas también tragan piedritas para moler su comida.","tier":3},{"w":"ARMADURA","clue":"Cubierta de placas duras que protegía al anquilosaurio","fact":"El anquilosaurio tenía una maza de hueso al final de la cola.","tier":3},{"w":"REY","clue":"Persona con corona que gobierna un reino","fact":"El nombre Tyrannosaurus rex significa \"rey de los lagartos tiranos\".","tier":1},{"w":"DIETA","clue":"Los alimentos que come normalmente un animal","fact":"La forma de los dientes muestra si un dinosaurio comía carne o plantas.","tier":1},{"w":"PATA","clue":"Pie y pierna de un animal, como la de un perro","fact":"Los dinosaurios caminaban con las patas debajo del cuerpo, no abiertas a los lados como un lagarto.","tier":1},{"w":"ALA","clue":"Parte del cuerpo con la que vuela un ave","fact":"Las alas de los pterosaurios eran de piel delgada, estirada desde un dedo larguísimo.","tier":1},{"w":"VOLAR","clue":"Moverse por el aire con alas","fact":"Los pterosaurios volaban sobre los dinosaurios, aunque no eran dinosaurios.","tier":1},{"w":"BARRO","clue":"Tierra mojada y pegajosa que se te pega en los zapatos","fact":"Una huella en barro blando puede volverse roca si algo la cubre rápido.","tier":1},{"w":"ROCA","clue":"Material duro de las montañas, en el que se forman los fósiles","fact":"Los fósiles se forman en capas de roca que antes fueron arena y lodo.","tier":1},{"w":"SOL","clue":"Estrella que da luz y calor a la Tierra","fact":"La luz del Sol tarda unos ocho minutos en llegar a la Tierra.","tier":1},{"w":"LAVA","clue":"Roca derretida y roja que sale de un volcán","fact":"Enormes erupciones de lava en la India ocurrieron más o menos cuando se extinguieron los dinosaurios.","tier":1},{"w":"POLLO","clue":"Ave de granja que se sirve frita o al horno","fact":"Los pollos son aves, y las aves son dinosaurios vivos.","tier":1},{"w":"PATO","clue":"Ave de pico plano que nada en lagunas y dice cuac","fact":"Los hadrosaurios, llamados dinosaurios de pico de pato, eran herbívoros.","tier":1},{"w":"DEDO","clue":"Cada una de las cinco partes móviles de tu mano","fact":"El T. rex tenía solo dos dedos en cada brazo diminuto.","tier":1},{"w":"BRAZO","clue":"Parte del cuerpo entre el hombro y la mano","fact":"Los brazos del T. rex eran cortos, pero tenían huesos gruesos y mucho músculo.","tier":1},{"w":"VELA","clue":"Tela grande que atrapa el viento en un barco","fact":"El espinosaurio tenía una gran vela en la espalda y probablemente cazaba peces en los ríos.","tier":1},{"w":"HOJA","clue":"Parte plana y verde de una planta que atrapa la luz","fact":"Los dinosaurios de cuello largo estiraban el cuello para alcanzar las hojas más altas de los árboles.","tier":1},{"w":"PASTO","clue":"Hierba verde y corta que cubre las canchas","fact":"Los primeros dinosaurios no tenían pasto para comer, porque los pastizales aparecieron mucho después.","tier":1},{"w":"SELVA","clue":"Bosque caliente y húmedo, lleno de plantas y lianas","fact":"Había dinosaurios en bosques cerca de los polos, donde los inviernos eran oscuros.","tier":1},{"w":"PALA","clue":"Herramienta de hoja plana para cavar","fact":"Los cazadores de fósiles usan palas para la tierra de arriba y pinceles pequeños cerca de los huesos.","tier":1},{"w":"YESO","clue":"Polvo blanco que, mojado, se endurece y protege un brazo roto","fact":"Los cazadores de fósiles envuelven los huesos en yeso para llevarlos sin romperlos.","tier":1},{"w":"LAGO","clue":"Gran cantidad de agua dulce rodeada de tierra","fact":"Muchos fósiles de dinosaurio aparecen donde antes había lagos y ríos, porque el lodo cubría los huesos.","tier":1},{"w":"ÁRBOL","clue":"Planta grande con tronco, ramas y hojas","fact":"Los árboles de ginkgo crecían en tiempos de los dinosaurios y todavía existen.","tier":1},{"w":"FLOR","clue":"Parte colorida de una planta que visitan las abejas","fact":"Las primeras flores aparecieron cuando todavía vivían los dinosaurios.","tier":1},{"w":"EDAD","clue":"Cuántos años tiene alguien o algo","fact":"Los T. rex más viejos que se conocen tenían unos 28 años.","tier":1},{"w":"POLVO","clue":"Tierra muy fina y seca que flota en el aire","fact":"El polvo que levantó el asteroide tapó la luz del Sol durante mucho tiempo.","tier":1},{"w":"HIELO","clue":"Agua congelada, dura y fría","fact":"Cuando vivían los dinosaurios casi no había hielo en los polos, porque el clima era más cálido.","tier":1},{"w":"ROBOT","clue":"Máquina que se mueve y trabaja sola","fact":"Algunos museos tienen dinosaurios robot que se mueven y hacen sonidos.","tier":1},{"w":"LUNA","clue":"Satélite natural que vemos brillar de noche","fact":"Los cráteres de la Luna se formaron por choques de asteroides, como el que acabó con los dinosaurios.","tier":1},{"w":"ISLA","clue":"Pedazo de tierra rodeado de agua por todos lados","fact":"Europasaurus, un dinosaurio de cuello largo, vivió en una isla y era pequeño.","tier":1},{"w":"DIENTE","clue":"Pieza dura de la boca que sirve para masticar","fact":"Algunos dientes de T. rex eran tan largos como un plátano.","tier":2},{"w":"HELECHO","clue":"Planta de hojas plumosas que crece en lugares sombríos","fact":"Los helechos cubrían el suelo en tiempos de los dinosaurios, mucho antes que el pasto.","tier":2},{"w":"PIEDRA","clue":"Trozo duro de roca que puedes levantar del suelo","fact":"Los huesos de dinosaurio se vuelven piedra cuando los minerales los reemplazan durante millones de años.","tier":2},{"w":"ESPACIO","clue":"El enorme vacío oscuro más allá del aire de la Tierra","fact":"El asteroide que chocó con la Tierra hace unos 66 millones de años medía unos diez kilómetros.","tier":2},{"w":"CRÁNEO","clue":"Hueso duro que protege el cerebro","fact":"El cráneo de un tricerátops podía medir más que un adulto de alto.","tier":2},{"w":"DRAGÓN","clue":"Criatura de cuentos que vuela y echa fuego","fact":"Hace mucho, quienes encontraban huesos de dinosaurio a veces creían que eran de dragón.","tier":2},{"w":"GALLINA","clue":"Ave de granja que pone huevos para el desayuno","fact":"Los científicos vieron que las proteínas del T. rex se parecían mucho a las de una gallina.","tier":2},{"w":"TIERRA","clue":"Nuestro planeta, el tercero desde el Sol","fact":"La Tierra tiene unos 4,500 millones de años, y los dinosaurios llegaron mucho después.","tier":2},{"w":"MORDIDA","clue":"Apretón fuerte que das con los dientes","fact":"La mordida del T. rex era de las más fuertes de cualquier animal terrestre.","tier":2},{"w":"PINCEL","clue":"Herramienta con cerdas para pintar o limpiar con suavidad","fact":"Los paleontólogos limpian los fósiles con pinceles pequeños para no romperlos.","tier":2},{"w":"VOLCÁN","clue":"Montaña que puede echar lava y ceniza","fact":"Un volcán puede lanzar ceniza a muchos kilómetros de altura.","tier":2},{"w":"IMPACTO","clue":"Choque fuerte de un objeto contra otro","fact":"El asteroide que chocó con la Tierra dejó un cráter de unos 180 kilómetros de ancho.","tier":2},{"w":"COMETA","clue":"Bola de hielo y polvo con una cola brillante en el espacio","fact":"Los cometas y los asteroides son sobras de cuando se formó el Sistema Solar.","tier":2},{"w":"JIRAFA","clue":"Animal africano de manchas y cuello larguísimo","fact":"Algunos dinosaurios de cuello largo tenían un cuello mucho más largo que el de una jirafa.","tier":2},{"w":"RAPTOR","clue":"Dinosaurio pequeño y veloz con una garra curva en el pie","fact":"Los velociraptores de verdad eran del tamaño de un pavo y tenían plumas.","tier":2},{"w":"EMBRIÓN","clue":"Bebé muy pequeño que crece dentro del huevo","fact":"Se han encontrado huevos fósiles de dinosaurio con embriones enroscados adentro.","tier":2},{"w":"CRECER","clue":"Hacerse más grande con el paso del tiempo","fact":"Un T. rex adolescente aumentaba unos dos kilos al día.","tier":2},{"w":"ALTURA","clue":"Qué tan alto es algo, de abajo hacia arriba","fact":"Un braquiosaurio era tan alto como un edificio de cuatro pisos.","tier":2},{"w":"ESCÁNER","clue":"Máquina que toma imágenes del interior de las cosas","fact":"Con escáneres, los científicos pueden ver dentro de un cráneo fósil sin romperlo.","tier":2},{"w":"PLANEAR","clue":"Volar sin batir las alas, dejándose llevar por el aire","fact":"El microraptor tenía plumas en brazos y piernas, y quizá planeaba entre los árboles.","tier":2},{"w":"MILLÓN","clue":"Mil veces mil","fact":"Los dinosaurios desaparecieron hace unos 66 millones de años.","tier":2},{"w":"RÉPLICA","clue":"Copia de algo real, como el molde de un cráneo","fact":"Muchos esqueletos de los museos son copias, porque los huesos de verdad son pesados y frágiles.","tier":2},{"w":"TRUENO","clue":"Ruido fuerte y grave que se oye después del rayo","fact":"Brontosaurio significa \"lagarto del trueno\".","tier":2},{"w":"MINERAL","clue":"Material duro natural, como el cuarzo, que se forma en las rocas","fact":"Un hueso se vuelve fósil cuando los minerales lo llenan y lo endurecen.","tier":2},{"w":"BOSQUE","clue":"Terreno con muchísimos árboles","fact":"Los bosques de la época de los dinosaurios tenían coníferas, helechos y plantas parecidas a palmeras.","tier":2},{"w":"PANTANO","clue":"Terreno bajo cubierto de agua poco profunda y lodo","fact":"Muchos fósiles se formaron en pantanos, donde el lodo cubría rápido los huesos.","tier":2},{"w":"DEFENSA","clue":"Forma en que un animal se protege de los ataques","fact":"El estegosaurio se defendía golpeando con su cola llena de púas.","tier":2},{"w":"CAMINAR","clue":"Moverse con los pies, paso a paso","fact":"Los científicos calculan qué tan rápido caminaba un dinosaurio midiendo la distancia entre sus huellas.","tier":2},{"w":"CORRER","clue":"Moverse a pie muy rápido, más que al caminar","fact":"Gallimimus se parecía a un avestruz y probablemente corría igual de rápido.","tier":2},{"w":"SONIDO","clue":"Lo que escuchas con tus oídos","fact":"Algunos dinosaurios con cresta quizá hacían sonidos graves al soplar por ella.","tier":2},{"w":"CENIZA","clue":"Polvo gris que queda de lo quemado y sale de los volcanes","fact":"La ceniza volcánica enterró a algunos animales rápido y ayudó a conservarlos.","tier":2},{"w":"CARBÓN","clue":"Roca negra que se quema, hecha de plantas antiguas","fact":"El carbón se formó con plantas enterradas hace cientos de millones de años.","tier":2},{"w":"DESIERTO","clue":"Región seca y arenosa donde casi no llueve","fact":"Muchos fósiles famosos de dinosaurio vienen de desiertos, donde el viento deja al descubierto huesos antiguos.","tier":3},{"w":"AVESTRUZ","clue":"Ave enorme que no vuela, de patas largas, y corre muy rápido","fact":"El avestruz es el ave viva más grande, y es pariente de los dinosaurios.","tier":3},{"w":"COCODRILO","clue":"Reptil grande de hocico largo y mandíbulas fuertes, pariente de los dinosaurios","fact":"Los cocodrilos y las aves son los parientes vivos más cercanos de los dinosaurios.","tier":3},{"w":"MICROSCOPIO","clue":"Aparato que hace ver enormes las cosas diminutas","fact":"Con un microscopio, los científicos ven cómo creció un hueso de dinosaurio, como los anillos de un árbol.","tier":3},{"w":"COMPUTADORA","clue":"Máquina con pantalla y teclado donde haces tareas y juegas","fact":"Los científicos usan computadoras para calcular qué tan rápido corría un dinosaurio según sus huesos.","tier":3},{"w":"PIGMENTO","clue":"Color natural de la piel, las plumas o el pelo","fact":"Se hallaron restos diminutos de pigmento en plumas fósiles y así se descubrieron los colores de algunos dinosaurios.","tier":3},{"w":"SOBREVIVIR","clue":"Seguir con vida después de un peligro","fact":"Cocodrilos, tortugas y aves sobrevivieron al suceso que acabó con los dinosaurios.","tier":3},{"w":"EXTINCIÓN","clue":"Cuando toda una clase de animales desaparece para siempre","fact":"Cuando murieron los dinosaurios, desapareció cerca de tres de cada cuatro tipos de seres vivos.","tier":3},{"w":"JURÁSICO","clue":"El periodo medio de la era de los dinosaurios","fact":"Muchos gigantes de cuello largo vivieron en el Jurásico, que lleva el nombre de las montañas del Jura.","tier":3},{"w":"TRIÁSICO","clue":"El primer periodo de la era de los dinosaurios","fact":"Los primeros dinosaurios aparecieron en el Triásico, hace unos 230 millones de años.","tier":3},{"w":"SEDIMENTO","clue":"Arena y lodo que se asientan y forman capas","fact":"Los huesos cubiertos rápido por sedimento tienen más posibilidades de volverse fósiles.","tier":3},{"w":"ENVERGADURA","clue":"Distancia de la punta de un ala a la otra","fact":"El Quetzalcoatlus tenía una envergadura tan ancha como la de un avión pequeño.","tier":3},{"w":"MANDÍBULA","clue":"Hueso que mueves al abrir y cerrar la boca","fact":"Algunos dinosaurios de pico de pato tenían cientos de dientes en las mandíbulas.","tier":3},{"w":"ALOSAURIO","clue":"Gran carnívoro del Jurásico, más antiguo que el T. rex","fact":"El alosaurio vivió unos 80 millones de años antes que el T. rex.","tier":3},{"w":"DIPLODOCUS","clue":"Herbívoro larguísimo cuyo nombre significa \"doble viga\"","fact":"Medía más que dos autobuses escolares, pero tenía la cabeza pequeña.","tier":3},{"w":"IGUANODONTE","clue":"Herbívoro con pulgares en forma de púa, de los primeros dinosaurios nombrados","fact":"Fue uno de los primeros dinosaurios con nombre, hace unos 200 años.","tier":3},{"w":"MOSASAURIO","clue":"Gran reptil marino del Cretácico, pariente de serpientes y lagartos","fact":"Los mosasaurios no eran dinosaurios: eran reptiles marinos gigantes.","tier":3},{"w":"OVIRAPTOR","clue":"Dinosaurio con plumas cuyo nombre significa por error \"ladrón de huevos\"","fact":"Lo llamaron así por error: en realidad cuidaba sus propios huevos.","tier":3},{"w":"COPROLITO","clue":"Fósil duro como piedra de excremento de animal","fact":"Los coprolitos muestran qué comían los dinosaurios, a veces con pedacitos de hueso.","tier":3},{"w":"EXCAVACIÓN","clue":"Cavar con cuidado para sacar cosas enterradas hace mucho","fact":"Una excavación grande de dinosaurios puede tardar muchos veranos de trabajo cuidadoso.","tier":3},{"w":"CONTINENTE","clue":"Una de las enormes masas de tierra del planeta","fact":"Se han encontrado fósiles de dinosaurio en todos los continentes, hasta en la Antártida.","tier":3},{"w":"ANTÁRTIDA","clue":"Tierra helada en el extremo sur del planeta","fact":"Hubo dinosaurios allí cuando era más cálida y tenía bosques.","tier":3},{"w":"MAMÍFERO","clue":"Animal con pelo que alimenta a sus crías con leche","fact":"Los primeros mamíferos eran pequeños y vivían junto a los dinosaurios.","tier":3},{"w":"CONÍFERA","clue":"Árbol como el pino, con hojas de aguja y piñas","fact":"Los dinosaurios de cuello largo probablemente comían coníferas, parientes de los pinos de hoy.","tier":3}]}},{"id":"space","icon":"🚀","name":{"en":"Space","es":"Espacio"},"words":{"en":[{"w":"MOON","clue":"Earth's natural satellite that seems to change shape each night","fact":"The Moon drifts away from Earth about as fast as your fingernails grow.","tier":1},{"w":"STAR","clue":"A giant ball of hot gas that shines in the night sky","fact":"Stars twinkle because the air around Earth makes their light wobble.","tier":1},{"w":"SUN","clue":"The star at the center of our solar system","fact":"More than a million Earths could fit inside it.","tier":1},{"w":"MARS","clue":"The red planet","fact":"Mars has a volcano more than twice as tall as Mount Everest.","tier":1},{"w":"ORBIT","clue":"The curved path a planet takes around the Sun","fact":"The Moon takes about 27 days to go once around Earth.","tier":1},{"w":"COMET","clue":"Icy space traveler that grows a glowing tail near the Sun","fact":"A comet's tail always points away from the Sun.","tier":1},{"w":"EARTH","clue":"The only planet we know that has life","fact":"About 70 percent of its surface is covered by ocean water.","tier":1},{"w":"VENUS","clue":"Super hot planet wrapped in thick clouds","fact":"A day on Venus is longer than its year.","tier":1},{"w":"RING","clue":"Saturn wears bright ones made of ice and rock","fact":"Saturn's rings are mostly chunks of ice, from tiny grains to house-sized.","tier":1},{"w":"ROVER","clue":"Wheeled robot that explores another planet","fact":"Messages take minutes to reach one on Mars, so it does some driving on its own.","tier":1},{"w":"PROBE","clue":"Robot spacecraft sent to explore far-off worlds","fact":"Two probes named Voyager have traveled beyond the planets into interstellar space.","tier":1},{"w":"TIDE","clue":"Daily rise and fall of the sea, pulled by the Moon","fact":"The Moon's pull makes ocean water bulge, causing two high ones a day in most places.","tier":1},{"w":"PLANET","clue":"A big world that circles a star","fact":"Planet comes from a Greek word meaning \"wanderer.\"","tier":2},{"w":"GALAXY","clue":"A giant city of stars held together by gravity","fact":"Our solar system sits in the Milky Way, which has hundreds of billions of stars.","tier":2},{"w":"METEOR","clue":"A shooting star is really one: a space rock burning up","fact":"Most are no bigger than a grain of sand or a pebble.","tier":2},{"w":"ROCKET","clue":"Powerful vehicle that blasts astronauts into space","fact":"Rockets can fly where there is no air by pushing out hot gas.","tier":2},{"w":"SATURN","clue":"Planet famous for its wide, icy rings","fact":"Saturn is so light for its size that it would float in a giant bathtub.","tier":2},{"w":"JUPITER","clue":"The biggest planet, with a giant red storm","fact":"Its Great Red Spot is a storm that has been spinning for more than a century.","tier":2},{"w":"ECLIPSE","clue":"When the Moon blocks the Sun for a few minutes","fact":"During a total solar one, daytime turns to twilight for a few minutes.","tier":2},{"w":"GRAVITY","clue":"Invisible pull that keeps your feet on the ground","fact":"Astronauts float on the space station because they are in constant free-fall around Earth.","tier":2},{"w":"CAPSULE","clue":"Small spacecraft that carries astronauts and splashes down at sea","fact":"Many capsules return to Earth under huge parachutes.","tier":2},{"w":"CRATER","clue":"Bowl-shaped dent made when a space rock hits the Moon","fact":"Moon craters last for billions of years because there is no wind or rain to erase them.","tier":2},{"w":"NEBULA","clue":"Giant cloud of gas and dust where new stars are born","fact":"Some are called stellar nurseries because new stars form inside them.","tier":2},{"w":"VACUUM","clue":"A space with no air in it at all","fact":"Sound cannot travel through the vacuum of space, so it is totally silent out there.","tier":2},{"w":"HELMET","clue":"Round hard hat astronauts wear, with a shiny visor","fact":"A spacesuit visor is coated with a thin layer of gold to shield eyes from bright sunlight.","tier":2},{"w":"NEPTUNE","clue":"Far-off blue planet with super fast winds","fact":"It takes Neptune about 165 Earth years to go once around the Sun.","tier":2},{"w":"ASTRONAUT","clue":"Person trained to travel and work in space","fact":"Astronauts grow a little taller in space because their spines stretch without gravity.","tier":3},{"w":"TELESCOPE","clue":"Tool that makes faraway stars look closer","fact":"Looking through one is like looking back in time, because starlight takes years to arrive.","tier":3},{"w":"SATELLITE","clue":"A moon, or a machine, that circles a planet","fact":"Satellites orbiting Earth help with weather maps, GPS directions, and TV signals.","tier":3},{"w":"UNIVERSE","clue":"Everything that exists: all the stars, planets and space","fact":"Light from the farthest galaxies has traveled for billions of years to reach us.","tier":3},{"w":"ASTEROID","clue":"Rocky space leftover; most circle the Sun between Mars and Jupiter","fact":"Asteroids range from pebbles to rocks hundreds of miles wide.","tier":3},{"w":"SUPERNOVA","clue":"The brilliant final burst of a huge star","fact":"A supernova can briefly shine brighter than a whole galaxy.","tier":3},{"w":"ATMOSPHERE","clue":"The blanket of air around a planet","fact":"Earth's atmosphere keeps us warm and burns up most small space rocks.","tier":3},{"w":"WEIGHTLESS","clue":"How astronauts feel when they float inside the space station","fact":"Astronauts exercise about two hours a day in space to keep their muscles strong.","tier":3},{"w":"EXOPLANET","clue":"A world that circles a star other than our Sun","fact":"Scientists have found thousands of them circling other stars.","tier":3},{"w":"ASTRONOMER","clue":"Scientist who studies stars, planets and the night sky","fact":"Ancient stargazers tracked the Moon and stars to make the first calendars.","tier":3},{"w":"PLUTO","clue":"Small icy world once counted as the ninth planet","fact":"Pluto is a dwarf planet, smaller than Earth's Moon.","tier":1},{"w":"ALIEN","clue":"Make-believe creature from another planet","fact":"Scientists hunting for life on other worlds would be thrilled to find even tiny microbes.","tier":1},{"w":"NOVA","clue":"Star that suddenly flares up bright, then slowly fades","fact":"Nova is Latin for new, because long ago people thought a brand-new star had appeared.","tier":1},{"w":"SOLAR","clue":"Describes panels or energy that come from sunlight","fact":"Solar panels on the space station turn sunlight into electricity.","tier":1},{"w":"LUNAR","clue":"Having to do with the Moon, as in a landing","fact":"Lunar comes from luna, the Latin word for Moon.","tier":1},{"w":"FLARE","clue":"Bright eruption of light on the Sun's surface","fact":"A big solar flare can briefly disturb radio signals on Earth.","tier":1},{"w":"BELT","clue":"Band of space rocks between Mars and Jupiter","fact":"Spacecraft cross the asteroid belt safely because the rocks are very far apart.","tier":1},{"w":"SUIT","clue":"Puffy outfit astronauts wear to float outside","fact":"A spacewalk suit has a drinking bag inside the helmet.","tier":1},{"w":"ICE","clue":"Frozen water that makes up much of a comet","fact":"Comets are mostly ice and dust, so people call them dirty snowballs.","tier":1},{"w":"GAS","clue":"Jupiter and Saturn are mostly made of this, not rock","fact":"A spaceship could not land on Jupiter or Saturn, because they are mostly gas.","tier":1},{"w":"CORE","clue":"Hot, deep center of a planet","fact":"Earth's inner core is about as hot as the surface of the Sun.","tier":1},{"w":"AXIS","clue":"Imaginary line through the middle that Earth spins around","fact":"Earth's axis is tilted, which is why we have seasons.","tier":1},{"w":"TAIL","clue":"Glowing streak that trails behind a comet","fact":"A comet's tail always points away from the Sun.","tier":1},{"w":"LENS","clue":"Curved glass in a telescope that bends light","fact":"Many telescopes use a big curved lens or mirror to gather faint starlight.","tier":1},{"w":"TITAN","clue":"Saturn's largest moon, wrapped in thick orange haze","fact":"Titan has lakes and rivers, but they hold liquid methane, not water.","tier":1},{"w":"LIGHT","clue":"Nothing travels faster than this, and the Sun gives lots of it","fact":"Light is so fast it could circle Earth about seven times in one second.","tier":1},{"w":"LEO","clue":"Star group that looks like a lion","fact":"Leo is Latin for lion, and part of its stars looks like a backward question mark.","tier":1},{"w":"ORION","clue":"Hunter constellation with three bright stars in a row","fact":"Orion is easy to spot on winter nights in the northern sky.","tier":1},{"w":"WIND","clue":"Invisible stream of tiny particles flowing out from the Sun","fact":"The solar wind creates colorful lights, called auroras, near Earth's poles.","tier":1},{"w":"HOLE","clue":"Black ___: a place where gravity is so strong light cannot escape","fact":"Some black holes form when a giant star runs out of fuel and collapses.","tier":1},{"w":"FUEL","clue":"Rockets burn lots of this to push off the ground","fact":"Some rockets burn super-cold liquid hydrogen as fuel.","tier":1},{"w":"PAD","clue":"Flat spot where a rocket stands before blast-off","fact":"A launch pad has a water system that soaks up the loud noise.","tier":1},{"w":"DAY","clue":"Time Earth takes to spin around one time","fact":"A day on Venus is longer than a year on Venus.","tier":1},{"w":"YEAR","clue":"Time Earth takes to travel once around the Sun","fact":"A year on Mercury lasts only 88 Earth days.","tier":1},{"w":"DUST","clue":"Fine powder that covered the astronauts' boots on the Moon","fact":"Moon dust is sharp and sticky, and it clung to the astronauts' suits.","tier":1},{"w":"CREW","clue":"Team of people working together on a spaceship","fact":"Crew members on the space station see about sixteen sunrises every day.","tier":1},{"w":"STORM","clue":"Jupiter's Great Red Spot is a giant swirling one","fact":"Jupiter's Great Red Spot has swirled for well over a hundred years.","tier":1},{"w":"DWARF","clue":"Small kind of planet that Pluto is","fact":"Pluto and Ceres are both dwarf planets, small and round.","tier":1},{"w":"EUROPA","clue":"Icy moon of Jupiter with an ocean hidden underneath","fact":"Europa's hidden ocean may hold more water than all of Earth's oceans together.","tier":2},{"w":"MERCURY","clue":"Smallest planet, closest to the Sun","fact":"Mercury is a planet, yet it is smaller than two moons in our solar system.","tier":2},{"w":"SUNSPOT","clue":"Dark, cooler patch on the Sun's surface","fact":"Sunspots look dark only because they are cooler than the glowing area around them.","tier":2},{"w":"SHUTTLE","clue":"Winged spacecraft that glided home and landed on a runway","fact":"Space shuttles launched like rockets but landed like airplanes.","tier":2},{"w":"LIFTOFF","clue":"Moment a rocket leaves the ground","fact":"At liftoff a big rocket burns through tons of fuel every second.","tier":2},{"w":"APOLLO","clue":"Name of the program that first landed people on the Moon","fact":"Some Apollo astronauts drove a small car on the Moon.","tier":2},{"w":"PULSAR","clue":"Tiny spinning star that flashes beams like a lighthouse","fact":"Some pulsars spin hundreds of times every second.","tier":2},{"w":"STATION","clue":"Place where astronauts live and work while circling Earth","fact":"The space station goes all the way around Earth about every ninety minutes.","tier":2},{"w":"VOYAGER","clue":"Name of two probes launched in 1977 carrying golden records","fact":"Voyager's golden records hold sounds and pictures from Earth, in case someone finds them.","tier":2},{"w":"ANTENNA","clue":"Rod or dish that sends and catches radio signals","fact":"Far-off probes use big dish antennas to send messages home to Earth.","tier":2},{"w":"DEBRIS","clue":"Broken bits of old rockets floating around Earth","fact":"Space debris moves so fast that a tiny flake can chip a window.","tier":2},{"w":"HELIUM","clue":"Light gas that makes party balloons float","fact":"Helium was discovered in sunlight before anyone found it on Earth.","tier":2},{"w":"PLASMA","clue":"Super-hot glowing state of matter, not solid, liquid or gas","fact":"Plasma is the fourth state of matter, and the Sun is made of it.","tier":2},{"w":"HORIZON","clue":"Faraway line where sky seems to meet the ground","fact":"The Moon's horizon looks closer than Earth's because the Moon is smaller.","tier":2},{"w":"LANDER","clue":"Spacecraft built to touch down gently on another world","fact":"Many landers fire rockets pointing down to slow their fall and touch down softly.","tier":2},{"w":"BOOSTER","clue":"Extra rocket attached to give a big push at liftoff","fact":"Some rocket boosters fly back down and land, ready to be used again.","tier":2},{"w":"NOZZLE","clue":"Cone at a rocket's bottom where hot gas blasts out","fact":"A rocket nozzle shapes the hot gas into a fast stream that pushes the rocket up.","tier":2},{"w":"THRUST","clue":"Forward push that makes a rocket move","fact":"A rocket moves up by blasting hot gas down.","tier":2},{"w":"AIRLOCK","clue":"Small room where astronauts wait before stepping outside","fact":"An airlock lets astronauts go outside without letting the station's air escape.","tier":2},{"w":"POLARIS","clue":"Star that sits almost straight above Earth's north pole","fact":"People have used Polaris, the North Star, to find north for hundreds of years.","tier":2},{"w":"SIRIUS","clue":"Brightest star in the night sky, called the Dog Star","fact":"Sirius is really two stars circling each other.","tier":2},{"w":"HALLEY","clue":"Famous comet that returns about every 76 years","fact":"Halley's Comet is next due to pass Earth in the year 2061.","tier":2},{"w":"OXYGEN","clue":"Gas we breathe that astronauts must carry into space","fact":"Astronauts on the space station make oxygen by splitting water apart.","tier":2},{"w":"VOLCANO","clue":"Mountain that erupts with lava and ash","fact":"Olympus Mons on Mars is a volcano more than twice as tall as Mount Everest.","tier":2},{"w":"CANYON","clue":"Deep valley with steep rocky walls, like one on Mars","fact":"Mars has a canyon so long it would stretch across much of the United States.","tier":2},{"w":"ELLIPSE","clue":"Stretched-out circle, the shape of most orbits","fact":"Planets travel around the Sun in slightly squashed ovals, not perfect circles.","tier":2},{"w":"ENGINE","clue":"Machine that burns fuel to make a rocket go","fact":"Rocket engines carry their own oxygen, because space has no air to breathe.","tier":2},{"w":"AURORA","clue":"Green and pink lights dancing in the sky near the poles","fact":"Auroras happen when particles from the Sun crash into gases in Earth's air.","tier":2},{"w":"TWINKLE","clue":"What the little star does in the nursery song","fact":"Stars twinkle because moving air bends their light, but planets twinkle much less.","tier":2},{"w":"SEASON","clue":"Spring, summer, fall or winter, for example","fact":"Earth has seasons because it is tilted as it travels around the Sun.","tier":2},{"w":"PAYLOAD","clue":"Cargo a rocket carries into space, such as a satellite","fact":"A rocket's payload can be a satellite, a rover, or even astronauts.","tier":2},{"w":"SUNDIAL","clue":"Old-fashioned clock that uses a stick's shadow and sunshine","fact":"People told time with sundials thousands of years before mechanical clocks were invented.","tier":2},{"w":"CRESCENT","clue":"Thin, curved Moon shape like a banana","fact":"A crescent Moon looks thin because we only see a sliver of its sunlit side.","tier":3},{"w":"MOONWALK","clue":"Bouncy stroll by an astronaut on the lunar ground","fact":"Footprints on the Moon will last a very long time, since there is no wind or rain.","tier":3},{"w":"COUNTDOWN","clue":"Numbers said backward just before a rocket blasts off","fact":"Rocket countdowns often pause so teams can check that everything is working.","tier":3},{"w":"SPACEWALK","clue":"Trip outside a spacecraft, floating in a suit","fact":"Astronauts on a spacewalk clip themselves on with tethers so they cannot drift away.","tier":3},{"w":"SPACECRAFT","clue":"Any vehicle built to travel beyond Earth's sky","fact":"Once moving, a spacecraft can coast for years because there is no air to slow it.","tier":3},{"w":"HYDROGEN","clue":"Lightest gas, and the main stuff stars are made of","fact":"Stars shine by squeezing hydrogen atoms together into helium.","tier":3},{"w":"MOONQUAKE","clue":"Shaking of lunar ground, like an earthquake","fact":"Moonquakes can rumble for many minutes, much longer than most earthquakes.","tier":3},{"w":"PARACHUTE","clue":"Big fabric canopy that slows a falling capsule","fact":"Mars landers open giant parachutes to slow down as they fall through thin air.","tier":3},{"w":"SPLASHDOWN","clue":"When a returning capsule lands in the ocean","fact":"Apollo capsules splashed down in the ocean, where ships waited to pick up the crew.","tier":3},{"w":"METEORITE","clue":"Space rock that has landed on the ground","fact":"Many meteorites are about 4.5 billion years old, as old as the planets.","tier":3},{"w":"EXPLORER","clue":"Traveler who visits new places to learn about them","fact":"Many space explorers are robots that never get tired or hungry.","tier":3},{"w":"SUNLIGHT","clue":"Light and warmth streaming down from our nearest star","fact":"Sunlight takes about eight minutes to travel from the Sun to Earth.","tier":3},{"w":"STARGAZER","clue":"Person who lies back and watches the night sky for fun","fact":"Stargazing is best on dark nights far away from bright city lights.","tier":3},{"w":"BINOCULARS","clue":"Two small tubes joined together that make faraway things look close","fact":"Even simple binoculars can show four of Jupiter's moons.","tier":3},{"w":"ASTRONOMY","clue":"The science of studying planets, galaxies and everything beyond Earth","fact":"People have studied the night sky for thousands of years, so astronomy is very old.","tier":3},{"w":"TOUCHDOWN","clue":"The moment a spacecraft lands on another world's surface","fact":"Landing on Mars is hard because its thin air gives little help slowing down.","tier":3},{"w":"OBSERVATORY","clue":"Building with a big telescope for studying the sky","fact":"Many observatories sit on tall mountains where the air is thin and clear.","tier":3},{"w":"PLANETARIUM","clue":"Dome theater that shows the night sky on its ceiling","fact":"A planetarium projector can show thousands of stars at one time.","tier":3},{"w":"TRAJECTORY","clue":"Curved path that a rocket or ball travels along","fact":"Spacecraft going to Mars aim at where the planet will be, not where it is now.","tier":3},{"w":"ACCELERATE","clue":"Go faster and faster, as a rocket does after liftoff","fact":"To orbit Earth, a rocket must speed up to about 28,000 kilometers per hour.","tier":3},{"w":"PROPELLANT","clue":"Mix of fuel and oxygen burned to power a rocket","fact":"Most of a rocket's weight at liftoff is propellant, not the rocket itself.","tier":3},{"w":"DIAMETER","clue":"Distance straight across a circle through its middle","fact":"Jupiter's diameter is about eleven times Earth's.","tier":3},{"w":"WORMHOLE","clue":"Made-up tunnel that shortcuts across space in science fiction","fact":"Nobody has ever found a wormhole; for now they are only an idea.","tier":3},{"w":"STARDUST","clue":"Tiny glittering grains left behind by exploded suns","fact":"Much of what your body is made of was first made inside stars.","tier":3}],"es":[{"w":"LUNA","clue":"Satélite natural de la Tierra que cambia de forma en el cielo","fact":"La Luna se aleja de la Tierra más o menos al ritmo en que te crecen las uñas.","tier":1},{"w":"SOL","clue":"La estrella en el centro de nuestro sistema de planetas","fact":"En el Sol cabrían más de un millón de Tierras.","tier":1},{"w":"MARTE","clue":"El planeta rojo","fact":"Marte tiene un volcán más de dos veces más alto que el monte Everest.","tier":1},{"w":"VENUS","clue":"El planeta más caliente, cubierto de nubes espesas","fact":"En Venus un día dura más que un año.","tier":1},{"w":"SONDA","clue":"Nave robot sin personas que viaja a explorar mundos lejanos","fact":"Las sondas Voyager ya salieron más allá de los planetas, hacia el espacio entre las estrellas.","tier":1},{"w":"ROVER","clue":"Robot con ruedas que explora otro planeta","fact":"Los mensajes de la Tierra tardan minutos en llegar a uno en Marte.","tier":1},{"w":"MAREA","clue":"Subida y bajada del agua del mar que provoca la Luna","fact":"La Luna atrae el mar y causa dos mareas altas al día en casi todo el mundo.","tier":1},{"w":"NAVE","clue":"Vehículo que viaja por el espacio","fact":"Para salir de la Tierra, una nave debe volar a unos 40 000 kilómetros por hora.","tier":1},{"w":"CIELO","clue":"Lo que ves arriba de ti, lleno de estrellas de noche","fact":"El cielo se ve azul de día porque el aire dispersa la luz azul del Sol.","tier":1},{"w":"LUZ","clue":"Lo que brilla en las estrellas y viaja rapidísimo","fact":"La luz del Sol tarda unos ocho minutos en llegar a la Tierra.","tier":1},{"w":"ASTRO","clue":"Cuerpo del cielo, como una estrella, un planeta o la Luna","fact":"La Luna es un astro que no brilla solo: refleja la luz del Sol.","tier":1},{"w":"FASE","clue":"Cada forma distinta que la Luna muestra en el cielo","fact":"La Luna tarda unos 29 días en pasar por todas sus fases.","tier":1},{"w":"PLANETA","clue":"Mundo grande que gira alrededor de una estrella","fact":"La palabra viene del griego y significa \"errante\", porque parecen vagar por el cielo.","tier":2},{"w":"GALAXIA","clue":"Enorme ciudad de estrellas unidas por la fuerza que las atrae","fact":"Nuestro sistema solar está en la Vía Láctea, que tiene cientos de miles de millones de estrellas.","tier":2},{"w":"METEORO","clue":"Lo que vemos como una estrella fugaz","fact":"La mayoría son rocas no más grandes que un grano de arena.","tier":2},{"w":"COHETE","clue":"Vehículo potente que lanza astronautas al espacio","fact":"Un cohete puede volar donde no hay aire porque expulsa gases calientes.","tier":2},{"w":"SATURNO","clue":"Planeta famoso por sus anillos de hielo","fact":"Saturno es tan liviano para su tamaño que flotaría en una bañera gigante de agua.","tier":2},{"w":"JÚPITER","clue":"El planeta más grande, con una enorme tormenta roja","fact":"Su Gran Mancha Roja es una tormenta que dura desde hace más de un siglo.","tier":2},{"w":"ECLIPSE","clue":"Cuando la Luna tapa al Sol por unos minutos","fact":"En uno total de Sol, el día se vuelve penumbra durante unos minutos.","tier":2},{"w":"TIERRA","clue":"Nuestro planeta, el único conocido con vida","fact":"Cerca del 70 por ciento de su superficie está cubierta de océanos.","tier":2},{"w":"ÓRBITA","clue":"Camino curvo que sigue un planeta alrededor del Sol","fact":"La Luna tarda unos 27 días en dar una vuelta alrededor de la Tierra.","tier":2},{"w":"CÁPSULA","clue":"Pequeña nave que lleva astronautas y vuelve con paracaídas","fact":"Muchas regresan a la Tierra con enormes paracaídas y caen al mar.","tier":2},{"w":"CRÁTER","clue":"Hoyo redondo de la Luna hecho por el golpe de una roca","fact":"Los de la Luna duran miles de millones de años porque no hay viento ni lluvia.","tier":2},{"w":"COMETA","clue":"Viajero de hielo que estrena una cola brillante cerca del Sol","fact":"La cola de un cometa siempre apunta lejos del Sol.","tier":2},{"w":"NEPTUNO","clue":"Planeta azul y lejano con vientos fortísimos","fact":"Neptuno tarda unos 165 años terrestres en dar una vuelta al Sol.","tier":2},{"w":"ESPACIO","clue":"Lugar enorme y vacío más allá del cielo de la Tierra","fact":"En el espacio no se oye nada porque el sonido no viaja sin aire.","tier":2},{"w":"ASTRONAUTA","clue":"Persona entrenada para viajar y trabajar en el espacio","fact":"Los astronautas crecen unos centímetros en el espacio porque su columna se estira.","tier":3},{"w":"TELESCOPIO","clue":"Instrumento que acerca las estrellas lejanas a tus ojos","fact":"Mirar con uno es mirar al pasado, porque la luz de las estrellas tarda años en llegar.","tier":3},{"w":"SATÉLITE","clue":"Una luna, o una máquina, que da vueltas alrededor de un planeta","fact":"Los satélites ayudan con el clima, los mapas y las señales de televisión.","tier":3},{"w":"UNIVERSO","clue":"Todo lo que existe: estrellas, planetas y espacio","fact":"La luz de las galaxias más lejanas viaja miles de millones de años para llegar a nosotros.","tier":3},{"w":"ASTEROIDE","clue":"Roca espacial sobrante; muchos giran entre Marte y Júpiter","fact":"Los hay desde guijarros hasta rocas de cientos de kilómetros de ancho.","tier":3},{"w":"ATMÓSFERA","clue":"Capa de aire que envuelve un planeta","fact":"La de la Tierra nos da calor y quema la mayoría de los meteoros pequeños.","tier":3},{"w":"GRAVEDAD","clue":"Fuerza invisible que mantiene tus pies en el suelo","fact":"Los astronautas flotan porque caen alrededor de la Tierra sin parar, no porque falte esta fuerza.","tier":3},{"w":"NEBULOSA","clue":"Nube enorme de gas y polvo donde nacen estrellas","fact":"Algunas son como guarderías donde se forman estrellas nuevas.","tier":3},{"w":"ESTRELLA","clue":"Bola gigante de gas caliente que brilla de noche","fact":"Las estrellas titilan porque el aire de la Tierra hace temblar su luz.","tier":3},{"w":"EXOPLANETA","clue":"Mundo que gira alrededor de otra estrella, no del Sol","fact":"Los científicos han descubierto miles de ellos alrededor de otras estrellas.","tier":3},{"w":"DÍA","clue":"Tiempo que tarda la Tierra en girar una vez sobre sí misma","fact":"En Venus, un día dura más que un año.","tier":1},{"w":"HIELO","clue":"Agua congelada que forma gran parte de un cometa","fact":"Los cometas son hielo y polvo, por eso los llaman bolas de nieve sucias.","tier":1},{"w":"GAS","clue":"Lo que forma casi todo Júpiter, en vez de tierra firme","fact":"Como Júpiter y Saturno son casi puro gas, una nave no podría posarse sobre ellos.","tier":1},{"w":"POLVO","clue":"Partículas finísimas que cubrían las botas de los astronautas en la Luna","fact":"El polvo de la Luna es afilado y pegajoso, y se pegó a los trajes.","tier":1},{"w":"COLA","clue":"Estela brillante que deja atrás un cometa","fact":"La cola de un cometa siempre apunta lejos del Sol.","tier":1},{"w":"EJE","clue":"Línea imaginaria alrededor de la cual gira la Tierra","fact":"El eje de la Tierra está inclinado, y por eso existen las estaciones del año.","tier":1},{"w":"LENTE","clue":"Cristal curvo que dobla la luz dentro de un telescopio","fact":"Muchos telescopios usan una lente o un espejo grande para juntar la luz débil.","tier":1},{"w":"TITÁN","clue":"La luna más grande de Saturno, envuelta en bruma naranja","fact":"En Titán hay lagos y ríos, pero son de metano líquido, no de agua.","tier":1},{"w":"ORIÓN","clue":"Constelación del cazador con tres estrellas brillantes en fila","fact":"Orión es fácil de encontrar porque las tres estrellas de su cinturón están en fila.","tier":1},{"w":"TRAJE","clue":"Ropa gruesa e inflada que protege al astronauta afuera de la nave","fact":"Algunos trajes espaciales llevan una bolsa para beber dentro del casco.","tier":1},{"w":"NOVA","clue":"Estrella que de pronto brilla mucho y luego se apaga","fact":"Nova significa nueva en latín, porque antes creían que había nacido una estrella.","tier":1},{"w":"AIRE","clue":"Mezcla invisible que respiramos y que no hay en el espacio","fact":"Los astronautas llevan su propio aire en el traje para poder respirar.","tier":1},{"w":"ROCA","clue":"Material duro del que están hechos Mercurio, Venus, la Tierra y Marte","fact":"Mercurio, Venus, la Tierra y Marte tienen suelo duro, no como Júpiter.","tier":1},{"w":"LAVA","clue":"Piedra derretida y caliente que sale de un volcán","fact":"Hace mucho tiempo, volcanes de Marte y de la Luna lanzaron lava.","tier":1},{"w":"NOCHE","clue":"Cuando el cielo se oscurece y salen las estrellas","fact":"En la Luna, una noche dura casi dos semanas de las nuestras.","tier":1},{"w":"CASCO","clue":"Pieza redonda que protege la cabeza del astronauta","fact":"El visor dorado del casco protege los ojos del astronauta de la luz del Sol.","tier":1},{"w":"PESO","clue":"Fuerza con que la gravedad te atrae hacia el suelo","fact":"En la Luna pesarías unas seis veces menos que en la Tierra.","tier":1},{"w":"SALTO","clue":"Impulso con las piernas para subir en el aire","fact":"En la Luna, un salto te llevaría mucho más alto que en la Tierra.","tier":1},{"w":"HELIO","clue":"Gas ligero que hace flotar los globos de fiesta","fact":"Se descubrió helio en la luz del Sol antes de hallarlo en la Tierra.","tier":1},{"w":"RADAR","clue":"Aparato que usa ondas de radio para ver objetos lejanos","fact":"El radar envía ondas de radio que rebotan en los objetos y regresan.","tier":1},{"w":"URANO","clue":"Séptimo planeta desde el Sol, que gira acostado","fact":"Urano gira de lado, como una pelota que rueda.","tier":1},{"w":"ENANO","clue":"Tipo de planeta pequeño, como Plutón","fact":"Plutón y Ceres son dos planetas enanos, pequeños y redondos.","tier":1},{"w":"MOTOR","clue":"Máquina que quema combustible para empujar un cohete","fact":"Los motores de cohete llevan su propio oxígeno, porque en el espacio no hay aire.","tier":1},{"w":"AGUA","clue":"Líquido que bebemos y que hace mucho corría sobre Marte","fact":"Se ha encontrado hielo de agua en la Luna y en Marte.","tier":1},{"w":"CARGA","clue":"Satélites o provisiones que lleva un cohete","fact":"Casi todo el peso de un cohete es combustible, y la carga es solo una parte.","tier":1},{"w":"CALOR","clue":"Lo que da el Sol y nos hace sudar","fact":"Venus es el planeta más caliente, aunque Mercurio está más cerca del Sol.","tier":1},{"w":"FRÍO","clue":"Lo que sientes con la nieve o con el hielo","fact":"La noche en la Luna es tan fría que baja de cien grados bajo cero.","tier":1},{"w":"NUBE","clue":"Algodón flotante del cielo; en el espacio, de gas y polvo","fact":"Las estrellas nacen dentro de enormes nubes de gas y polvo.","tier":1},{"w":"PLUTÓN","clue":"Pequeño mundo helado que antes era el noveno planeta","fact":"Plutón es más chico que nuestra Luna.","tier":2},{"w":"ANILLO","clue":"Aro de hielo y roca que rodea a Saturno","fact":"Los anillos de Saturno son enormes de ancho, pero casi planos y delgados.","tier":2},{"w":"OXÍGENO","clue":"Gas que respiramos y que los astronautas llevan al espacio","fact":"En la estación espacial se fabrica oxígeno separando el agua en partes.","tier":2},{"w":"ANTENA","clue":"Varilla o plato que envía y recibe señales de radio","fact":"Las sondas lejanas usan antenas grandes para mandar mensajes a la Tierra.","tier":2},{"w":"NÚCLEO","clue":"Centro muy caliente de un planeta","fact":"El núcleo de la Tierra está casi tan caliente como la superficie del Sol.","tier":2},{"w":"VIENTO","clue":"El ___ solar: corriente de partículas que sale del Sol","fact":"El viento solar ayuda a formar las luces de colores llamadas auroras.","tier":2},{"w":"AGUJERO","clue":"Negro ___: lugar donde ni la luz puede escapar","fact":"Algunos agujeros negros nacen cuando una estrella gigante se queda sin combustible.","tier":2},{"w":"FLOTAR","clue":"Quedarse en el aire sin caer, como los astronautas","fact":"Los astronautas duermen en bolsas atadas a la pared para no flotar por todos lados.","tier":2},{"w":"AURORA","clue":"Luces verdes y rosadas que bailan cerca de los polos","fact":"Las auroras ocurren cuando partículas del Sol chocan con los gases del aire.","tier":2},{"w":"ESPEJO","clue":"Superficie lisa y brillante que refleja la luz","fact":"Algunos telescopios grandes usan espejos gigantes para captar la luz de estrellas lejanas.","tier":2},{"w":"EUROPA","clue":"Luna helada de Júpiter con un océano escondido debajo","fact":"Se cree que el océano oculto de Europa tiene más agua que todos los mares de la Tierra.","tier":2},{"w":"VOLCÁN","clue":"Montaña que echa lava y ceniza","fact":"El monte Olimpo de Marte es un volcán más del doble de alto que el Everest.","tier":2},{"w":"POLARIS","clue":"Estrella casi fija sobre el polo norte, que guiaba a los marineros","fact":"Durante siglos los marineros usaron la Estrella Polar para encontrar el norte.","tier":2},{"w":"PULSAR","clue":"Estrella diminuta que gira y lanza destellos como un faro","fact":"Algunos púlsares giran cientos de veces cada segundo.","tier":2},{"w":"CUENTA","clue":"Números al revés antes del despegue: ___ regresiva","fact":"La cuenta regresiva termina en cero, justo cuando el cohete despega.","tier":2},{"w":"GIGANTE","clue":"Planeta enorme y gaseoso como Júpiter","fact":"En Júpiter cabrían más de mil Tierras.","tier":2},{"w":"HUELLA","clue":"Marca que deja un pie sobre el polvo de la Luna","fact":"Las huellas de la Luna durarán muchísimo tiempo, porque allí no hay viento.","tier":2},{"w":"TITILAR","clue":"Brillar y apagarse muy rápido, como las estrellas","fact":"Las estrellas titilan porque el aire en movimiento dobla su luz.","tier":2},{"w":"SOMBRA","clue":"Zona oscura que deja un objeto cuando tapa la luz","fact":"En un eclipse de Sol, la sombra de la Luna cae sobre la Tierra.","tier":2},{"w":"BRILLAR","clue":"Echar luz propia, como hacen el Sol y las estrellas","fact":"El Sol brilla desde hace unos cuatro mil quinientos millones de años.","tier":2},{"w":"ORBITAR","clue":"Dar vueltas alrededor de un planeta, como la Luna","fact":"La Luna tarda algo menos de un mes en dar una vuelta a la Tierra.","tier":2},{"w":"HALLEY","clue":"Famoso cometa que regresa cada 76 años","fact":"El cometa Halley volverá a pasar cerca de la Tierra en el año 2061.","tier":2},{"w":"ESCUDO","clue":"Placa protectora de una cápsula contra el calor","fact":"El escudo térmico protege a los astronautas del calor al volver a la Tierra.","tier":2},{"w":"ESPIRAL","clue":"Forma que gira y gira alrededor de un centro","fact":"Nuestra galaxia, la Vía Láctea, tiene forma de espiral.","tier":2},{"w":"CABINA","clue":"Cuarto diminuto donde duerme un astronauta","fact":"Cada astronauta de la estación espacial tiene su propia cabina para dormir.","tier":2},{"w":"CÁMARA","clue":"Aparato que toma fotos; los rovers de Marte llevan varias","fact":"Los rovers de Marte tienen muchas cámaras, como ojos de robot.","tier":2},{"w":"RUEDAS","clue":"Piezas redondas que permiten al rover rodar sobre Marte","fact":"Las ruedas de algunos rovers de Marte son de metal, no de goma.","tier":2},{"w":"MANCHA","clue":"Zona oscura y más fría en la superficie del Sol","fact":"Las manchas solares se ven oscuras solo porque están más frías.","tier":2},{"w":"ESFERA","clue":"Cuerpo redondo como una pelota, la forma de los planetas","fact":"La Tierra casi es una esfera, pero es un poco más ancha en el medio.","tier":2},{"w":"SÓLIDO","clue":"Estado de una roca, que no es líquido ni gas","fact":"Mercurio, Venus, la Tierra y Marte tienen un suelo sólido para pisar.","tier":2},{"w":"FUERZA","clue":"Empuje o jalón que mueve las cosas; la gravedad es una","fact":"La gravedad es la fuerza que mantiene a la Luna girando alrededor de la Tierra.","tier":2},{"w":"GÉISER","clue":"Chorro de agua o vapor que sale disparado del suelo","fact":"La luna Encélado, de Saturno, lanza chorros de hielo y vapor al espacio.","tier":2},{"w":"MERCURIO","clue":"El planeta más pequeño y más cercano al Sol","fact":"Mercurio es un planeta, pero hay dos lunas más grandes que él.","tier":3},{"w":"CHATARRA","clue":"Pedazos rotos de cohetes viejos que giran alrededor de la Tierra","fact":"Un trocito diminuto de chatarra espacial puede marcar una ventana, porque va rapidísimo.","tier":3},{"w":"ESTACIÓN","clue":"Laboratorio que da vueltas a la Tierra donde viven astronautas","fact":"La estación espacial da una vuelta a la Tierra cada noventa minutos, más o menos.","tier":3},{"w":"HORIZONTE","clue":"Línea lejana donde el cielo parece tocar el suelo","fact":"El horizonte de la Luna se ve más cerca que el de la Tierra porque es más pequeña.","tier":3},{"w":"ALUNIZAJE","clue":"Llegada suave de una nave al suelo de nuestro satélite natural","fact":"Los astronautas de Apolo 11 alunizaron en un lugar llamado Mar de la Tranquilidad.","tier":3},{"w":"COMBUSTIBLE","clue":"Lo que quema un cohete para poder despegar","fact":"Algunos cohetes usan hidrógeno líquido, que está a muchos grados bajo cero.","tier":3},{"w":"PARACAÍDAS","clue":"Gran tela que frena una cápsula cuando cae","fact":"Las naves que llegan a Marte abren paracaídas gigantes para frenar en su aire delgado.","tier":3},{"w":"AMERIZAJE","clue":"Caída suave de una cápsula espacial sobre el mar","fact":"Las cápsulas Apolo caían al mar y los barcos rescataban a los astronautas.","tier":3},{"w":"DESPEGUE","clue":"Momento en que un cohete deja el suelo","fact":"Al despegar, un cohete grande quema toneladas de combustible cada segundo.","tier":3},{"w":"BINÓCULOS","clue":"Dos tubos unidos que hacen ver cerca lo lejano","fact":"Con unos binoculares sencillos puedes ver cuatro lunas de Júpiter.","tier":3},{"w":"PLANETARIO","clue":"Sala con domo donde se proyecta el cielo nocturno en el techo","fact":"Un proyector de planetario puede mostrar miles de estrellas al mismo tiempo.","tier":3},{"w":"ASTRONOMÍA","clue":"Ciencia que estudia los cuerpos del cielo y sus movimientos","fact":"La gente observa el cielo desde hace miles de años, así que esta ciencia es antiquísima.","tier":3},{"w":"DIÁMETRO","clue":"Distancia de un lado a otro de un círculo por su centro","fact":"El diámetro de Júpiter es unas once veces el de la Tierra.","tier":3},{"w":"TRAYECTORIA","clue":"Camino curvo que sigue un cohete o una pelota","fact":"Las naves que van a Marte apuntan a donde estará el planeta, no a donde está.","tier":3},{"w":"ACELERAR","clue":"Ir cada vez más rápido, como un cohete que sube","fact":"Para orbitar la Tierra, un cohete debe llegar a unos 28.000 kilómetros por hora.","tier":3},{"w":"HIDRÓGENO","clue":"El gas más ligero y el que más abunda en las estrellas","fact":"Las estrellas brillan al juntar átomos de hidrógeno para formar helio.","tier":3},{"w":"METEORITO","clue":"Roca del espacio que ya cayó al suelo","fact":"Muchos meteoritos tienen unos cuatro mil quinientos millones de años, como los planetas.","tier":3},{"w":"EXPLORADOR","clue":"Viajero que visita lugares nuevos para aprender de ellos","fact":"Muchos exploradores del espacio son robots que nunca se cansan ni tienen hambre.","tier":3},{"w":"CINTURÓN","clue":"Franja de rocas que giran entre Marte y Júpiter","fact":"Las naves cruzan el cinturón de asteroides sin peligro porque las rocas están muy lejos unas de otras.","tier":3},{"w":"TRIPULACIÓN","clue":"Equipo de personas que trabaja a bordo de una nave","fact":"La tripulación de la estación espacial hace ejercicio unas dos horas al día.","tier":3},{"w":"TORMENTA","clue":"Remolino enorme de viento y nubes, como la Gran Mancha Roja","fact":"La Gran Mancha Roja de Júpiter es una tormenta que gira desde hace más de cien años.","tier":3},{"w":"SILENCIO","clue":"Falta total de ruido, como en el espacio","fact":"En el espacio no se oye ningún sonido, porque no hay aire que lo lleve.","tier":3},{"w":"LLAMARADA","clue":"Estallido brillante de luz en la superficie del Sol","fact":"Una llamarada solar puede molestar por un rato las señales de radio en la Tierra.","tier":3},{"w":"ALIENÍGENA","clue":"Criatura imaginaria que viene de otro mundo","fact":"Los científicos se alegrarían de hallar hasta microbios diminutos en otros mundos.","tier":3}]}},{"id":"ocean","icon":"🌊","name":{"en":"Ocean","es":"Océano"},"words":{"en":[{"w":"CRAB","clue":"Sideways-walking shellfish with two pinching claws","fact":"Crabs walk sideways because of the way their leg joints bend.","tier":1},{"w":"REEF","clue":"Rocky or coral ridge just under the sea's surface","fact":"Reefs cover under one percent of the seafloor yet shelter about a quarter of sea life.","tier":1},{"w":"KELP","clue":"Giant brown seaweed that grows in underwater forests","fact":"Giant kelp can grow up to two feet in a single day.","tier":1},{"w":"EEL","clue":"Long, slippery, snake-shaped fish","fact":"An electric eel is not a true eel; it is a kind of knifefish.","tier":1},{"w":"SQUID","clue":"Ten-armed sea animal that can spray dark ink","fact":"A giant squid has eyes as big as dinner plates.","tier":1},{"w":"CORAL","clue":"Tiny animals build reefs out of this stony stuff","fact":"Coral looks like rock or plants, but it is made of tiny animals called polyps.","tier":1},{"w":"CLAM","clue":"Two-shelled sea animal that buries itself in sand","fact":"Some ocean clams live for hundreds of years.","tier":1},{"w":"SEAL","clue":"Whiskered sea mammal that barks and slides on ice","fact":"Some seals can stay underwater for over an hour without breathing.","tier":1},{"w":"WAVE","clue":"Rolling ridge of water that surfers ride","fact":"Most ocean waves are made by wind blowing across the water.","tier":1},{"w":"SHELL","clue":"Hard outer home of a snail or clam","fact":"Animals build seashells from minerals that are dissolved in seawater.","tier":1},{"w":"OTTER","clue":"Furry swimmer that floats on its back and cracks shells with rocks","fact":"Sea otters sometimes hold paws while resting so they do not drift apart.","tier":1},{"w":"TUNA","clue":"Big, fast fish often packed in cans","fact":"Some tuna keep their bodies warmer than the water around them.","tier":1},{"w":"DOLPHIN","clue":"Smart, playful sea mammal that clicks and whistles","fact":"Dolphins sleep with half their brain awake so they can keep breathing.","tier":2},{"w":"OCTOPUS","clue":"Soft sea animal with eight arms that squeezes through tiny gaps","fact":"An octopus has three hearts and blue blood.","tier":2},{"w":"TURTLE","clue":"Reptile with a shell that lays eggs on beaches","fact":"Many sea turtles return to the beach where they hatched to lay their own eggs.","tier":2},{"w":"LOBSTER","clue":"Clawed sea animal that turns red when cooked","fact":"A lobster's teeth are inside its stomach, not in its mouth.","tier":2},{"w":"URCHIN","clue":"Spiny round sea animal that looks like a pincushion","fact":"Sea urchins move around on hundreds of tiny tube feet.","tier":2},{"w":"SHRIMP","clue":"Small bendy-bodied sea creature with long feelers","fact":"One kind of snapping shrimp snaps its claw so fast it makes a loud popping bubble.","tier":2},{"w":"MANATEE","clue":"Gentle gray \"sea cow\" that nibbles underwater plants","fact":"Manatees are distant relatives of elephants.","tier":2},{"w":"WALRUS","clue":"Giant Arctic sea mammal with two long ivory tusks","fact":"Walruses use their tusks to help haul their heavy bodies onto the ice.","tier":2},{"w":"NARWHAL","clue":"Arctic whale with one long spiral tusk","fact":"A narwhal's tusk is really a long tooth that grows through its lip.","tier":2},{"w":"TRENCH","clue":"Deepest, narrowest valley on the ocean floor","fact":"Some ocean trenches are deeper than Mount Everest is tall.","tier":2},{"w":"CURRENT","clue":"Stream of water flowing through the sea like a river","fact":"The Gulf Stream is a warm ocean current that helps keep parts of Europe mild.","tier":2},{"w":"HARBOR","clue":"Sheltered bay where ships safely dock","fact":"Many harbors are in coves, where land shields boats from big waves.","tier":2},{"w":"SALMON","clue":"Pink-fleshed fish that swims up rivers to lay eggs","fact":"Salmon find the stream where they were born by using their sense of smell.","tier":2},{"w":"ISLAND","clue":"Land with water all around it","fact":"Some islands are the tops of volcanoes rising from the sea floor.","tier":2},{"w":"SEAHORSE","clue":"Tiny fish with a horse-shaped head and curled tail","fact":"A male seahorse carries the babies in a pouch and gives birth to them.","tier":3},{"w":"STARFISH","clue":"Sea animal that is usually five-armed and can regrow lost arms","fact":"Starfish are not really fish, so scientists call them sea stars.","tier":3},{"w":"JELLYFISH","clue":"Wobbly, see-through drifter with stinging tentacles","fact":"Jellyfish have no brain, no heart and no bones.","tier":3},{"w":"BARNACLE","clue":"Tiny animal that glues itself to rocks and boat bottoms","fact":"Barnacles are crustaceans, so they are related to crabs and shrimp.","tier":3},{"w":"PORPOISE","clue":"Small, shy cousin of the dolphin with a blunt face","fact":"Porpoises have flat, spade-shaped teeth, while dolphins have cone-shaped ones.","tier":3},{"w":"STINGRAY","clue":"Flat, wing-shaped fish that glides along the sandy sea floor","fact":"Rays are cousins of sharks, with skeletons made of bendy cartilage.","tier":3},{"w":"ANGLERFISH","clue":"Deep-sea fish with a glowing lure dangling from its head","fact":"Anglerfish glow thanks to helpful bacteria living inside their lure.","tier":3},{"w":"TIDEPOOL","clue":"Small rocky puddle left behind when the sea goes out","fact":"Animals in tide pools survive being underwater and out in the air every day.","tier":3},{"w":"NAUTILUS","clue":"Sea animal with a spiral shell and many tiny tentacles","fact":"The nautilus is an ancient kind of animal related to squid and octopuses.","tier":3},{"w":"SUBMARINE","clue":"Underwater ship that can dive deep","fact":"A submarine dives by filling tanks with water and rises by pushing it out.","tier":3},{"w":"WHALE","clue":"Giant sea mammal that breathes air through a hole on its head","fact":"The blue whale is the biggest animal that has ever lived.","tier":1},{"w":"ORCA","clue":"Black-and-white ocean hunter that is really the biggest kind of dolphin","fact":"Orcas hunt in family groups called pods and talk with clicks and whistles.","tier":1},{"w":"PIER","clue":"Wooden walkway that sticks out over the water","fact":"The posts under a pier become a home for crabs, mussels and fish.","tier":1},{"w":"SAND","clue":"Tiny bits of rock and shell that cover a beach","fact":"Parrotfish chew coral, and much of the white sand in the tropics is what they leave behind.","tier":1},{"w":"SALT","clue":"White crystals dissolved in the sea that make it taste yucky","fact":"Ocean water is salty because rivers carry tiny bits of salt from rocks into the sea.","tier":1},{"w":"BEACH","clue":"Sandy shore where waves roll in and kids build castles","fact":"Waves keep pushing sand along a beach, so shorelines slowly change shape.","tier":1},{"w":"KAYAK","clue":"Narrow paddle boat with a covered top, first made in the Arctic","fact":"Arctic peoples first built kayaks with animal skins stretched over frames of wood or bone.","tier":1},{"w":"FOAM","clue":"White bubbly froth on top of waves","fact":"Sea foam forms when waves whip up tiny bits of plants and animals.","tier":1},{"w":"BOAT","clue":"Small vessel moved by oars, sails or a motor","fact":"Some of the oldest boats ever found are hollowed-out logs thousands of years old.","tier":1},{"w":"SAIL","clue":"Big sheet of cloth that catches the wind to move a boat","fact":"A curved sail works a lot like an airplane wing.","tier":1},{"w":"BUOY","clue":"Floating marker that bobs on the water","fact":"Some buoys carry tools that measure wave height and water temperature.","tier":1},{"w":"DIVE","clue":"To plunge headfirst under the water","fact":"Elephant seals can hold their breath for over an hour while they dive.","tier":1},{"w":"GILL","clue":"Body part a fish uses to breathe under water","fact":"Fish gills pull oxygen out of the water as it flows past.","tier":1},{"w":"PEARL","clue":"Shiny round gem that grows inside an oyster","fact":"A pearl forms when a bit of grit gets inside an oyster and is wrapped in layers.","tier":1},{"w":"KRILL","clue":"Tiny shrimp-like animals that big whales eat by the ton","fact":"Krill are tiny, but a blue whale eats tons of them in one day.","tier":1},{"w":"MANTA","clue":"Giant ray with wide wing-like fins that scoops up plankton","fact":"Manta rays have the biggest brains of any fish.","tier":1},{"w":"SONAR","clue":"Machine that uses sound echoes to find things underwater","fact":"Dolphins use natural sonar, clicking and listening for echoes to find fish.","tier":1},{"w":"ALGAE","clue":"Simple plant-like living things that float or grow in water","fact":"Tiny ocean algae make a large part of the oxygen we breathe.","tier":1},{"w":"DEEP","clue":"Opposite of shallow","fact":"The deepest part of the ocean is deeper than Mount Everest is tall.","tier":1},{"w":"SCUBA","clue":"Gear with an air tank that lets divers breathe underwater","fact":"SCUBA stands for Self-Contained Underwater Breathing Apparatus.","tier":1},{"w":"FLUKE","clue":"Wide flat tail of a whale or dolphin","fact":"Each humpback whale has a tail pattern as unique as a fingerprint.","tier":1},{"w":"SCALE","clue":"Thin, hard plate that covers a fish's skin","fact":"Fish scales grow rings like trees, so scientists can estimate a fish's age.","tier":1},{"w":"TUSK","clue":"Long pointed tooth that sticks out of a walrus's mouth","fact":"Walruses use their tusks to haul their heavy bodies onto the ice.","tier":1},{"w":"HULL","clue":"Main body of a ship, the part that floats","fact":"The biggest ships have hulls longer than three football fields.","tier":1},{"w":"ATOLL","clue":"Ring-shaped island of coral around a calm lagoon","fact":"Many atolls are rings of coral growing on top of old sunken volcanoes.","tier":1},{"w":"SWELL","clue":"Long smooth wave rolling across the open ocean","fact":"Swells can travel thousands of kilometers from the storm that made them.","tier":1},{"w":"FLOAT","clue":"To stay on top of the water without sinking","fact":"You float more easily in the sea than in a pool, because salt water holds you up better.","tier":1},{"w":"FERRY","clue":"Boat that carries people and cars across the water","fact":"Some ferries are so big they carry hundreds of cars.","tier":1},{"w":"ANCHOR","clue":"Heavy metal hook that stops a ship from drifting away","fact":"Early anchors were just heavy stones tied to a rope.","tier":2},{"w":"LAGOON","clue":"Calm shallow pool of water partly walled off by a reef","fact":"A lagoon is calm because the reef outside blocks the big waves.","tier":2},{"w":"OYSTER","clue":"Shellfish with two rough shells that sometimes hides a pearl","fact":"Oysters clean the water by filtering out tiny bits of food and dirt.","tier":2},{"w":"MUSSEL","clue":"Dark blue shellfish that clings to rocks with sticky threads","fact":"Mussels glue themselves to rocks with strong threads so waves cannot wash them away.","tier":2},{"w":"SPONGE","clue":"Simple sea animal full of holes that soaks up water","fact":"Sponges are animals, even though they stay stuck in one place.","tier":2},{"w":"PUFFER","clue":"Fish that swells up like a ball when it is scared","fact":"A puffer fish swells into a ball by gulping water or air.","tier":2},{"w":"SNORKEL","clue":"Tube that lets you breathe while your face is in the water","fact":"A snorkel cannot be long, because deep water squeezes your chest too hard.","tier":2},{"w":"FLIPPER","clue":"Flat paddle-shaped limb of a seal, turtle or penguin","fact":"A sea turtle's front flippers flap like wings to push it through the water.","tier":2},{"w":"SAILOR","clue":"Person who works aboard a ship, hauling ropes and steering","fact":"Sailors long ago used the stars to find their way across the ocean.","tier":2},{"w":"BELUGA","clue":"Small white whale that chirps and whistles","fact":"Sailors nicknamed belugas sea canaries because they chirp and trill so much.","tier":2},{"w":"ANEMONE","clue":"Flower-like sea animal with stinging tentacles","fact":"Sea anemones are animals, not plants, and they sting small fish for food.","tier":2},{"w":"ESTUARY","clue":"Place where a river meets the sea and the water mixes","fact":"Many young fish grow up in estuaries, where the water is a mix of fresh and salty.","tier":2},{"w":"SEAGULL","clue":"Noisy white bird at the beach that loves stealing snacks","fact":"Seagulls can drink salt water, because special glands remove the salt.","tier":2},{"w":"PELICAN","clue":"Big bird with a stretchy pouch under its beak for scooping fish","fact":"A pelican's pouch can hold more than its stomach can.","tier":2},{"w":"PENGUIN","clue":"Black-and-white bird that cannot fly but swims fast","fact":"Penguins use their wings like flippers to fly through water.","tier":2},{"w":"SEAWEED","clue":"Slimy green or brown stuff that washes up on the beach","fact":"Seaweed is used in sushi and even in some ice cream.","tier":2},{"w":"MIGRATE","clue":"Travel a long way each year to find food or have babies","fact":"Gray whales swim more than 15,000 kilometers every year going back and forth.","tier":2},{"w":"GOGGLES","clue":"Tight glasses that keep water out of your eyes","fact":"Without goggles, things look blurry under water because our eyes cannot focus well there.","tier":2},{"w":"WETSUIT","clue":"Stretchy rubber suit that keeps divers warm","fact":"A wetsuit traps a thin layer of water that your body warms up.","tier":2},{"w":"MERMAID","clue":"Make-believe sea woman with a fish tail","fact":"Some old sailors' mermaid stories may have started when they saw manatees.","tier":2},{"w":"TUGBOAT","clue":"Small, strong vessel that pulls or pushes big ships into port","fact":"Tugboats are small but have powerful engines that can move ships much bigger than themselves.","tier":2},{"w":"ICEBERG","clue":"Giant floating mountain of frozen water, mostly hidden below the surface","fact":"Most of an iceberg is hidden under the water.","tier":2},{"w":"RIPTIDE","clue":"Strong narrow current that drags swimmers away from the beach","fact":"If a rip current grabs you, swim sideways along the shore, not straight back.","tier":2},{"w":"SHALLOW","clue":"Not deep, so you can stand up in it","fact":"Coral reefs grow in shallow water where sunlight can reach them.","tier":2},{"w":"BLUBBER","clue":"Thick layer of fat that keeps whales and seals warm","fact":"Blubber works like a built-in winter coat for animals in icy water.","tier":2},{"w":"SEASICK","clue":"Queasy from the rocking of a boat","fact":"Seasickness happens when your eyes and inner ears disagree about movement.","tier":2},{"w":"SARDINE","clue":"Small silver fish often packed in tin cans","fact":"Sardines swim in giant shimmering schools that confuse the animals hunting them.","tier":2},{"w":"SCHOOL","clue":"Group of fish swimming together","fact":"Fish in a school turn together because each one watches its neighbors.","tier":2},{"w":"SANDBAR","clue":"Long underwater ridge of tiny grains just off the beach","fact":"Waves and currents pile up sandbars just off the shore.","tier":2},{"w":"FISHING","clue":"Trying to catch dinner with a rod, reel and hook","fact":"People were fishing with hooks made of bone or shell tens of thousands of years ago.","tier":2},{"w":"COMPASS","clue":"Tool with a needle that always points north","fact":"A compass needle points north because Earth acts like a giant magnet.","tier":2},{"w":"PINCER","clue":"Gripping claw of a crab or lobster","fact":"Most lobsters have one thick crusher claw and one thinner cutter claw.","tier":2},{"w":"PLANKTON","clue":"Tiny drifting life that is food for whales and fish","fact":"Plankton comes from a Greek word meaning wanderer or drifter.","tier":3},{"w":"HUMPBACK","clue":"Whale famous for leaping and singing long songs","fact":"Humpback whales sing long songs that other whales can hear from far away.","tier":3},{"w":"TREASURE","clue":"Gold and jewels that divers sometimes find in old wrecks","fact":"Divers have found real treasure in shipwrecks that sank hundreds of years ago.","tier":3},{"w":"LIGHTHOUSE","clue":"Tall tower with a bright beam that guides ships at night","fact":"Lighthouses use special lenses to turn a small lamp into a beam seen from miles away.","tier":3},{"w":"CUTTLEFISH","clue":"Squid cousin that changes color in a flash","fact":"A cuttlefish can change its color and skin bumps in a blink to hide.","tier":3},{"w":"CLOWNFISH","clue":"Orange fish with white stripes that hides among stinging anemones","fact":"Clownfish are safe among anemones because a special coating protects them from the stings.","tier":3},{"w":"SWORDFISH","clue":"Big fish whose long pointed nose looks like a blade","fact":"A swordfish uses its long bill to slash through schools of smaller fish.","tier":3},{"w":"BLOWHOLE","clue":"Breathing hole on top of a whale's head","fact":"A whale breathes out through its blowhole with a loud whoosh and a misty spout.","tier":3},{"w":"TENTACLE","clue":"Long bendy arm of a squid or jellyfish","fact":"Squid have eight arms and two longer tentacles for grabbing food.","tier":3},{"w":"CRUSTACEAN","clue":"Group of hard-shelled animals that includes crabs and shrimp","fact":"Crabs, lobsters and shrimp are relatives, and so are barnacles.","tier":3},{"w":"SEAFLOOR","clue":"The bottom of the sea, covered in mud and sand","fact":"The seafloor has mountains, valleys and even volcanoes, just like land.","tier":3},{"w":"SURFBOARD","clue":"Long, flat float that carries a rider across a breaking wave","fact":"Surfing began long ago in Polynesia, where people rode waves on wooden boards.","tier":3},{"w":"HATCHLING","clue":"Baby sea turtle that has just come out of its egg","fact":"Baby sea turtles race toward the brightest horizon, which usually leads them to the sea.","tier":3},{"w":"PROPELLER","clue":"Spinning blades at the back of a boat","fact":"A propeller works like a screw, pushing water backward so the boat moves forward.","tier":3},{"w":"SUBMERSIBLE","clue":"Small research craft that carries scientists down into the deep","fact":"Deep-sea submersibles must be very strong to survive the huge pressure far below.","tier":3},{"w":"SAILBOAT","clue":"Vessel with tall masts that is pushed along by the wind","fact":"A sailboat can travel against the wind by zigzagging back and forth.","tier":3},{"w":"LEATHERBACK","clue":"Biggest sea turtle, with a soft rubbery shell","fact":"Leatherback turtles can dive deeper than a kilometer.","tier":3},{"w":"AQUARIUM","clue":"Building with giant tanks where you can watch sea animals","fact":"The biggest aquariums have tanks holding millions of liters of water.","tier":3},{"w":"SHIPWRECK","clue":"Broken boat lying on the bottom of the sea","fact":"Sunken ships often become reefs where fish and corals make their homes.","tier":3},{"w":"HURRICANE","clue":"Giant spinning storm born over warm ocean water","fact":"Hurricanes get their energy from warm sea water and weaken when they move over land.","tier":3},{"w":"LIFEBOAT","clue":"Small rescue vessel carried on a big ship","fact":"Big ships carry enough lifeboats for every person on board.","tier":3},{"w":"PRESSURE","clue":"The heavy squeeze of water that grows stronger the deeper you go","fact":"At the deepest trench's bottom, the water squeezes over a thousand times harder than at the surface.","tier":3},{"w":"MANGROVE","clue":"Tree that grows with its roots standing in salty water","fact":"Mangrove roots give baby fish a safe place to grow up.","tier":3},{"w":"PORTHOLE","clue":"Round window in the side of a ship","fact":"Ship windows are round because square corners are weak spots.","tier":3}],"es":[{"w":"OLA","clue":"Cresta de agua que avanza y rompe en la orilla","fact":"La mayoría de las olas las produce el viento al soplar sobre el mar.","tier":1},{"w":"FOCA","clue":"Mamífero marino de bigotes que se desliza sobre el hielo","fact":"Algunas focas pueden quedarse bajo el agua más de una hora sin respirar.","tier":1},{"w":"ALGA","clue":"Ser verde o marrón del mar que parece una planta","fact":"Las algas del mar producen buena parte del oxígeno que respiramos.","tier":1},{"w":"PULPO","clue":"Animal marino blando de ocho brazos que se cuela por huecos pequeños","fact":"El pulpo tiene tres corazones y sangre azul.","tier":1},{"w":"CORAL","clue":"Animalitos diminutos que forman arrecifes de roca de colores","fact":"Los corales parecen rocas o plantas, pero son animales diminutos llamados pólipos.","tier":1},{"w":"ATÚN","clue":"Pez grande y veloz que se vende en latas","fact":"Algunos atunes mantienen el cuerpo más caliente que el agua que los rodea.","tier":1},{"w":"ORCA","clue":"Delfín gigante de piel blanca y negra que caza en grupo","fact":"La orca no es una ballena: es el delfín más grande de todos.","tier":1},{"w":"ISLA","clue":"Tierra rodeada de agua por todos lados","fact":"Algunas islas son la cima de volcanes que crecieron desde el fondo del mar.","tier":1},{"w":"ERIZO","clue":"Animal redondo del fondo marino cubierto de púas","fact":"El erizo de mar se mueve con cientos de patitas diminutas.","tier":1},{"w":"PERLA","clue":"Bolita brillante que se forma dentro de una ostra","fact":"Una perla se forma cuando una ostra cubre con capas un granito que la molesta.","tier":1},{"w":"ARENA","clue":"Granitos finos de roca que cubren la playa","fact":"Mucha arena de playa viene de rocas y conchas que el mar fue rompiendo.","tier":1},{"w":"PLAYA","clue":"Orilla del mar cubierta de arena donde juegan los niños","fact":"Hay playas con arena rosada, negra o verde, según las rocas de donde viene.","tier":1},{"w":"MEDUSA","clue":"Animal transparente y blandito que flota y tiene tentáculos que pican","fact":"Las medusas no tienen cerebro, ni corazón, ni huesos.","tier":2},{"w":"DELFÍN","clue":"Mamífero marino listo y juguetón que chasquea y silba","fact":"Los delfines duermen con la mitad del cerebro despierta para poder respirar.","tier":2},{"w":"CALAMAR","clue":"Primo del pulpo con diez brazos que suelta tinta oscura","fact":"El calamar gigante tiene ojos tan grandes como platos.","tier":2},{"w":"CONCHA","clue":"Casita dura que dejan en la arena los animales marinos","fact":"Los animales fabrican sus conchas con minerales que hay en el agua del mar.","tier":2},{"w":"TORTUGA","clue":"Reptil con caparazón que pone sus huevos en la playa","fact":"Muchas tortugas marinas regresan a poner huevos a la playa donde nacieron.","tier":2},{"w":"CARACOL","clue":"Animal lento con una concha en espiral","fact":"La lengua de un caracol tiene cientos o miles de dientes diminutos.","tier":2},{"w":"ALMEJA","clue":"Animal de dos conchas que se entierra en la arena","fact":"Algunas almejas del océano viven cientos de años.","tier":2},{"w":"MANATÍ","clue":"Vaca marina gris y tranquila que come plantas bajo el agua","fact":"El manatí es pariente lejano del elefante.","tier":2},{"w":"NARVAL","clue":"Ballena del Ártico con un diente largo en espiral","fact":"El colmillo del narval es en realidad un diente larguísimo que crece atravesando el labio.","tier":2},{"w":"CAMARÓN","clue":"Animalito marino de cuerpo curvo y largas antenas","fact":"Una clase de camarón chasquea su pinza tan rápido que hace una burbuja ruidosa.","tier":2},{"w":"SALMÓN","clue":"Pez rosado que nada río arriba para poner huevos","fact":"Los salmones encuentran el río donde nacieron guiándose por el olfato.","tier":2},{"w":"PUERTO","clue":"Lugar protegido de la costa donde atracan los barcos","fact":"Muchos puertos se construyen en bahías, donde la costa protege a los barcos del oleaje.","tier":2},{"w":"BALLENA","clue":"Gigante del mar que respira aire por un orificio en la cabeza","fact":"Las ballenas son mamíferos: respiran aire y alimentan a sus crías con leche.","tier":2},{"w":"OCÉANO","clue":"Agua salada enorme que cubre casi tres cuartas partes de la Tierra","fact":"El océano Pacífico es más grande que todas las tierras juntas.","tier":2},{"w":"ARRECIFE","clue":"Barrera de roca o coral justo bajo la superficie del mar","fact":"Los arrecifes cubren menos del uno por ciento del fondo marino, pero albergan mucha vida.","tier":3},{"w":"LANGOSTA","clue":"Crustáceo de largas antenas que vive en cuevas rocosas del mar","fact":"Las langostas tienen los dientes dentro del estómago.","tier":3},{"w":"CANGREJO","clue":"Crustáceo que camina de lado con dos pinzas","fact":"Los cangrejos caminan de lado por la forma de las articulaciones de sus patas.","tier":3},{"w":"PINGÜINO","clue":"Ave que no vuela pero nada de maravilla","fact":"Los pingüinos usan sus alas como aletas para \"volar\" bajo el agua.","tier":3},{"w":"SUBMARINO","clue":"Barco que puede navegar bajo el agua","fact":"Un submarino baja llenando tanques con agua y sube sacándola.","tier":3},{"w":"CORRIENTE","clue":"Río de agua que fluye dentro del mar","fact":"Las corrientes marinas mueven agua tibia y fría por todo el planeta.","tier":3},{"w":"ACANTILADO","clue":"Pared de roca muy alta y casi recta junto al mar","fact":"Con los años, las olas van tallando el acantilado y lo hacen retroceder.","tier":3},{"w":"OCEANÓGRAFO","clue":"Científico que estudia los mares","fact":"Los oceanógrafos usan submarinos pequeños y robots para explorar el fondo del mar.","tier":3},{"w":"CRUSTÁCEO","clue":"Animal con caparazón duro y muchas patas, como cangrejos y camarones","fact":"Los crustáceos mudan su caparazón para poder seguir creciendo.","tier":3},{"w":"HIPOCAMPO","clue":"Pececito con cabeza de caballo; el papá lleva a las crías","fact":"El macho del hipocampo lleva los huevos en una bolsa y luego da a luz.","tier":3},{"w":"MAR","clue":"Enorme extensión de agua salada","fact":"El agua del mar cubre más de dos tercios de nuestro planeta.","tier":1},{"w":"SAL","clue":"Polvo blanco disuelto en el océano que también echamos a la sopa","fact":"El agua del mar es salada porque los ríos le llevan pedacitos de sal de las rocas.","tier":1},{"w":"BARCA","clue":"Vehículo pequeño que flota y se mueve con remos o velas","fact":"Algunas de las barcas más antiguas que se han hallado son troncos ahuecados.","tier":1},{"w":"VELA","clue":"Gran tela que atrapa el viento para mover un barco","fact":"Una vela curva funciona un poco como el ala de un avión.","tier":1},{"w":"BOYA","clue":"Marca flotante que se mece sobre el agua","fact":"Algunas boyas llevan aparatos que miden la altura de las olas y la temperatura del agua.","tier":1},{"w":"ANCLA","clue":"Gancho pesado que evita que un barco se aleje a la deriva","fact":"Las primeras anclas eran piedras pesadas atadas a una cuerda.","tier":1},{"w":"PROA","clue":"Parte delantera de un barco","fact":"La proa es puntiaguda para abrir el agua y avanzar mejor.","tier":1},{"w":"BRISA","clue":"Viento suave y fresco que llega del mar","fact":"De día la brisa va del mar a la tierra, y de noche al revés.","tier":1},{"w":"COSTA","clue":"Franja de tierra que toca el mar","fact":"Las costas cambian de forma poco a poco por la fuerza de las olas.","tier":1},{"w":"BAHÍA","clue":"Entrada curva del mar en la tierra, de aguas tranquilas","fact":"Las bahías suelen ser buenos puertos porque las olas llegan más calmadas.","tier":1},{"w":"REMO","clue":"Palo con una paleta plana para mover un bote","fact":"Los remos empujan el agua hacia atrás para que el bote avance.","tier":1},{"w":"NADAR","clue":"Moverse en el agua con brazos y piernas","fact":"Las tortugas marinas nadan moviendo sus aletas delanteras como si fueran alas.","tier":1},{"w":"BUZO","clue":"Persona que baja bajo el agua con un tanque de aire","fact":"Los buzos suben despacio a la superficie para que su cuerpo se acostumbre a la presión.","tier":1},{"w":"ALETA","clue":"Parte plana que usan los peces para nadar","fact":"Las aletas ayudan a los peces a girar, frenar y mantenerse derechos.","tier":1},{"w":"KRILL","clue":"Animalitos parecidos a camarones que las ballenas comen por toneladas","fact":"Aunque el krill es diminuto, una ballena azul come toneladas en un solo día.","tier":1},{"w":"SONAR","clue":"Aparato que usa ecos de sonido para hallar cosas bajo el agua","fact":"Muchos barcos usan sonar para medir qué tan hondo está el fondo.","tier":1},{"w":"FARO","clue":"Torre alta con luz potente que guía a los barcos de noche","fact":"Los faros usan lentes especiales para que una lámpara pequeña se vea desde muy lejos.","tier":1},{"w":"PEZ","clue":"Animal con aletas y branquias que vive en el agua","fact":"La mayoría de los peces no tiene párpados, así que duermen con los ojos abiertos.","tier":1},{"w":"OSTRA","clue":"Molusco de dos conchas rugosas que puede esconder una perla","fact":"Las ostras limpian el agua filtrando restos diminutos de comida y suciedad.","tier":1},{"w":"FONDO","clue":"Parte más baja del mar, donde hay arena y rocas","fact":"El fondo del mar tiene montañas, valles y hasta volcanes, igual que la tierra.","tier":1},{"w":"MORSA","clue":"Animal de colmillos largos que vive sobre el hielo del Ártico","fact":"Un macho adulto de morsa puede pesar más de una tonelada.","tier":1},{"w":"SEPIA","clue":"Pariente del calamar que cambia de color muy rápido","fact":"La sepia cambia el color y la textura de su piel en un parpadeo para esconderse.","tier":1},{"w":"TIMÓN","clue":"Rueda o palanca que sirve para guiar un barco","fact":"Aunque es pequeño, el timón puede hacer girar un barco enorme.","tier":1},{"w":"FOSA","clue":"Valle larguísimo y hondo en el fondo del océano","fact":"La parte más honda del océano es más profunda de lo que mide el Everest de alto.","tier":1},{"w":"BANCO","clue":"Gran grupo de peces que nadan juntos","fact":"Los peces de un banco giran juntos porque cada uno vigila a sus vecinos.","tier":1},{"w":"GAFAS","clue":"Lentes ajustados que evitan que el agua entre a tus ojos","fact":"Sin gafas, bajo el agua todo se ve borroso porque nuestros ojos no enfocan bien.","tier":1},{"w":"PINZA","clue":"Garra con la que un cangrejo o una langosta agarra cosas","fact":"La mayoría de las langostas tiene una pinza fuerte para aplastar y otra más fina para cortar.","tier":1},{"w":"KAYAK","clue":"Bote angosto y cubierto con remo de dos palas","fact":"Los pueblos del Ártico hicieron los primeros kayaks con pieles de animales sobre armazones de madera o hueso.","tier":1},{"w":"MUELLE","clue":"Plataforma de madera que se adentra en el agua","fact":"Los pilotes bajo un muelle se vuelven casa de cangrejos, mejillones y peces.","tier":2},{"w":"ESPUMA","clue":"Burbujitas blancas en la cresta de las olas","fact":"La espuma del mar se forma cuando las olas revuelven restos diminutos de plantas y animales.","tier":2},{"w":"SIRENA","clue":"Mujer con cola de pez de los cuentos","fact":"Algunos cuentos antiguos de sirenas quizá nacieron cuando marineros vieron manatíes.","tier":2},{"w":"AGALLA","clue":"Parte con la que los peces respiran bajo el agua","fact":"Las agallas de los peces sacan el oxígeno del agua que pasa por ellas.","tier":2},{"w":"ESCAMA","clue":"Placa delgada y dura que cubre la piel de un pez","fact":"Las escamas de los peces forman anillos como los árboles, y sirven para calcular su edad.","tier":2},{"w":"ANZUELO","clue":"Gancho pequeño de metal con el que se atrapa un pez","fact":"Los anzuelos más antiguos que se han hallado eran de hueso o de concha.","tier":2},{"w":"LANCHA","clue":"Barco pequeño y veloz con motor","fact":"Una lancha rápida casi no toca el agua: planea sobre ella.","tier":2},{"w":"NUTRIA","clue":"Animal peludo que flota boca arriba y rompe almejas con una piedra","fact":"Las nutrias marinas duermen tomadas de las patas para no separarse.","tier":2},{"w":"ATOLÓN","clue":"Isla de coral en forma de anillo que rodea una laguna","fact":"Muchos atolones son anillos de coral que crecieron sobre antiguos volcanes hundidos.","tier":2},{"w":"LAGUNA","clue":"Poza tranquila de agua separada del mar por arena o arrecife","fact":"Una laguna está en calma porque el arrecife detiene las olas grandes.","tier":2},{"w":"ESPONJA","clue":"Animal marino sencillo lleno de huecos que absorbe agua","fact":"Las esponjas son animales aunque pasan toda la vida pegadas en un lugar.","tier":2},{"w":"ANÉMONA","clue":"Animal marino parecido a una flor, con tentáculos que pican","fact":"Las anémonas son animales, no plantas, y pican a los peces pequeños para comérselos.","tier":2},{"w":"GAVIOTA","clue":"Ave blanca y ruidosa de la playa que roba comida","fact":"Las gaviotas pueden beber agua salada porque unas glándulas especiales sacan la sal.","tier":2},{"w":"TESORO","clue":"Oro y joyas que a veces se hallan en barcos hundidos","fact":"Algunos buzos han encontrado tesoros de verdad en naufragios de hace siglos.","tier":2},{"w":"ICEBERG","clue":"Enorme montaña de agua helada que flota en los mares fríos","fact":"La mayor parte de un iceberg está escondida bajo el agua.","tier":2},{"w":"HURACÁN","clue":"Enorme tormenta giratoria que nace sobre agua cálida del mar","fact":"Los huracanes obtienen su fuerza del agua tibia y se debilitan al llegar a tierra.","tier":2},{"w":"OLEAJE","clue":"Movimiento continuo de muchas olas","fact":"Algunas olas viajan miles de kilómetros desde la tormenta que las formó.","tier":2},{"w":"ACUARIO","clue":"Edificio con grandes peceras donde ves animales marinos","fact":"Los acuarios más grandes tienen tanques con millones de litros de agua.","tier":2},{"w":"HÉLICE","clue":"Aspas que giran en la parte trasera de un barco","fact":"Una hélice empuja el agua hacia atrás y así el barco avanza.","tier":2},{"w":"BRÚJULA","clue":"Instrumento con una aguja que siempre señala el norte","fact":"La aguja señala el norte porque la Tierra funciona como un imán gigante.","tier":2},{"w":"PRESIÓN","clue":"Apretón del agua que crece cuanto más hondo bajas","fact":"Allá abajo, en la fosa más honda, el agua aprieta más de mil veces más que arriba.","tier":2},{"w":"MIGRAR","clue":"Viajar lejos cada año para buscar comida o tener crías","fact":"Las ballenas grises recorren más de 15.000 kilómetros cada año, entre ida y vuelta.","tier":2},{"w":"SARDINA","clue":"Pez plateado y pequeño que se vende en lata","fact":"Las sardinas nadan en enormes bancos brillantes que confunden a sus cazadores.","tier":2},{"w":"YUBARTA","clue":"Ballena que salta fuera del agua y canta canciones largas","fact":"Las yubartas cantan canciones largas que otras ballenas oyen desde muy lejos.","tier":2},{"w":"BELUGA","clue":"Ballena blanca pequeña que chilla y silba","fact":"Los marineros llamaban canarios del mar a las belugas por sus chillidos.","tier":2},{"w":"MANGLAR","clue":"Bosque de árboles con raíces dentro del agua salada","fact":"Las raíces del manglar son un lugar seguro donde crecen peces pequeños.","tier":2},{"w":"ABISMO","clue":"Profundidad enorme y oscura del océano","fact":"En el abismo no llega la luz del Sol, y algunos animales fabrican su propia luz.","tier":2},{"w":"VELERO","clue":"Barco que avanza empujado por el viento en sus telas","fact":"Un velero puede avanzar contra el viento yendo en zigzag.","tier":2},{"w":"BURBUJA","clue":"Bolita de aire que sube cuando un buzo respira bajo el agua","fact":"Las burbujas suben porque el aire pesa menos que el agua.","tier":2},{"w":"RESACA","clue":"Corriente fuerte que arrastra a los nadadores mar adentro","fact":"Si una resaca te arrastra, nada de lado, paralelo a la playa, y no de frente.","tier":2},{"w":"NAVEGAR","clue":"Viajar por el agua en un barco","fact":"Hace miles de años, los marinos ya navegaban guiándose por las estrellas.","tier":2},{"w":"ANGUILA","clue":"Pez largo y resbaloso con forma de serpiente","fact":"Las anguilas europeas nacen en el mar de los Sargazos y nadan miles de kilómetros.","tier":2},{"w":"PELÍCANO","clue":"Ave grande con una bolsa elástica bajo el pico para atrapar peces","fact":"La bolsa de un pelícano puede guardar más que su estómago.","tier":3},{"w":"NAUFRAGIO","clue":"Barco roto y hundido en el fondo del mar","fact":"Los barcos hundidos suelen convertirse en arrecifes donde viven peces y corales.","tier":3},{"w":"SALVAVIDAS","clue":"Aro o chaleco que te ayuda a mantenerte a flote","fact":"Los chalecos salvavidas flotan porque están llenos de un material más ligero que el agua.","tier":3},{"w":"SUMERGIBLE","clue":"Nave pequeña de investigación que baja a las profundidades","fact":"Los sumergibles de aguas profundas deben ser muy fuertes para aguantar la presión.","tier":3},{"w":"MARINERO","clue":"Persona que trabaja en un barco, tirando cuerdas y manejando velas","fact":"Hace mucho, los marineros usaban las estrellas para encontrar su camino en el mar.","tier":3},{"w":"BALLENATO","clue":"Cría de un animal marino gigante que toma leche","fact":"Un ballenato toma leche de su mamá, igual que tú cuando eras bebé.","tier":3},{"w":"CACHALOTE","clue":"Ballena de cabeza enorme que bucea muy hondo","fact":"Los cachalotes pueden aguantar la respiración más de una hora cuando bucean.","tier":3},{"w":"ESTUARIO","clue":"Donde un río se une al mar y el agua se mezcla","fact":"Muchos peces jóvenes crecen en los estuarios, donde el agua es mezcla de dulce y salada.","tier":3},{"w":"PLANCTON","clue":"Seres diminutos que flotan a la deriva y alimentan a las ballenas","fact":"Plancton viene de una palabra griega que significa errante o vagabundo.","tier":3},{"w":"TENTÁCULO","clue":"Brazo largo y flexible de un pulpo o una medusa","fact":"Los calamares tienen ocho brazos y dos tentáculos más largos para atrapar comida.","tier":3},{"w":"CAPARAZÓN","clue":"Cubierta dura de una tortuga o un cangrejo","fact":"El caparazón de una tortuga es parte de su esqueleto, con costillas unidas.","tier":3},{"w":"MANTARRAYA","clue":"Raya gigante con aletas anchas como alas que atrapa plancton","fact":"Las mantarrayas tienen el cerebro más grande de todos los peces.","tier":3},{"w":"ALBATROS","clue":"Ave marina que planea sobre el océano durante horas","fact":"Los albatros pueden planear sobre el mar durante horas casi sin mover las alas.","tier":3},{"w":"MEJILLÓN","clue":"Molusco azul oscuro que se pega a las rocas con hilos","fact":"Los mejillones se pegan a las rocas con hilos tan fuertes que las olas no los arrancan.","tier":3},{"w":"SUPERFICIE","clue":"La parte de arriba del agua, donde se mecen las olas","fact":"Las ballenas suben a la superficie para respirar aire.","tier":3},{"w":"PROFUNDIDAD","clue":"Distancia desde la superficie hasta el fondo del agua","fact":"La luz del Sol solo llega hasta unos doscientos metros de profundidad en el mar.","tier":3},{"w":"SURFISTA","clue":"Persona que se desliza sobre las olas con una tabla","fact":"El surf nació hace mucho en Polinesia, donde la gente montaba olas en tablas de madera.","tier":3},{"w":"DEPREDADOR","clue":"Animal que caza a otros animales para comérselos","fact":"Las orcas cazan en equipo para atrapar a sus presas.","tier":3},{"w":"CAMUFLAJE","clue":"Truco de cambiar de color o forma para esconderse","fact":"El pulpo puede cambiar de color y se confunde con las rocas del fondo.","tier":3},{"w":"ESPADARTE","clue":"Pez grande con una nariz larga y puntiaguda como un sable","fact":"El espadarte usa su pico largo para golpear bancos de peces pequeños.","tier":3},{"w":"ECOLOCACIÓN","clue":"Forma de ubicarse con sonidos y ecos, como hacen delfines y murciélagos","fact":"Los delfines hacen clics y escuchan los ecos para saber dónde hay peces.","tier":3},{"w":"ASTILLERO","clue":"Lugar donde se construyen y reparan barcos","fact":"Algunos barcos construidos en astilleros miden más que tres canchas de fútbol.","tier":3},{"w":"PESCADOR","clue":"Persona que sale al mar a atrapar peces","fact":"Hace miles de años, los pescadores ya usaban redes hechas con fibras de plantas.","tier":3},{"w":"COLMILLO","clue":"Diente largo y puntiagudo que sobresale de la boca de una morsa","fact":"La morsa usa sus colmillos para subir su cuerpo pesado al hielo.","tier":3}]}},{"id":"baseball","icon":"⚾","name":{"en":"Baseball","es":"Béisbol"},"words":{"en":[{"w":"BAT","clue":"Long stick players swing to hit a pitched baseball","fact":"Pro baseball bats are made from one solid piece of wood, often maple, ash or birch.","tier":1},{"w":"BALL","clue":"Round, stitched sphere that pitchers throw","fact":"A regulation baseball has 108 raised red stitches.","tier":1},{"w":"BASE","clue":"Square bag runners step on as they circle the diamond","fact":"Bases are 90 feet apart in professional baseball.","tier":1},{"w":"MITT","clue":"Thick padded hand covering worn by catchers","fact":"A catcher's mitt has extra padding and no separate fingers.","tier":1},{"w":"GLOVE","clue":"Leather wear on a fielder's hand","fact":"Fielders have worn gloves since the 1800s, and they soften with use.","tier":1},{"w":"PLATE","clue":"Five-sided white slab where runners score","fact":"Home plate has five sides, so it looks like a little house.","tier":1},{"w":"MOUND","clue":"Small hill in the middle of the field where pitching starts","fact":"The pitcher's mound can be up to ten inches higher than the rest of the field.","tier":1},{"w":"SWING","clue":"Move the bat through the air to try to hit","fact":"A fast pitch takes less than half a second to reach home plate.","tier":1},{"w":"BUNT","clue":"Tap the ball softly so it rolls just a short way","fact":"Players often bunt to help a teammate move up to the next base.","tier":1},{"w":"FOUL","clue":"A ball hit outside the lines is called this","fact":"A foul ball counts as a strike unless the batter already has two strikes.","tier":1},{"w":"WALK","clue":"Free trip to first base after four balls","fact":"A walk is also called a base on balls.","tier":1},{"w":"STEAL","clue":"Sneak to the next base while the pitcher throws","fact":"Stealing a base takes speed and a quick, clever jump from the runner.","tier":1},{"w":"PITCHER","clue":"Player who throws from the mound toward the batter","fact":"Pitchers use different grips on the ball to make it curve, dip or zoom.","tier":2},{"w":"CATCHER","clue":"Crouching player behind home plate who receives throws","fact":"Catchers wear shin guards, a chest protector and a mask for safety.","tier":2},{"w":"BATTER","clue":"Player holding a stick, trying to hit the pitch","fact":"Switch hitters can bat from either side of the plate.","tier":2},{"w":"STRIKE","clue":"Three of these and the batter is out","fact":"A pitch in the strike zone counts even if the batter does not swing.","tier":2},{"w":"INNING","clue":"Nine of these make a game; each team hits once per one","fact":"Baseball has no clock, so tied games just keep going with extra innings.","tier":2},{"w":"UMPIRE","clue":"Official who decides if a pitch is a ball or a strike","fact":"Umpires use hand signals to call safe, out and strikes.","tier":2},{"w":"DUGOUT","clue":"Sunken shelter where players sit during the game","fact":"Many dugouts sit lower than the field, which is how they got their name.","tier":2},{"w":"DIAMOND","clue":"Shape formed by the four bases on a baseball field","fact":"The infield is a square turned sideways, which looks like a diamond.","tier":2},{"w":"INFIELD","clue":"Dirt-and-grass area around the four bases","fact":"Infielders stand close to the bases, while outfielders play farther back.","tier":2},{"w":"SINGLE","clue":"A hit that gets the batter safely to first base","fact":"Singles are the most common kind of hit in baseball.","tier":2},{"w":"DOUBLE","clue":"A hit that gets the batter all the way to second base","fact":"Old-timers call a double a \"two-bagger,\" because bases were once called bags.","tier":2},{"w":"TRIPLE","clue":"A hit that gets the runner to third base","fact":"Triples are rarer than doubles because they need a long hit and fast running.","tier":2},{"w":"BULLPEN","clue":"Where relief pitchers warm up before entering the game","fact":"A bullpen holds extra pitchers, ready to take over if the starter gets tired.","tier":2},{"w":"HELMET","clue":"Hard hat batters wear for protection","fact":"Batting helmets have an extra-hard shell, and some have a flap to cover an ear.","tier":2},{"w":"OUTFIELD","clue":"Left, center and right fielders patrol this grassy area","fact":"Every ballpark's outfield has its own shape and size, so no two are alike.","tier":3},{"w":"SHORTSTOP","clue":"Infielder between second and third base","fact":"Shortstops need quick feet and a strong arm for long throws to first base.","tier":3},{"w":"BLEACHERS","clue":"Outdoor benches where fans sit, often in the sun","fact":"Bleachers got their name from seats that were bleached pale by the sun.","tier":3},{"w":"FASTBALL","clue":"Pitch thrown straight and as quick as possible","fact":"Top pitchers can throw a fastball faster than cars drive on a highway.","tier":3},{"w":"SCOREBOARD","clue":"Big display showing each team's runs and the inning","fact":"Some old ballparks still have scoreboards that people change by hand.","tier":3},{"w":"BASEBALL","clue":"Game with bats, bases and nine innings, played on a diamond","fact":"A baseball team defends with nine players on the field at once.","tier":3},{"w":"CURVEBALL","clue":"Pitch that bends in the air before reaching the batter","fact":"A curveball curves because its spin changes the air pressure around the ball.","tier":3},{"w":"STRIKEOUT","clue":"Out made when a batter fails to hit three good pitches","fact":"A strikeout is written with the letter K in a scorebook.","tier":3},{"w":"BALLPARK","clue":"Stadium where baseball games are played","fact":"Fans sing a song and stretch their legs in the middle of the seventh inning.","tier":3},{"w":"BASERUNNER","clue":"Player on first, second or third who hopes to score","fact":"Runners can slide head-first or feet-first to avoid being tagged out.","tier":3},{"w":"OUT","clue":"Three of these end a team's turn at bat","fact":"Three outs end each half-inning, so nine full innings means 27 outs per team.","tier":1},{"w":"RUN","clue":"A point scored when a player touches home plate safely","fact":"A home run with the bases loaded scores four runs at once.","tier":1},{"w":"HIT","clue":"A batter earns this by smacking the ball and reaching base safely","fact":"A hitter who gets a hit in three of every ten tries is considered excellent.","tier":1},{"w":"TEAM","clue":"Group of players who wear the same uniform and play together","fact":"A baseball team puts nine players on the field when it is on defense.","tier":1},{"w":"FAN","clue":"Someone who cheers from the stands for a favorite team","fact":"Fans in the stands who catch a foul ball usually get to keep it.","tier":1},{"w":"TAG","clue":"Touch a runner with the ball to get an out","fact":"A fielder can tag a runner with the ball held in a glove.","tier":1},{"w":"SAFE","clue":"What the umpire calls when a runner reaches the base in time","fact":"Umpires show a safe call by spreading both arms wide with palms down.","tier":1},{"w":"LEAD","clue":"Distance a runner steps off the base before the pitch","fact":"Runners take a lead to get a head start, but stray too far and get tagged.","tier":1},{"w":"FLY","clue":"Birds do this, and so does a ball hit very high","fact":"A fly ball caught before it touches the ground is an out.","tier":1},{"w":"SLIDE","clue":"Drop low and skid along the dirt to reach a base","fact":"Players slide feet first or head first to dodge the tag.","tier":1},{"w":"PITCH","clue":"The throw sent from the mound toward the batter","fact":"From the pitcher's rubber to home plate is exactly 60 feet, 6 inches.","tier":1},{"w":"CATCH","clue":"Grab a flying ball out of the air with a glove","fact":"Outfielders sometimes leap high against the wall to rob a hitter of a home run.","tier":1},{"w":"NINE","clue":"The number of innings in a regular game, spelled out","fact":"A team has nine players on defense, and a regular game lasts nine innings.","tier":1},{"w":"CLEAT","clue":"Shoe with bumps or spikes on the bottom for gripping dirt","fact":"Cleats help players dig into the dirt and take off fast without slipping.","tier":1},{"w":"TURF","clue":"Fake grass that covers the field in some stadiums","fact":"Some indoor ballparks use turf because real grass cannot grow well under a roof.","tier":1},{"w":"DIRT","clue":"Brown stuff that coats a uniform after sliding into a base","fact":"Infield dirt is a mix of clay and sand, raked smooth before games.","tier":1},{"w":"ACE","clue":"A team's very best starting pitcher","fact":"Teams usually give their ace the ball for the most important games.","tier":1},{"w":"SEAM","clue":"The stitched line on a baseball where the leather pieces meet","fact":"A baseball has 108 red stitches holding its leather cover together.","tier":1},{"w":"ROOT","clue":"Cheer for a team, or the underground part of a plant","fact":"A famous baseball song says to root, root, root for the home team.","tier":1},{"w":"SCORE","clue":"The count of runs each team has, shown on the big board","fact":"Baseball scores are often low, like 3 to 2, unlike many other sports.","tier":1},{"w":"ERROR","clue":"A fielder's mistake, like dropping an easy ball","fact":"Official scorers record errors, and an error does not count as a hit for the batter.","tier":1},{"w":"CAGE","clue":"Net-covered tunnel where hitters practice swinging","fact":"The net around a batting cage keeps practice balls from flying all over the place.","tier":1},{"w":"TEE","clue":"Short post that holds a ball still for young kids to hit","fact":"T-ball players hit off a tee before they learn to hit real pitches.","tier":1},{"w":"NET","clue":"Mesh wall behind home plate that protects fans from fast balls","fact":"Foul balls can fly faster than 100 miles per hour, so many parks use a net.","tier":1},{"w":"ARM","clue":"Strong body part an outfielder uses to throw the ball far","fact":"A strong throwing arm lets an outfielder fire the ball in to stop runners.","tier":1},{"w":"COACH","clue":"Adult who teaches players and waves runners on from near a base","fact":"Base coaches stand in small marked boxes near first base and third base.","tier":1},{"w":"HOMER","clue":"Nickname for a hit that sails over the outfield wall","fact":"A ball hit over the fence in fair territory is a home run, and runners can jog.","tier":1},{"w":"CROWD","clue":"Thousands of fans packed together in the stands","fact":"A loud crowd can make a ballpark so noisy that players cannot hear each other.","tier":1},{"w":"SEASON","clue":"Spring to fall, the stretch of months when teams play games","fact":"Pro teams play well over a hundred games in a single season.","tier":2},{"w":"LEAGUE","clue":"A big group of teams that play against each other","fact":"Professional baseball leagues began in America in the 1800s.","tier":2},{"w":"PENNANT","clue":"Triangle-shaped flag, also the prize for winning a league","fact":"Pennants are triangle flags that sailors used on ships long before baseball existed.","tier":2},{"w":"MASCOT","clue":"Costumed character who dances and entertains the crowd","fact":"Mascots wear giant furry costumes and dance, race or cheer in the stands.","tier":2},{"w":"ROOKIE","clue":"A player in his very first big-league year","fact":"Many famous stars were rookies once, learning the game from older teammates.","tier":2},{"w":"WINDUP","clue":"Pitcher's turning, arm-swinging motion before letting go of the ball","fact":"Some pitchers skip the big windup when runners are on base so they can throw faster.","tier":2},{"w":"ROSTER","clue":"The list of all the players on a team","fact":"Teams change their roster during the year by adding and removing players.","tier":2},{"w":"LINEUP","clue":"List that says which player bats first, second, third and so on","fact":"The manager picks the lineup and writes it on a card before the game.","tier":2},{"w":"MANAGER","clue":"Leader who picks the lineup and decides when to change pitchers","fact":"Managers wear the same kind of uniform as their players.","tier":2},{"w":"SLUGGER","clue":"Player famous for hitting the ball very hard and far","fact":"A slugger's long home runs can travel more than 400 feet.","tier":2},{"w":"STADIUM","clue":"Huge building with thousands of seats where fans watch games","fact":"The word stadium comes from an ancient Greek running track about 600 feet long.","tier":2},{"w":"STRETCH","clue":"In the seventh inning, fans stand up and do this","fact":"The seventh-inning stretch is a baseball tradition more than a hundred years old.","tier":2},{"w":"DEFENSE","clue":"What the team in the field plays while the other team bats","fact":"In baseball, the defense is the team that holds the ball, unlike most sports.","tier":2},{"w":"OFFENSE","clue":"What the team at bat plays while trying to score runs","fact":"The offense sends hitters to the plate in a set batting order, over and over.","tier":2},{"w":"RUNNER","clue":"Player on a base trying to make it all the way around","fact":"Runners must touch each base in order: first, second, third, then home.","tier":2},{"w":"FIELDER","clue":"Defensive player who gathers hit balls out on the grass","fact":"Fielders wear gloves, and first basemen and catchers use special glove shapes.","tier":2},{"w":"UNIFORM","clue":"Matching outfit that all teammates wear to play","fact":"Many teams wear white uniforms at home and gray uniforms on the road.","tier":2},{"w":"JERSEY","clue":"Shirt with the team name and a number on the back","fact":"Numbers on the back of a jersey help fans tell players apart.","tier":2},{"w":"BATTERY","clue":"Name for the pitcher and catcher working together as a pair","fact":"A pitcher and catcher agree on every pitch using secret hand signals.","tier":2},{"w":"SIGNAL","clue":"Secret hand motion that tells a player what to do","fact":"Catchers flash finger signals to tell the pitcher which pitch to throw next.","tier":2},{"w":"CLOSER","clue":"Pitcher brought in near the end to protect a lead","fact":"A closer often pitches for just one inning, the last one.","tier":2},{"w":"REPLAY","clue":"Video that umpires can watch again to check a call","fact":"Video replay lets umpires look again at close plays to get the call right.","tier":2},{"w":"TICKET","clue":"Paper or phone pass you need to get into the game","fact":"Fans often keep old ticket stubs as souvenirs of games they saw.","tier":2},{"w":"PEANUT","clue":"Salty snack in a shell sold by vendors in the stands","fact":"Peanuts are not true nuts; they grow underground and are related to beans.","tier":2},{"w":"POPCORN","clue":"Fluffy white snack that pops from heated kernels","fact":"Popcorn kernels pop because the water inside turns to steam and bursts the shell.","tier":2},{"w":"LEATHER","clue":"Cow skin used to make gloves and to cover baseballs","fact":"A baseball's cover is two pieces of leather shaped like figure eights.","tier":2},{"w":"PLAYOFF","clue":"Extra games after the season to decide who is champion","fact":"Only the best teams from the season get to play in the playoffs.","tier":2},{"w":"RAINOUT","clue":"A game canceled because clouds are dropping water","fact":"Some stadiums have roofs that close so weather cannot stop the game.","tier":2},{"w":"SPRING","clue":"The warm season when teams practice before real games start","fact":"Many teams train in warm states like Florida and Arizona before the season begins.","tier":2},{"w":"SINKER","clue":"Pitch that dips downward, falling toward the dirt as it arrives","fact":"A sinker tricks batters into hitting the ball into the ground instead of the air.","tier":2},{"w":"SLIDER","clue":"Pitch that darts sideways as it reaches the batter","fact":"A slider is thrown a little slower than a fastball but breaks sideways.","tier":2},{"w":"SHUTOUT","clue":"When one team stops the other from scoring any runs at all","fact":"In a shutout, the losing team goes the whole game without a single run.","tier":2},{"w":"INFIELDER","clue":"Defender who guards first, second or third near the dirt diamond","fact":"Infielders must throw fast and accurately because runners sprint toward the bag.","tier":3},{"w":"OUTFIELDER","clue":"Defender who stands deep on the grass, far from the dirt diamond","fact":"Baseball has three outfielders: left, center and right.","tier":3},{"w":"GROUNDER","clue":"Ball that rolls and skips across the dirt after being hit","fact":"Infielders charge a slow grounder, running toward the ball to throw out the runner.","tier":3},{"w":"COMEBACK","clue":"Winning even though your team was losing by a lot","fact":"Because baseball has no clock, a team is never out of it until the final out.","tier":3},{"w":"RELIEVER","clue":"Pitcher who replaces the tired starter during the game","fact":"Relievers wait in the bullpen until the manager calls them to the mound.","tier":3},{"w":"CHANGEUP","clue":"A slow pitch thrown with the same motion as a fast one","fact":"A changeup fools hitters because they swing early at the slow pitch.","tier":3},{"w":"KNUCKLEBALL","clue":"Floating pitch with almost no spin that wobbles unpredictably","fact":"A knuckleball hardly spins, so the air makes it flutter and dance.","tier":3},{"w":"CHAMPION","clue":"Winner of the final series at the end of the year","fact":"Teams that win it all receive special championship rings.","tier":3},{"w":"SOFTBALL","clue":"Game like baseball but with a larger ball and underhand pitches","fact":"In softball, pitchers throw underhand, swinging their arm in a low circle.","tier":3},{"w":"TEAMMATE","clue":"A player who wears the same colors and plays on your side","fact":"Teammates give high fives and fist bumps after good plays.","tier":3},{"w":"AUTOGRAPH","clue":"A famous player's name written by hand, a prized souvenir","fact":"Players sign baseballs, cards and bats for fans who wait by the dugout.","tier":3},{"w":"SOUVENIR","clue":"Item you keep to remember a game, like a ball you caught","fact":"Fans who catch a foul ball or home run in the stands can keep it.","tier":3},{"w":"PRACTICE","clue":"What players do before games to get better, like batting drills","fact":"Players take batting practice before games, hitting pitches tossed by a coach.","tier":3},{"w":"SCOREKEEPER","clue":"Person who notes each hit, out and run in a notebook","fact":"Some fans keep score by hand, marking each play with special symbols.","tier":3},{"w":"BASEPATH","clue":"Dirt lane that runners follow between the bases","fact":"A runner who leaves the baseline to dodge a tag can be called out.","tier":3},{"w":"STATISTICS","clue":"Numbers that track every player's hits, runs and catches","fact":"Baseball fans love statistics, and some track dozens of numbers for each player.","tier":3},{"w":"STRATEGY","clue":"A plan for how to win, like when to bunt or steal","fact":"Managers plan which pitchers face which batters, using strategy based on past games.","tier":3},{"w":"CELEBRATE","clue":"Jump, cheer and hug after winning a big game","fact":"After a big win, teams often gather on the field to celebrate together.","tier":3},{"w":"FIREWORKS","clue":"Colorful explosions in the night sky launched after some games","fact":"Some ballparks launch fireworks after games on special nights like holidays.","tier":3},{"w":"SCREWBALL","clue":"Rare pitch that curves the opposite way from a curveball","fact":"A screwball breaks the opposite direction of a curveball, so it surprises hitters.","tier":3},{"w":"SCHEDULE","clue":"Calendar listing when and where a team will play","fact":"A baseball schedule is long because teams play almost every day in summer.","tier":3},{"w":"BACKSTOP","clue":"Tall fence behind the catcher that stops balls that get past","fact":"A backstop keeps missed pitches and foul balls from rolling far away.","tier":3},{"w":"SPECTATOR","clue":"Person who watches a game without playing in it","fact":"Spectators in the stands might catch a foul ball hit their way.","tier":3},{"w":"ANNOUNCER","clue":"Voice on the radio or loudspeaker telling you what is happening","fact":"Radio announcers describe every pitch so listeners can picture the game.","tier":3}],"es":[{"w":"BATE","clue":"Palo largo de madera con el que se golpea la pelota","fact":"Los bates profesionales se hacen de una sola pieza de madera, como arce o fresno.","tier":1},{"w":"BASE","clue":"Almohadilla blanca que los corredores deben pisar","fact":"La distancia entre las bases es de 90 pies, unos 27 metros, en el béisbol profesional.","tier":1},{"w":"CASCO","clue":"Protección dura para la cabeza del bateador","fact":"Los bateadores usan casco porque un lanzamiento puede ir muy rápido.","tier":1},{"w":"GORRA","clue":"Prenda con visera que protege los ojos del sol","fact":"La visera de la gorra ayuda a ver la pelota cuando el sol da de frente.","tier":1},{"w":"JUEGO","clue":"Partido o competencia entre dos equipos","fact":"El béisbol no tiene reloj: el juego sigue hasta que termina la última entrada.","tier":1},{"w":"LIGA","clue":"Grupo de equipos que compiten entre sí durante una temporada","fact":"En países como México, Venezuela y República Dominicana el béisbol es un deporte muy querido.","tier":1},{"w":"DOBLE","clue":"Batazo que lleva al bateador hasta la segunda base","fact":"Para llegar a segunda, el corredor recorre 180 pies, unos 55 metros.","tier":1},{"w":"TOQUE","clue":"Golpe suave que hace rodar la pelota apenas unos pasos","fact":"Con un toque, el bateador ayuda a que un compañero avance a la siguiente base.","tier":1},{"w":"CAMPO","clue":"Terreno grande de césped y tierra donde se juega","fact":"En el béisbol profesional, cada estadio tiene un campo con medidas distintas en los jardines.","tier":1},{"w":"CURVA","clue":"Lanzamiento que se dobla en el aire antes de llegar al plato","fact":"Una bola de curva dobla porque su giro cambia la presión del aire a su alrededor.","tier":1},{"w":"GRADA","clue":"Escalones donde se sientan los aficionados a mirar el juego","fact":"A la mitad de la séptima entrada, los aficionados se paran a estirarse y cantar.","tier":1},{"w":"ZURDO","clue":"Jugador que batea o lanza con la mano izquierda","fact":"Muchos bateadores batean zurdos porque quedan unos pasos más cerca de primera base.","tier":1},{"w":"BÉISBOL","clue":"Deporte con bates, bases y nueve entradas","fact":"Un equipo de béisbol defiende con nueve jugadores en el campo a la vez.","tier":2},{"w":"JONRÓN","clue":"Batazo que sale del estadio y permite dar toda la vuelta","fact":"Tras un jonrón, el bateador da la vuelta a las bases trotando, sin apuro.","tier":2},{"w":"GUANTE","clue":"Prenda de cuero para atrapar la pelota","fact":"Los guantes de béisbol se hacen de cuero y se suavizan con el uso.","tier":2},{"w":"PELOTA","clue":"Esfera blanca con costuras rojas que se lanza y se batea","fact":"Una pelota de béisbol tiene 108 costuras rojas.","tier":2},{"w":"ESTADIO","clue":"Edificio grande donde miles de aficionados ven los partidos","fact":"Algunos estadios tienen techos que se abren o se cierran según el clima.","tier":2},{"w":"ÁRBITRO","clue":"Persona que decide si un lanzamiento es bola o estrike","fact":"El árbitro usa señales con las manos para anunciar estrikes y outs.","tier":2},{"w":"ENTRADA","clue":"Parte del juego en la que ambos equipos batean una vez","fact":"Un juego tiene nueve entradas, pero si hay empate se juegan más.","tier":2},{"w":"CARRERA","clue":"Punto que se anota al llegar a home","fact":"Un equipo puede anotar carreras sin pegar hits, con bases por bolas y errores.","tier":2},{"w":"PONCHE","clue":"Out que ocurre cuando el bateador falla tres veces","fact":"En el libro de anotaciones, un ponche se escribe con la letra K.","tier":2},{"w":"TRIPLE","clue":"Batazo que lleva al corredor hasta la tercera base","fact":"Los triples son raros porque exigen un batazo largo y mucha velocidad.","tier":2},{"w":"BATAZO","clue":"Golpe fuerte a la pelota con el bate","fact":"Una recta rápida llega al plato en menos de medio segundo.","tier":2},{"w":"EQUIPO","clue":"Grupo de jugadores que trabajan juntos para ganar","fact":"En cada entrada, un equipo tiene su turno para batear y otro para defender.","tier":2},{"w":"MÁSCARA","clue":"Protección de la cara que usa el receptor detrás del plato","fact":"La máscara tiene barras de metal que protegen la cara de pelotas rápidas.","tier":2},{"w":"ESTRIKE","clue":"Tres de estos y el bateador queda fuera","fact":"Un foul cuenta como estrike, salvo que el bateador ya tenga dos.","tier":2},{"w":"LANZADOR","clue":"Jugador que tira la pelota desde el montículo","fact":"Los lanzadores usan distintos agarres de la pelota para hacerla curvar, caer o acelerar.","tier":3},{"w":"RECEPTOR","clue":"Jugador agachado detrás del plato al que le llegan los lanzamientos","fact":"El receptor ve todo el campo de frente y ayuda a decidir qué lanzamientos pedir.","tier":3},{"w":"BATEADOR","clue":"Jugador que intenta pegarle a la pelota con el bate","fact":"Un bateador ambidiestro puede batear de ambos lados del plato.","tier":3},{"w":"JARDINERO","clue":"Jugador que cuida la zona de césped lejos del cuadro","fact":"Los jardineros corren mucho y a veces se lanzan al suelo para atrapar una pelota.","tier":3},{"w":"CAMPOCORTO","clue":"Jugador del cuadro que cubre el espacio entre segunda y tercera base","fact":"El campocorto hace tiros largos y rápidos hasta primera base.","tier":3},{"w":"MONTÍCULO","clue":"Pequeña colina de tierra desde donde se lanza","fact":"El montículo puede medir hasta 25 centímetros de altura sobre el resto del campo.","tier":3},{"w":"MARCADOR","clue":"Tablero gigante que muestra las carreras de cada equipo","fact":"En algunos estadios antiguos, el marcador todavía se cambia a mano.","tier":3},{"w":"DIAMANTE","clue":"Figura del campo que forman las cuatro bases","fact":"El cuadro de béisbol es un cuadrado girado de lado, por eso parece un diamante.","tier":3},{"w":"SENCILLO","clue":"Batazo que lleva al bateador solo hasta primera base","fact":"El sencillo es el tipo de hit más común en el béisbol.","tier":3},{"w":"ENTRENADOR","clue":"Adulto que dirige y enseña al equipo","fact":"Los entrenadores dan señales con gestos para decirles a los jugadores qué hacer.","tier":3},{"w":"BOLA","clue":"Lanzamiento fuera de la zona; con cuatro, el bateador camina a primera","fact":"Con cuatro bolas, el bateador camina a primera base sin tener que batear.","tier":1},{"w":"OUT","clue":"Tres de estos terminan la media entrada","fact":"Cada equipo tiene 27 outs en un juego completo de nueve entradas.","tier":1},{"w":"HOME","clue":"La última base, donde el corredor anota su carrera","fact":"El plato de home tiene cinco lados y forma de casita.","tier":1},{"w":"SAFE","clue":"Lo que grita el árbitro cuando el corredor llega a tiempo","fact":"Los árbitros señalan safe abriendo los dos brazos hacia los lados.","tier":1},{"w":"HIT","clue":"Golpe del bateador que lo deja llegar salvo a una base","fact":"Un bateador que conecta tres hits cada diez turnos es considerado excelente.","tier":1},{"w":"ZONA","clue":"Espacio imaginario sobre el plato por donde debe pasar un buen lanzamiento","fact":"La zona de strike va, más o menos, de las rodillas al pecho del bateador.","tier":1},{"w":"SERIE","clue":"Varios juegos seguidos entre los mismos dos equipos","fact":"Los equipos suelen jugar tres o cuatro juegos seguidos contra el mismo rival.","tier":1},{"w":"RED","clue":"Malla detrás del plato que protege a los fanáticos","fact":"Las pelotas de foul pueden volar a más de 160 kilómetros por hora.","tier":1},{"w":"CAL","clue":"Polvo blanco con el que se marcan las líneas del campo","fact":"Las líneas de falta se pintan de blanco para que todos las vean bien.","tier":1},{"w":"ROBO","clue":"Cuando un corredor corre a la siguiente base mientras el lanzador tira","fact":"Un corredor veloz puede aprovechar un descuido del lanzador para robar una base.","tier":1},{"w":"POSTE","clue":"Palo muy alto al final de cada línea blanca del campo","fact":"Si la pelota pega en este poste de falta, cuenta como jonrón.","tier":1},{"w":"FOUL","clue":"Pelota bateada que cae fuera de las líneas blancas del campo","fact":"Un foul cuenta como strike, pero no como el tercero si el bateador ya tiene dos.","tier":1},{"w":"GANAR","clue":"Terminar el juego con más carreras que el rival","fact":"En el béisbol casi no hay empates: si hay igualdad, se juegan entradas extras.","tier":1},{"w":"LUCES","clue":"Torres altas que se encienden para jugar cuando oscurece","fact":"Gracias a estas luces del estadio, se puede jugar béisbol de noche.","tier":1},{"w":"PISAR","clue":"Tocar la base con el pie al llegar corriendo","fact":"Para anotar, un corredor debe pisar cada base en orden.","tier":1},{"w":"TURNO","clue":"Cada vez que un bateador se para en el plato a batear","fact":"Cada bateador espera su turno según el orden de bateo de su equipo.","tier":1},{"w":"BRAZO","clue":"Parte del cuerpo con la que se lanza la pelota","fact":"Un brazo fuerte permite a un jardinero mandar la pelota lejos y rápido.","tier":1},{"w":"MANO","clue":"Parte del cuerpo donde se pone el guante","fact":"Los zurdos lanzan con la mano izquierda y los derechos con la derecha.","tier":1},{"w":"PIE","clue":"Parte del cuerpo que toca la base al llegar","fact":"Un jugador veloz puede llegar de home a primera en unos cuatro segundos.","tier":1},{"w":"TACOS","clue":"Puntas de plástico o metal en la suela de los zapatos","fact":"Los tacos ayudan a los jugadores a no resbalar sobre el pasto y la tierra.","tier":1},{"w":"PASTO","clue":"Hierba corta y verde que cubre el fondo del campo","fact":"Las franjas del pasto se forman porque la podadora lo dobla en distintas direcciones.","tier":1},{"w":"NUEVE","clue":"Número de entradas de un juego normal, escrito con letras","fact":"Cada equipo pone nueve jugadores en el campo cuando defiende.","tier":1},{"w":"OLA","clue":"Movimiento en las gradas cuando los fanáticos se paran uno tras otro","fact":"La multitud hace esta figura levantando los brazos en orden alrededor de todo el estadio.","tier":1},{"w":"TRES","clue":"Cantidad de strikes que ponchan a un bateador, escrita con letras","fact":"Tres strikes ponchan al bateador, y tres outs terminan la media entrada.","tier":1},{"w":"FIRMA","clue":"El nombre de un jugador escrito por él mismo en una pelota","fact":"Muchos aficionados esperan horas para que un jugador les firme su pelota.","tier":1},{"w":"DEDO","clue":"Parte de la mano con que el receptor hace señas","fact":"El receptor usa sus dedos para decirle al lanzador qué lanzamiento tirar.","tier":1},{"w":"TECHO","clue":"Cubierta de algunos estadios que se cierra cuando llueve","fact":"Algunos estadios tienen techo que se abre y se cierra según el clima.","tier":1},{"w":"RECTA","clue":"Lanzamiento muy rápido que viaja derecho hacia el bateador","fact":"Los mejores lanzadores profesionales pueden tirar una recta a más de 150 kilómetros por hora.","tier":1},{"w":"ELEVADO","clue":"Pelota bateada muy alto que cae en el pasto del fondo","fact":"Si un jardinero atrapa un elevado antes de que toque el suelo, es out.","tier":2},{"w":"NOVATO","clue":"Jugador que está en su primer año en las ligas grandes","fact":"Muchos jugadores famosos fueron novatos y aprendieron de sus compañeros veteranos.","tier":2},{"w":"NOVENA","clue":"Nombre antiguo de un equipo de béisbol, por sus jugadores","fact":"Un equipo de béisbol pone nueve jugadores en el campo cuando defiende.","tier":2},{"w":"TROFEO","clue":"Copa o premio que recibe el equipo que gana todo","fact":"Los equipos campeones suelen recibir anillos y trofeos que muestran con orgullo.","tier":2},{"w":"CAMPEÓN","clue":"El equipo que gana la serie final del año","fact":"Los campeones suelen recibir anillos especiales para recordar su título.","tier":2},{"w":"ANOTAR","clue":"Hacer una carrera al tocar el plato final","fact":"Un corredor anota cuando toca el home después de pisar las otras tres bases.","tier":2},{"w":"TIERRA","clue":"Polvo marrón del cuadro con el que se ensucian los uniformes","fact":"La tierra del cuadro se riega y se rastrilla antes de cada juego.","tier":2},{"w":"CÉSPED","clue":"Hierba cuidada y cortada que cubre el campo de juego","fact":"Algunos estadios cerrados usan césped artificial porque el natural no crece sin sol.","tier":2},{"w":"AFICIÓN","clue":"Grupo de seguidores que apoya a su equipo","fact":"Los aficionados llevan camisetas, gorras y banderas con los colores de su equipo.","tier":2},{"w":"APLAUSO","clue":"Sonido de las manos chocando para felicitar una buena jugada","fact":"Una jugada espectacular suele recibir un aplauso de todo el público.","tier":2},{"w":"LANZAR","clue":"Mandar la pelota con fuerza hacia el bateador desde el montículo","fact":"De la goma del montículo al plato hay unos 18 metros de distancia.","tier":2},{"w":"ATRAPAR","clue":"Agarrar la pelota con el guante antes de que caiga","fact":"Los jardineros a veces saltan contra la pared para quitarle un jonrón al bateador.","tier":2},{"w":"CORRER","clue":"Mover las piernas muy rápido para llegar a la siguiente base","fact":"Entre una base y otra hay unos 27 metros de distancia.","tier":2},{"w":"BULLPEN","clue":"Zona donde calientan los lanzadores que van a entrar al juego","fact":"El bullpen suele estar junto al campo, y los relevistas calientan allí.","tier":2},{"w":"ABRIDOR","clue":"El lanzador que empieza el juego","fact":"El abridor suele lanzar durante varias entradas antes de salir del juego.","tier":2},{"w":"CAMISA","clue":"Prenda con el nombre del equipo y un número en la espalda","fact":"Los números en la espalda ayudan a distinguir a los jugadores.","tier":2},{"w":"BANDERA","clue":"Tela con los colores del equipo que ondea en el estadio","fact":"Las banderas de los estadios muestran de qué lado sopla el viento.","tier":2},{"w":"VIENTO","clue":"Aire en movimiento que puede empujar la pelota en pleno vuelo","fact":"Con viento a favor, un batazo puede volar más lejos.","tier":2},{"w":"LLUVIA","clue":"Agua que cae de las nubes y puede cancelar el juego","fact":"Algunos estadios tienen techo para que este clima no cancele el juego.","tier":2},{"w":"BOLETO","clue":"Papel o pase en el celular que necesitas para entrar al estadio","fact":"Muchos aficionados guardan el boleto de su primer juego como recuerdo.","tier":2},{"w":"CONTEO","clue":"El número de bolas y strikes que lleva el bateador","fact":"Con tres bolas y dos strikes se dice que la cuenta está llena.","tier":2},{"w":"DERROTA","clue":"Cuando tu equipo termina un juego con menos carreras que el rival","fact":"Hasta los mejores equipos tienen derrotas durante la temporada.","tier":2},{"w":"EMPATE","clue":"Cuando los dos equipos tienen las mismas carreras","fact":"En béisbol casi nunca terminan en empate porque se juegan entradas extras.","tier":2},{"w":"MÁNAGER","clue":"Líder que escoge la alineación y decide cuándo cambiar al lanzador","fact":"Los mánagers usan el mismo tipo de uniforme que sus jugadores.","tier":2},{"w":"BATEAR","clue":"Golpear la pelota con el palo de madera","fact":"Pegarle a una pelota que viene muy rápido es de lo más difícil del deporte.","tier":2},{"w":"DEFENSA","clue":"El equipo que está en el campo tratando de sacar outs","fact":"En el béisbol, el equipo que defiende es el que tiene la pelota.","tier":2},{"w":"JUGADA","clue":"Acción rápida del juego, como atrapar y tirar para sacar un out","fact":"Con una doble jugada, la defensa puede sacar dos outs en una sola acción.","tier":2},{"w":"PERDER","clue":"Terminar el juego con menos carreras que el rival","fact":"Hasta los mejores equipos del año pierden muchos juegos.","tier":2},{"w":"CUADRO","clue":"Parte del campo con forma de rombo, entre las cuatro bases","fact":"Cada lado del cuadro mide unos 27 metros.","tier":2},{"w":"JARDÍN","clue":"Zona de pasto al fondo del campo, más allá del cuadro","fact":"Cada equipo defiende con tres jardineros: izquierdo, central y derecho.","tier":2},{"w":"VISERA","clue":"Parte de la gorra que da sombra a los ojos","fact":"La visera de la gorra protege los ojos del sol cuando la pelota sube.","tier":2},{"w":"COSTURA","clue":"Hilo rojo que une las piezas de cuero de la pelota","fact":"Una pelota de béisbol tiene 108 puntadas rojas.","tier":2},{"w":"CORREDOR","clue":"Jugador parado en una base que intenta llegar hasta el home","fact":"Los corredores deben tocar las bases en orden: primera, segunda, tercera y home.","tier":3},{"w":"CERRADOR","clue":"Lanzador que entra al final para proteger una ventaja","fact":"Un cerrador suele lanzar solo una entrada, la última del juego.","tier":3},{"w":"RELEVISTA","clue":"Lanzador que sustituye al abridor cuando se cansa","fact":"Los relevistas esperan en el bullpen hasta que el mánager los llama.","tier":3},{"w":"UNIFORME","clue":"Ropa igual que usan todos los compañeros de un equipo","fact":"Muchos equipos usan uniforme blanco en casa y gris cuando juegan de visitantes.","tier":3},{"w":"PALOMITAS","clue":"Maíz inflado y crujiente que se vende en el estadio","fact":"Las palomitas revientan porque el agua dentro del grano se convierte en vapor.","tier":3},{"w":"VENDEDOR","clue":"Persona que pasea por las gradas ofreciendo comida y bebidas","fact":"Los vendedores caminan entre los asientos gritando lo que venden.","tier":3},{"w":"PELOTERO","clue":"Nombre que dan en el Caribe a un jugador de béisbol","fact":"En el Caribe llaman peloteros a los jugadores de béisbol.","tier":3},{"w":"DESLIZARSE","clue":"Tirarse al suelo para llegar a la base más rápido","fact":"Los jugadores se deslizan con los pies o con la cabeza por delante.","tier":3},{"w":"FANÁTICO","clue":"Persona que anima con mucha pasión a su equipo","fact":"Muchos fanáticos pintan su cara con los colores de su equipo.","tier":3},{"w":"VETERANO","clue":"Jugador con muchos años de experiencia","fact":"Los veteranos enseñan a los novatos los secretos del juego.","tier":3},{"w":"PRÁCTICA","clue":"Sesión de ejercicios antes del juego para mejorar","fact":"Antes del juego hay práctica de bateo, con pelotas lanzadas por un entrenador.","tier":3},{"w":"NARRADOR","clue":"Voz de la radio que cuenta cada jugada","fact":"Los narradores describen cada lanzamiento para que los oyentes imaginen el juego.","tier":3},{"w":"CALENDARIO","clue":"Lista de fechas con los juegos de un equipo","fact":"El calendario de béisbol es largo porque se juega casi todos los días en verano.","tier":3},{"w":"ESTADÍSTICA","clue":"Números que registran los hits y las carreras de cada jugador","fact":"A los fanáticos les encantan las estadísticas, y algunos anotan decenas de números por jugador.","tier":3},{"w":"ESTRATEGIA","clue":"Plan para ganar, como decidir cuándo tocar o robar una base","fact":"Los mánagers planean qué lanzador enfrenta a cada bateador usando datos de juegos pasados.","tier":3},{"w":"CELEBRAR","clue":"Saltar, gritar y abrazarse después de ganar un juego importante","fact":"Tras una gran victoria, los equipos suelen reunirse en el campo para celebrar juntos.","tier":3},{"w":"ESTRELLA","clue":"Jugador muy famoso y talentoso que todos admiran","fact":"Cada año, los mejores jugadores son invitados a un juego de estrellas.","tier":3},{"w":"COMPAÑERO","clue":"Jugador de tu mismo equipo","fact":"Los compañeros chocan las manos después de una buena jugada.","tier":3},{"w":"AUTÓGRAFO","clue":"Firma de un jugador famoso, un tesoro para los fanáticos","fact":"Los jugadores firman pelotas, tarjetas y bates para los fanáticos que esperan.","tier":3},{"w":"SUPLENTE","clue":"Jugador que espera en la banca y entra si lo necesitan","fact":"Los suplentes esperan en el banquillo hasta que el mánager los llama.","tier":3},{"w":"VICTORIA","clue":"Cuando tu equipo gana el juego","fact":"Después de una victoria, los jugadores suelen chocar las manos en fila.","tier":3},{"w":"ALINEACIÓN","clue":"Lista que dice quién batea primero, segundo, tercero y así sucesivamente","fact":"El mánager escribe la alineación en una tarjeta antes de cada juego.","tier":3},{"w":"TEMPORADA","clue":"Meses de primavera a otoño en que se juegan los partidos","fact":"Los equipos profesionales juegan más de cien partidos en una sola temporada.","tier":3},{"w":"OFENSIVA","clue":"Lo que hace el equipo que está bateando para anotar carreras","fact":"La ofensiva manda a sus bateadores al plato en un orden fijo.","tier":3}]}},{"id":"land-animals","icon":"🦁","name":{"en":"Land Animals","es":"Animales de la tierra"},"words":{"en":[{"w":"LION","clue":"Big cat whose males wear a shaggy mane","fact":"Lions live in family groups called prides, unlike most other big cats.","tier":1},{"w":"BEAR","clue":"Big furry animal that sleeps through winter in a den","fact":"Bears can run faster than most people, even though they look slow and heavy.","tier":1},{"w":"WOLF","clue":"Wild relative of dogs that howls with its pack","fact":"A wolf's howl can be heard from several miles away.","tier":1},{"w":"DEER","clue":"Graceful animal whose males grow antlers","fact":"A male deer sheds its antlers every year and grows a new set.","tier":1},{"w":"MOOSE","clue":"Giant deer with huge flat antlers and a floppy nose","fact":"Moose are great swimmers and can even dive underwater to find plants.","tier":1},{"w":"ZEBRA","clue":"Striped relative of the horse from African plains","fact":"Every zebra has its own stripe pattern, like a fingerprint.","tier":1},{"w":"SLOTH","clue":"Super-slow tree dweller that hangs upside down","fact":"Sloths come down from their tree only about once a week to go to the bathroom.","tier":1},{"w":"PANDA","clue":"Black-and-white bear that munches bamboo","fact":"Giant pandas spend up to twelve hours a day eating bamboo.","tier":1},{"w":"KOALA","clue":"Fuzzy Australian tree-climber that sleeps most of the day","fact":"Koalas are not bears; they are marsupials that carry babies in a pouch.","tier":1},{"w":"HIPPO","clue":"Huge, round African animal that spends the day in water","fact":"Hippos make a reddish, oily liquid that helps protect their skin from the sun.","tier":1},{"w":"CAMEL","clue":"Desert animal with humps on its back","fact":"A camel's hump stores fat, not water.","tier":1},{"w":"SKUNK","clue":"Black-and-white animal that sprays a stinky mist","fact":"A skunk can spray from about ten feet away.","tier":1},{"w":"GIRAFFE","clue":"Tallest animal on land, with a very long neck","fact":"A giraffe has the same number of neck bones as you: seven.","tier":2},{"w":"CHEETAH","clue":"Spotted cat that sprints faster than any other land animal","fact":"Cheetahs cannot roar; they purr and chirp like house cats.","tier":2},{"w":"GORILLA","clue":"Biggest ape, gentle and strong, from African forests","fact":"Gorillas build a fresh nest of leaves each night to sleep in.","tier":2},{"w":"LEOPARD","clue":"Spotted big cat that drags its meals up into trees","fact":"A leopard can carry prey heavier than itself up a tree.","tier":2},{"w":"MONKEY","clue":"Clever, tail-swinging climber that is smaller than an ape","fact":"Apes, like gorillas, have no tails, but most monkeys do.","tier":2},{"w":"BEAVER","clue":"Busy builder with a flat tail and big front teeth","fact":"Beavers build dams that make ponds to protect their homes, called lodges.","tier":2},{"w":"OSTRICH","clue":"Largest bird alive; it runs fast but cannot fly","fact":"An ostrich egg is about as big as two dozen chicken eggs.","tier":2},{"w":"MEERKAT","clue":"Small desert animal that stands on its back legs to look around","fact":"Meerkats take turns standing guard to warn the group of danger.","tier":2},{"w":"JAGUAR","clue":"Spotted big cat of the Americas that swims well","fact":"Unlike most cats, jaguars love water and are strong swimmers.","tier":2},{"w":"COYOTE","clue":"Yipping wild relative of dogs found across North America","fact":"Coyotes have adapted so well that some live in big cities.","tier":2},{"w":"RACCOON","clue":"Masked-faced animal with a ringed tail and nimble paws","fact":"Raccoons have very sensitive front paws that help them feel for food.","tier":2},{"w":"WOMBAT","clue":"Chubby digging marsupial from Australia","fact":"Wombats are the only animals known to make cube-shaped droppings.","tier":2},{"w":"PARROT","clue":"Colorful bird that can copy human words","fact":"Parrots have two toes pointing forward and two back, which helps them grip.","tier":2},{"w":"BADGER","clue":"Short-legged digger with a striped face","fact":"Badgers dig underground homes called setts, with many tunnels.","tier":2},{"w":"ELEPHANT","clue":"Giant gray animal with a trunk and tusks","fact":"An elephant's trunk can pick up a single peanut or lift a heavy log.","tier":3},{"w":"KANGAROO","clue":"Hopping Australian animal that carries its baby in a pouch","fact":"A baby kangaroo is born about the size of a jellybean.","tier":3},{"w":"PORCUPINE","clue":"Rodent covered in sharp quills","fact":"A porcupine cannot shoot its quills; they only stick in if something touches it.","tier":3},{"w":"HEDGEHOG","clue":"Small spiky mammal that rolls into a ball","fact":"A hedgehog has thousands of spines, which it can fluff up to look bigger.","tier":3},{"w":"ARMADILLO","clue":"Mammal with bony armor plates; some can roll into a ball","fact":"Nine-banded armadillos usually have four identical babies at a time.","tier":3},{"w":"ANTEATER","clue":"Long-snouted animal that slurps up insects with a sticky tongue","fact":"A giant anteater can flick its tongue about 150 times in one minute.","tier":3},{"w":"CHIMPANZEE","clue":"Clever ape that uses sticks as tools","fact":"Chimpanzees poke sticks into termite mounds to fish out a snack.","tier":3},{"w":"ORANGUTAN","clue":"Red-haired ape of Borneo's rainforests with very long arms","fact":"Its name means \"person of the forest\" in the Malay language.","tier":3},{"w":"CHAMELEON","clue":"Lizard that changes color and has bulging, swiveling eyes","fact":"Chameleons can aim each eye in a different direction at the same time.","tier":3},{"w":"RHINOCEROS","clue":"Thick-skinned giant with one or two horns on its nose","fact":"A rhino's horn is made of keratin, the same stuff as your fingernails.","tier":3},{"w":"TIGER","clue":"Biggest wild cat, orange with black stripes","fact":"No two tigers have the same stripe pattern, much like human fingerprints.","tier":1},{"w":"FOX","clue":"Clever wild relative of dogs with a bushy tail and pointed ears","fact":"Foxes hear tiny sounds, so they can find a mouse hiding under snow.","tier":1},{"w":"HARE","clue":"Fast, long-eared cousin of the rabbit that lives above ground","fact":"Baby hares are born with fur and open eyes and can hop soon after birth.","tier":1},{"w":"GOAT","clue":"Hoofed farm animal with a beard that is great at climbing rocks","fact":"Goats have rectangular pupils, which give them a wide view of their surroundings.","tier":1},{"w":"YAK","clue":"Shaggy, long-haired ox that lives high in the Himalayas","fact":"Yaks have large lungs and hearts that help them breathe thin mountain air.","tier":1},{"w":"ELK","clue":"Large deer of North America with huge branching antlers","fact":"A male elk makes a loud whistling call called a bugle.","tier":1},{"w":"LYNX","clue":"Wild cat with ear tufts and a stubby tail","fact":"A lynx has big furry paws that work like built-in snowshoes.","tier":1},{"w":"MOLE","clue":"Small underground digger with velvety fur and tiny eyes","fact":"Moles dig long tunnels using big, shovel-shaped front paws.","tier":1},{"w":"BISON","clue":"Huge shaggy animal with a humped back that roams prairies","fact":"A bison can run about 35 miles per hour, much faster than most people.","tier":1},{"w":"HORSE","clue":"Animal people ride, with a flowing mane and hard hooves","fact":"Horses can sleep while standing up because their legs lock in place.","tier":1},{"w":"SNAKE","clue":"Long legless reptile that slithers along the ground","fact":"Snakes smell by flicking their forked tongues in and out.","tier":1},{"w":"GECKO","clue":"Small lizard that can climb walls and walk on ceilings","fact":"Gecko toes have millions of tiny hairs that help them stick to smooth surfaces.","tier":1},{"w":"OKAPI","clue":"Shy rainforest relative of the giraffe with striped legs","fact":"Okapis can lick their own ears and eyes with their very long tongues.","tier":1},{"w":"EMU","clue":"Tall flightless bird of Australia that runs very fast","fact":"An emu can run about 30 miles per hour on its long legs.","tier":1},{"w":"HYENA","clue":"Spotted African hunter famous for a giggly, laughing call","fact":"Hyena clans are led by females, who are bigger than the males.","tier":1},{"w":"LEMUR","clue":"Big-eyed primate with a long ringed tail from Madagascar","fact":"Wild lemurs live only on Madagascar and a few nearby islands.","tier":1},{"w":"DINGO","clue":"Wild dog of Australia with a sandy-yellow coat","fact":"Dingoes came to Australia thousands of years ago, likely on boats with travelers.","tier":1},{"w":"ANT","clue":"Tiny insect that marches in long lines back to its colony","fact":"An ant can lift something many times heavier than its own body.","tier":1},{"w":"TUSK","clue":"Long pointed tooth sticking out of an elephant's mouth","fact":"An elephant's tusks are really its two extra-long front teeth.","tier":1},{"w":"MANE","clue":"Thick hair around a male lion's head and neck","fact":"Only male lions grow a mane; females have none.","tier":1},{"w":"HORN","clue":"Hard, pointed bump on a rhino's snout","fact":"A rhino's horn is made of keratin, the same stuff as your fingernails.","tier":1},{"w":"PACK","clue":"Group of wolves that live and hunt together","fact":"A wolf pack is usually a family: a mother, a father and their young.","tier":1},{"w":"TRUNK","clue":"An elephant's long, bendy nose","fact":"An elephant's trunk has tens of thousands of muscles but no bones.","tier":1},{"w":"HUMP","clue":"Fatty bump on the back of a camel","fact":"A camel's hump stores fat, not water.","tier":1},{"w":"ROAR","clue":"Loud, deep sound a lion makes","fact":"A lion's roar can be heard from about five miles away.","tier":1},{"w":"HOWL","clue":"Long, loud cry that wolves send up into the night","fact":"Wolves howl to talk to pack members who are far away.","tier":1},{"w":"GRAZE","clue":"Eat grass in a field, like cows and zebras do","fact":"Cows spend many hours each day eating grass and chewing it again.","tier":1},{"w":"CLAW","clue":"Sharp curved nail on a cat's paw","fact":"Most cats can pull their claws in so they stay sharp.","tier":1},{"w":"TURTLE","clue":"Slow reptile that carries a hard shell on its back","fact":"A turtle's shell is part of its skeleton, so it can never take it off.","tier":2},{"w":"LIZARD","clue":"Scaly reptile with four legs and a long tail","fact":"Some lizards can drop their tails to escape, then grow new ones.","tier":2},{"w":"IGUANA","clue":"Large green tropical lizard with a row of spikes down its back","fact":"Iguanas bask in the sun because they need outside heat to warm their bodies.","tier":2},{"w":"RABBIT","clue":"Hopping animal with long ears and a twitchy nose","fact":"A rabbit's teeth never stop growing, so chewing keeps them worn down.","tier":2},{"w":"GAZELLE","clue":"Small graceful antelope that bounds across African grasslands","fact":"Some gazelles can sprint around 50 miles per hour in short bursts.","tier":2},{"w":"WARTHOG","clue":"African wild pig with curved tusks and bumps on its face","fact":"Warthogs often kneel on their front knees while they munch grass.","tier":2},{"w":"ANTLER","clue":"Branching bone that grows from a deer's head and falls off yearly","fact":"Most deer shed their antlers every year and grow a bigger set.","tier":2},{"w":"COUGAR","clue":"Big tan cat of the Americas, also called a mountain lion","fact":"Cougars cannot roar, but they can purr like pet cats.","tier":2},{"w":"WEASEL","clue":"Slim, quick hunter with a long body and short legs","fact":"Weasels are small enough to chase mice right into their tunnels.","tier":2},{"w":"OPOSSUM","clue":"Pouched animal that can play dead when scared","fact":"Baby opossums ride on their mother's back as she walks.","tier":2},{"w":"BOBCAT","clue":"Wild North American cat with tufted ears and a short, bobbed tail","fact":"Bobcats are strong swimmers and good climbers.","tier":2},{"w":"BUFFALO","clue":"Huge wild ox with heavy curved horns that wallows in mud","fact":"Water buffalo roll in mud to stay cool and keep insects away.","tier":2},{"w":"DONKEY","clue":"Gray farm animal like a small horse with long ears","fact":"A donkey's loud bray can be heard from miles away.","tier":2},{"w":"SPIDER","clue":"Eight-legged creature that spins silk webs","fact":"Spiders are not insects, because insects have six legs and spiders have eight.","tier":2},{"w":"BEETLE","clue":"Insect with hard wing covers like a shell","fact":"Scientists have named more kinds of beetles than any other group of animals.","tier":2},{"w":"MANTIS","clue":"Insect that folds its front legs as if praying","fact":"A praying mantis can turn its head to look over its own shoulder.","tier":2},{"w":"CRICKET","clue":"Insect that chirps by rubbing its wings together","fact":"Crickets have ears on their front legs, just below the knees.","tier":2},{"w":"KOMODO","clue":"The largest lizard in the world is this kind of dragon","fact":"Komodo dragons can smell food from miles away using their forked tongues.","tier":2},{"w":"PEACOCK","clue":"Male bird with a giant shimmering fan of tail feathers","fact":"A peacock spreads its tail feathers wide to show off to peahens.","tier":2},{"w":"BABOON","clue":"Large African monkey with a long, dog-like snout","fact":"Baboons live in big groups called troops and groom one another.","tier":2},{"w":"WALLABY","clue":"Small kangaroo relative that hops on strong back legs","fact":"Baby wallabies, called joeys, live in their mother's pouch.","tier":2},{"w":"ALPACA","clue":"Fluffy South American animal raised for its soft wool","fact":"Alpacas hum to each other.","tier":2},{"w":"JACKAL","clue":"Wild dog of Africa and Asia that is smaller than a wolf","fact":"Jackals call to each other with howls and yips to stay in touch.","tier":2},{"w":"OCELOT","clue":"Spotted wild cat of Central and South America","fact":"Ocelots hunt mostly at night and often nap in trees or thick brush.","tier":2},{"w":"BURROW","clue":"Underground tunnel or hole a rabbit digs to live in","fact":"Prairie dogs dig burrows with many rooms, like little underground houses.","tier":2},{"w":"HABITAT","clue":"The natural place where an animal finds food, water and shelter","fact":"A habitat can be a forest, a desert, a grassland or even a pond.","tier":2},{"w":"MIGRATE","clue":"Travel a long way each year to find food or warmth","fact":"Huge herds of wildebeest migrate across Africa following the rains.","tier":2},{"w":"STRIPES","clue":"Long bands of color on a tiger or a zebra","fact":"No two zebras have exactly the same pattern of stripes.","tier":2},{"w":"WHISKER","clue":"Long stiff hair on a cat's face that senses things nearby","fact":"A cat's whiskers are about as wide as its body, helping it judge tight gaps.","tier":2},{"w":"QUILLS","clue":"Sharp spines covering a porcupine's back","fact":"A porcupine cannot shoot its quills; they only stick when touched.","tier":2},{"w":"POUNCE","clue":"Leap suddenly onto prey, the way a cat does","fact":"Cats often wiggle their back ends before they pounce.","tier":2},{"w":"GIBBON","clue":"Small ape that swings through trees using very long arms","fact":"Gibbon pairs sing loud duets that echo through the forest.","tier":2},{"w":"SQUIRREL","clue":"Bushy-tailed climber that buries acorns","fact":"Squirrels forget where they bury many nuts, so new trees sprout from them.","tier":3},{"w":"CHIPMUNK","clue":"Small striped rodent that stuffs its cheeks with seeds","fact":"Chipmunks have stretchy cheek pouches that carry seeds back to their burrows.","tier":3},{"w":"ANTELOPE","clue":"Fast hoofed grazer of Africa with horns, like an impala","fact":"Antelopes keep their horns for life, unlike deer, which shed their antlers.","tier":3},{"w":"TORTOISE","clue":"Slow land reptile with a high, domed shell","fact":"Some giant tortoises live for well over a hundred years.","tier":3},{"w":"GROUNDHOG","clue":"Burrower famous for supposedly predicting spring each February","fact":"A groundhog's heartbeat drops a lot during its long winter sleep.","tier":3},{"w":"SCORPION","clue":"Desert creature with pincers and a curved tail with a stinger","fact":"Scorpions glow blue-green under ultraviolet light.","tier":3},{"w":"BUTTERFLY","clue":"Flying insect with big colorful wings that starts life as a caterpillar","fact":"Butterflies taste with their feet.","tier":3},{"w":"GRASSHOPPER","clue":"Green insect with powerful back legs that leaps through fields","fact":"A grasshopper can jump about twenty times the length of its own body.","tier":3},{"w":"CATERPILLAR","clue":"Wiggly, many-legged larva that becomes a butterfly or moth","fact":"Inside its chrysalis or cocoon, a caterpillar changes completely into a flying insect.","tier":3},{"w":"PLATYPUS","clue":"Australian mammal that lays eggs and has a duck-like bill","fact":"A platypus finds food underwater using sensors in its bill.","tier":3},{"w":"MONGOOSE","clue":"Slim, speedy close cousin of the meerkat found in Africa and Asia","fact":"Banded mongooses live in groups and take turns watching over the babies.","tier":3},{"w":"PANGOLIN","clue":"Scaly mammal that curls into a ball when frightened","fact":"Pangolins are the only mammals covered in hard scales.","tier":3},{"w":"CHINCHILLA","clue":"Fluffy South American rodent with super soft gray fur","fact":"Chinchillas take dust baths instead of water baths to keep their fur clean.","tier":3},{"w":"ALLIGATOR","clue":"Broad-snouted swamp reptile found in Florida and China","fact":"Alligator mothers gently carry their hatchlings to the water in their mouths.","tier":3},{"w":"AARDVARK","clue":"African night digger that licks up termites with a long, sticky tongue","fact":"Aardvark means earth pig in Afrikaans, a language of South Africa.","tier":3},{"w":"MANDRILL","clue":"Big monkey with a bright red and blue face","fact":"The mandrill is the largest kind of monkey in the world.","tier":3},{"w":"REINDEER","clue":"Cold-weather deer that migrates in huge herds across the Arctic","fact":"Reindeer are the only deer where both males and females grow antlers.","tier":3},{"w":"CAPYBARA","clue":"South American animal that is the biggest rodent in the world","fact":"Birds often perch on a capybara's back, and the capybara does not mind.","tier":3},{"w":"PREDATOR","clue":"Animal that hunts other animals for food","fact":"Predators usually have sharp teeth, keen eyes or strong claws for catching prey.","tier":3},{"w":"HERBIVORE","clue":"Animal that eats only plants","fact":"Elephants eat only plants but can munch over a hundred pounds a day.","tier":3},{"w":"CARNIVORE","clue":"Animal whose diet is mostly meat","fact":"Cats cannot taste sweetness, and they need meat in their diet to stay healthy.","tier":3},{"w":"NOCTURNAL","clue":"Active at night and asleep during the day","fact":"Owls, bats and many mice are busiest after dark.","tier":3},{"w":"HIBERNATE","clue":"Sleep deeply through the cold winter months","fact":"A sleeping bear's heartbeat drops way down to save energy all winter.","tier":3},{"w":"CAMOUFLAGE","clue":"Colors or patterns that help an animal blend in","fact":"A leopard's spots help it blend into leafy shadows.","tier":3}],"es":[{"w":"LEÓN","clue":"Felino grande cuyos machos tienen una melena","fact":"Los leones viven en familias grandes llamadas manadas, a diferencia de otros grandes felinos.","tier":1},{"w":"OSO","clue":"Animal grande y peludo que duerme en invierno","fact":"Los osos pueden correr más rápido que la mayoría de las personas, aunque parezcan pesados.","tier":1},{"w":"LOBO","clue":"Pariente salvaje del perro que aúlla en grupo","fact":"El aullido de un lobo se puede oír desde varios kilómetros.","tier":1},{"w":"ZORRO","clue":"Animal astuto de cola esponjosa y hocico puntiagudo","fact":"El zorro usa su cola esponjosa como una manta para abrigarse al dormir.","tier":1},{"w":"CEBRA","clue":"Pariente rayado del caballo que vive en la sabana","fact":"Cada cebra tiene un patrón de rayas único, como una huella digital.","tier":1},{"w":"PUMA","clue":"Felino americano de pelaje color arena que vive en los Andes","fact":"El puma ronronea como un gato casero, pero no puede rugir.","tier":1},{"w":"LLAMA","clue":"Animal andino de cuello largo, lana suave y cara graciosa","fact":"Las llamas llevan carga en los Andes desde hace miles de años.","tier":1},{"w":"TAPIR","clue":"Animal de la selva con nariz larga y flexible como una trompita","fact":"El tapir usa su nariz flexible como un snorkel cuando nada.","tier":1},{"w":"PANDA","clue":"Oso blanco y negro que come bambú","fact":"El panda gigante pasa hasta doce horas al día comiendo bambú.","tier":1},{"w":"CUY","clue":"Roedor andino de pelo suave y chillidos agudos","fact":"Los cuyes viven junto a las personas en los Andes desde hace miles de años.","tier":1},{"w":"ALCE","clue":"Ciervo gigante de cuernos anchos y planos","fact":"Los alces son buenos nadadores y pueden sumergirse para comer plantas.","tier":1},{"w":"MONO","clue":"Trepador ágil de cola larga, más pequeño que un simio","fact":"La mayoría de los monos tiene cola, pero los simios, como los gorilas, no.","tier":1},{"w":"JIRAFA","clue":"El animal terrestre más alto, de cuello larguísimo","fact":"La jirafa tiene siete huesos en el cuello, igual que tú.","tier":2},{"w":"CAMELLO","clue":"Animal del desierto con jorobas en el lomo","fact":"La joroba del camello guarda grasa, no agua.","tier":2},{"w":"CIERVO","clue":"Animal elegante cuyos machos tienen astas ramificadas","fact":"Los ciervos mudan las astas cada año y les crecen nuevas.","tier":2},{"w":"GORILA","clue":"El simio más grande, fuerte y tranquilo, de África","fact":"Cada noche el gorila arma un nido nuevo de hojas para dormir.","tier":2},{"w":"JAGUAR","clue":"Felino manchado de las selvas americanas que nada muy bien","fact":"A diferencia de la mayoría de los gatos, al jaguar le encanta el agua.","tier":2},{"w":"VICUÑA","clue":"Animal andino de lana finísima, pariente de la llama","fact":"La lana de vicuña es una de las más finas del mundo.","tier":2},{"w":"ALPACA","clue":"Pariente de la llama que se cría por su lana suave","fact":"La lana de alpaca abriga mucho y se encuentra en más de veinte colores naturales.","tier":2},{"w":"COYOTE","clue":"Salvaje parecido a un perro que aúlla de noche en Norteamérica","fact":"Los coyotes se han adaptado tan bien que algunos viven en grandes ciudades.","tier":2},{"w":"MAPACHE","clue":"Animal de antifaz negro y cola con anillos","fact":"Los mapaches tienen patas delanteras muy sensibles para tantear su comida.","tier":2},{"w":"ARDILLA","clue":"Roedor de cola esponjosa que guarda nueces","fact":"Muchas ardillas olvidan dónde enterraron semillas y así ayudan a que nazcan árboles.","tier":2},{"w":"CASTOR","clue":"Constructor de presas con cola plana y dientes fuertes","fact":"Los castores construyen presas que forman estanques para proteger sus casas.","tier":2},{"w":"CANGURO","clue":"Saltador australiano que lleva a su cría en una bolsa","fact":"Al nacer, una cría de canguro mide menos que tu dedo pulgar.","tier":2},{"w":"BÚFALO","clue":"Animal grande con cuernos curvos que vive en manadas","fact":"Los búfalos africanos viven en manadas y se agrupan para proteger a sus crías.","tier":2},{"w":"PANTERA","clue":"Felino de pelaje negro que vive en la selva","fact":"Una pantera negra es en realidad un jaguar o un leopardo de pelaje muy oscuro.","tier":2},{"w":"ELEFANTE","clue":"Gigante gris con trompa y colmillos","fact":"La trompa del elefante puede recoger un maní o levantar un tronco pesado.","tier":3},{"w":"PEREZOSO","clue":"Trepador lentísimo de la selva que cuelga boca abajo","fact":"Los perezosos bajan del árbol solo una vez por semana, más o menos.","tier":3},{"w":"RINOCERONTE","clue":"Gigante de piel gruesa con uno o dos cuernos en la nariz","fact":"El cuerno del rinoceronte está hecho de queratina, igual que tus uñas.","tier":3},{"w":"HIPOPÓTAMO","clue":"Enorme animal africano que pasa el día en el agua","fact":"El hipopótamo produce un líquido rojizo que lo protege del sol.","tier":3},{"w":"ARMADILLO","clue":"Mamífero con placas duras como una armadura; algunos se hacen bolita","fact":"El armadillo de nueve bandas casi siempre tiene cuatro crías idénticas.","tier":3},{"w":"CHIMPANCÉ","clue":"Simio listo que usa palitos como herramientas","fact":"Los chimpancés usan ramitas para sacar termitas de sus nidos.","tier":3},{"w":"ORANGUTÁN","clue":"Simio de pelo rojizo de Borneo con brazos larguísimos","fact":"Su nombre significa \"persona de la selva\" en lengua malaya.","tier":3},{"w":"CAMALEÓN","clue":"Lagarto que cambia de color y mueve cada ojo por separado","fact":"Un camaleón puede mirar en dos direcciones a la vez, una con cada ojo.","tier":3},{"w":"PUERCOESPÍN","clue":"Roedor cubierto de púas largas y afiladas","fact":"El puercoespín no lanza sus púas; solo se clavan si lo tocan.","tier":3},{"w":"GUEPARDO","clue":"Felino manchado que corre más rápido que cualquier animal terrestre","fact":"Los guepardos no rugen: ronronean y pían como gatitos.","tier":3},{"w":"TIGRE","clue":"El felino más grande del mundo, naranja con rayas negras","fact":"Las rayas de cada tigre son únicas, como las huellas dactilares de las personas.","tier":1},{"w":"TOPO","clue":"Animal pequeño de pelaje suave que vive cavando túneles bajo tierra","fact":"Los topos cavan túneles largos con sus patas delanteras anchas, como palas.","tier":1},{"w":"RANA","clue":"Anfibio verde de piel lisa que salta y croa","fact":"Una rana atrapa insectos con una lengua pegajosa que sale en un instante.","tier":1},{"w":"SAPO","clue":"Primo de la rana, de piel rugosa, que vive más en tierra","fact":"Un sapo puede comer cientos de insectos en una sola noche.","tier":1},{"w":"GECO","clue":"Lagartija pequeña que trepa paredes y camina por el techo","fact":"Los dedos del geco tienen millones de pelitos que se pegan a las superficies lisas.","tier":1},{"w":"EMÚ","clue":"Ave alta de Australia que no vuela pero corre muy rápido","fact":"Un emú puede correr a unos 50 kilómetros por hora.","tier":1},{"w":"HIENA","clue":"Cazadora africana con manchas, famosa por su risa","fact":"Los clanes de hienas son dirigidos por hembras, que son más grandes que los machos.","tier":1},{"w":"LÉMUR","clue":"Primate de ojos grandes y cola con anillos, de Madagascar","fact":"Los lémures salvajes viven solo en Madagascar y en unas pocas islas cercanas.","tier":1},{"w":"DINGO","clue":"Perro salvaje de Australia, de pelaje amarillo arenoso","fact":"Los dingos llegaron a Australia hace miles de años, probablemente en barcos con viajeros.","tier":1},{"w":"KOALA","clue":"Animal australiano que duerme casi todo el día abrazado a un eucalipto","fact":"Los koalas duermen unas 18 horas al día porque las hojas de eucalipto dan poca energía.","tier":1},{"w":"ERIZO","clue":"Animal pequeño cubierto de espinas que se hace bolita","fact":"Cuando se asusta, un erizo se hace bolita y esconde su cara y sus patas.","tier":1},{"w":"COATÍ","clue":"Animal de nariz larga y cola con anillos, primo del mapache","fact":"Los coatíes usan su hocico largo para buscar insectos entre las hojas.","tier":1},{"w":"LORO","clue":"Ave de colores que repite palabras que escucha","fact":"Algunos loros pueden imitar la voz humana y aprender muchas palabras.","tier":1},{"w":"CABRA","clue":"Animal de granja con barba y cuernos que trepa rocas","fact":"Las cabras tienen pupilas rectangulares que les dan una vista muy amplia.","tier":1},{"w":"LINCE","clue":"Gato salvaje con mechones en las orejas y cola corta","fact":"Un lince tiene patas peludas y anchas que funcionan como raquetas de nieve.","tier":1},{"w":"TUCÁN","clue":"Ave tropical con un pico enorme y colorido","fact":"El enorme pico del tucán es ligero porque por dentro es casi hueco.","tier":1},{"w":"BOA","clue":"Serpiente grande y sin veneno que aprieta con su cuerpo","fact":"Las boas atrapan a sus presas apretándolas con su cuerpo, no con veneno.","tier":1},{"w":"OVEJA","clue":"Animal de granja cubierto de lana que dice bee","fact":"Con la lana de una oveja se hacen suéteres, bufandas y gorros.","tier":1},{"w":"GARRA","clue":"Uña fuerte, curva y afilada de un gato","fact":"La mayoría de los gatos pueden esconder sus garras para mantenerlas afiladas.","tier":1},{"w":"PÚAS","clue":"Espinas largas y duras que cubren a un erizo","fact":"Un erizo tiene miles de púas, y cada una es un pelo endurecido.","tier":1},{"w":"CRÍA","clue":"Bebé de un animal","fact":"Las crías de muchos mamíferos beben la leche de su mamá.","tier":1},{"w":"NIDO","clue":"Casita de ramitas y plumas donde un ave pone sus huevos","fact":"Algunas aves construyen su nido con ramitas, barro y hasta telarañas.","tier":1},{"w":"RUGIR","clue":"Hacer el sonido fuerte y profundo de un león","fact":"El rugido de un león puede oírse desde unos ocho kilómetros de distancia.","tier":1},{"w":"CUEVA","clue":"Hueco grande dentro de una montaña donde duermen osos y murciélagos","fact":"Los osos pueden pasar el invierno durmiendo dentro de una cueva.","tier":1},{"w":"SELVA","clue":"Bosque cálido y húmedo, lleno de árboles altos y animales","fact":"En la selva viven monos, jaguares, tucanes y muchísimos insectos.","tier":1},{"w":"CAZAR","clue":"Perseguir a otro animal para comérselo","fact":"Los leones suelen cazar en grupo, y las hembras hacen casi todo el trabajo.","tier":1},{"w":"PATA","clue":"Pie de un perro, un gato u otro animal","fact":"Las almohadillas de la pata de un gato le ayudan a caminar sin hacer ruido.","tier":1},{"w":"ARAÑA","clue":"Animal de ocho patas que teje telas de seda","fact":"Las arañas no son insectos: tienen ocho patas y los insectos tienen seis.","tier":1},{"w":"LIEBRE","clue":"Pariente veloz del conejo, de orejas muy largas","fact":"Las liebres nacen con pelo y ojos abiertos, y saltan poco después.","tier":2},{"w":"BISONTE","clue":"Animal enorme y peludo con joroba que recorre las praderas","fact":"Un bisonte puede correr a unos 55 kilómetros por hora.","tier":2},{"w":"CABALLO","clue":"Animal que se monta, con crin larga y cascos duros","fact":"Los caballos pueden dormir de pie porque sus patas se traban en su lugar.","tier":2},{"w":"TORTUGA","clue":"Reptil lento que lleva un caparazón duro en la espalda","fact":"El caparazón de una tortuga es parte de su esqueleto, así que no puede quitárselo.","tier":2},{"w":"LAGARTO","clue":"Reptil de piel con escamas, cuatro patas y cola larga","fact":"Algunos lagartos sueltan la cola para escapar y luego les crece otra.","tier":2},{"w":"IGUANA","clue":"Reptil verde tropical con una fila de púas en el lomo","fact":"Las iguanas toman el sol porque necesitan calor de afuera para calentar su cuerpo.","tier":2},{"w":"CAIMÁN","clue":"Reptil americano de hocico ancho que vive en ríos y pantanos","fact":"Las mamás caimán llevan a sus crías con cuidado en la boca hasta el agua.","tier":2},{"w":"CÓNDOR","clue":"Ave gigante de los Andes que planea muy alto","fact":"Los cóndores pueden planear durante horas casi sin mover las alas.","tier":2},{"w":"CHACAL","clue":"Perro salvaje de África y Asia, más pequeño que un lobo","fact":"Los chacales se llaman entre sí con aullidos para no perderse.","tier":2},{"w":"GACELA","clue":"Antílope pequeño y elegante que da saltos en la sabana","fact":"Algunas gacelas pueden correr a unos 80 kilómetros por hora en carreras cortas.","tier":2},{"w":"JABALÍ","clue":"Cerdo salvaje con colmillos y pelo duro","fact":"Los jabalíes usan el hocico para escarbar la tierra en busca de raíces.","tier":2},{"w":"BABUINO","clue":"Mono grande de África con hocico largo parecido al de un perro","fact":"Los babuinos viven en grupos grandes y se acicalan unos a otros.","tier":2},{"w":"MANDRIL","clue":"Mono grande de cara roja y azul muy brillante","fact":"El mandril es el mono más grande del mundo.","tier":2},{"w":"WOMBAT","clue":"Marsupial australiano rechoncho que cava túneles con sus fuertes garras","fact":"La caca de un wombat tiene forma de cubitos.","tier":2},{"w":"OCELOTE","clue":"Gato manchado de Centroamérica y Sudamérica","fact":"Los ocelotes cazan sobre todo de noche y suelen descansar en los árboles.","tier":2},{"w":"QUETZAL","clue":"Ave verde brillante de Centroamérica con una cola larguísima","fact":"Los quetzales machos tienen plumas de la cola más largas que su cuerpo.","tier":2},{"w":"ALACRÁN","clue":"Animal del desierto con pinzas y una cola curva con aguijón","fact":"Los alacranes brillan con color azul verdoso bajo luz ultravioleta.","tier":2},{"w":"GRILLO","clue":"Insecto que canta frotando sus alas","fact":"Los grillos tienen oídos en las patas delanteras.","tier":2},{"w":"MANADA","clue":"Grupo de lobos, leones o elefantes que viven juntos","fact":"Una manada de lobos suele ser una familia: mamá, papá y sus crías.","tier":2},{"w":"MELENA","clue":"Pelo largo y espeso alrededor de la cabeza de un león macho","fact":"Solo los leones machos tienen melena; las hembras no.","tier":2},{"w":"CUERNO","clue":"Parte dura y puntiaguda en la cabeza de un rinoceronte","fact":"El cuerno del rinoceronte está hecho de queratina, igual que tus uñas.","tier":2},{"w":"TROMPA","clue":"La larga nariz flexible de un elefante","fact":"La trompa de un elefante tiene decenas de miles de músculos y ningún hueso.","tier":2},{"w":"JOROBA","clue":"Bulto de grasa en el lomo de un camello","fact":"La joroba de un camello guarda grasa, no agua.","tier":2},{"w":"AULLAR","clue":"Dar un grito largo y fuerte, como hacen los lobos de noche","fact":"Los lobos aúllan para comunicarse con su manada cuando están lejos.","tier":2},{"w":"PASTAR","clue":"Comer hierba en el campo, como hacen las vacas y las cebras","fact":"Las vacas pasan muchas horas al día comiendo hierba y masticándola de nuevo.","tier":2},{"w":"GUARIDA","clue":"Refugio escondido donde vive un zorro o un lobo","fact":"Muchos animales salvajes cavan una guarida para proteger a sus crías.","tier":2},{"w":"HÁBITAT","clue":"El lugar natural donde un animal encuentra comida, agua y refugio","fact":"Un hábitat puede ser un bosque, un desierto, una pradera o hasta un estanque.","tier":2},{"w":"MIGRAR","clue":"Viajar muy lejos cada año para buscar comida o clima cálido","fact":"Enormes manadas de ñus migran por África siguiendo las lluvias.","tier":2},{"w":"BIGOTES","clue":"Pelos duros en la cara de un gato que sienten lo cercano","fact":"Los bigotes de un gato miden casi lo mismo que su cuerpo de ancho.","tier":2},{"w":"COLIBRÍ","clue":"Ave diminuta que bate sus alas muy rápido y chupa néctar","fact":"El colibrí es una de las pocas aves que puede volar hacia atrás.","tier":2},{"w":"TREPAR","clue":"Subir a un árbol agarrándose con manos y pies","fact":"Algunos monos usan su cola como una quinta mano para moverse entre las ramas.","tier":2},{"w":"ACECHAR","clue":"Observar escondido y en silencio antes de lanzarse a atrapar","fact":"Los gatos agachan el cuerpo y mueven el trasero antes de saltar sobre su presa.","tier":2},{"w":"SERPIENTE","clue":"Reptil largo sin patas que se desliza por el suelo","fact":"Las serpientes huelen sacando y metiendo su lengua partida en dos.","tier":3},{"w":"TARÁNTULA","clue":"Gran arácnido peludo de ocho patas, de los trópicos","fact":"Las tarántulas hembra pueden vivir más de veinte años.","tier":3},{"w":"MARIPOSA","clue":"Insecto de alas grandes y coloridas que antes fue oruga","fact":"Las mariposas saborean las cosas con las patas.","tier":3},{"w":"MURCIÉLAGO","clue":"Mamífero volador que duerme colgado cabeza abajo","fact":"El murciélago es el único mamífero que puede volar de verdad.","tier":3},{"w":"AVESTRUZ","clue":"El ave más grande del mundo; no vuela pero corre veloz","fact":"Los ojos de un avestruz son más grandes que su cerebro.","tier":3},{"w":"GUACAMAYO","clue":"Ave grande y muy colorida de la selva con cola larguísima","fact":"Los guacamayos pueden vivir más de cincuenta años.","tier":3},{"w":"CAPIBARA","clue":"El roedor más grande del mundo, al que le encanta el agua","fact":"Algunas aves se paran sobre un capibara y a él no le molesta.","tier":3},{"w":"TAMANDUÁ","clue":"Animal de lengua larguísima que come hormigas","fact":"Un tamanduá puede comer miles de hormigas y termitas en un solo día.","tier":3},{"w":"ZARIGÜEYA","clue":"Marsupial americano que se hace el muerto cuando se asusta","fact":"Las crías de la zarigüeya viajan agarradas a la espalda de su mamá.","tier":3},{"w":"SURICATA","clue":"Mamífero pequeño del desierto africano que vigila parado en dos patas","fact":"Las suricatas se turnan para vigilar mientras el resto busca comida.","tier":3},{"w":"PANGOLÍN","clue":"Mamífero cubierto de escamas que se enrolla en una bola","fact":"Los pangolines son los únicos mamíferos cubiertos de escamas duras.","tier":3},{"w":"ANTÍLOPE","clue":"Rápido animal de la sabana con cuernos largos, como el impala","fact":"Los antílopes conservan sus cuernos toda la vida, a diferencia de los ciervos.","tier":3},{"w":"COCODRILO","clue":"Gran reptil de hocico largo y dientes afilados de ríos cálidos","fact":"Los cocodrilos pueden tener miles de dientes en su vida porque les crecen nuevos.","tier":3},{"w":"ESCARABAJO","clue":"Insecto con alas duras que parecen un caparazón","fact":"Los científicos han descrito más tipos de escarabajos que de cualquier otro grupo animal.","tier":3},{"w":"LIBÉLULA","clue":"Insecto de cuatro alas transparentes que vuela sobre los estanques","fact":"Los antepasados de las libélulas ya volaban antes de que existieran los dinosaurios.","tier":3},{"w":"SALTAMONTES","clue":"Insecto verde de patas traseras fuertes que da grandes brincos","fact":"Un saltamontes puede saltar unas veinte veces el largo de su cuerpo.","tier":3},{"w":"HERBÍVORO","clue":"Animal que solo come plantas","fact":"Los elefantes solo comen plantas, pero pueden comer más de cuarenta kilos al día.","tier":3},{"w":"CARNÍVORO","clue":"Animal que se alimenta principalmente de carne","fact":"Los gatos no pueden saborear lo dulce y necesitan carne para estar sanos.","tier":3},{"w":"NOCTURNO","clue":"Que está despierto de noche y duerme de día","fact":"Los búhos, los murciélagos y muchos ratones están más activos cuando oscurece.","tier":3},{"w":"HIBERNAR","clue":"Dormir muy profundo durante los meses fríos del invierno","fact":"Cuando un oso duerme en invierno, su corazón late mucho más lento.","tier":3},{"w":"CAMUFLAJE","clue":"Colores o dibujos que ayudan a un animal a pasar desapercibido","fact":"Las manchas de un leopardo lo ayudan a confundirse entre las sombras de las hojas.","tier":3},{"w":"DEPREDADOR","clue":"Animal que caza a otros animales para alimentarse","fact":"Los depredadores suelen tener dientes afilados, buena vista o garras fuertes.","tier":3},{"w":"COLMILLO","clue":"Diente largo y puntiagudo que sobresale de la boca de un elefante","fact":"Los colmillos de un elefante son en realidad sus dientes delanteros muy largos.","tier":3},{"w":"MADRIGUERA","clue":"Túnel bajo tierra donde viven los conejos y los zorros","fact":"Los perritos de la pradera construyen madrigueras con muchas habitaciones.","tier":3}]}},{"id":"food-and-cooking","icon":"🍳","name":{"en":"Food and Cooking","es":"Comida y cocina"},"words":{"en":[{"w":"RICE","clue":"Tiny white or brown grains grown in flooded fields","fact":"Rice plants grow best with their roots in shallow, flooded fields called paddies.","tier":1},{"w":"CORN","clue":"Golden kernels grow in rows on a cob","fact":"An ear of corn usually has an even number of rows of kernels.","tier":1},{"w":"BEAN","clue":"Seed that grows in a pod, tasty in chili","fact":"Beans have protein, and bean plants help put nutrients back into the soil.","tier":1},{"w":"HONEY","clue":"Sweet golden food made by bees","fact":"A honeybee makes only about a twelfth of a teaspoon of honey in its whole life.","tier":1},{"w":"FLOUR","clue":"Soft powder ground from wheat, used for baking","fact":"Bread flour has more protein than cake flour, so it makes chewier dough.","tier":1},{"w":"YEAST","clue":"Tiny living puffs that make bread dough rise","fact":"Yeast is a living fungus that eats sugar and makes gas bubbles.","tier":1},{"w":"BREAD","clue":"Baked loaf made from flour, water and yeast","fact":"People were baking bread thousands of years ago, long before the pyramids.","tier":1},{"w":"MANGO","clue":"Sweet orange-yellow tropical fruit with a big flat pit","fact":"Mangoes are related to cashews and pistachios.","tier":1},{"w":"BAKE","clue":"Cook food with dry heat in an oven","fact":"Cakes rise in the oven because heat makes tiny gas bubbles grow bigger.","tier":1},{"w":"CHEF","clue":"Cook in charge of a restaurant kitchen","fact":"The tall white hat a chef wears is called a toque.","tier":1},{"w":"STIR","clue":"Mix food around with a spoon","fact":"Stirring a pot keeps food from sticking and helps it heat evenly.","tier":1},{"w":"PASTA","clue":"Italian dough shaped into noodles, shells or tubes","fact":"There are hundreds of pasta shapes, from tiny stars to long strands.","tier":1},{"w":"BUTTER","clue":"Creamy yellow spread made by churning cream","fact":"If you shake cream long enough, it turns into butter.","tier":2},{"w":"CHEESE","clue":"Food made from milk that is pressed and aged","fact":"It takes about ten pounds of milk to make one pound of cheese.","tier":2},{"w":"TOMATO","clue":"Round red fruit often mistaken for a vegetable","fact":"A tomato is a fruit because it grows from a flower and holds seeds.","tier":2},{"w":"POTATO","clue":"Underground tuber made into fries and chips","fact":"Potatoes were first grown in the Andes mountains of South America.","tier":2},{"w":"PEPPER","clue":"Spicy black powder shaken from a small shaker","fact":"Black pepper comes from berries that are dried until they turn dark and wrinkled.","tier":2},{"w":"VINEGAR","clue":"Sour liquid used for pickling and salad dressing","fact":"The word comes from French words meaning \"sour wine.\"","tier":2},{"w":"NOODLE","clue":"Long thin strand of dough cooked in soup","fact":"Some of the oldest known noodles were found in China and are about 4,000 years old.","tier":2},{"w":"SPATULA","clue":"Flat tool for flipping pancakes","fact":"A rubber spatula can scrape a bowl almost completely clean.","tier":2},{"w":"POPCORN","clue":"Corn kernels that burst into fluffy white snacks","fact":"Popcorn pops because water inside the kernel turns to steam and bursts it open.","tier":2},{"w":"PRETZEL","clue":"Twisted baked snack with coarse salt crystals","fact":"Soft pretzels get their shiny brown crust from a quick bath in baking soda water.","tier":2},{"w":"AVOCADO","clue":"Green fruit with a big pit that is mashed for guacamole","fact":"Avocados ripen only after they are picked, not while still on the tree.","tier":2},{"w":"PUMPKIN","clue":"Big orange squash carved at Halloween","fact":"Pumpkins are fruits, and they are mostly water.","tier":2},{"w":"COCONUT","clue":"Hairy brown tropical fruit with sweet water inside","fact":"A coconut can float across the ocean and sprout on a faraway beach.","tier":2},{"w":"SIMMER","clue":"Cook gently, just below the boiling point","fact":"Water at a simmer is about 185 to 205 degrees Fahrenheit.","tier":2},{"w":"CINNAMON","clue":"Sweet brown spice from tree bark, sprinkled on toast","fact":"Cinnamon sticks are really curled-up strips of tree bark.","tier":3},{"w":"CHOCOLATE","clue":"Sweet treat made from roasted cacao beans","fact":"Chocolate is made from seeds of the cacao tree, which first grew in the Americas.","tier":3},{"w":"PINEAPPLE","clue":"Spiky tropical fruit with a leafy crown","fact":"A pineapple plant takes about two years to grow a single fruit.","tier":3},{"w":"STRAWBERRY","clue":"Red berry with seeds on the outside","fact":"A strawberry has about two hundred seeds on its outside skin.","tier":3},{"w":"BROCCOLI","clue":"Green vegetable that looks like tiny trees","fact":"Broccoli is a flower bud that we eat before it blooms.","tier":3},{"w":"SPAGHETTI","clue":"Long, thin Italian noodles often topped with tomato sauce","fact":"The name comes from an Italian word meaning \"little strings.\"","tier":3},{"w":"TORTILLA","clue":"Thin round flatbread made from corn or wheat","fact":"Tortillas have been made in Mexico for thousands of years.","tier":3},{"w":"CUCUMBER","clue":"Long green veggie that is cool and crunchy","fact":"A cucumber is about 95 percent water.","tier":3},{"w":"INGREDIENT","clue":"One of the foods you mix together in a recipe","fact":"Bakers weigh ingredients because a cup of flour can weigh different amounts.","tier":3},{"w":"WATERMELON","clue":"Big green fruit with sweet red inside and black seeds","fact":"Watermelons are related to cucumbers and pumpkins.","tier":3},{"w":"SOUP","clue":"Hot liquid meal you eat with a spoon","fact":"People have been making soup for thousands of years, ever since they had pots.","tier":1},{"w":"CAKE","clue":"Sweet baked treat topped with candles on birthdays","fact":"Long ago, cakes were more like sweet bread made with honey.","tier":1},{"w":"MILK","clue":"White drink from cows that goes well with cookies","fact":"Milk can be turned into cheese, butter, yogurt and ice cream.","tier":1},{"w":"PEAR","clue":"Sweet fruit that is wide at the bottom and narrow on top","fact":"Pears ripen best after they are picked, not while hanging on the tree.","tier":1},{"w":"PLUM","clue":"Smooth purple fruit with one hard pit; dried, it becomes a prune","fact":"Plums, peaches and cherries all belong to the same big plant family.","tier":1},{"w":"LIME","clue":"Small green citrus fruit that is very sour","fact":"Sailors once ate limes on long voyages to stay healthy.","tier":1},{"w":"PEACH","clue":"Fuzzy fruit with orange-pink flesh and a big pit","fact":"Peach trees first grew in China many thousands of years ago.","tier":1},{"w":"APPLE","clue":"Crunchy red or green fruit, often baked in a pie","fact":"Apples float in water because about a quarter of each one is air.","tier":1},{"w":"GRAPE","clue":"Small juicy fruit that grows in bunches on a vine","fact":"Grapes dried in the sun become raisins.","tier":1},{"w":"ONION","clue":"Round, layered vegetable that can make your eyes water","fact":"Cutting an onion releases a gas that stings your eyes, so tears wash it away.","tier":1},{"w":"SYRUP","clue":"Thick sweet sauce poured on pancakes, often from maple trees","fact":"It takes about forty buckets of maple sap to make one bucket of syrup.","tier":1},{"w":"SUGAR","clue":"Sweet white crystals stirred into drinks and baked into cookies","fact":"Sugar comes from two plants: sugar cane and sugar beets.","tier":1},{"w":"TOAST","clue":"Bread browned until crisp, great with butter or jam","fact":"Heat dries out the outside of bread and turns it brown and crunchy.","tier":1},{"w":"PIZZA","clue":"Round baked dish with cheese and sauce, cut into slices","fact":"Modern pizza began in Naples, Italy, where flat bread was topped with tomatoes.","tier":1},{"w":"BAGEL","clue":"Chewy bread ring with a hole, spread with cream cheese","fact":"Bagels are boiled briefly in water before baking, which gives them a chewy crust.","tier":1},{"w":"SALAD","clue":"Bowl of mixed raw veggies with dressing","fact":"The word salad comes from an old word meaning salted, because greens were served with salt.","tier":1},{"w":"BOIL","clue":"Heat water until it bubbles wildly and makes steam","fact":"Water boils at a lower temperature on a tall mountain, so food cooks slowly there.","tier":1},{"w":"WHISK","clue":"Wire kitchen tool for beating eggs and cream","fact":"Whisking cream adds tiny air bubbles that make it light and fluffy.","tier":1},{"w":"OVEN","clue":"Hot kitchen box where bread and cookies bake","fact":"Ancient bakers cooked flat breads in ovens made of clay.","tier":1},{"w":"TONGS","clue":"Tool with two arms for grabbing hot food","fact":"Tongs work like extra-long fingers so cooks can keep their hands away from heat.","tier":1},{"w":"TACO","clue":"Folded tortilla filled with meat, beans or veggies","fact":"Tacos come from Mexico, where people have eaten corn tortillas for centuries.","tier":1},{"w":"DOUGH","clue":"Soft, stretchy mix of flour and water before baking","fact":"Yeast makes dough rise by giving off tiny bubbles of gas.","tier":1},{"w":"CRUST","clue":"Hard brown outside of a loaf of bread","fact":"Bread turns brown in the oven because heat changes its sugars and proteins.","tier":1},{"w":"SAUCE","clue":"Thick liquid poured over spaghetti or dipped with nuggets","fact":"Cooks around the world have invented hundreds of different sauces.","tier":1},{"w":"OLIVE","clue":"Small salty fruit that is pressed to make a golden oil","fact":"Some olive trees are still growing after more than a thousand years.","tier":1},{"w":"YOLK","clue":"Yellow center of an egg","fact":"A yolk gives a growing chick the food it needs inside the egg.","tier":1},{"w":"BUN","clue":"Soft round bread that holds a burger or hot dog","fact":"Bakers brush buns with egg or milk before baking to make them shiny.","tier":1},{"w":"HERB","clue":"Leafy plant like basil or mint that adds flavor","fact":"Fresh herbs smell strong because their leaves hold tiny drops of oil.","tier":1},{"w":"CARROT","clue":"Crunchy orange root that grows underground","fact":"Carrots used to be purple or yellow before orange ones became popular.","tier":2},{"w":"LETTUCE","clue":"Crunchy pale-green leaves piled into salads and burgers","fact":"Lettuce leaves are mostly water, which is why they feel crisp and cool.","tier":2},{"w":"SPINACH","clue":"Soft dark-green leaves that shrink to almost nothing in a hot pan","fact":"Spinach shrinks a lot when cooked because it loses most of its water.","tier":2},{"w":"GARLIC","clue":"Smelly white bulb made of small sections called cloves","fact":"Garlic is a close cousin of onions, leeks and chives.","tier":2},{"w":"GINGER","clue":"Knobby, spicy underground part of a plant used in tea and cookies","fact":"Ginger is really an underground stem, not a root.","tier":2},{"w":"ALMOND","clue":"Smooth oval nut used to make a plant-based milk","fact":"An almond is the seed of a tree that is related to peach trees.","tier":2},{"w":"CHERRY","clue":"Small round red fruit with a long stem, atop a sundae","fact":"Cherry trees are famous for their pink and white blossoms in spring.","tier":2},{"w":"BANANA","clue":"Curved yellow fruit with a peel you remove","fact":"Bananas grow in bunches called hands, and each banana is called a finger.","tier":2},{"w":"ORANGE","clue":"Round citrus fruit squeezed for breakfast juice","fact":"Orange peels hold tiny pockets of oil that squirt a fine spray when bent.","tier":2},{"w":"PANCAKE","clue":"Flat round breakfast treat flipped in a hot pan","fact":"Bubbles on the top of pancake batter tell a cook it is time to flip.","tier":2},{"w":"WAFFLE","clue":"Breakfast food with a grid of squares to hold syrup","fact":"Waffle irons press a grid of squares into batter, making little pockets for syrup.","tier":2},{"w":"COOKIE","clue":"Small sweet baked treat, often with chocolate chips","fact":"The word cookie comes from a Dutch word meaning little cake.","tier":2},{"w":"CELERY","clue":"Crunchy, stringy green stalk, great with peanut butter","fact":"Celery stalks have long stringy fibers that run from the bottom to the top.","tier":2},{"w":"CEREAL","clue":"Crunchy breakfast food poured into a bowl with milk","fact":"Many cereals are made from grains such as corn, wheat, rice or oats.","tier":2},{"w":"YOGURT","clue":"Thick, tangy, spoonable food made from milk, often with fruit","fact":"Yogurt forms when friendly bacteria turn milk thick and tangy.","tier":2},{"w":"SAUSAGE","clue":"Seasoned ground meat packed into a tube and grilled at cookouts","fact":"People have been making sausages for thousands of years.","tier":2},{"w":"PICKLE","clue":"Sour, crunchy green slice on a burger, once a cucumber","fact":"Pickling food in salty or sour liquid keeps it from spoiling for a long time.","tier":2},{"w":"BLENDER","clue":"Machine with spinning blades in a jug that mixes smoothies","fact":"Blender blades spin so fast they can turn ice into tiny crushed pieces.","tier":2},{"w":"TOASTER","clue":"Slotted machine that pops up crisp, brown slices of bread","fact":"The first electric toasters browned only one side, so you flipped the bread by hand.","tier":2},{"w":"FREEZER","clue":"Super-cold compartment where ice cream and popsicles stay hard","fact":"Freezing puts germs that spoil food to sleep, so frozen food lasts a long time.","tier":2},{"w":"KITCHEN","clue":"Room in a home or restaurant where cooks prepare meals","fact":"Big restaurant kitchens are split into stations, and each cook handles one job.","tier":2},{"w":"RECIPE","clue":"List of ingredients and steps for making a dish","fact":"Some of the oldest known recipes were written on clay tablets thousands of years ago.","tier":2},{"w":"SKILLET","clue":"Heavy flat pan with a long handle for frying","fact":"A cast iron skillet can last for generations if it is cared for.","tier":2},{"w":"CUPCAKE","clue":"Small frosted dessert baked in a paper wrapper, one per person","fact":"Some say cupcakes got their name because the recipe used cups to measure.","tier":2},{"w":"RAISIN","clue":"Wrinkly, chewy sweet snack that used to be a grape","fact":"It takes about four pounds of fresh grapes to make one pound of raisins.","tier":2},{"w":"MUSTARD","clue":"Tangy yellow sauce squirted on hot dogs and pretzels","fact":"Mustard is made from the ground-up seeds of the mustard plant.","tier":2},{"w":"PANTRY","clue":"Small closet where cans, boxes and dry foods are stored","fact":"The word pantry comes from an old word for bread, because bread was kept there.","tier":2},{"w":"CASHEW","clue":"Curved nut that grows hanging below a fruit","fact":"Cashews grow hanging from the bottom of a fruit called a cashew apple.","tier":2},{"w":"OATMEAL","clue":"Warm breakfast porridge made from rolled grain","fact":"Oats are a kind of grass grown for its seeds.","tier":2},{"w":"NUTMEG","clue":"Brown spice grated from a hard seed, used in eggnog and pies","fact":"Nutmeg is the seed of a tropical tree, and its covering becomes another spice, mace.","tier":2},{"w":"KERNEL","clue":"Single hard seed of corn, sitting on a cob","fact":"A popcorn kernel pops because water inside turns to steam and bursts the shell.","tier":2},{"w":"WALNUT","clue":"Wrinkly, brain-shaped nut inside a hard round shell","fact":"A walnut kernel has two wrinkly halves that look like a tiny brain.","tier":2},{"w":"SANDWICH","clue":"Two slices of bread with a filling in the middle","fact":"The sandwich is named after the Earl of Sandwich, an English nobleman long ago.","tier":3},{"w":"SPRINKLES","clue":"Tiny colorful sugar bits scattered on cupcakes and ice cream","fact":"In Britain, sprinkles are often called hundreds and thousands.","tier":3},{"w":"LEMONADE","clue":"Sweet-and-sour cold drink sold at summer kids' stands","fact":"Lemonade tastes sour because citrus fruits are full of citric acid.","tier":3},{"w":"BLUEBERRY","clue":"Round berry the color of the sky, baked into muffins","fact":"Blueberries have a tiny star-shaped crown on one end.","tier":3},{"w":"RASPBERRY","clue":"Soft red berry that leaves a hollow when picked off its stem","fact":"Each raspberry is made of many tiny bumps, and every bump has its own seed.","tier":3},{"w":"CAULIFLOWER","clue":"White head of tiny clustered buds, a cousin of broccoli","fact":"Cauliflower, broccoli and cabbage all come from the same wild plant.","tier":3},{"w":"ZUCCHINI","clue":"Long green squash that grows fast in summer gardens","fact":"Zucchini is a fruit, because it grows from a flower and holds seeds.","tier":3},{"w":"MUSHROOM","clue":"Cap-and-stem food that pops up in damp, shady spots","fact":"Mushrooms are not plants; they belong to a separate group called fungi.","tier":3},{"w":"MEATBALL","clue":"Round lump of seasoned ground meat, often served on spaghetti","fact":"Meatballs are made in many countries, from Italy to Sweden.","tier":3},{"w":"MACARONI","clue":"Short, curvy pasta tubes used in a cheesy dinner","fact":"Macaroni is made from wheat flour and water, pushed through machines to make hollow shapes.","tier":3},{"w":"DUMPLING","clue":"Soft dough pocket stuffed with filling, steamed or boiled","fact":"Almost every food culture in the world has its own kind of dumpling.","tier":3},{"w":"BREAKFAST","clue":"First meal of the day, eaten in the morning","fact":"The word means breaking your fast, since you have not eaten all night.","tier":3},{"w":"SAUCEPAN","clue":"Deep pot with one long handle for heating soup","fact":"Copper pots are favorites of chefs because copper heats up and cools down quickly.","tier":3},{"w":"COLANDER","clue":"Bowl full of holes for draining pasta","fact":"The word colander comes from an old Latin word meaning to strain.","tier":3},{"w":"CHEESECAKE","clue":"Creamy dessert on a crumbly cookie crust","fact":"Some cheesecakes are baked in a pan of hot water so they do not crack.","tier":3},{"w":"TEASPOON","clue":"Small spoon that measures a little bit of a baking ingredient","fact":"In the U.S., three teaspoons make one tablespoon.","tier":3},{"w":"MARSHMALLOW","clue":"Fluffy white sweet toasted over a campfire for s'mores","fact":"The first marshmallows were made from a plant that grows in wet marshes.","tier":3},{"w":"PEPPERONI","clue":"Spicy red sausage circles scattered on a pizza","fact":"Pepperoni was invented in America, not in Italy, despite its Italian-sounding name.","tier":3},{"w":"ARTICHOKE","clue":"Round green vegetable with tough, pointy leaves and a tender heart","fact":"An artichoke is the unopened flower bud of a thistle plant.","tier":3},{"w":"GUACAMOLE","clue":"Mashed green dip for tortilla chips, made of avocados","fact":"The word guacamole comes from an Aztec word meaning avocado sauce.","tier":3},{"w":"HAMBURGER","clue":"Ground-beef patty served in a round bun","fact":"Hamburgers have no ham in them; the name comes from Hamburg, a city in Germany.","tier":3},{"w":"VEGETABLE","clue":"Plant food like a carrot or broccoli that is good for you","fact":"Cooks call a tomato a vegetable, but scientists say it is a fruit.","tier":3},{"w":"SMOOTHIE","clue":"Thick fruity drink whirled up in a blender","fact":"Frozen fruit makes a smoothie thick and cold without needing much ice.","tier":3},{"w":"CHOPSTICKS","clue":"Pair of slim eating sticks held in one hand in East Asia","fact":"Chopsticks have been used in China for thousands of years.","tier":3}],"es":[{"w":"ARROZ","clue":"Granitos blancos que se cultivan en campos inundados","fact":"Las plantas de arroz crecen mejor con las raíces en campos poco profundos llenos de agua.","tier":1},{"w":"PAN","clue":"Alimento horneado que se hace con harina, agua y levadura","fact":"La gente ya horneaba pan hace miles de años, mucho antes de las pirámides.","tier":1},{"w":"SOPA","clue":"Comida caliente y líquida que se toma con cuchara","fact":"En Ecuador hay sopas deliciosas, como el locro de papa con queso y aguacate.","tier":1},{"w":"HUEVO","clue":"Lo ponen las gallinas y se come frito o cocido","fact":"Un huevo cocido gira rápido si está duro y lento si está crudo.","tier":1},{"w":"MAÍZ","clue":"Grano dorado que crece en una mazorca","fact":"El maíz nació en América y se cultiva allí desde hace miles de años.","tier":1},{"w":"MIEL","clue":"Líquido dorado y dulce que hacen las abejas","fact":"En toda su vida, una abeja hace menos de una cucharadita de miel.","tier":1},{"w":"QUESO","clue":"Alimento hecho con leche que se prensa y se deja madurar","fact":"Se necesitan unos diez litros de leche para hacer un kilo de queso.","tier":1},{"w":"PAPA","clue":"Tubérculo que crece bajo tierra y se hace en puré o fritas","fact":"Las papas se empezaron a cultivar en los Andes hace miles de años.","tier":1},{"w":"YUCA","clue":"Raíz larga de cáscara café que se hierve o se fríe","fact":"La yuca siempre se cocina antes de comer, porque cruda no es segura.","tier":1},{"w":"MOTE","clue":"Granos grandes de maíz cocidos, típicos de los Andes","fact":"El mote es maíz pelado y cocido que se come en Ecuador desde hace mucho tiempo.","tier":1},{"w":"SAL","clue":"Polvo blanco que da sabor y que también tiene el mar","fact":"El agua del mar está llena de sal, y también se saca de minas bajo tierra.","tier":1},{"w":"HORNO","clue":"Cajón caliente de la cocina donde se cuecen pasteles y pan","fact":"Los pasteles suben en el horno porque el calor agranda las burbujitas de gas.","tier":1},{"w":"CHOCLO","clue":"Mazorca tierna de maíz que se come en los Andes","fact":"En Ecuador, el choclo se come con queso o en sopas como el locro.","tier":2},{"w":"CEVICHE","clue":"Plato frío de camarón o pescado con limón","fact":"El jugo de limón cambia el pescado y lo hace parecer cocido, aunque no se calienta.","tier":2},{"w":"HUMITA","clue":"Masa de choclo molido envuelta en hojas y cocida al vapor","fact":"Las humitas se envuelven en hojas de la misma mazorca de maíz para cocerlas.","tier":2},{"w":"CEBOLLA","clue":"Bulbo que hace llorar al cortarla","fact":"Al cortar una cebolla se libera un gas que irrita los ojos y los hace lagrimear.","tier":2},{"w":"TOMATE","clue":"Fruta roja y redonda que se usa en ensaladas y salsas","fact":"El tomate es una fruta porque crece de una flor y guarda semillas.","tier":2},{"w":"PLÁTANO","clue":"Fruta alargada que se fríe en tajadas, como los patacones","fact":"La planta del plátano parece un árbol, pero en realidad es una hierba gigante.","tier":2},{"w":"AZÚCAR","clue":"Polvito dulce y blanco que se saca de la caña","fact":"El azúcar se saca de la caña de azúcar y también de la remolacha.","tier":2},{"w":"HARINA","clue":"Polvo suave de trigo molido que sirve para hacer pan","fact":"Hay harinas de trigo, de maíz y de otros granos, y cada una da una textura distinta.","tier":2},{"w":"SARTÉN","clue":"Utensilio plano con mango para freír huevos","fact":"Las sartenes antiadherentes tienen una capa lisa para que la comida no se pegue.","tier":2},{"w":"TENEDOR","clue":"Cubierto con púas para pinchar la comida","fact":"En muchos países de Asia la gente come con palillos en lugar de tenedor.","tier":2},{"w":"RECETA","clue":"Lista de ingredientes y pasos para preparar un plato","fact":"Muchos cocineros anotan sus recetas favoritas y las pasan a sus hijos y nietos.","tier":2},{"w":"HERVIR","clue":"Cocinar en agua que burbujea fuerte","fact":"En Quito, el agua hierve a unos 91 grados, no a 100, por la altura.","tier":2},{"w":"HORNEAR","clue":"Cocer pan o pasteles con calor seco, sin freír","fact":"Las galletas se doran porque el calor cambia los azúcares y las proteínas de la masa.","tier":2},{"w":"SANDÍA","clue":"Fruta enorme, verde por fuera y roja por dentro, con semillas negras","fact":"La sandía es pariente del pepino y del zapallo.","tier":2},{"w":"EMPANADA","clue":"Masa rellena de queso o carne que se fríe o se hornea","fact":"En Ecuador hay empanadas de viento, rellenas de queso y espolvoreadas con azúcar.","tier":3},{"w":"MARACUYÁ","clue":"Fruta ácida de cáscara arrugada con pulpa llena de semillitas","fact":"La maracuyá crece en una enredadera con flores muy vistosas.","tier":3},{"w":"AGUACATE","clue":"Fruta verde cremosa con una semilla grande, ideal para guacamole","fact":"Los aguacates maduran después de cortarlos del árbol, no mientras cuelgan de él.","tier":3},{"w":"CHOCOLATE","clue":"Dulce hecho con semillas tostadas de cacao","fact":"El chocolate se hace con semillas del árbol de cacao, que crece en Ecuador.","tier":3},{"w":"ZANAHORIA","clue":"Raíz larga y crujiente de color naranja","fact":"Hay zanahorias moradas, amarillas y blancas, además de las naranjas.","tier":3},{"w":"MANTEQUILLA","clue":"Pasta amarilla y cremosa que se pone sobre el pan tostado","fact":"Si agitas crema de leche el tiempo suficiente, se convierte en mantequilla.","tier":3},{"w":"ENCEBOLLADO","clue":"Sopa de pescado muy popular en la costa de Ecuador","fact":"Lleva yuca y cebolla curtida con limón, y se acompaña con chifles.","tier":3},{"w":"LEVADURA","clue":"Hongo diminuto y vivo que hace crecer la masa del pan","fact":"La levadura come azúcar y suelta gas, por eso la masa se infla.","tier":3},{"w":"MERMELADA","clue":"Dulce espeso de fruta cocida con azúcar para untar","fact":"La mermelada se espesa por una sustancia natural de las frutas llamada pectina.","tier":3},{"w":"INGREDIENTE","clue":"Cada alimento que se mezcla en una receta","fact":"Los panaderos pesan los ingredientes porque una taza de harina puede pesar distinto cada vez.","tier":3},{"w":"FLAN","clue":"Postre suave y tembloroso con caramelo líquido encima","fact":"El flan se cocina dentro de un recipiente con agua caliente alrededor, llamado baño María.","tier":1},{"w":"CARNE","clue":"Parte musculosa de un animal que se cocina para comer","fact":"La carne tiene proteínas que ayudan a que los músculos crezcan.","tier":1},{"w":"PERA","clue":"Fruta dulce más ancha abajo y angosta arriba","fact":"Las peras y las manzanas son primas: pertenecen a la misma familia de plantas.","tier":1},{"w":"UVA","clue":"Fruta pequeña y jugosa que crece en racimos","fact":"Las uvas secadas al sol se convierten en pasas.","tier":1},{"w":"PIÑA","clue":"Fruta tropical de piel áspera y una corona de hojas","fact":"Cada piña se forma de muchas florecitas que crecieron juntas.","tier":1},{"w":"FRESA","clue":"Fruta roja con corazón dulce y semillitas por fuera","fact":"La fresa es de las pocas frutas que llevan las semillas por fuera.","tier":1},{"w":"MANGO","clue":"Fruta tropical dulce, de pulpa naranja y hueso grande","fact":"Un árbol de mango puede seguir dando frutos por más de cien años.","tier":1},{"w":"COCO","clue":"Fruto peludo y duro de las playas que guarda agua dulce","fact":"Los cocos pueden flotar en el mar y llegar a otras islas.","tier":1},{"w":"NUEZ","clue":"Fruto seco de cáscara dura que se parte con un cascanueces","fact":"La nuez tiene una forma parecida a un cerebro en miniatura.","tier":1},{"w":"LECHE","clue":"Bebida blanca que dan las vacas","fact":"Con leche se hacen queso, mantequilla, yogur y helado.","tier":1},{"w":"JUGO","clue":"Líquido que sale al exprimir una naranja","fact":"En algunos países se dice jugo y en otros zumo.","tier":1},{"w":"PIZZA","clue":"Masa redonda con salsa y queso, cortada en triángulos","fact":"La pizza moderna nació en Nápoles, Italia.","tier":1},{"w":"PASTA","clue":"Comida italiana de masa seca, como los fideos o los macarrones","fact":"Hay cientos de formas de pasta, como tubos, moños, conchas y espirales.","tier":1},{"w":"CACAO","clue":"Semillas de un árbol tropical con las que se hace el chocolate","fact":"Los antiguos mayas y aztecas tomaban el cacao como una bebida espumosa.","tier":1},{"w":"SABOR","clue":"Lo que sientes en la lengua cuando pruebas una comida","fact":"Gran parte del sabor viene del olfato: con la nariz tapada, todo sabe menos.","tier":1},{"w":"SALSA","clue":"Mezcla espesa y sabrosa para bañar o mojar la comida","fact":"Muchas salsas llevan tomate, una fruta que viajó desde América al resto del mundo.","tier":1},{"w":"TAMAL","clue":"Masa de maíz con relleno, envuelta en hojas y cocida al vapor","fact":"Las hojas que envuelven al tamal sirven para cocinarlo, pero no se comen.","tier":1},{"w":"AREPA","clue":"Disco de masa de maíz, típico de Colombia y Venezuela","fact":"Una arepa se abre como un sándwich y se rellena con queso o carne.","tier":1},{"w":"ASAR","clue":"Cocinar carne sobre brasas o en una parrilla","fact":"Al asar, el calor seco dora la comida por fuera y la deja jugosa por dentro.","tier":1},{"w":"FREÍR","clue":"Cocinar papas o huevos en aceite muy caliente","fact":"Al freír, el aceite caliente hace que la comida quede crujiente por fuera.","tier":1},{"w":"OLLA","clue":"Recipiente hondo con asas donde se hierve la sopa","fact":"Hace miles de años las ollas se hacían de barro cocido.","tier":1},{"w":"TAZA","clue":"Recipiente con asa para tomar bebidas calientes","fact":"La porcelana, con la que se hacen muchas tazas, se inventó en China hace más de mil años.","tier":1},{"w":"VASO","clue":"Recipiente de vidrio o plástico para beber agua o jugo","fact":"El vidrio se hace calentando arena hasta que se derrite.","tier":1},{"w":"PLATO","clue":"Recipiente plano y redondo donde se sirve la comida","fact":"La palabra plato también nombra cada comida de un menú, como el plato fuerte.","tier":1},{"w":"HABA","clue":"Semilla grande, aplanada y verde, que crece en una vaina","fact":"Las habas están entre los cultivos más antiguos: se siembran desde hace miles de años.","tier":1},{"w":"AJÍ","clue":"Fruto pequeño que pica mucho y da sabor a las salsas","fact":"El picante del ají viene de una sustancia llamada capsaicina.","tier":1},{"w":"KIWI","clue":"Fruta de piel peluda y pulpa verde con semillitas negras","fact":"El kiwi nació en China, pero lo bautizaron con el nombre del ave de Nueva Zelanda.","tier":1},{"w":"PAVO","clue":"Ave grande que se come asada en las fiestas","fact":"El pavo es originario de América, y los pueblos indígenas lo criaban hace siglos.","tier":1},{"w":"CEREZA","clue":"Fruta pequeña, roja y redonda con rabito, encima de un helado","fact":"El cerezo es famoso por sus flores rosadas y blancas en primavera.","tier":2},{"w":"DURAZNO","clue":"Fruta de piel aterciopelada, pulpa naranja y un solo hueso duro","fact":"El durazno nació en China y llegó a América con los españoles.","tier":2},{"w":"NARANJA","clue":"Cítrico redondo con gajos jugosos que se exprime para el desayuno","fact":"La cáscara de la naranja tiene bolsitas de aceite que sueltan un rocío al doblarla.","tier":2},{"w":"MANZANA","clue":"Fruta crujiente roja, verde o amarilla que crece en árboles","fact":"Las manzanas flotan en el agua porque una cuarta parte de su volumen es aire.","tier":2},{"w":"CIRUELA","clue":"Fruta ovalada de piel lisa y morada, con pulpa jugosa","fact":"Las ciruelas, los duraznos y las cerezas pertenecen a la misma gran familia de plantas.","tier":2},{"w":"GUAYABA","clue":"Fruta tropical redonda de aroma fuerte, con pulpa rosada y semillitas","fact":"La guayaba tiene mucha más vitamina C que una naranja.","tier":2},{"w":"LENTEJA","clue":"Semilla pequeña y aplanada como un disco que se cocina en guisos","fact":"Las lentejas están entre los cultivos más antiguos de la humanidad.","tier":2},{"w":"ARVEJA","clue":"Bolitas verdes que viven en fila dentro de una vaina","fact":"Un científico estudió arvejas para descubrir cómo se heredan los rasgos de padres a hijos.","tier":2},{"w":"ACEITE","clue":"Líquido grasoso y dorado para freír, que no se mezcla con agua","fact":"El aceite flota sobre el agua porque es más ligero y no se mezcla con ella.","tier":2},{"w":"CANELA","clue":"Especia marrón y dulce que sale de la corteza de un árbol","fact":"Al secarse, la corteza de canela se enrolla sola formando tubitos.","tier":2},{"w":"COCINA","clue":"Habitación de la casa donde se preparan las comidas","fact":"En los restaurantes grandes, cada cocinero se encarga de una tarea distinta.","tier":2},{"w":"CUCHARA","clue":"Cubierto con la parte honda para tomar sopa","fact":"Las primeras cucharas se hacían de madera, conchas o hueso.","tier":2},{"w":"GALLETA","clue":"Dulce horneado, delgado y crujiente, que va muy bien con leche","fact":"Los marineros llevaban galletas duras porque duraban meses sin dañarse.","tier":2},{"w":"CEREAL","clue":"Granos crujientes que se comen con leche en el desayuno","fact":"Muchos cereales se hacen con maíz, trigo, arroz o avena.","tier":2},{"w":"LECHUGA","clue":"Hojas verdes y crujientes que van en las ensaladas","fact":"La lechuga es casi toda agua, por eso se siente fresca y crujiente.","tier":2},{"w":"PEPINO","clue":"Verdura verde, larga y fresca que se corta en rodajas","fact":"El pepino es casi todo agua y es pariente de la sandía y la calabaza.","tier":2},{"w":"HELADO","clue":"Postre frío y cremoso que se derrite al sol","fact":"El helado se bate mientras se congela para que no se formen cristales grandes de hielo.","tier":2},{"w":"PALETA","clue":"Helado congelado en un palito que se lame","fact":"En México es común vender paletas de fruta de muchísimos sabores.","tier":2},{"w":"CHURRO","clue":"Barra de masa frita y estriada, cubierta de azúcar","fact":"Los churros salen estriados porque la masa pasa por una boquilla con forma de estrella.","tier":2},{"w":"PUPUSA","clue":"Tortilla gruesa de maíz rellena de queso, típica de El Salvador","fact":"Las pupusas se rellenan antes de cocinarlas, con queso, frijoles o chicharrón.","tier":2},{"w":"POZOLE","clue":"Sopa mexicana de granos grandes y blancos de maíz con carne","fact":"El pozole se sirve con rábanos, lechuga y limón por encima.","tier":2},{"w":"COLADOR","clue":"Utensilio con agujeritos para separar el líquido de la pasta cocida","fact":"Hay coladores tan finos que atrapan hasta las hojitas del té.","tier":2},{"w":"MEZCLAR","clue":"Juntar ingredientes distintos en un tazón hasta formar una sola cosa","fact":"Al mezclar harina con agua se forma una masa gracias a unas proteínas llamadas gluten.","tier":2},{"w":"AMASAR","clue":"Apretar y estirar la masa del pan con las manos","fact":"Al amasar el pan se forman hilos de gluten que lo hacen esponjoso.","tier":2},{"w":"CORTAR","clue":"Partir una cebolla o una zanahoria en pedazos con un cuchillo","fact":"Los chefs cortan los ingredientes del mismo tamaño para que se cocinen parejo.","tier":2},{"w":"FRIJOL","clue":"Semilla negra, roja o café que se cocina en caldo con arroz","fact":"Los pueblos de América cultivan el frijol desde hace miles de años.","tier":2},{"w":"ESPECIA","clue":"Polvo o semilla aromática que da sabor, como la pimienta","fact":"Hace siglos, algunas especias valían tanto como el oro.","tier":2},{"w":"BATIDO","clue":"Bebida espesa de fruta y leche mezcladas en licuadora","fact":"Las frutas congeladas hacen que el batido quede espeso y frío.","tier":2},{"w":"BUÑUELO","clue":"Bola de masa frita, hueca y dorada, con azúcar o miel","fact":"Los buñuelos se hinchan al freírse porque el agua de la masa se vuelve vapor.","tier":2},{"w":"REPOLLO","clue":"Verdura redonda de hojas apretadas, verde o morada","fact":"El repollo morado cambia de color según lo ácido que sea el líquido que le eches.","tier":2},{"w":"PEREJIL","clue":"Hierba de hojitas verdes que se pica para dar sabor y adorno","fact":"El perejil es de la misma familia de plantas que la zanahoria.","tier":2},{"w":"ORÉGANO","clue":"Hierba aromática seca que se echa sobre la pizza","fact":"Al secarse, el orégano suele tener un sabor más fuerte que cuando está fresco.","tier":2},{"w":"TORTILLA","clue":"Disco plano de masa de maíz que se asa en una plancha","fact":"En México se hacen tortillas de maíz desde hace miles de años.","tier":3},{"w":"ALMENDRA","clue":"Fruto seco ovalado, de cáscara dura, que da una leche vegetal","fact":"El almendro es pariente del durazno y del cerezo.","tier":3},{"w":"CALABAZA","clue":"Fruto grande, redondo y de cáscara dura, de pulpa naranja","fact":"Las calabazas son frutas, aunque se cocinan como verduras.","tier":3},{"w":"BERENJENA","clue":"Verdura alargada de piel morada y brillante","fact":"La berenjena es pariente cercana del tomate y de la papa.","tier":3},{"w":"SALCHICHA","clue":"Tubo de carne molida y sazonada que se come en pan","fact":"En los partidos de béisbol de Estados Unidos es típico comer salchicha en pan.","tier":3},{"w":"QUESADILLA","clue":"Tortilla doblada por la mitad y calentada con relleno derretido","fact":"En México algunas quesadillas llevan flor de calabaza como relleno.","tier":3},{"w":"LICUADORA","clue":"Aparato con cuchillas giratorias para hacer jugos y batidos","fact":"Las cuchillas de una licuadora giran tan rápido que convierten fruta entera en líquido.","tier":3},{"w":"TOSTADORA","clue":"Aparato con ranuras donde el pan se dora con electricidad","fact":"Las primeras tostadoras eléctricas tostaban solo un lado del pan.","tier":3},{"w":"MERIENDA","clue":"Comida ligera de la tarde, entre el almuerzo y la cena","fact":"En muchos países los niños comen una merienda al salir de la escuela.","tier":3},{"w":"CUCHARÓN","clue":"Utensilio hondo de mango largo para servir sopa de la olla","fact":"Un cucharón puede servir varias cucharadas de sopa de una sola vez.","tier":3},{"w":"REBANADA","clue":"Pedazo delgado y plano cortado de un pan o un queso","fact":"El pan ya rebanado se vendió por primera vez hace casi cien años.","tier":3},{"w":"ESPAGUETI","clue":"Pasta larga, delgada y redonda como cuerdas","fact":"La palabra espagueti viene de una palabra italiana que significa cordelitos.","tier":3},{"w":"HAMBURGUESA","clue":"Carne molida redonda dentro de un pan, con queso y lechuga","fact":"La hamburguesa no lleva jamón: su nombre viene de la ciudad alemana de Hamburgo.","tier":3},{"w":"FRAMBUESA","clue":"Baya roja y suave formada por muchas bolitas, con un hueco adentro","fact":"Cada frambuesa está hecha de muchas bolitas, y cada bolita tiene su semilla.","tier":3},{"w":"ARÁNDANO","clue":"Baya redonda de color azul oscuro, muy usada en jugos y postres","fact":"Los arándanos tienen una pequeña corona en forma de estrella en la punta.","tier":3},{"w":"ALBAHACA","clue":"Hierba de hojas verdes y aroma fuerte, típica de las salsas italianas","fact":"La albahaca es de la misma familia de plantas que la menta.","tier":3},{"w":"GELATINA","clue":"Postre transparente y tembloroso que se endurece en un molde","fact":"Si le pones piña cruda, la gelatina no cuaja, porque la fruta tiene una sustancia que la deshace.","tier":3},{"w":"CHAMPIÑÓN","clue":"Hongo blanco y redondo que se come, con sombrerito y tallo","fact":"Los hongos no son plantas: forman un grupo aparte de seres vivos.","tier":3},{"w":"COLIFLOR","clue":"Verdura blanca de cabeza apretada, prima del brócoli","fact":"La coliflor, el brócoli y el repollo vienen de la misma planta silvestre.","tier":3},{"w":"CACEROLA","clue":"Olla ancha, poco profunda y con dos asas para guisar","fact":"Las cacerolas de cobre calientan muy rápido porque el cobre conduce bien el calor.","tier":3},{"w":"DESAYUNO","clue":"Primera comida del día, que se toma por la mañana","fact":"La palabra desayuno significa dejar el ayuno, o sea, dejar de pasar tiempo sin comer.","tier":3},{"w":"ALMUERZO","clue":"Comida de la mitad del día","fact":"En muchos países de América Latina el almuerzo es la comida más grande del día.","tier":3},{"w":"PANADERÍA","clue":"Tienda con olor a recién horneado donde venden panes y bollos","fact":"Los panaderos empiezan a trabajar de madrugada para que el pan esté fresco por la mañana.","tier":3},{"w":"RESTAURANTE","clue":"Lugar donde pagas por una comida que otros preparan","fact":"La palabra restaurante viene de un verbo francés que significa devolver las fuerzas.","tier":3}]}},{"id":"weather-and-earth","icon":"🌦️","name":{"en":"Weather and Earth","es":"Clima y Tierra"},"words":{"en":[{"w":"RAIN","clue":"Water drops that fall from clouds","fact":"Small raindrops are round, and bigger ones flatten out like a hamburger bun.","tier":1},{"w":"SNOW","clue":"Frozen flakes that fall from winter clouds","fact":"Snow looks white because tiny ice crystals scatter all the colors of light.","tier":1},{"w":"HAIL","clue":"Balls of ice that fall from storm clouds","fact":"Hailstones grow bigger as wind tosses them up and down inside a storm cloud.","tier":1},{"w":"WIND","clue":"Air moving from place to place","fact":"Wind blows from areas of high air pressure toward areas of low air pressure.","tier":1},{"w":"FOG","clue":"Cloud that touches the ground","fact":"Fog forms when air cools so much that its water vapor turns into tiny droplets.","tier":1},{"w":"CLOUD","clue":"Floating puffs of tiny water drops or ice crystals","fact":"A fluffy cumulus cloud can weigh about a million pounds, yet it floats.","tier":1},{"w":"STORM","clue":"Wild weather with strong wind, rain or snow","fact":"A thunderstorm cloud can be taller than the tallest mountain.","tier":1},{"w":"FROST","clue":"Thin layer of ice crystals on cold mornings","fact":"Frost forms when water vapor freezes right onto cold surfaces, skipping the liquid stage.","tier":1},{"w":"LAVA","clue":"Hot melted rock that flows out of a volcano","fact":"Lava cools into hard rock, and over time it can build new islands.","tier":1},{"w":"QUAKE","clue":"Sudden shaking of the ground","fact":"Earth has thousands of tiny quakes every day that people never feel.","tier":1},{"w":"CORE","clue":"Super hot center of Earth","fact":"Earth's inner core is solid metal, nearly as hot as the surface of the Sun.","tier":1},{"w":"MAGMA","clue":"Hot melted rock underground","fact":"Magma is called lava once it breaks through to Earth's surface.","tier":1},{"w":"RAINBOW","clue":"Colorful arc that appears when sunshine hits water drops","fact":"A rainbow is really a full circle, but the ground hides the bottom half.","tier":2},{"w":"THUNDER","clue":"Loud rumbling noise after a flash in the sky","fact":"Count the seconds between the flash and the rumble: five seconds is about one mile.","tier":2},{"w":"TORNADO","clue":"Spinning funnel of wind that touches the ground","fact":"Most tornadoes last only a few minutes.","tier":2},{"w":"BREEZE","clue":"Light, gentle wind","fact":"Sea breezes blow from the cool ocean toward the warm land during the day.","tier":2},{"w":"DROUGHT","clue":"Long stretch of dry weather with very little rain","fact":"Cacti store water in their stems to survive long dry spells.","tier":2},{"w":"MONSOON","clue":"Seasonal wind that brings months of heavy rain to places like India","fact":"The word monsoon comes from an Arabic word meaning \"season.\"","tier":2},{"w":"TSUNAMI","clue":"Giant ocean wave set off by a quake under the sea","fact":"Tsunami is a Japanese word that means \"harbor wave.\"","tier":2},{"w":"CLIMATE","clue":"Usual weather of a place over many years","fact":"Weather changes every day, but climate describes typical weather over decades.","tier":2},{"w":"SEASON","clue":"One of four parts of the year, such as winter","fact":"Seasons happen because Earth is tilted as it circles the Sun.","tier":2},{"w":"GEYSER","clue":"Hot spring that shoots water and steam into the air","fact":"Geysers erupt when underground water gets so hot that it bursts up as steam.","tier":2},{"w":"MINERAL","clue":"Natural, solid, non-living stuff that rocks are made of","fact":"The salt in your kitchen is a mineral.","tier":2},{"w":"CRYSTAL","clue":"Solid with flat faces and a repeating pattern, like quartz","fact":"Crystals grow slowly as atoms line up in neat, repeating patterns.","tier":2},{"w":"MANTLE","clue":"Thick hot layer of rock between Earth's crust and core","fact":"Earth's mantle is solid rock that flows very slowly, like thick putty.","tier":2},{"w":"EROSION","clue":"Wearing away of rock and soil by wind or water","fact":"The Grand Canyon was carved by a river wearing away rock for millions of years.","tier":2},{"w":"LIGHTNING","clue":"Giant spark of electricity in a storm cloud","fact":"A bolt of lightning is hotter than the surface of the Sun.","tier":3},{"w":"AVALANCHE","clue":"Mass of snow sliding fast down a mountain","fact":"Most avalanches happen on slopes tilted between 30 and 45 degrees.","tier":3},{"w":"HURRICANE","clue":"Giant spinning storm that forms over warm ocean water","fact":"The calm center of a hurricane is called its eye.","tier":3},{"w":"BLIZZARD","clue":"Snowstorm with strong winds and very little to see","fact":"A blizzard is defined by strong wind and blowing snow, not by how much snow falls.","tier":3},{"w":"EARTHQUAKE","clue":"Shaking of the ground when pieces of Earth's crust slip","fact":"Earth's crust is broken into huge pieces called plates that slowly move.","tier":3},{"w":"THERMOMETER","clue":"Tool that measures how hot or cold something is","fact":"Its name comes from Greek words meaning \"heat\" and \"measure.\"","tier":3},{"w":"SNOWFLAKE","clue":"Tiny six-sided ice crystal that falls in winter","fact":"Every snowflake has six sides or six points.","tier":3},{"w":"EVAPORATION","clue":"When liquid water slowly turns into invisible vapor","fact":"Water that evaporated from the ocean may fall as rain on a faraway mountain.","tier":3},{"w":"HUMIDITY","clue":"Amount of water vapor in the air","fact":"Humid air feels sticky because sweat cannot dry easily from your skin.","tier":3},{"w":"STALACTITE","clue":"Icicle-shaped rock hanging from a cave ceiling","fact":"A stalactite grows when mineral-rich water drips and leaves tiny deposits behind.","tier":3},{"w":"DEW","clue":"Tiny drops of water on grass early in the morning","fact":"Dew forms when the air cools overnight and water vapor turns into drops.","tier":1},{"w":"SKY","clue":"Blue space above us where clouds and birds float","fact":"The sky looks blue because air scatters blue sunlight more than other colors.","tier":1},{"w":"SLEET","clue":"Tiny icy pellets of frozen rain that fall in winter","fact":"Sleet forms when raindrops freeze into ice pellets on their way down.","tier":1},{"w":"FLOOD","clue":"Too much water covering land that is usually dry","fact":"Floodwaters can leave rich mud that helps farmers grow crops.","tier":1},{"w":"ROCK","clue":"Hard, solid lump of stone that mountains are made of","fact":"Some rocks are made from melted lava that cooled and hardened.","tier":1},{"w":"SOIL","clue":"Brown top layer of ground where plants put down roots","fact":"A teaspoon of healthy soil holds billions of tiny living things.","tier":1},{"w":"CLAY","clue":"Sticky, smooth earth that potters mold into bowls","fact":"Clay turns hard as rock when it is heated in a very hot furnace called a kiln.","tier":1},{"w":"COAL","clue":"Black rock that people burn for heat","fact":"Most coal comes from swampy forests that grew about 300 million years ago, before dinosaurs.","tier":1},{"w":"STEAM","clue":"Hot white cloud that puffs from a boiling kettle","fact":"Steam power made the first trains and factory machines run.","tier":1},{"w":"GALE","clue":"Very strong wind that bends trees","fact":"A gale can snap branches off trees and make it hard to walk.","tier":1},{"w":"GUST","clue":"Sudden short blast of wind","fact":"Gusts happen when air moves in uneven bursts instead of a steady flow.","tier":1},{"w":"FAULT","clue":"Crack in the ground where earthquakes often begin","fact":"Earthquakes happen when rock suddenly slips along a fault.","tier":1},{"w":"SMOG","clue":"Dirty yellow-gray haze that hangs over a busy city","fact":"The word smog was made by mashing together smoke and fog.","tier":1},{"w":"ASH","clue":"Gray powder left over after wood burns","fact":"Volcanic ash is made of tiny bits of rock and glass.","tier":1},{"w":"HEAT","clue":"What a fire or the Sun gives off that makes you sweat","fact":"Heat always moves from warmer things toward cooler things.","tier":1},{"w":"HAZE","clue":"Thin dusty veil in the air that blurs faraway views","fact":"Haze can make faraway mountains look blue and blurry.","tier":1},{"w":"SUNNY","clue":"Bright and clear, with no clouds blocking the Sun","fact":"Plants grow well on sunny days because they use sunlight to make food.","tier":1},{"w":"THAW","clue":"What ice and frozen ground do when warm weather returns","fact":"In spring, melting snow from a thaw helps fill rivers and streams.","tier":1},{"w":"SLUSH","clue":"Wet, mushy, half-melted snow","fact":"Salt on roads makes ice melt into slush even when it is quite cold.","tier":1},{"w":"OPAL","clue":"Milky gem that flashes tiny rainbows of color","fact":"Opals flash color because tiny balls of silica inside them bend light.","tier":1},{"w":"GEODE","clue":"Plain round rock that sparkles with crystals when cracked open","fact":"Geodes form when crystals slowly grow inside hollow spaces in rock.","tier":1},{"w":"FLINT","clue":"Hard gray stone that makes sparks when struck on steel","fact":"Early people chipped flint into tools and used it to start fires.","tier":1},{"w":"SLATE","clue":"Gray rock that splits into flat sheets, used for roofs","fact":"Old school chalkboards were often made of slate.","tier":1},{"w":"ORE","clue":"Rock dug from a mine that holds useful metal","fact":"Iron ore is dug up and made into steel for buildings and machines.","tier":1},{"w":"SOOT","clue":"Black powder that smoke leaves behind on a chimney","fact":"Soot is made of tiny bits of carbon left when things do not burn completely.","tier":1},{"w":"RUBY","clue":"Deep red gem that is the birthstone for July","fact":"Rubies are red because of a tiny bit of the metal chromium.","tier":1},{"w":"WINDY","clue":"Full of moving air that sends kites soaring and hats tumbling","fact":"Windy days help plants spread seeds, like dandelion fluff, to faraway places.","tier":1},{"w":"GOLD","clue":"Shiny yellow metal found in nuggets, used for jewelry","fact":"Gold never rusts, so gold coins stay shiny for thousands of years.","tier":1},{"w":"ICICLE","clue":"Pointy spike of ice hanging from a roof edge","fact":"Icicles grow when melting snow drips down and freezes again.","tier":2},{"w":"SUNSET","clue":"When the sun drops out of sight in the evening","fact":"Sunsets look orange and red because sunlight travels through more air to reach you.","tier":2},{"w":"SUNRISE","clue":"Moment in the morning when the sun first peeks up","fact":"The sun seems to rise because Earth is spinning toward it.","tier":2},{"w":"SHOWER","clue":"Short burst of rain from a passing cloud","fact":"One street can get a rain shower while the next street stays dry.","tier":2},{"w":"DRIZZLE","clue":"Very light rain with tiny drops","fact":"Drizzle drops are so small they seem to float in the air.","tier":2},{"w":"WEATHER","clue":"Sunny, rainy, windy or snowy: what it is like outside today","fact":"Weather changes from day to day, but climate is the usual pattern over many years.","tier":2},{"w":"PUDDLE","clue":"Small pool of rainwater on the road, fun to jump in","fact":"Puddles disappear as the sun warms the water and it evaporates into the air.","tier":2},{"w":"GRAVEL","clue":"Crunchy small stones spread on driveways and paths","fact":"Gravel is often made by crushing bigger rocks into small pieces.","tier":2},{"w":"PEBBLE","clue":"Small, smooth, rounded stone worn by water","fact":"Pebbles are smooth because moving water has rolled them around for years.","tier":2},{"w":"BOULDER","clue":"Giant rock, bigger than a person","fact":"Glaciers can carry huge boulders for miles and then drop them far from home.","tier":2},{"w":"GRANITE","clue":"Hard speckled rock used for countertops and statues","fact":"Granite forms slowly when melted rock cools deep underground.","tier":2},{"w":"QUARTZ","clue":"Hard clear or milky crystal common in rocks","fact":"Much of the sand on beaches is made mostly of tiny bits of quartz.","tier":2},{"w":"SUMMER","clue":"Warmest season, with long days and school vacation","fact":"It is summer when your part of Earth is tilted toward the Sun.","tier":2},{"w":"WINTER","clue":"Coldest season of the year, when days are short","fact":"Winter days are short because the Sun stays low in the sky.","tier":2},{"w":"AUTUMN","clue":"Cool season when leaves turn orange and drop off trees","fact":"Leaves change color when green chlorophyll fades and reveals yellow and orange underneath.","tier":2},{"w":"FREEZE","clue":"Turn solid from being very cold, like water into ice","fact":"Water is unusual because it takes up more space when it freezes.","tier":2},{"w":"FLURRY","clue":"Brief burst of light snowfall","fact":"A snow flurry can last just a few minutes and barely cover the ground.","tier":2},{"w":"DEWDROP","clue":"Sparkling bead of water on a spiderweb in the morning","fact":"Dewdrops cling to spiderwebs because the thin threads cool down quickly at night.","tier":2},{"w":"SUNBURN","clue":"Sore pink skin from staying out in the Sun too long","fact":"Sunburn comes from invisible ultraviolet light, and it can happen on cloudy days.","tier":2},{"w":"SNOWMAN","clue":"Winter figure with a carrot nose and coal eyes","fact":"Snow packs together best for building when the weather is just a little above freezing.","tier":2},{"w":"CLOUDY","clue":"Covered with gray puffs, so the Sun stays hidden","fact":"Cloudy nights are often warmer than clear ones because clouds hold in heat.","tier":2},{"w":"STORMY","clue":"Wild, rough weather with rumbling booms and flashes in the sky","fact":"Thunder always comes with lightning, even when you cannot see the flash.","tier":2},{"w":"EMERALD","clue":"Rich green gem, the color of fresh grass","fact":"Emeralds are a green form of a mineral called beryl.","tier":2},{"w":"MARBLE","clue":"Smooth swirly stone used for statues and fancy floors","fact":"Marble is limestone that was squeezed and heated deep underground until it changed.","tier":2},{"w":"BASALT","clue":"Dark gray rock that makes up much of the ocean floor","fact":"Basalt forms when runny lava cools and hardens, like the lava in Hawaii.","tier":2},{"w":"PUMICE","clue":"Lightweight rock full of tiny holes, made when lava foams","fact":"Pumice is so full of air bubbles that it can float on water.","tier":2},{"w":"GARNET","clue":"Deep red gem, often set in rings and January's birthstone","fact":"Garnet is usually deep red, but it also comes in orange and green.","tier":2},{"w":"FROZEN","clue":"Hard as ice because it got very, very cold","fact":"Some wood frogs survive winter by freezing solid and thawing out in spring.","tier":2},{"w":"MOLTEN","clue":"Melted into hot liquid, like rock inside a volcano","fact":"Deep underground, molten rock called magma is hot enough to glow.","tier":2},{"w":"SUNBEAM","clue":"Narrow stripe of light shining through a window or cloud gap","fact":"Dust floating in the air is what makes a sunbeam visible.","tier":2},{"w":"CINDER","clue":"Small burnt bit of coal or wood left from a fire","fact":"Some volcanoes shoot out cinders, which are small chunks of rock full of holes.","tier":2},{"w":"COPPER","clue":"Reddish-orange metal used in electric wires","fact":"Copper turns green over time, which is why the Statue of Liberty is green.","tier":2},{"w":"LANDSLIDE","clue":"Rocks and dirt suddenly sliding down a steep hillside","fact":"Heavy rain can soak a hillside until the loose soil slides down.","tier":3},{"w":"SANDSTORM","clue":"Desert wind that whips up thick clouds of grit","fact":"Dust from the Sahara desert can blow all the way across the Atlantic Ocean.","tier":3},{"w":"FORECAST","clue":"Prediction of what the sky will do tomorrow","fact":"Forecasters use satellites, weather balloons and computers to predict tomorrow's weather.","tier":3},{"w":"RAINDROP","clue":"Tiny ball of water falling from a cloud","fact":"Each raindrop forms around a tiny speck of dust floating in a cloud.","tier":3},{"w":"LIMESTONE","clue":"Pale rock made long ago from sea shells and coral","fact":"Much limestone is made of the tiny shells and bones of ancient sea creatures.","tier":3},{"w":"OBSIDIAN","clue":"Shiny black volcanic glass","fact":"Obsidian forms when lava cools so fast that crystals have no time to grow.","tier":3},{"w":"STALAGMITE","clue":"Pointy rock spike rising up from a cave floor","fact":"Stalagmites grow very slowly, often less than a millimeter in a year.","tier":3},{"w":"WILDFIRE","clue":"Huge uncontrolled fire racing through a dry forest","fact":"Some trees need the heat of a wildfire to open their cones and release seeds.","tier":3},{"w":"BAROMETER","clue":"Instrument that measures the push of the air to predict storms","fact":"Falling air pressure on a barometer often means a storm is coming.","tier":3},{"w":"WINDMILL","clue":"Tall machine with big spinning blades turned by moving air","fact":"Windmills have been used for hundreds of years to grind grain and pump water.","tier":3},{"w":"SEISMOGRAPH","clue":"Machine that draws wiggly lines when the ground shakes","fact":"Seismographs can detect shaking from earthquakes on the other side of the planet.","tier":3},{"w":"WEATHERVANE","clue":"Spinning rooftop pointer, often a rooster, showing wind direction","fact":"A weather vane points toward the direction the wind is coming from.","tier":3},{"w":"TEMPERATURE","clue":"How hot or cold something is, measured in degrees","fact":"It gets colder the higher you climb up a mountain.","tier":3},{"w":"OVERCAST","clue":"Gray, cloud-covered sky with no blue showing","fact":"Even on an overcast day, rays from the Sun can still cause sunburn.","tier":3},{"w":"GEOLOGIST","clue":"Scientist who studies rocks, volcanoes and fossils","fact":"Geologists read layers of rock like pages in a very old history book.","tier":3},{"w":"SUNSHINE","clue":"Warm light from our nearest star on a clear day","fact":"Sunlight takes about eight minutes to travel from the Sun to Earth.","tier":3},{"w":"SNOWPLOW","clue":"Big truck with a front blade that clears roads after a blizzard","fact":"Many snowplows also spread salt to help melt ice on the road.","tier":3},{"w":"UMBRELLA","clue":"Folding canopy on a stick that keeps you dry in a downpour","fact":"Umbrellas were first used for shade from the Sun, long before they were used for rain.","tier":3},{"w":"SAPPHIRE","clue":"Deep blue gem, hard as a rock, set in rings","fact":"Sapphires and rubies are the same mineral, called corundum, in different colors.","tier":3},{"w":"GRAPHITE","clue":"Soft, slippery gray mineral that leaves marks when you write","fact":"The black part of a pencil is really graphite mixed with clay, not lead.","tier":3},{"w":"SANDSTONE","clue":"Rock of cemented, gritty grains, often red or tan in canyons","fact":"Sandstone forms when sand is buried and pressed into solid rock over millions of years.","tier":3},{"w":"THUNDERCLAP","clue":"Sudden, very loud boom from the sky during a storm","fact":"Thunder is the sound of air heating so fast around lightning that it booms.","tier":3},{"w":"ANEMOMETER","clue":"Tool with spinning cups that measures how fast the wind blows","fact":"The word anemometer comes from a Greek word for wind.","tier":3},{"w":"SNOWDRIFT","clue":"Smooth heap of white fluff piled by the wind against a fence","fact":"Wind can pile flakes into drifts taller than a house.","tier":3}],"es":[{"w":"NIEVE","clue":"Copitos blancos y fríos que caen del cielo en invierno","fact":"La nieve se ve blanca porque los cristalitos de hielo reflejan todos los colores de la luz.","tier":1},{"w":"NUBE","clue":"Masa flotante de gotitas de agua o cristales de hielo","fact":"Una nube esponjosa puede pesar unos 500 000 kilos y aun así flota.","tier":1},{"w":"RAYO","clue":"Chispa gigante de electricidad que sale de una nube de tormenta","fact":"Un rayo es más caliente que la superficie del Sol.","tier":1},{"w":"LAVA","clue":"Roca derretida y ardiente que sale de un volcán","fact":"La lava se enfría y se endurece hasta formar roca; así pueden nacer islas nuevas.","tier":1},{"w":"MAGMA","clue":"Roca derretida que está bajo la tierra","fact":"El magma se llama lava cuando llega a la superficie.","tier":1},{"w":"ROCA","clue":"Material duro y sólido de la corteza de la Tierra","fact":"Hay tres grandes tipos de rocas: ígneas, sedimentarias y metamórficas.","tier":1},{"w":"HIELO","clue":"Agua congelada y dura","fact":"El hielo flota porque es menos denso que el agua líquida.","tier":1},{"w":"CUEVA","clue":"Espacio hueco y oscuro dentro de una montaña o bajo la tierra","fact":"Muchas cuevas se forman cuando el agua disuelve la roca durante miles de años.","tier":1},{"w":"CLIMA","clue":"El tiempo típico de un lugar durante muchos años","fact":"En Ecuador no hay cuatro estaciones marcadas porque está sobre la línea del ecuador.","tier":1},{"w":"GARÚA","clue":"Lluvia muy finita, casi como niebla, que moja poco a poco","fact":"En las islas Galápagos, la garúa es una niebla húmeda que riega las plantas durante la temporada fresca.","tier":1},{"w":"BRISA","clue":"Viento suave y agradable","fact":"La brisa marina sopla del mar frío hacia la tierra caliente durante el día.","tier":1},{"w":"SUELO","clue":"Capa de tierra donde crecen las plantas","fact":"Una cucharadita de suelo sano tiene más seres vivos diminutos que personas hay en el planeta.","tier":1},{"w":"LLUVIA","clue":"Gotas de agua que caen de las nubes","fact":"Las gotas de lluvia pequeñas son redondas y las grandes se aplastan como un pancito.","tier":2},{"w":"VIENTO","clue":"Lo que mueve las hojas y hace volar las cometas","fact":"El viento mueve el aire de las zonas de alta presión a las de baja presión.","tier":2},{"w":"NIEBLA","clue":"Nube que toca el suelo","fact":"La niebla se forma cuando el aire se enfría tanto que su vapor de agua se vuelve gotitas.","tier":2},{"w":"TRUENO","clue":"Ruido fuerte que se escucha después de ver un relámpago","fact":"Si cuentas cinco segundos entre el destello y el ruido, la tormenta está a unos 1,6 kilómetros.","tier":2},{"w":"HURACÁN","clue":"Gran tormenta que gira sobre el mar cálido","fact":"El centro de un huracán, llamado ojo, está en calma.","tier":2},{"w":"TORNADO","clue":"Embudo de viento que gira y toca el suelo","fact":"La mayoría de los tornados duran solo unos minutos.","tier":2},{"w":"GRANIZO","clue":"Bolitas de hielo que caen en una tormenta","fact":"Los granizos crecen porque el viento los sube y los baja dentro de la nube.","tier":2},{"w":"SEQUÍA","clue":"Largo tiempo sin casi nada de lluvia","fact":"Los cactus guardan agua en su tallo para sobrevivir a las sequías.","tier":2},{"w":"NÚCLEO","clue":"Centro caliente de la Tierra","fact":"El núcleo interno de la Tierra es de metal sólido, casi tan caliente como la superficie del Sol.","tier":2},{"w":"CORTEZA","clue":"Capa de roca de afuera de la Tierra, donde vivimos","fact":"La corteza terrestre está rota en grandes placas que se mueven muy despacio.","tier":2},{"w":"CRISTAL","clue":"Sólido con caras planas y forma ordenada, como el cuarzo","fact":"Los cristales crecen despacio mientras sus átomos se acomodan en patrones ordenados.","tier":2},{"w":"MINERAL","clue":"Sustancia sólida de la naturaleza con la que se forman las rocas","fact":"La sal de cocina es un mineral.","tier":2},{"w":"PÁRAMO","clue":"Paisaje frío y húmedo de alta montaña andina, con neblina y pastos","fact":"El páramo guarda agua como una esponja gigante y alimenta muchos ríos.","tier":2},{"w":"EROSIÓN","clue":"Desgaste lento de rocas y tierra por el agua y el viento","fact":"Un río puede tallar un cañón enorme a lo largo de millones de años.","tier":2},{"w":"ARCOÍRIS","clue":"Arco de colores que aparece con sol y gotas de agua","fact":"Un arcoíris en realidad es un círculo completo, pero el suelo tapa la mitad de abajo.","tier":3},{"w":"TORMENTA","clue":"Mal tiempo con viento fuerte, lluvia y relámpagos","fact":"Una nube de tormenta puede ser más alta que la montaña más alta del mundo.","tier":3},{"w":"RELÁMPAGO","clue":"Destello de luz brillante en el cielo durante una tormenta","fact":"Ves el relámpago antes de oír el trueno porque la luz viaja más rápido que el sonido.","tier":3},{"w":"TERREMOTO","clue":"Sacudida del suelo cuando se mueven las rocas bajo la Tierra","fact":"Cada día ocurren miles de temblores pequeños que casi nadie siente.","tier":3},{"w":"AVALANCHA","clue":"Masa de nieve que se desliza rápido por una montaña","fact":"La mayoría de las avalanchas ocurre en pendientes de entre 30 y 45 grados.","tier":3},{"w":"ESCARCHA","clue":"Capa fina de cristalitos de hielo en las mañanas muy frías","fact":"La escarcha se forma cuando el vapor de agua se congela directo sobre superficies frías.","tier":3},{"w":"TERMÓMETRO","clue":"Instrumento que mide qué tan caliente o frío está algo","fact":"Su nombre viene del griego: termo significa calor y metro significa medir.","tier":3},{"w":"ESTALACTITA","clue":"Roca en forma de carámbano que cuelga del techo de una cueva","fact":"Una estalactita crece cuando gotas de agua con minerales dejan restos al caer.","tier":3},{"w":"EVAPORACIÓN","clue":"Cuando el agua líquida se convierte despacio en vapor invisible","fact":"El agua que se evapora del mar puede caer como lluvia sobre una montaña lejana.","tier":3},{"w":"AGUACERO","clue":"Lluvia fuerte y repentina que dura poco","fact":"En muchos lugares tropicales llueve fuerte casi todas las tardes.","tier":3},{"w":"ROCÍO","clue":"Gotitas de agua que aparecen sobre el pasto al amanecer","fact":"El rocío se forma cuando el aire se enfría de noche y el vapor se vuelve gotitas.","tier":1},{"w":"HUMO","clue":"Nube gris que sube cuando algo se quema","fact":"El humo es una mezcla de gases y partículas diminutas que flotan en el aire.","tier":1},{"w":"GOTA","clue":"Pedacito redondo de agua que cae del cielo o de un grifo","fact":"Las gotas de lluvia se forman alrededor de una partícula minúscula de polvo.","tier":1},{"w":"CAÑÓN","clue":"Valle profundo de paredes verticales que abrió un río","fact":"El Gran Cañón del Colorado fue excavado por un río durante millones de años.","tier":1},{"w":"GEMA","clue":"Piedra preciosa y brillante que se usa en joyas","fact":"Muchas gemas se forman muy adentro de la Tierra, con calor y presión durante millones de años.","tier":1},{"w":"ÓPALO","clue":"Gema lechosa que muestra destellos de colores","fact":"Los ópalos tienen bolitas diminutas que desvían la luz y muestran un arcoíris.","tier":1},{"w":"RUBÍ","clue":"Gema de color rojo intenso, muy dura y valiosa","fact":"El rubí y el zafiro son el mismo mineral, el corindón, con distinto color.","tier":1},{"w":"GEODA","clue":"Piedra redonda y común por fuera, brillante de cristales por dentro","fact":"Las geodas se forman cuando cristales crecen despacio dentro de huecos de roca.","tier":1},{"w":"FUEGO","clue":"Llamas calientes que dan luz y calor al quemar leña","fact":"El fuego necesita tres cosas: calor, algo que se queme y oxígeno.","tier":1},{"w":"SECO","clue":"Sin una gota de agua, lo contrario de mojado","fact":"Algunos desiertos pasan años sin una sola gota de lluvia.","tier":1},{"w":"TIBIO","clue":"Ni frío ni caliente, con temperatura agradable","fact":"El agua tibia está más o menos a la temperatura de tu cuerpo, unos 37 grados.","tier":1},{"w":"VAPOR","clue":"Agua convertida en gas que sube de una olla hirviendo","fact":"El vapor de agua es invisible; lo que ves blanco son gotitas diminutas.","tier":1},{"w":"TIZA","clue":"Barrita blanca de roca blanda con la que se escribe en pizarrón","fact":"La tiza natural está hecha de esqueletos diminutos de algas del mar.","tier":1},{"w":"JADE","clue":"Piedra verde muy valorada por los antiguos mayas y olmecas","fact":"Los pueblos antiguos de Mesoamérica valoraban el jade más que el oro.","tier":1},{"w":"ONDA","clue":"Ondulación circular que se forma al tirar una piedra al agua","fact":"Las ondas se alejan en círculos y se van debilitando hasta desaparecer.","tier":1},{"w":"CALMA","clue":"Momento sin viento ni olas en que todo está tranquilo","fact":"Los marineros llamaban calma chicha a cuando no había viento y los barcos no avanzaban.","tier":1},{"w":"ORO","clue":"Metal amarillo y brillante que se encuentra en las rocas","fact":"El oro no se oxida, por eso un objeto de oro brilla igual después de miles de años.","tier":1},{"w":"PLATA","clue":"Metal blanco y brillante con el que se hacen joyas y cubiertos","fact":"La plata conduce la electricidad mejor que cualquier otro metal.","tier":1},{"w":"COBRE","clue":"Metal rojizo y brillante con el que se hacen cables eléctricos","fact":"Con el tiempo el cobre se vuelve verde, como la Estatua de la Libertad.","tier":1},{"w":"BRASA","clue":"Trozo de leña al rojo vivo, sin llamas, que queda del fuego","fact":"Una brasa puede seguir caliente durante horas, aunque ya no tenga llamas.","tier":1},{"w":"MUSGO","clue":"Planta verde, suave y diminuta que crece sobre piedras húmedas","fact":"El musgo no tiene raíces de verdad: absorbe el agua por sus hojitas.","tier":1},{"w":"TALCO","clue":"Mineral muy blando que se muele para hacer polvos suaves","fact":"El talco es el mineral más blando que existe.","tier":1},{"w":"ÓXIDO","clue":"Capa rojiza que cubre el hierro mojado","fact":"El óxido aparece cuando el hierro se junta con oxígeno y agua.","tier":1},{"w":"ÓNIX","clue":"Piedra negra o con bandas paralelas, usada en joyas y adornos","fact":"El ónix suele tener bandas paralelas de colores negros, blancos o cafés.","tier":1},{"w":"MINA","clue":"Túnel bajo tierra de donde se sacan metales y piedras","fact":"Algunas minas son tan profundas que el ascensor tarda varios minutos en bajar.","tier":1},{"w":"ÁGATA","clue":"Piedra con franjas de colores, como los anillos de un tronco","fact":"Las ágatas se forman capa por capa en huecos de roca volcánica durante mucho tiempo.","tier":1},{"w":"PLOMO","clue":"Metal gris y muy pesado que se usa en pesas de pesca","fact":"El plomo es un metal tan blando que se puede rayar con una uña.","tier":1},{"w":"NEVAR","clue":"Caer copos blancos del cielo","fact":"Puede nevar aunque en el suelo no haga tanto frío, si arriba el aire está helado.","tier":1},{"w":"SIERRA","clue":"Cadena de montañas con picos en fila","fact":"Se llama sierra porque sus picos se parecen a los dientes de una sierra de cortar.","tier":2},{"w":"GRIETA","clue":"Abertura larga y estrecha en el suelo o en una roca","fact":"Las grietas aparecen cuando la tierra se seca o se mueve en un temblor.","tier":2},{"w":"CHARCO","clue":"Pequeña poza de agua de lluvia en la calle","fact":"Los charcos desaparecen porque el sol calienta el agua y esta se evapora.","tier":2},{"w":"ARCILLA","clue":"Tierra suave y pegajosa que se moldea para hacer vasijas","fact":"La arcilla se endurece como piedra cuando se calienta en un horno muy caliente.","tier":2},{"w":"GRANITO","clue":"Roca dura y moteada que se usa en encimeras de cocina","fact":"El granito se forma cuando roca derretida se enfría despacio, muy adentro de la Tierra.","tier":2},{"w":"CUARZO","clue":"Cristal duro, transparente o lechoso, común en las rocas","fact":"Los relojes de cuarzo funcionan con un cristalito que vibra cuando le llega electricidad.","tier":2},{"w":"VERANO","clue":"Estación más calurosa del año, con días largos","fact":"Es verano cuando tu parte de la Tierra está inclinada hacia el Sol.","tier":2},{"w":"BASALTO","clue":"Roca oscura que se forma cuando la lava se enfría","fact":"Gran parte del fondo del océano está hecha de basalto.","tier":2},{"w":"LLANURA","clue":"Terreno muy extenso y plano, sin montañas","fact":"Las llanuras son buenas para sembrar porque son planas y su suelo suele ser fértil.","tier":2},{"w":"RÁFAGA","clue":"Golpe de viento fuerte que dura un instante","fact":"Las ráfagas ocurren porque el aire se mueve a golpes desiguales y no de forma pareja.","tier":2},{"w":"ISLOTE","clue":"Isla muy pequeña, a veces solo un montón de rocas","fact":"Algunos islotes son el hogar de miles de aves marinas.","tier":2},{"w":"CALIZA","clue":"Roca clara hecha de conchas y esqueletos de animales marinos antiguos","fact":"Muchas cuevas se forman cuando el agua de lluvia va disolviendo la caliza poco a poco.","tier":2},{"w":"MÁRMOL","clue":"Roca lisa y brillante que se usa para esculturas y pisos","fact":"El mármol es caliza que cambió por mucho calor y presión bajo la tierra.","tier":2},{"w":"HIERRO","clue":"Metal duro y gris con el que se hacen rieles y herramientas","fact":"El centro de la Tierra está hecho sobre todo de hierro y níquel.","tier":2},{"w":"LLOVER","clue":"Caer gotas de agua del cielo","fact":"En algunos lugares del mundo llueve casi todos los días del año.","tier":2},{"w":"TEMBLOR","clue":"Sacudida corta y suave del suelo, más leve que un terremoto","fact":"Todos los días ocurren miles de temblores muy pequeños que casi nadie siente.","tier":2},{"w":"NUBLADO","clue":"Día en que el cielo está cubierto de nubes grises","fact":"Las noches nubladas suelen ser más cálidas porque las nubes atrapan el calor.","tier":2},{"w":"SOLEADO","clue":"Día claro y brillante, sin nubes que tapen la luz","fact":"Al mediodía tu sombra es más corta que al amanecer.","tier":2},{"w":"HUMEDAD","clue":"Cantidad de vapor de agua que hay en el aire","fact":"Con mucha humedad el sudor se seca mal y sientes más calor.","tier":2},{"w":"ZAFIRO","clue":"Gema azul intenso, muy dura","fact":"El zafiro es de los minerales más duros que existen.","tier":2},{"w":"TOPACIO","clue":"Gema transparente y brillante, a veces de color miel","fact":"El topacio puede ser amarillo, azul, rosa o incoloro.","tier":2},{"w":"GRANATE","clue":"Gema de un rojo oscuro, parecida a las semillas de una fruta","fact":"El granate casi siempre es rojo oscuro, pero también existe naranja y verde.","tier":2},{"w":"AZUFRE","clue":"Mineral amarillo brillante que se encuentra cerca de los volcanes","fact":"Cerca de algunos volcanes huele a huevo podrido por los gases con azufre.","tier":2},{"w":"PIZARRA","clue":"Roca gris oscura que se parte en láminas planas, usada en techos","fact":"Con pizarra se hacían techos y los tableros donde antes se escribía en las escuelas.","tier":2},{"w":"GRAFITO","clue":"Mineral gris y suave que deja marcas oscuras sobre el papel","fact":"La punta de un lápiz es de grafito mezclado con arcilla, no de plomo.","tier":2},{"w":"CHISPA","clue":"Partícula brillante que salta de una fogata o de un cable","fact":"Si golpeas pedernal contra acero salen chispas.","tier":2},{"w":"SOPLAR","clue":"Echar aire por la boca para apagar una vela","fact":"El viento es aire que se mueve porque el aire caliente sube y el frío ocupa su lugar.","tier":2},{"w":"ALUVIÓN","clue":"Corriente repentina de agua, lodo y piedras que baja de un cerro","fact":"Los aluviones ocurren después de lluvias muy fuertes en las montañas.","tier":2},{"w":"FOGATA","clue":"Fuego al aire libre, rodeado de piedras, para calentarse de noche","fact":"Los seres humanos usan fogatas desde hace cientos de miles de años.","tier":2},{"w":"GEÓLOGO","clue":"Científico que estudia las rocas, los volcanes y los fósiles","fact":"Los geólogos leen las capas de roca como páginas de un libro muy antiguo.","tier":2},{"w":"ESTAÑO","clue":"Metal blando y plateado con el que se cubren las latas","fact":"El estaño se usa desde hace miles de años; mezclado con cobre da bronce.","tier":2},{"w":"NÍQUEL","clue":"Metal plateado que resiste el óxido y brilla mucho","fact":"Muchas monedas llevan níquel porque es un metal duro que casi no se desgasta.","tier":2},{"w":"INVIERNO","clue":"Estación más fría del año, de días cortos","fact":"En invierno los días son cortos porque el Sol sube poco en el cielo.","tier":3},{"w":"PRIMAVERA","clue":"Estación de flores y brotes nuevos, después del invierno","fact":"Al comenzar la primavera, el día y la noche duran casi lo mismo.","tier":3},{"w":"ATARDECER","clue":"Momento en que el Sol baja y el cielo se pone naranja","fact":"Los atardeceres se ven rojizos porque la luz del Sol atraviesa más aire para llegar a ti.","tier":3},{"w":"AMANECER","clue":"Momento en que sale el sol y termina la noche","fact":"El Sol parece salir porque la Tierra gira sobre sí misma.","tier":3},{"w":"PARARRAYOS","clue":"Barra metálica sobre un techo que atrae las descargas de las nubes","fact":"Un pararrayos lleva la electricidad de la descarga por un cable hasta la tierra sin dañar el edificio.","tier":3},{"w":"OBSIDIANA","clue":"Vidrio negro y brillante formado cuando la lava se enfría rápido","fact":"Los pueblos antiguos de América hacían espejos y herramientas con obsidiana.","tier":3},{"w":"NUBARRÓN","clue":"Nube grande y oscura que anuncia lluvia","fact":"Las nubes oscuras tienen tantas gotas que casi no dejan pasar la luz.","tier":3},{"w":"ESTALAGMITA","clue":"Roca puntiaguda que crece hacia arriba desde el piso de una cueva","fact":"Las estalagmitas crecen muy despacio, a veces menos de un milímetro por año.","tier":3},{"w":"INUNDACIÓN","clue":"Cuando mucha agua cubre tierra que suele estar seca","fact":"Las crecidas del río Nilo dejaban lodo fértil donde los agricultores sembraban.","tier":3},{"w":"DERRUMBE","clue":"Caída de rocas y tierra por una ladera empinada","fact":"La lluvia fuerte puede empapar una ladera hasta que la tierra suelta se deslice.","tier":3},{"w":"TEMPERATURA","clue":"Qué tan caliente o frío está algo, medido en grados","fact":"Mientras más subes una montaña, más baja la temperatura.","tier":3},{"w":"PRONÓSTICO","clue":"Anuncio de cómo estará el tiempo en los próximos días","fact":"Los meteorólogos usan satélites, globos y computadoras para hacer el pronóstico.","tier":3},{"w":"BARÓMETRO","clue":"Aparato que mide la presión del aire y ayuda a anunciar tormentas","fact":"Cuando la presión baja en un barómetro, a menudo viene una tormenta.","tier":3},{"w":"PARAGUAS","clue":"Cúpula plegable con mango que te mantiene seco en un aguacero","fact":"Los paraguas se usaron primero para dar sombra y después para la lluvia.","tier":3},{"w":"ESMERALDA","clue":"Gema de un verde profundo, como el pasto fresco","fact":"Colombia es famosa en el mundo por sus esmeraldas.","tier":3},{"w":"IMPERMEABLE","clue":"Abrigo ligero que no deja pasar el agua de la lluvia","fact":"En un impermeable el agua forma gotas y resbala sin mojar la tela.","tier":3},{"w":"VENTISCA","clue":"Viento helado y fuerte que arrastra nieve","fact":"En una ventisca se ve muy poco, porque la nieve vuela en todas direcciones.","tier":3},{"w":"SOLSTICIO","clue":"Día del año con el día o la noche más largos","fact":"En el solsticio de verano ocurre el día más largo del año en tu mitad de la Tierra.","tier":3},{"w":"EQUINOCCIO","clue":"Dos veces al año, el día y la noche duran casi igual","fact":"La palabra equinoccio viene del latín y significa noche igual.","tier":3},{"w":"PETRÓLEO","clue":"Líquido negro y espeso que sale de pozos y se vuelve gasolina","fact":"El petróleo se formó hace millones de años de animalitos y algas del mar.","tier":3},{"w":"ANEMÓMETRO","clue":"Aparato de copitas giratorias que mide la velocidad del viento","fact":"La palabra anemómetro viene de una palabra griega que significa viento.","tier":3},{"w":"PLUVIÓMETRO","clue":"Recipiente que mide cuánta lluvia cae","fact":"Un pluviómetro puede ser un simple tubo transparente con rayitas para medir el agua.","tier":3},{"w":"ERUPCIÓN","clue":"Salida repentina de lava, ceniza y gases de un volcán","fact":"Una erupción puede lanzar ceniza a muchos kilómetros de altura.","tier":3},{"w":"SISMÓGRAFO","clue":"Aparato que dibuja líneas ondulantes cuando tiembla la tierra","fact":"Los sismógrafos detectan temblores que ocurren al otro lado del planeta.","tier":3}]}},{"id":"world-landmarks","icon":"🗺️","name":{"en":"World Landmarks","es":"Lugares del mundo"},"words":{"en":[{"w":"PEAK","clue":"Pointed top of a mountain","fact":"The air gets thinner near a high peak, so climbers sometimes carry extra oxygen.","tier":1},{"w":"CAVE","clue":"Big hollow room inside a hillside or under the ground","fact":"Some caves have rivers and lakes deep inside, where sunlight never reaches.","tier":1},{"w":"LAKE","clue":"Large body of water surrounded by land","fact":"Some lakes were made by glaciers digging out huge basins in the ground.","tier":1},{"w":"DUNE","clue":"Hill of sand piled up by the wind","fact":"Sand dunes slowly travel as wind pushes grains up one side and over the top.","tier":1},{"w":"ARCH","clue":"Curved opening that holds up a bridge or doorway","fact":"Natural rock arches are carved by wind and water over thousands of years.","tier":1},{"w":"OASIS","clue":"Green spot with water in the middle of a desert","fact":"Palm trees grow at an oasis, where water rises from underground.","tier":1},{"w":"DELTA","clue":"Fan-shaped land where a river meets the sea","fact":"River deltas are named for a Greek letter shaped like a triangle.","tier":1},{"w":"FJORD","clue":"Long, narrow sea inlet between steep cliffs","fact":"Fjords were carved by glaciers, then filled by the sea when the ice melted.","tier":1},{"w":"GORGE","clue":"Deep, narrow valley with steep rocky walls","fact":"A river often cuts a gorge by slowly wearing away rock over many years.","tier":1},{"w":"TOWER","clue":"Very tall, narrow building or structure","fact":"Paris's famous iron tower grows taller in summer because metal expands in heat.","tier":1},{"w":"CANAL","clue":"Waterway dug by people to move boats","fact":"The Panama Canal lifts ships up and down with giant water-filled locks.","tier":1},{"w":"CLIFF","clue":"Steep rocky wall at the edge of land or sea","fact":"Some sea cliffs rise higher than a thousand feet.","tier":1},{"w":"CASTLE","clue":"Stone fortress with towers where a king or queen lived","fact":"Many castles were built on hills so people could see far across the land.","tier":2},{"w":"TUNNEL","clue":"Underground passage dug through a mountain or under water","fact":"The Channel Tunnel connects England and France beneath the sea.","tier":2},{"w":"BRIDGE","clue":"Structure that lets people or cars cross a river","fact":"Some bridges are built to sway a little in the wind so they do not break.","tier":2},{"w":"DESERT","clue":"Land that gets very little rain","fact":"Not every desert is hot; Antarctica is a very cold desert.","tier":2},{"w":"PALACE","clue":"Fancy home of a king, queen or leader","fact":"Some palaces have hundreds of rooms.","tier":2},{"w":"STATUE","clue":"Carved or cast figure of a person or animal","fact":"The Statue of Liberty is made of thin copper sheets that turned green over time.","tier":2},{"w":"TUNDRA","clue":"Cold, treeless plain where the ground stays frozen underneath","fact":"The frozen soil under the Arctic tundra is called permafrost.","tier":2},{"w":"VOLCANO","clue":"Mountain that can erupt with melted rock and ash","fact":"Many volcanoes sit in a ring around the Pacific Ocean.","tier":2},{"w":"GLACIER","clue":"River of ice that moves very slowly downhill","fact":"Glaciers move too slowly to watch, but over time they carve out whole valleys.","tier":2},{"w":"CANYON","clue":"Deep valley with steep sides, carved by a river","fact":"Canyon walls show layers of rock like pages in a giant book.","tier":2},{"w":"PLATEAU","clue":"High, flat stretch of land","fact":"The Tibetan Plateau is so high that it is called the roof of the world.","tier":2},{"w":"PYRAMID","clue":"Ancient stone building with triangle sides meeting at a point","fact":"The Great Pyramid in Egypt is built from over two million stone blocks.","tier":2},{"w":"SAVANNA","clue":"Warm grassland with scattered trees where zebras and lions roam","fact":"Savannas have a rainy season and a dry season, and the grass turns golden when dry.","tier":2},{"w":"LAGOON","clue":"Shallow calm water separated from the sea by sand or coral","fact":"Atolls are rings of coral islands that surround a calm lagoon.","tier":2},{"w":"LIGHTHOUSE","clue":"Tower with a bright beam to guide ships","fact":"Lighthouse lenses turn lamplight into a strong beam that can be seen from miles away.","tier":3},{"w":"RAINFOREST","clue":"Thick, warm forest that gets lots of rain","fact":"Rainforests are home to more kinds of plants and animals than any other land habitat.","tier":3},{"w":"WATERFALL","clue":"Stream of water dropping off a high cliff","fact":"Waterfalls slowly wear away rock and creep upstream over many years.","tier":3},{"w":"MONUMENT","clue":"Statue or building made to remember something important","fact":"A ring of huge standing stones in England has stood for over 4,000 years.","tier":3},{"w":"FOUNTAIN","clue":"Jet of water shooting up into the air for show","fact":"Old fountains used gravity: water flowed downhill through pipes and shot up at the end.","tier":3},{"w":"MOUNTAIN","clue":"Very high landform that rises far above the land around it","fact":"Mountains form when pieces of Earth's crust push together and crumple upward.","tier":3},{"w":"SKYSCRAPER","clue":"Super tall building with many floors","fact":"Tall skyscrapers sway a little in strong wind, and some have heavy weights to steady them.","tier":3},{"w":"OBSERVATORY","clue":"Building with a big telescope for studying the stars","fact":"Many observatories are built on high mountains where the air is thin and clear.","tier":3},{"w":"AQUEDUCT","clue":"Bridge-like channel that carries water over long distances","fact":"Ancient Romans built stone aqueducts that carried water to cities using gentle slopes.","tier":3},{"w":"FORTRESS","clue":"Strong walled stronghold built to protect a town","fact":"Some fortresses were built on islands or hills so they were hard to reach.","tier":3},{"w":"NILE","clue":"Long African river where ancient Egyptians farmed","fact":"The Nile flows toward the north, so the river's mouth is at the top of Africa.","tier":1},{"w":"ALPS","clue":"Snowy mountain range in Switzerland, Austria and France","fact":"The Alps stretch across eight countries in Europe.","tier":1},{"w":"ANDES","clue":"Longest mountain range on land, running down South America","fact":"Farmers in the Andes grew the first potatoes thousands of years ago.","tier":1},{"w":"REEF","clue":"Ridge of coral or rock just below the sea's surface","fact":"The Great Barrier Reef off Australia is so big that astronauts can see it from space.","tier":1},{"w":"BEACH","clue":"Sandy shore where waves roll in and kids build sandcastles","fact":"Sand on some beaches is pink, black or even green, depending on what it is made from.","tier":1},{"w":"MOAT","clue":"Water-filled ditch around a castle to keep visitors out","fact":"A moat made it hard for enemies to dig a tunnel under the castle wall.","tier":1},{"w":"DAM","clue":"Strong wall built across a river to hold back water","fact":"Beavers are nature's dam builders, using sticks, mud and stones to block streams.","tier":1},{"w":"DOME","clue":"Rounded roof shaped like half a ball","fact":"The Pantheon in Rome has a huge concrete dome with a round hole at the top.","tier":1},{"w":"SPIRE","clue":"Tall, pointed top of a church or castle tower","fact":"The word spire comes from an old word for a sprout or blade of grass.","tier":1},{"w":"RUINS","clue":"What is left of very old buildings that crumbled","fact":"Some Roman ruins are still standing after nearly two thousand years.","tier":1},{"w":"MESA","clue":"Flat-topped hill with steep sides, found in dry lands","fact":"Mesa is the Spanish word for table, which is what these hills look like.","tier":1},{"w":"ULURU","clue":"Giant red rock in the middle of Australia's outback","fact":"Uluru looks like it glows orange and red at sunrise and sunset.","tier":1},{"w":"MOAI","clue":"Giant carved stone heads standing on Easter Island","fact":"Moai look like only heads, but many have long bodies buried under the soil.","tier":1},{"w":"PETRA","clue":"Ancient rose-colored city carved into the cliffs of Jordan","fact":"Petra was built by people called Nabataeans more than two thousand years ago.","tier":1},{"w":"GIZA","clue":"Place near Cairo, Egypt, where the Great Pyramids and Sphinx stand","fact":"The Great Pyramid of Giza was built more than 4,500 years ago.","tier":1},{"w":"FUJI","clue":"Snowcapped volcano shaped like a cone, Japan's tallest mountain","fact":"Many hikers climb Mount Fuji overnight to watch the sunrise from the top.","tier":1},{"w":"BAY","clue":"Wide curve of coastline where the sea reaches into the land","fact":"Tides in Canada's Bay of Fundy can rise taller than a four-story building.","tier":1},{"w":"ATOLL","clue":"Ring-shaped coral island circling a calm shallow sea","fact":"Many atolls began as volcano islands that slowly sank while coral kept growing.","tier":1},{"w":"FORT","clue":"Strong building where soldiers once guarded a place","fact":"Star-shaped forts had pointed corners so defenders could see along every wall.","tier":1},{"w":"CAPE","clue":"Point of land that sticks far out into the sea","fact":"Ships once sailed around Cape Horn, at the tip of South America, through stormy seas.","tier":1},{"w":"RIDGE","clue":"Long, narrow strip of high ground along the top of hills","fact":"Rain falling on opposite sides of a ridge can flow into different rivers.","tier":1},{"w":"PIER","clue":"Walkway built out over water for boats, fishing or strolling","fact":"Santa Monica Pier in California has a Ferris wheel powered by sunlight.","tier":1},{"w":"ARENA","clue":"Big building where crowds watch sports or shows","fact":"Arena is the Latin word for sand, which once covered the floor of the Colosseum.","tier":1},{"w":"SEA","clue":"Salty body of water smaller than an ocean","fact":"The Mediterranean Sea touches Europe, Asia and Africa.","tier":1},{"w":"OCEAN","clue":"Giant body of salt water; the Pacific is the biggest","fact":"Earth's oceans are all connected, so a boat could sail from one to the next.","tier":1},{"w":"POLE","clue":"Icy spot at the very top or bottom of Earth","fact":"At the North Pole, every direction you face is south.","tier":1},{"w":"ASIA","clue":"Biggest continent, home to Mount Everest, China and India","fact":"Asia covers nearly one third of all the land on Earth.","tier":1},{"w":"CORAL","clue":"Colorful reef builder made by tiny sea animals","fact":"Coral looks like rock or plants, but it is made by tiny animals called polyps.","tier":1},{"w":"SAHARA","clue":"World's biggest hot desert, stretching across northern Africa","fact":"Thousands of years ago the Sahara was green, with lakes, grass and animals.","tier":2},{"w":"EVEREST","clue":"Tallest mountain on Earth above sea level, in the Himalayas","fact":"Climbers carry extra oxygen near Everest's top because the air is so thin.","tier":2},{"w":"AMAZON","clue":"Mighty South American river flowing through a giant rainforest","fact":"Pink river dolphins swim in the Amazon River.","tier":2},{"w":"GEYSER","clue":"Hot spring that shoots a tall jet of water and steam","fact":"A geyser erupts when underground water heated by hot rock bursts upward.","tier":2},{"w":"CRATER","clue":"Bowl-shaped hole left by a volcano or a space rock","fact":"Meteor Crater in Arizona was made by a space rock about 50,000 years ago.","tier":2},{"w":"SPHINX","clue":"Egyptian statue with a lion's body and a human head","fact":"The Great Sphinx near Giza was carved from one huge piece of limestone.","tier":2},{"w":"LOUVRE","clue":"Huge Paris museum with a glass pyramid out front","fact":"The Louvre was a royal castle long before it became a museum.","tier":2},{"w":"ISTHMUS","clue":"Narrow strip of land linking two bigger pieces of land","fact":"The Isthmus of Panama connects North America and South America.","tier":2},{"w":"OBELISK","clue":"Tall, thin, four-sided stone pillar with a pointed top","fact":"Many ancient Egyptian obelisks were carved from a single block of granite.","tier":2},{"w":"STADIUM","clue":"Giant building where crowds watch baseball or soccer games","fact":"The word comes from the Greek stadion, a distance of about 600 feet.","tier":2},{"w":"AFRICA","clue":"Continent where you find Egypt's pyramids, lions and the Sahara","fact":"The equator crosses Africa, which has rainforests, deserts and even snowy mountains.","tier":2},{"w":"EUROPE","clue":"Continent with Italy, France, Spain and the Alps","fact":"Europe and Asia are joined as one giant landmass called Eurasia.","tier":2},{"w":"ARCTIC","clue":"Icy region around the top of the world, where polar bears live","fact":"The Arctic is mostly frozen ocean, while Antarctica is a frozen continent.","tier":2},{"w":"ISLAND","clue":"Land with water all the way around it","fact":"Some islands are the tops of volcanoes that have risen above the sea.","tier":2},{"w":"CAVERN","clue":"Huge hollow room deep underground, with dripping stalactites","fact":"Carlsbad Caverns in New Mexico has a single room as big as six football fields.","tier":2},{"w":"PAGODA","clue":"Tall East Asian tower with several curved roofs","fact":"Many pagodas have an odd number of levels, such as three, five or seven.","tier":2},{"w":"NIAGARA","clue":"Famous thundering waterfalls on the United States and Canada border","fact":"Niagara Falls is really three waterfalls: Horseshoe, American and Bridal Veil.","tier":2},{"w":"HAWAII","clue":"Pacific island chain built by volcanoes, a US state","fact":"Measured from the ocean floor, Hawaii's Mauna Kea is taller than Mount Everest.","tier":2},{"w":"RAPIDS","clue":"Fast, bumpy part of a river where water rushes over rocks","fact":"River rapids are rated from Class I, which is gentle, to Class VI, which is extreme.","tier":2},{"w":"EIFFEL","clue":"Iron tower in Paris named after its engineer","fact":"The Eiffel Tower grows a few inches taller in summer, when heat expands its iron.","tier":2},{"w":"TRENCH","clue":"Deep, narrow valley on the ocean floor","fact":"The Mariana Trench is deeper than Mount Everest is tall.","tier":2},{"w":"SKYLINE","clue":"Outline of a city's tall buildings against the sky","fact":"The world's first skyscraper was built in Chicago in the 1880s.","tier":2},{"w":"HARBOR","clue":"Sheltered port where ships and boats can safely stay","fact":"Many great cities, like New York and Sydney, grew up around natural harbors.","tier":2},{"w":"MUSEUM","clue":"Place where visitors look at fossils, art and old objects","fact":"Many museums display real dinosaur skeletons that were dug out of the ground.","tier":2},{"w":"SUMMIT","clue":"Highest point at the top of a mountain","fact":"People first reached the summit of Mount Everest in 1953.","tier":2},{"w":"VALLEY","clue":"Low land between hills or mountains, often with a river","fact":"Death Valley in California is one of the hottest places on Earth.","tier":2},{"w":"JUNGLE","clue":"Thick, hot forest full of vines, monkeys and parrots","fact":"In a thick jungle, very little sunlight reaches the ground.","tier":2},{"w":"EQUATOR","clue":"Imaginary line around the middle of Earth","fact":"Near the equator, days and nights stay almost the same length all year.","tier":2},{"w":"HORIZON","clue":"Faraway line where the sky seems to touch the sea","fact":"Standing on a beach, you can see about three miles to the horizon.","tier":2},{"w":"PRAIRIE","clue":"Wide, flat grassland of North America","fact":"Some prairie grasses have roots that grow deeper than a grown-up is tall.","tier":2},{"w":"ICEBERG","clue":"Huge floating chunk of ice, mostly hidden underwater","fact":"About nine tenths of an iceberg is below the water.","tier":2},{"w":"MARINA","clue":"Dock area where people keep sailboats and yachts","fact":"Marina del Rey in Los Angeles was dug out of marshland and holds thousands of boats.","tier":2},{"w":"STONEHENGE","clue":"Ring of giant standing stones on a grassy plain in England","fact":"Some of Stonehenge's stones were carried from Wales, about 150 miles away.","tier":3},{"w":"COLOSSEUM","clue":"Giant oval arena in Rome, built almost two thousand years ago","fact":"The Colosseum could seat tens of thousands, about as many as a big baseball stadium.","tier":3},{"w":"PARTHENON","clue":"Ancient marble building with tall columns on a hill in Athens","fact":"The Parthenon has stood on the Acropolis in Athens for nearly 2,500 years.","tier":3},{"w":"ACROPOLIS","clue":"High rocky hill in Athens topped by ancient Greek buildings","fact":"Acropolis means \"high city\" in Greek.","tier":3},{"w":"MATTERHORN","clue":"Pointed, pyramid-shaped Alpine peak between Switzerland and Italy","fact":"The Matterhorn has four steep faces, so it looks like a giant pyramid.","tier":3},{"w":"HIMALAYAS","clue":"Huge Asian mountain range that includes Mount Everest","fact":"The Himalayas are still growing taller by a few millimeters each year.","tier":3},{"w":"KILIMANJARO","clue":"Africa's tallest mountain, a volcano rising alone from the plains","fact":"Kilimanjaro has three volcano cones, named Kibo, Mawenzi and Shira.","tier":3},{"w":"SERENGETI","clue":"Vast African grassland where millions of animals migrate","fact":"Each year over a million wildebeest travel across the Serengeti following the rains.","tier":3},{"w":"ANTARCTICA","clue":"Icy southern continent around the South Pole, home to penguins","fact":"Antarctica is the coldest, windiest and driest continent.","tier":3},{"w":"GREENLAND","clue":"World's biggest island, mostly buried under thick ice","fact":"Despite its name, most of Greenland is covered in ice, not grass.","tier":3},{"w":"VESUVIUS","clue":"Volcano near Naples, Italy, that buried the town of Pompeii","fact":"Ash from Vesuvius kept the Roman town of Pompeii preserved for over 1,600 years.","tier":3},{"w":"PENINSULA","clue":"Land surrounded by water on three sides","fact":"Florida is a peninsula, and so is Baja California.","tier":3},{"w":"ARCHIPELAGO","clue":"Chain or cluster of many islands","fact":"Hawaii is an archipelago with eight main islands.","tier":3},{"w":"HEMISPHERE","clue":"Half of the Earth, like north or south","fact":"California is in both the Northern Hemisphere and the Western Hemisphere.","tier":3},{"w":"CONTINENT","clue":"Giant area of land such as Africa or Antarctica","fact":"Asia is the biggest continent, and Australia is the smallest.","tier":3},{"w":"LANDMARK","clue":"Famous place that helps you spot where you are","fact":"Sailors long ago used tall rocks, hills and towers as landmarks to find their way.","tier":3},{"w":"PLANETARIUM","clue":"Dome theater that shows the stars on its ceiling","fact":"The first modern planetarium projector was built in Germany in the 1920s.","tier":3},{"w":"AQUARIUM","clue":"Building with huge tanks of fish, sharks and jellyfish","fact":"The first public aquarium opened at the London Zoo in 1853.","tier":3},{"w":"BALLPARK","clue":"Place where baseball fans watch games, with a diamond-shaped infield","fact":"Every major-league infield is the same size, with bases 90 feet apart, but outfields differ.","tier":3},{"w":"DRAWBRIDGE","clue":"Castle entrance that lifts up on chains to cross a moat","fact":"Some drawbridges are still used today to let tall boats pass.","tier":3},{"w":"COASTLINE","clue":"The long edge where land meets the sea","fact":"A coastline gets longer the closer you measure it, because of all the tiny bays and rocks.","tier":3},{"w":"TIDEPOOL","clue":"Small pool of seawater left behind among rocks at low tide","fact":"Tide pools are tiny ocean worlds with sea stars, crabs and anemones.","tier":3},{"w":"SHIPWRECK","clue":"Sunken ship resting on the seafloor","fact":"Shipwrecks become underwater homes for fish, octopuses and coral.","tier":3},{"w":"BADLANDS","clue":"Dry land carved by wind and rain into strange ridges and spikes","fact":"The Badlands in South Dakota hold fossils of animals that lived millions of years ago.","tier":3}],"es":[{"w":"FARO","clue":"Torre con una luz potente que guía a los barcos","fact":"Las lámparas de los faros usan lentes especiales para lanzar un rayo que se ve desde lejos.","tier":1},{"w":"LAGO","clue":"Gran extensión de agua rodeada de tierra","fact":"Algunos lagos nacen cuando un glaciar excava un enorme hueco en la tierra.","tier":1},{"w":"TORRE","clue":"Construcción muy alta y angosta","fact":"La torre de hierro de París crece unos 15 centímetros con el calor del verano.","tier":1},{"w":"CERRO","clue":"Montaña pequeña o colina alta, de cima redondeada","fact":"La ciudad de Quito está rodeada de cerros y volcanes.","tier":1},{"w":"VALLE","clue":"Terreno bajo entre dos montañas","fact":"Un valle puede formarse cuando un río o un glaciar va tallando la tierra.","tier":1},{"w":"DUNA","clue":"Colina de arena amontonada por el viento","fact":"Las dunas se desplazan lentamente cuando el viento empuja la arena por un lado.","tier":1},{"w":"OASIS","clue":"Lugar verde con agua en medio del desierto","fact":"En un oasis crecen palmeras porque el agua sube desde bajo la tierra.","tier":1},{"w":"CIMA","clue":"La parte más alta de una montaña","fact":"Cerca de las cimas más altas el aire es tan delgado que cuesta respirar.","tier":1},{"w":"COSTA","clue":"Zona de tierra que está junto al mar","fact":"Ecuador tiene cuatro regiones: Costa, Sierra, Amazonía y Galápagos.","tier":1},{"w":"CANAL","clue":"Camino de agua hecho por personas para que pasen barcos","fact":"El Canal de Panamá sube y baja a los barcos con grandes cámaras llenas de agua.","tier":1},{"w":"ARCO","clue":"Estructura curva que sostiene un puente o una puerta","fact":"Los arcos naturales de roca los tallan el viento y el agua durante miles de años.","tier":1},{"w":"SELVA","clue":"Bosque tropical muy espeso y húmedo con árboles altísimos","fact":"La selva amazónica de Ecuador es una de las más ricas en especies del mundo.","tier":1},{"w":"PUENTE","clue":"Construcción que permite cruzar un río","fact":"Algunos puentes se mueven un poco con el viento para no romperse.","tier":2},{"w":"PALACIO","clue":"Casa enorme y lujosa de un rey o una reina","fact":"Algunos palacios tienen cientos de habitaciones.","tier":2},{"w":"ESTATUA","clue":"Figura tallada en piedra o metal que representa a alguien","fact":"La Estatua de la Libertad es de láminas de cobre que se pusieron verdes con el tiempo.","tier":2},{"w":"VOLCÁN","clue":"Montaña que puede lanzar lava y ceniza","fact":"Ecuador forma parte del Cinturón de Fuego del Pacífico, por eso tiene muchos volcanes.","tier":2},{"w":"GLACIAR","clue":"Río de hielo que baja muy despacio por la montaña","fact":"Los glaciares se mueven tan despacio que no se ven, pero tallan valles enteros.","tier":2},{"w":"MESETA","clue":"Terreno alto y plano","fact":"La meseta del Tíbet es tan alta que la llaman el techo del mundo.","tier":2},{"w":"SABANA","clue":"Pradera cálida con árboles dispersos donde viven cebras y leones","fact":"En la sabana hay una época de lluvias y otra de sequía, y los pastos se ponen dorados.","tier":2},{"w":"LAGUNA","clue":"Lago pequeño y poco profundo","fact":"Ecuador tiene lagunas dentro de cráteres de volcanes, como la de Quilotoa.","tier":2},{"w":"TUNDRA","clue":"Llanura fría sin árboles con el suelo helado por debajo","fact":"Bajo la tundra el suelo está helado todo el año y se llama permafrost.","tier":2},{"w":"CASCADA","clue":"Chorro de agua que cae desde lo alto de una roca","fact":"Las cascadas van desgastando la roca y, con los años, se desplazan río arriba.","tier":2},{"w":"FIORDO","clue":"Entrada larga y angosta del mar entre montañas altas","fact":"Los glaciares tallaron los fiordos y luego el mar los llenó al derretirse el hielo.","tier":2},{"w":"MURALLA","clue":"Pared gruesa que rodea y protege una ciudad","fact":"La Gran Muralla china está hecha de muchos muros construidos durante siglos.","tier":2},{"w":"MIRADOR","clue":"Lugar alto desde donde se contempla un paisaje","fact":"Quito tiene miradores desde donde se ven volcanes nevados en días despejados.","tier":2},{"w":"MONTAÑA","clue":"Elevación enorme de terreno, mucho más alta que lo que la rodea","fact":"Las montañas nacen cuando las placas de la Tierra se empujan y el suelo se arruga hacia arriba.","tier":2},{"w":"PIRÁMIDE","clue":"Construcción antigua con caras triangulares que terminan en punta","fact":"La Gran Pirámide de Egipto tiene más de dos millones de bloques de piedra.","tier":3},{"w":"CASTILLO","clue":"Fortaleza de piedra con torres donde vivía un rey","fact":"Muchos castillos se construían en lo alto de cerros para ver a lo lejos.","tier":3},{"w":"DESIERTO","clue":"Tierra donde llueve muy poco","fact":"No todos los desiertos son calientes: la Antártida es un desierto helado.","tier":3},{"w":"RASCACIELOS","clue":"Edificio altísimo con muchos pisos","fact":"Los rascacielos se mecen un poco con el viento fuerte, y algunos tienen pesas para estabilizarse.","tier":3},{"w":"ACUEDUCTO","clue":"Canal elevado que lleva agua a lo largo de grandes distancias","fact":"Los romanos construyeron acueductos de piedra que llevaban agua a las ciudades por suaves pendientes.","tier":3},{"w":"FORTALEZA","clue":"Construcción fuerte con murallas gruesas que protege una ciudad","fact":"Algunas fortalezas se construyeron en islas o cerros para que fueran difíciles de alcanzar.","tier":3},{"w":"MONUMENTO","clue":"Estatua o edificio hecho para recordar algo importante","fact":"Un círculo de enormes piedras en Inglaterra lleva más de 4000 años en pie.","tier":3},{"w":"PENÍNSULA","clue":"Tierra rodeada de agua por todos lados menos uno","fact":"Italia es una península con forma de bota.","tier":3},{"w":"CORDILLERA","clue":"Larga cadena de montañas, como los Andes","fact":"Los Andes cruzan siete países de Sudamérica, incluido Ecuador.","tier":3},{"w":"CATARATAS","clue":"Enormes caídas de agua, más grandes que una cascada","fact":"En las cataratas del Iguazú caen cientos de saltos de agua entre Argentina y Brasil.","tier":3},{"w":"ISLA","clue":"Pedazo de tierra con agua por todos lados","fact":"Algunas islas son la punta de volcanes que salieron del fondo del mar.","tier":1},{"w":"MAR","clue":"Gran extensión de agua salada donde navegan los barcos","fact":"Más del setenta por ciento de la superficie de la Tierra está cubierta por agua.","tier":1},{"w":"RÍO","clue":"Corriente de agua dulce que baja de las montañas hacia el mar","fact":"Muchos ríos nacen como pequeños arroyos en lo alto de las montañas.","tier":1},{"w":"PLAYA","clue":"Orilla de arena suave donde llegan las olas","fact":"La arena de algunas playas es rosada, negra o hasta verde.","tier":1},{"w":"BAHÍA","clue":"Curva grande de la costa donde el mar entra en la tierra","fact":"En la bahía de Fundy, en Canadá, la marea sube más que un edificio de cuatro pisos.","tier":1},{"w":"CUEVA","clue":"Hueco grande y oscuro dentro de una montaña","fact":"En algunas cuevas hay dibujos hechos por personas hace miles de años.","tier":1},{"w":"NILO","clue":"Larguísimo río de África donde vivieron los antiguos egipcios","fact":"El Nilo corre hacia el norte, así que su desembocadura queda arriba en el mapa.","tier":1},{"w":"ANDES","clue":"Montañas altísimas que cruzan Chile, Perú y Argentina","fact":"Los primeros agricultores de papa vivieron en los Andes hace miles de años.","tier":1},{"w":"ALPES","clue":"Montañas nevadas de Europa famosas por el esquí","fact":"Los Alpes cruzan ocho países de Europa.","tier":1},{"w":"UYUNI","clue":"Desierto blanco de sal en Bolivia que parece un espejo","fact":"Cuando llueve, el Salar de Uyuni se vuelve un espejo gigante que refleja el cielo.","tier":1},{"w":"FUJI","clue":"Volcán nevado de Japón con forma de cono casi perfecto","fact":"Mucha gente sube al monte Fuji de noche para ver salir el sol desde la cima.","tier":1},{"w":"TIKAL","clue":"Ciudad maya de templos de piedra en la selva de Guatemala","fact":"Algunos templos de Tikal sobresalen por encima de las copas de los árboles.","tier":1},{"w":"MOÁI","clue":"Gigantescas cabezas de piedra de la isla de Pascua","fact":"Los moáis parecen solo cabezas, pero muchos tienen el cuerpo enterrado bajo la tierra.","tier":1},{"w":"PRESA","clue":"Muro enorme que detiene el agua de un río","fact":"Los castores hacen presas con ramas, barro y piedras.","tier":1},{"w":"FOSO","clue":"Zanja con agua alrededor de un castillo","fact":"Un foso dificultaba que los enemigos cavaran un túnel bajo la muralla.","tier":1},{"w":"PLAZA","clue":"Espacio abierto en el centro del pueblo, con bancas","fact":"En muchos pueblos de Latinoamérica, la plaza es donde se junta la gente.","tier":1},{"w":"HAWÁI","clue":"Islas del Pacífico con volcanes, surf y collares de flores","fact":"Medido desde el fondo del mar, el Mauna Kea de Hawái es más alto que el Everest.","tier":1},{"w":"ASIA","clue":"El continente más grande, donde están China, India y el Everest","fact":"Asia ocupa casi un tercio de toda la tierra firme del planeta.","tier":1},{"w":"CORAL","clue":"Animalitos del mar que construyen arrecifes de colores","fact":"El coral parece roca o planta, pero lo hacen animalitos llamados pólipos.","tier":1},{"w":"CAÑÓN","clue":"Valle hondo con paredes de roca, tallado por un río","fact":"El Gran Cañón de Arizona fue tallado por el río Colorado durante millones de años.","tier":1},{"w":"CABO","clue":"Punta de tierra que se adentra mucho en el mar","fact":"El Cabo de Hornos, al sur de América, es famoso por sus mares bravos.","tier":1},{"w":"ISTMO","clue":"Franja estrecha de tierra que une dos tierras grandes","fact":"El istmo de Panamá une América del Norte con América del Sur.","tier":1},{"w":"TÚNEL","clue":"Pasaje largo que atraviesa una montaña o pasa bajo la tierra","fact":"Muchos túneles se cavan con enormes máquinas llamadas tuneladoras.","tier":1},{"w":"MUSEO","clue":"Lugar donde se exhiben fósiles, arte y objetos antiguos","fact":"Muchos museos muestran esqueletos reales de dinosaurios sacados de la tierra.","tier":1},{"w":"DELTA","clue":"Terreno en forma de abanico donde un río llega al mar","fact":"Se llama delta por una letra griega con forma de triángulo, como el delta del Nilo.","tier":1},{"w":"PICO","clue":"Punta alta y afilada de una montaña","fact":"El Aconcagua es el pico más alto de los Andes y de toda América.","tier":1},{"w":"PAMPA","clue":"Llanura enorme y plana cubierta de pasto, en Argentina","fact":"La palabra pampa viene del quechua y significa llanura.","tier":1},{"w":"CAYO","clue":"Isla pequeña y plana de arena y coral en el Caribe","fact":"Muchos cayos del Caribe están hechos de arena y restos de coral.","tier":1},{"w":"ÁFRICA","clue":"Continente con el Sahara, las pirámides de Egipto y los leones","fact":"El ecuador cruza África, que tiene selvas, desiertos y hasta montañas con nieve.","tier":2},{"w":"EUROPA","clue":"Continente de España, Francia, Italia y los Alpes","fact":"Europa y Asia forman una sola masa de tierra llamada Eurasia.","tier":2},{"w":"ÁRTICO","clue":"Región helada alrededor del Polo Norte, donde viven los osos polares","fact":"El Ártico es sobre todo océano congelado; la Antártida, en cambio, es un continente de hielo.","tier":2},{"w":"OCÉANO","clue":"Enorme extensión de agua salada; el Pacífico es el más grande","fact":"Los océanos de la Tierra están conectados, así que un barco puede navegar de uno a otro.","tier":2},{"w":"ATOLÓN","clue":"Isla de coral en forma de anillo que rodea una laguna","fact":"Muchos atolones nacieron de volcanes que se hundieron mientras el coral seguía creciendo.","tier":2},{"w":"CRÁTER","clue":"Hoyo en forma de tazón dejado por un volcán o un meteorito","fact":"El Cráter del Meteoro, en Arizona, lo hizo una roca del espacio hace unos cincuenta mil años.","tier":2},{"w":"GÉISER","clue":"Fuente natural que lanza un chorro de agua caliente y vapor","fact":"Un géiser estalla cuando el agua calentada bajo tierra por roca caliente sale disparada hacia arriba.","tier":2},{"w":"ESFINGE","clue":"Estatua egipcia con cuerpo de león y cabeza de persona","fact":"La Gran Esfinge de Guiza fue tallada en un solo bloque enorme de piedra caliza.","tier":2},{"w":"IGUAZÚ","clue":"Enormes saltos de agua entre Argentina y Brasil, en plena selva","fact":"Las cataratas del Iguazú son más de doscientos saltos de agua rodeados de selva.","tier":2},{"w":"ATACAMA","clue":"Desierto de Chile, uno de los lugares más secos del mundo","fact":"En partes del Atacama pasan años enteros sin una gota de lluvia.","tier":2},{"w":"CARIBE","clue":"Mar cálido de aguas turquesas, con islas, arrecifes y cayos","fact":"En el Caribe está el segundo arrecife de coral más grande del mundo.","tier":2},{"w":"MUELLE","clue":"Estructura que se mete en el mar para que los barcos atraquen","fact":"El muelle de Santa Mónica, en California, tiene una rueda de la fortuna que funciona con luz solar.","tier":2},{"w":"PUERTO","clue":"Lugar protegido de la costa donde llegan y salen los barcos","fact":"Muchas ciudades grandes crecieron junto a un puerto natural.","tier":2},{"w":"ESTADIO","clue":"Lugar enorme donde miles de personas ven un partido de béisbol","fact":"La palabra estadio viene del griego stadion, una medida de unos 185 metros.","tier":2},{"w":"CÚPULA","clue":"Techo redondo con forma de media pelota","fact":"El Panteón de Roma tiene una cúpula de concreto con un agujero redondo arriba.","tier":2},{"w":"RUINAS","clue":"Lo que queda de edificios muy antiguos que se derrumbaron","fact":"Algunas ruinas de Roma siguen en pie después de casi dos mil años.","tier":2},{"w":"SIERRA","clue":"Cadena de montañas con picos que parecen dientes","fact":"La palabra sierra también nombra una herramienta con dientes para cortar madera.","tier":2},{"w":"COLINA","clue":"Elevación suave del terreno, más baja que una montaña","fact":"La ciudad de Roma está construida sobre siete colinas.","tier":2},{"w":"ACUARIO","clue":"Edificio con enormes peceras llenas de peces, tiburones y medusas","fact":"El primer acuario público abrió en el zoológico de Londres en 1853.","tier":2},{"w":"CAVERNA","clue":"Cueva gigantesca y profunda con estalactitas que cuelgan del techo","fact":"Las Cavernas de Carlsbad, en Nuevo México, tienen una sala del tamaño de seis canchas de fútbol americano.","tier":2},{"w":"CENOTE","clue":"Pozo natural de agua dulce y cristalina en Yucatán, México","fact":"Los antiguos mayas sacaban agua dulce de los cenotes.","tier":2},{"w":"FUENTE","clue":"Estructura de piedra con chorros de agua en una plaza","fact":"Los antiguos romanos construyeron fuentes públicas para que todos pudieran tomar agua.","tier":2},{"w":"LOUVRE","clue":"Gran museo de París con una pirámide de cristal en la entrada","fact":"El Louvre fue un castillo de reyes antes de convertirse en museo.","tier":2},{"w":"EIFFEL","clue":"Torre de hierro de París que lleva el nombre de su ingeniero","fact":"La torre Eiffel crece unos centímetros en verano porque el calor dilata el hierro.","tier":2},{"w":"SAHARA","clue":"El desierto caliente más grande del mundo, en el norte de África","fact":"Hace miles de años el Sahara era verde, con lagos y pastizales.","tier":2},{"w":"EVEREST","clue":"La montaña más alta de la Tierra sobre el nivel del mar","fact":"Cerca de la cima del Everest hay tan poco aire que los alpinistas llevan oxígeno extra.","tier":2},{"w":"NIÁGARA","clue":"Famosas cataratas en la frontera entre Estados Unidos y Canadá","fact":"Las cataratas del Niágara son en realidad tres: Herradura, Americana y Velo de Novia.","tier":2},{"w":"LLANURA","clue":"Terreno muy grande y plano, sin montañas ni colinas","fact":"En Venezuela y Colombia hay llanuras enormes donde viven los capibaras.","tier":2},{"w":"ECUADOR","clue":"Línea imaginaria que rodea la Tierra por la mitad","fact":"El país Ecuador se llama así porque la línea del ecuador lo cruza.","tier":2},{"w":"ICEBERG","clue":"Enorme bloque de hielo flotante, casi todo escondido bajo el agua","fact":"Casi nueve décimas partes de un iceberg quedan bajo el agua.","tier":2},{"w":"JUNGLA","clue":"Bosque caliente y espeso lleno de lianas, monos y loros","fact":"En una jungla espesa llega muy poca luz del sol hasta el suelo.","tier":2},{"w":"PANTANO","clue":"Terreno bajo y encharcado, con plantas y árboles dentro del agua","fact":"Los cipreses de los pantanos sacan raíces que sobresalen del agua como rodillas.","tier":2},{"w":"ARRECIFE","clue":"Cresta de coral o roca cerca de la superficie del mar","fact":"La Gran Barrera de Coral, en Australia, es tan grande que se ve desde el espacio.","tier":3},{"w":"OBELISCO","clue":"Pilar de piedra alto, delgado y de cuatro lados, con punta","fact":"Muchos obeliscos del antiguo Egipto se tallaron de un solo bloque de granito.","tier":3},{"w":"ESTRECHO","clue":"Paso angosto de mar entre dos tierras","fact":"El estrecho de Magallanes, en el sur de Chile, une el océano Atlántico con el Pacífico.","tier":3},{"w":"GALÁPAGOS","clue":"Islas volcánicas de Ecuador donde viven tortugas gigantes","fact":"Las tortugas gigantes de las islas Galápagos pueden vivir más de cien años.","tier":3},{"w":"PATAGONIA","clue":"Región fría y ventosa en el extremo sur de Argentina y Chile","fact":"En la Patagonia hay glaciares enormes, y en sus costas viven pingüinos y ballenas.","tier":3},{"w":"ACONCAGUA","clue":"Montaña más alta de América, en la cordillera de los Andes","fact":"El Aconcagua, en Argentina, es la montaña más alta fuera de Asia.","tier":3},{"w":"TITICACA","clue":"Gran lago de los Andes entre Perú y Bolivia","fact":"En el lago Titicaca hay islas flotantes hechas de totora, una planta.","tier":3},{"w":"TEOTIHUACÁN","clue":"Ciudad antigua de México con las pirámides del Sol y la Luna","fact":"La Pirámide del Sol de Teotihuacán mide más de sesenta metros de altura.","tier":3},{"w":"AMAZONAS","clue":"Río gigante de América del Sur que atraviesa una enorme selva","fact":"En el Amazonas viven delfines rosados de río.","tier":3},{"w":"ANTÁRTIDA","clue":"Continente helado alrededor del Polo Sur, hogar de pingüinos","fact":"La Antártida es el continente más frío, más ventoso y más seco.","tier":3},{"w":"GROENLANDIA","clue":"La isla más grande del mundo, casi toda cubierta de hielo","fact":"Aunque su nombre significa tierra verde, casi toda Groenlandia está cubierta de hielo.","tier":3},{"w":"HEMISFERIO","clue":"Cada una de las mitades de la Tierra, como norte o sur","fact":"Argentina está en el hemisferio sur y México en el norte, y ambos en el occidental.","tier":3},{"w":"CONTINENTE","clue":"Gran masa de tierra como África, Asia o la Antártida","fact":"Asia es el continente más grande y Oceanía es el más pequeño.","tier":3},{"w":"PLANETARIO","clue":"Sala con cúpula que muestra el cielo nocturno en el techo","fact":"El primer proyector de planetario moderno se construyó en Alemania en la década de 1920.","tier":3},{"w":"HIMALAYA","clue":"Cordillera de Asia donde está el monte Everest","fact":"El Himalaya sigue creciendo unos milímetros cada año.","tier":3},{"w":"KILIMANJARO","clue":"Montaña más alta de África, un volcán que se alza solo","fact":"El Kilimanjaro tiene tres conos de volcán llamados Kibo, Mawenzi y Shira.","tier":3},{"w":"PARTENÓN","clue":"Edificio antiguo de mármol con columnas sobre una colina de Atenas","fact":"El Partenón se levanta en la Acrópolis de Atenas desde hace casi dos mil quinientos años.","tier":3},{"w":"ACRÓPOLIS","clue":"Colina rocosa de Atenas coronada por antiguos edificios griegos","fact":"Acrópolis significa ciudad alta en griego.","tier":3},{"w":"HORIZONTE","clue":"Línea lejana donde el cielo parece tocar el mar","fact":"Desde una playa puedes ver unos cuatro o cinco kilómetros hasta el horizonte.","tier":3},{"w":"ACANTILADO","clue":"Pared de roca muy alta y casi recta junto al mar","fact":"En los acantilados anidan miles de aves marinas.","tier":3},{"w":"SERENGETI","clue":"Enorme llanura de África donde millones de animales migran","fact":"Cada año más de un millón de ñus cruzan el Serengeti siguiendo las lluvias.","tier":3},{"w":"STONEHENGE","clue":"Círculo de piedras gigantes en una llanura de Inglaterra","fact":"Algunas piedras de Stonehenge se trajeron desde Gales, a unos 240 kilómetros.","tier":3},{"w":"ANFITEATRO","clue":"Gran edificio redondo de la antigua Roma con gradas alrededor","fact":"La palabra anfiteatro viene del griego y quiere decir teatro con asientos por todos lados.","tier":3},{"w":"FARALLÓN","clue":"Gran roca que sale sola del mar, cerca de la orilla","fact":"Los farallones se forman cuando las olas desgastan la roca durante miles de años.","tier":3}]}},{"id":"inventions-and-machines","icon":"⚙️","name":{"en":"Inventions and Machines","es":"Inventos y máquinas"},"words":{"en":[{"w":"GEAR","clue":"Toothed wheel that fits into another to pass on motion","fact":"Gears of different sizes can make a machine turn faster or push harder.","tier":1},{"w":"WHEEL","clue":"Round part that rolls and makes moving heavy things easier","fact":"A wheel on an axle lets people move heavy loads with much less effort.","tier":1},{"w":"LEVER","clue":"Bar that pivots on a point to help lift heavy things","fact":"A seesaw is a lever with the pivot point in the middle.","tier":1},{"w":"ROBOT","clue":"Machine that can be programmed to do tasks by itself","fact":"The word robot comes from a Czech word meaning \"hard work.\"","tier":1},{"w":"CLOCK","clue":"Machine that shows what time it is","fact":"Pendulum clocks keep time because each swing takes almost exactly the same time.","tier":1},{"w":"RADIO","clue":"Device that picks up sound sent through the air","fact":"Radio waves travel at the speed of light.","tier":1},{"w":"LASER","clue":"Super-narrow, focused beam of light","fact":"Scientists used a laser beam to measure the distance to the Moon.","tier":1},{"w":"MOTOR","clue":"Machine part that makes things spin using electricity or fuel","fact":"Electric motors use magnets and electricity to make things spin.","tier":1},{"w":"RAMP","clue":"Slanted surface that makes it easier to go up","fact":"A ramp lets you lift something heavy with less push by making the trip longer.","tier":1},{"w":"AXLE","clue":"Rod that a wheel turns on","fact":"A car's axle is a strong rod that lets the wheels spin while holding up the car.","tier":1},{"w":"CRANE","clue":"Tall machine that lifts heavy loads at building sites","fact":"Tower cranes can build themselves taller by lifting new sections of their own tower.","tier":1},{"w":"LENS","clue":"Curved glass that bends light, found in cameras and glasses","fact":"A lens can bend light to make faraway or tiny things look bigger.","tier":1},{"w":"PULLEY","clue":"Wheel with a rope that helps lift heavy things","fact":"Using more pulley wheels in a set lets you lift a load with less pull.","tier":2},{"w":"CAMERA","clue":"Device that captures pictures with light","fact":"The word camera comes from a Latin word for \"room\"; early cameras were whole dark rooms.","tier":2},{"w":"ENGINE","clue":"Machine that burns fuel to make power","fact":"Steam engines used burning coal and boiling water to move trains and ships.","tier":2},{"w":"BATTERY","clue":"Stores chemical energy and gives electricity to toys","fact":"A battery makes electricity through a chemical reaction between its parts.","tier":2},{"w":"MAGNET","clue":"Object that pulls on iron and sticks to a fridge door","fact":"Earth acts like a giant magnet, which is why compass needles point north.","tier":2},{"w":"COMPASS","clue":"Tool with a needle that points north","fact":"Compasses were invented long ago in China, and sailors used them to find their way.","tier":2},{"w":"PRINTER","clue":"Machine that puts words and pictures onto paper","fact":"Some 3D printers build objects out of melted plastic, one thin layer at a time.","tier":2},{"w":"TRACTOR","clue":"Strong farm vehicle with huge back wheels","fact":"Tractor tires have deep tread to grip soft, muddy fields.","tier":2},{"w":"BALLOON","clue":"Floating bag of gas","fact":"Hot-air balloons float because heated air is lighter than cool air.","tier":2},{"w":"HAMMER","clue":"Tool with a heavy head for pounding nails","fact":"Early humans used stones as hammers long before people had metal.","tier":2},{"w":"WRENCH","clue":"Tool that grips and turns nuts and bolts","fact":"A long wrench handle works like a lever, so a stuck bolt is easier to turn.","tier":2},{"w":"SPRING","clue":"Coiled metal that squishes and bounces back","fact":"A spring stores energy when squeezed and releases it when it bounces back.","tier":2},{"w":"TURBINE","clue":"Wheel with blades that spins from wind, water or steam","fact":"Wind turbines turn the motion of the wind into electricity.","tier":2},{"w":"BICYCLE","clue":"Two-wheeled ride that you pedal","fact":"Riding a bicycle takes less energy per mile than walking.","tier":2},{"w":"HELICOPTER","clue":"Aircraft with spinning blades on top that can hover","fact":"A helicopter's spinning blades work like wings, lifting it straight up.","tier":3},{"w":"MICROSCOPE","clue":"Tool that makes tiny things look huge","fact":"Microscopes revealed tiny living things swimming in a drop of pond water.","tier":3},{"w":"PARACHUTE","clue":"Big fabric canopy that slows a fall","fact":"Some spacecraft use huge parachutes to slow down before landing.","tier":3},{"w":"COMPUTER","clue":"Electronic machine that follows instructions to handle information","fact":"Early computers filled whole rooms; today's can fit in your pocket.","tier":3},{"w":"ELEVATOR","clue":"Box that carries people up and down in tall buildings","fact":"An elevator has safety brakes that grab the rails if the cable ever fails.","tier":3},{"w":"TELEPHONE","clue":"Invention that lets you talk to someone far away","fact":"Early telephones sent voices over wires as changing electrical signals.","tier":3},{"w":"CALCULATOR","clue":"Pocket gadget that does math with buttons","fact":"The abacus, a counting frame with beads, is an ancient calculator still in use.","tier":3},{"w":"BULLDOZER","clue":"Heavy machine with a huge front blade for pushing dirt","fact":"Bulldozers use wide metal tracks so they do not sink in soft ground.","tier":3},{"w":"SKATEBOARD","clue":"Board with four wheels that you ride standing up","fact":"The first skateboards were made by attaching roller skate wheels to wooden boards.","tier":3},{"w":"LIGHTBULB","clue":"Glass bulb that glows when electricity flows through","fact":"Modern LED bulbs use far less electricity than old glowing-filament bulbs.","tier":3},{"w":"SAW","clue":"Tool with a toothed blade that cuts through wood","fact":"Some saws have tiny bits of diamond on the blade so they can cut stone.","tier":1},{"w":"DRILL","clue":"Power tool that spins a sharp bit to make holes","fact":"Long ago, people spun a drill with a bow and string to make holes.","tier":1},{"w":"CHIP","clue":"Tiny silicon square packed with circuits, found inside every computer","fact":"Computer chips are made from silicon, which comes from ordinary sand.","tier":1},{"w":"KITE","clue":"Light frame covered in paper or cloth that flies on a string","fact":"Kites were invented in China more than two thousand years ago.","tier":1},{"w":"SAIL","clue":"Big sheet of cloth that catches wind to push a boat","fact":"A sailboat can travel almost against the wind by zigzagging back and forth.","tier":1},{"w":"NAIL","clue":"Thin metal spike you hammer into wood","fact":"Long ago, blacksmiths made every nail by hand, one at a time.","tier":1},{"w":"SCREW","clue":"Metal pin with spiral ridges that twists into wood","fact":"A screw is really a ramp wrapped around a pole.","tier":1},{"w":"PUMP","clue":"Machine that pushes water or air from one place to another","fact":"Your heart is a pump that moves blood all around your body.","tier":1},{"w":"DRONE","clue":"Flying machine with spinning blades and no pilot inside","fact":"Drone is also the name for a male bee, which makes a humming buzz.","tier":1},{"w":"JET","clue":"Very fast airplane with powerful engines but no propeller","fact":"A jet engine pushes a plane forward by blasting hot gas backward.","tier":1},{"w":"TRAIN","clue":"Long line of connected cars that rolls along tracks","fact":"Some of the first trains were pulled along rails by horses.","tier":1},{"w":"RADAR","clue":"Machine that bounces radio waves off planes and storms to find them","fact":"Radar is a palindrome, so it reads the same forward and backward.","tier":1},{"w":"SONAR","clue":"Machine that uses sound echoes to find things underwater","fact":"Bats and dolphins find things using echoes, the same trick that sonar uses.","tier":1},{"w":"MOUSE","clue":"Hand-held gadget you slide to move the pointer on a screen","fact":"The very first computer mouse was made of wood.","tier":1},{"w":"PIANO","clue":"Big instrument with 88 black and white keys","fact":"Inside a piano, tiny hammers hit strings when you press a key.","tier":1},{"w":"FAN","clue":"Spinning blades that blow air to keep you cool","fact":"A fan does not cool the air; it helps sweat on your skin dry faster.","tier":1},{"w":"PROBE","clue":"Robot spacecraft sent to study far-off planets and moons","fact":"Two probes launched in 1977 have since flown out into the space between the stars.","tier":1},{"w":"ROVER","clue":"Wheeled robot that drives around exploring Mars","fact":"Robot rovers have rolled across the surface of Mars and the Moon.","tier":1},{"w":"SCUBA","clue":"Tank-and-mask gear that lets divers breathe underwater","fact":"Scuba stands for Self-Contained Underwater Breathing Apparatus.","tier":1},{"w":"VALVE","clue":"Part that opens and closes to control how liquid or air flows","fact":"Your heart has valves that keep blood flowing in only one direction.","tier":1},{"w":"WIRE","clue":"Thin metal thread that carries electricity","fact":"Most electrical wire is made of copper, which carries electricity very well.","tier":1},{"w":"ANVIL","clue":"Heavy iron block a blacksmith hammers hot metal on","fact":"Your ear has a tiny bone called the anvil, because it looks like one.","tier":1},{"w":"CHAIN","clue":"Loop of linked metal rings, like on a bike","fact":"A bicycle chain carries power from your pedals to the back wheel.","tier":1},{"w":"BRAKE","clue":"Part that slows or stops a moving vehicle","fact":"Many car brakes squeeze pads against a spinning disc to slow the wheel.","tier":1},{"w":"TIRE","clue":"Rubber ring around a wheel","fact":"Tires have grooves, called tread, that help them grip the road.","tier":1},{"w":"BOAT","clue":"Small vehicle that floats and carries people on water","fact":"One of the oldest known boats is a canoe made from a hollowed log.","tier":1},{"w":"TRUCK","clue":"Big road vehicle for hauling heavy loads","fact":"Monster truck tires are about 66 inches tall, taller than most kids.","tier":1},{"w":"PIXEL","clue":"Tiny dot of color; millions make up a screen picture","fact":"The word pixel is short for picture element.","tier":1},{"w":"ROCKET","clue":"Vehicle that blasts into space by shooting hot gas downward","fact":"Rockets work in empty space because they push against the gas they shoot out.","tier":2},{"w":"ABACUS","clue":"Counting frame with beads that slide on rods","fact":"People used abacuses to do math thousands of years before calculators existed.","tier":2},{"w":"ARCADE","clue":"Room full of coin-powered video game machines","fact":"Many classic arcade games had only a joystick and one or two buttons.","tier":2},{"w":"CONSOLE","clue":"Box you plug into a TV to play video games","fact":"The first home game consoles, in the 1970s, showed only simple blocks and lines.","tier":2},{"w":"SCREEN","clue":"Flat surface where a TV or computer shows pictures","fact":"Old TV screens were deep boxes because they used big glass tubes.","tier":2},{"w":"PISTON","clue":"Part that slides up and down inside an engine","fact":"In a car engine, each piston moves up and down thousands of times a minute.","tier":2},{"w":"NOZZLE","clue":"Narrow spout at the end of a hose or rocket","fact":"A rocket nozzle is shaped like a bell to speed up the hot gas.","tier":2},{"w":"BLENDER","clue":"Kitchen machine with spinning blades for making smoothies","fact":"A blender's blades can spin thousands of times every minute.","tier":2},{"w":"TOASTER","clue":"Kitchen gadget that browns bread with hot wires","fact":"Inside a toaster, thin wires glow orange when electricity flows through them.","tier":2},{"w":"VACUUM","clue":"Cleaning machine that sucks dust off carpets","fact":"A vacuum cleaner's fan lowers the air pressure inside, so outside air rushes in with dirt.","tier":2},{"w":"ANCHOR","clue":"Heavy hook dropped from a ship to keep it from drifting","fact":"An anchor holds a ship in place by digging into the seabed.","tier":2},{"w":"SEESAW","clue":"Playground board that kids balance on, tipping up and down","fact":"A seesaw is a lever, with the middle acting as the pivot.","tier":2},{"w":"SENSOR","clue":"Device that detects things like light, heat or motion","fact":"Automatic doors use sensors to notice when someone walks up.","tier":2},{"w":"SWITCH","clue":"Button or lever that turns electricity on or off","fact":"A switch works by connecting or breaking the path that electricity travels along.","tier":2},{"w":"SKATES","clue":"Boots with blades or wheels for gliding along","fact":"The earliest ice skates were made from animal bones.","tier":2},{"w":"GLIDER","clue":"Airplane with no engine that floats on rising air","fact":"Glider pilots can stay up for hours by riding warm air that rises.","tier":2},{"w":"GAMEPAD","clue":"Handheld controller with buttons and sticks for playing on a TV","fact":"Many game controllers have a tiny motor inside that makes them rumble.","tier":2},{"w":"MIRROR","clue":"Shiny glass that shows your reflection","fact":"The first mirrors were polished stones, such as shiny volcanic glass called obsidian.","tier":2},{"w":"SPEAKER","clue":"Gadget that turns electric signals into sound","fact":"A speaker makes sound by shaking a paper or plastic cone back and forth.","tier":2},{"w":"ANTENNA","clue":"Metal rod or wire that sends and catches radio signals","fact":"A satellite dish is an antenna shaped like a bowl.","tier":2},{"w":"SUNDIAL","clue":"Clock that tells time with the shadow of a stick","fact":"Ancient Egyptians used sundials about 3,500 years ago.","tier":2},{"w":"SHUTTLE","clue":"Winged spacecraft that carried astronauts to orbit and glided home","fact":"Space shuttles landed like gliders, with their engines off.","tier":2},{"w":"CAPSULE","clue":"Small spacecraft that returns astronauts to Earth under parachutes","fact":"Many space capsules splash down in the ocean at the end of a flight.","tier":2},{"w":"LANDER","clue":"Spacecraft built to touch down on the Moon or another world","fact":"Landers have touched down on the Moon, Mars, Venus and even a comet.","tier":2},{"w":"SCANNER","clue":"Machine that copies a page or picture into a computer","fact":"Grocery store scanners read a barcode's stripes using a laser beam.","tier":2},{"w":"CIRCUIT","clue":"Closed loop that electricity flows around","fact":"Electricity only flows when a circuit makes a complete loop.","tier":2},{"w":"DYNAMO","clue":"Machine that turns spinning motion into electricity","fact":"Some bike lights use a small dynamo that makes power while you pedal.","tier":2},{"w":"LADDER","clue":"Climbing tool with rungs to step on","fact":"Rock paintings in Spain show a person climbing a ladder thousands of years ago.","tier":2},{"w":"ZIPPER","clue":"Fastener with two rows of teeth that lock when you slide it","fact":"The zipper was first called a hookless fastener.","tier":2},{"w":"RATCHET","clue":"Gear with teeth that lets it turn only one way","fact":"A ratchet clicks because a small lever slips over its teeth.","tier":2},{"w":"SNORKEL","clue":"Curved tube that lets swimmers breathe with their face in the water","fact":"Snorkels must stay short, because breathing through a long tube underwater is too hard.","tier":2},{"w":"COMBINE","clue":"Giant farm machine that cuts and sorts grain","fact":"Before combines, many workers cut and sorted grain by hand.","tier":2},{"w":"TELESCOPE","clue":"Long tube with lenses for looking at planets and stars","fact":"Telescopes look back in time, because light from far-away stars takes years to arrive.","tier":3},{"w":"SUBMARINE","clue":"Ship that travels deep underwater","fact":"A submarine dives by filling tanks with water and rises by pushing it out with air.","tier":3},{"w":"SATELLITE","clue":"Machine that circles Earth in space","fact":"Some satellites take pictures of weather, and others help your phone find its location.","tier":3},{"w":"PROPELLER","clue":"Spinning twisted blades that push a plane or boat along","fact":"Airplane propellers are really spinning wings that pull the plane forward.","tier":3},{"w":"LOCOMOTIVE","clue":"Powerful engine at the front of a train","fact":"Early locomotives burned coal or wood to boil water into steam.","tier":3},{"w":"TELEGRAPH","clue":"Old machine that sent messages as clicks along wires","fact":"Telegraph operators sent words using Morse code, a pattern of short and long signals.","tier":3},{"w":"ESCALATOR","clue":"Moving staircase in a mall","fact":"An escalator is a loop of stairs, with steps flattening out at each end.","tier":3},{"w":"GENERATOR","clue":"Machine that spins magnets to make electricity","fact":"Hydro generators are turned by falling water to make electricity at dams.","tier":3},{"w":"EXCAVATOR","clue":"Digging machine with a long arm and a bucket","fact":"An excavator's powerful arm moves using hydraulics, which is pressure from liquid.","tier":3},{"w":"AIRPLANE","clue":"Machine with wings that carries people through the sky","fact":"The first airplane flight, in 1903, lasted only twelve seconds.","tier":3},{"w":"KEYBOARD","clue":"Rows of keys you press to type","fact":"Most keyboards use the QWERTY layout, named for the first six letters in the top row.","tier":3},{"w":"TRANSISTOR","clue":"Tiny electronic switch found by the billions in computer chips","fact":"Today's chips pack billions of them, each far smaller than a germ.","tier":3},{"w":"FLASHLIGHT","clue":"Handheld battery light you carry in the dark","fact":"Early flashlights got their name because weak batteries only made short flashes of light.","tier":3},{"w":"MICROWAVE","clue":"Kitchen oven that heats food with invisible waves","fact":"Microwave ovens heat food by making the water inside it jiggle.","tier":3},{"w":"FORKLIFT","clue":"Truck with two metal prongs for lifting heavy pallets","fact":"A forklift has a heavy back end that balances the load it lifts, like a seesaw.","tier":3},{"w":"TRAMPOLINE","clue":"Bouncy fabric sheet stretched over springs for jumping","fact":"Astronauts have trained on trampolines to practice flips and spins.","tier":3},{"w":"JOYSTICK","clue":"Lever you tilt to steer in video games","fact":"Airplane pilots used control sticks long before video games had joysticks.","tier":3},{"w":"SCOREBOARD","clue":"Big sign at a baseball game showing runs and outs","fact":"Some old ballparks still keep score by hanging number plates on the scoreboard by hand.","tier":3},{"w":"SCISSORS","clue":"Tool with two blades joined in the middle, for cutting paper","fact":"Scissors are two levers joined at a pivot.","tier":3},{"w":"WINDMILL","clue":"Tower with big blades that spin in the wind","fact":"Windmills were first used to grind grain into flour and to pump water.","tier":3},{"w":"HOURGLASS","clue":"Two glass bulbs that measure time with trickling sand","fact":"Sailors used hourglasses because pendulum clocks do not work on rocking ships.","tier":3},{"w":"PENDULUM","clue":"Weight swinging back and forth that keeps a clock steady","fact":"A pendulum's swing takes almost the same time whether it swings wide or small.","tier":3},{"w":"PERISCOPE","clue":"Mirrored tube a submarine crew uses to see above the waves","fact":"A periscope uses two mirrors to bend light around corners.","tier":3},{"w":"WHEELBARROW","clue":"One-wheeled cart with two handles for hauling dirt","fact":"Wheelbarrows were used in China about 2,000 years ago.","tier":3}],"es":[{"w":"RUEDA","clue":"Pieza redonda que gira y facilita mover cosas pesadas","fact":"Una rueda con eje permite mover cargas pesadas con mucho menos esfuerzo.","tier":1},{"w":"POLEA","clue":"Rueda con una cuerda que ayuda a subir cosas pesadas","fact":"Con varias poleas juntas puedes levantar una carga haciendo menos fuerza.","tier":1},{"w":"ROBOT","clue":"Máquina programada para hacer tareas sola","fact":"La palabra robot viene de una palabra checa que significa trabajo duro.","tier":1},{"w":"RELOJ","clue":"Aparato que marca la hora","fact":"Los relojes de péndulo funcionan porque cada vaivén dura casi lo mismo.","tier":1},{"w":"RADIO","clue":"Aparato que recibe sonidos enviados por el aire","fact":"Las ondas de radio viajan a la velocidad de la luz.","tier":1},{"w":"LÁSER","clue":"Rayo de luz muy fino y concentrado","fact":"Con un láser se midió la distancia a la Luna con increíble precisión.","tier":1},{"w":"MOTOR","clue":"Parte que hace girar y mover una máquina","fact":"Los motores eléctricos usan imanes y electricidad para hacer girar cosas.","tier":1},{"w":"RAMPA","clue":"Superficie inclinada que facilita subir cosas","fact":"Una rampa permite subir algo pesado con menos esfuerzo, aunque el camino sea más largo.","tier":1},{"w":"GRÚA","clue":"Máquina alta que levanta cargas pesadas en las obras","fact":"Las grúas torre pueden subir solas, agregando secciones nuevas a su propia torre.","tier":1},{"w":"LENTE","clue":"Vidrio curvo que desvía la luz, como en unas gafas","fact":"Un lente puede hacer que lo lejano o lo diminuto se vea más grande.","tier":1},{"w":"PILA","clue":"Pequeño aparato que guarda energía para juguetes","fact":"Una pila produce electricidad con una reacción química en su interior.","tier":1},{"w":"FOCO","clue":"Bulbo de vidrio que alumbra cuando pasa electricidad","fact":"Las luces LED gastan mucha menos electricidad que los focos antiguos.","tier":1},{"w":"PALANCA","clue":"Barra que gira sobre un punto y ayuda a levantar cosas","fact":"Un subibaja es una palanca con el punto de apoyo en el medio.","tier":2},{"w":"CÁMARA","clue":"Aparato que captura imágenes con luz","fact":"La palabra cámara viene del latín y significa cuarto; las primeras eran habitaciones oscuras.","tier":2},{"w":"BRÚJULA","clue":"Instrumento con una aguja que siempre señala el norte","fact":"La Tierra funciona como un imán gigante, por eso la aguja apunta al norte.","tier":2},{"w":"TRACTOR","clue":"Vehículo fuerte de granja con enormes ruedas traseras","fact":"Las llantas de los tractores tienen surcos profundos para agarrarse al barro.","tier":2},{"w":"TURBINA","clue":"Rueda con aspas que gira con viento, agua o vapor","fact":"Las turbinas de viento convierten el movimiento del aire en electricidad.","tier":2},{"w":"RESORTE","clue":"Alambre enroscado que se aprieta y vuelve a su forma","fact":"Un resorte guarda energía al apretarlo y la suelta al estirarse de nuevo.","tier":2},{"w":"HÉLICE","clue":"Aspas que giran para empujar un barco o un avión","fact":"Una hélice empuja el aire o el agua hacia atrás y así avanza el vehículo.","tier":2},{"w":"TIJERAS","clue":"Herramienta de dos hojas que corta papel","fact":"Las tijeras son dos palancas unidas por un tornillo en el medio.","tier":2},{"w":"BATERÍA","clue":"Guarda energía y le da electricidad al celular","fact":"Las baterías recargables pueden usarse muchas veces si se vuelven a cargar.","tier":2},{"w":"CAMIÓN","clue":"Vehículo grande que transporta cargas pesadas por carretera","fact":"Algunos camiones grandes tienen dieciocho ruedas.","tier":2},{"w":"MOLINO","clue":"Construcción con aspas que gira con el viento para moler granos","fact":"Los molinos de viento se usaron durante siglos para moler grano y sacar agua.","tier":2},{"w":"MÁQUINA","clue":"Aparato con piezas que trabajan juntas para facilitar un trabajo","fact":"Una máquina simple, como una palanca o una rampa, tiene muy pocas piezas.","tier":2},{"w":"ENGRANE","clue":"Rueda con dientes que encaja con otra para transmitir movimiento","fact":"Los engranes de distintos tamaños hacen que una máquina gire más rápido o con más fuerza.","tier":2},{"w":"ANTENA","clue":"Varilla o plato que recibe señales de radio o de televisión","fact":"Las antenas captan ondas invisibles que viajan por el aire.","tier":2},{"w":"HELICÓPTERO","clue":"Aeronave con aspas arriba que puede quedarse quieta en el aire","fact":"Las aspas de un helicóptero funcionan como alas que lo levantan hacia arriba.","tier":3},{"w":"MICROSCOPIO","clue":"Instrumento que hace ver enormes las cosas diminutas","fact":"Con el microscopio se descubrieron seres vivos diminutos en una gota de agua de estanque.","tier":3},{"w":"PARACAÍDAS","clue":"Gran tela que frena la caída de una persona","fact":"Algunas naves espaciales usan paracaídas gigantes para frenar antes de aterrizar.","tier":3},{"w":"COMPUTADORA","clue":"Máquina electrónica que sigue instrucciones para manejar información","fact":"Las primeras computadoras llenaban salas enteras; las de hoy caben en el bolsillo.","tier":3},{"w":"ASCENSOR","clue":"Cabina que sube y baja a las personas en edificios altos","fact":"Un ascensor tiene frenos de seguridad que sujetan los rieles si el cable falla.","tier":3},{"w":"TELÉFONO","clue":"Invento que permite hablar con alguien que está lejos","fact":"Los primeros teléfonos enviaban la voz por cables como señales eléctricas.","tier":3},{"w":"CALCULADORA","clue":"Aparato de bolsillo que hace cuentas con botones","fact":"El ábaco, un marco con cuentas, es una calculadora antigua que aún se usa.","tier":3},{"w":"EXCAVADORA","clue":"Máquina con brazo y pala grande que cava la tierra","fact":"Algunas excavadoras tienen orugas anchas para no hundirse en el suelo blando.","tier":3},{"w":"BICICLETA","clue":"Vehículo de dos ruedas que se mueve con pedales","fact":"Ir en bicicleta gasta menos energía por kilómetro que caminar.","tier":3},{"w":"PATINETA","clue":"Tabla con cuatro ruedas sobre la que te paras para deslizarte","fact":"Las primeras patinetas se hicieron con ruedas de patines clavadas a tablas.","tier":3},{"w":"CLAVO","clue":"Barrita de metal con punta que se golpea con un martillo","fact":"Antiguamente, los herreros hacían cada clavo a mano, uno por uno.","tier":1},{"w":"FRENO","clue":"Pieza que hace que un vehículo se detenga o vaya más lento","fact":"Muchos frenos de carro aprietan unas pastillas contra un disco que gira.","tier":1},{"w":"CABLE","clue":"Hilo grueso de metal cubierto de plástico que lleva electricidad","fact":"La mayoría de los cables eléctricos tienen cobre por dentro, que conduce muy bien la electricidad.","tier":1},{"w":"PÍXEL","clue":"Puntito de color; millones forman la imagen de una pantalla","fact":"La palabra píxel viene de las palabras inglesas para imagen y elemento.","tier":1},{"w":"SONDA","clue":"Nave robot sin personas que viaja a explorar planetas lejanos","fact":"Dos sondas lanzadas en 1977 ya salieron al espacio entre las estrellas.","tier":1},{"w":"SONAR","clue":"Aparato que usa ecos de sonido para encontrar cosas bajo el agua","fact":"Los murciélagos y los delfines encuentran cosas con ecos, igual que el sonar.","tier":1},{"w":"ANCLA","clue":"Gancho pesado que se lanza al mar para sujetar un barco","fact":"El ancla sujeta al barco clavándose en el fondo del mar.","tier":1},{"w":"TIMÓN","clue":"Rueda o palanca que sirve para dirigir un barco","fact":"En un barco, el timón mueve una pieza en el agua que cambia la dirección.","tier":1},{"w":"BARCO","clue":"Vehículo grande que flota y viaja por el mar","fact":"Uno de los barcos más antiguos que se conocen es una canoa hecha de un tronco hueco.","tier":1},{"w":"TREN","clue":"Fila de vagones conectados que rueda sobre rieles","fact":"Algunos de los primeros trenes eran jalados por caballos sobre rieles.","tier":1},{"w":"AVIÓN","clue":"Máquina con alas que lleva personas por el cielo","fact":"El primer vuelo en avión con motor, en 1903, duró solo doce segundos.","tier":1},{"w":"MOTO","clue":"Vehículo de dos ruedas, con manubrio, que ronca y corre mucho","fact":"La primera moto, de 1885, tenía el cuerpo de madera.","tier":1},{"w":"DRON","clue":"Aparato volador con hélices que no lleva piloto a bordo","fact":"Dron viene de una palabra inglesa que significa zángano, la abeja macho.","tier":1},{"w":"IMÁN","clue":"Objeto de metal que atrae el hierro","fact":"La Tierra entera funciona como un gigantesco imán.","tier":1},{"w":"LUPA","clue":"Lente de vidrio que hace ver más grandes las cosas pequeñas","fact":"Las lupas más antiguas que se conocen tienen casi tres mil años.","tier":1},{"w":"ÁBACO","clue":"Marco con bolitas que se deslizan para contar y sumar","fact":"Hace miles de años la gente ya hacía cuentas con ábacos.","tier":1},{"w":"PIANO","clue":"Instrumento grande con 88 teclas blancas y negras","fact":"Dentro de un piano, pequeños martillos golpean cuerdas cuando presionas una tecla.","tier":1},{"w":"ZÍPER","clue":"Cierre con dos filas de dientes que se juntan al deslizarlo","fact":"Al principio, el zíper se llamaba cierre sin ganchos.","tier":1},{"w":"CASCO","clue":"Protección dura para la cabeza que usan ciclistas y bateadores","fact":"Los cascos de bicicleta tienen una capa de espuma que se aplasta para amortiguar un golpe.","tier":1},{"w":"ARADO","clue":"Herramienta que abre surcos en la tierra para sembrar","fact":"Hace miles de años, los bueyes jalaban los primeros arados.","tier":1},{"w":"BALSA","clue":"Plataforma plana de troncos o tablas que flota en el agua","fact":"La madera de balsa es tan ligera que se usa para hacer aviones de juguete.","tier":1},{"w":"REMO","clue":"Pala larga que sirve para mover una lancha en el agua","fact":"Los remos son palancas: la lancha avanza cuando empujas el agua hacia atrás.","tier":1},{"w":"RADAR","clue":"Aparato que usa ondas de radio para encontrar aviones y tormentas","fact":"Radar se escribe igual al derecho y al revés.","tier":1},{"w":"TECLA","clue":"Pieza que presionas con el dedo para escribir una letra","fact":"Las teclas del piano y las de la computadora se llaman igual.","tier":1},{"w":"RATÓN","clue":"Dispositivo que deslizas sobre la mesa para mover el cursor","fact":"El primer ratón de computadora tenía una cajita de madera.","tier":1},{"w":"GLOBO","clue":"Bolsa enorme llena de aire caliente que lleva personas por el cielo","fact":"Los primeros pasajeros de un globo fueron una oveja, un pato y un gallo.","tier":1},{"w":"HORNO","clue":"Caja caliente donde se cocinan pan y pasteles","fact":"La gente usa hornos de piedra para hacer pan desde hace miles de años.","tier":1},{"w":"CARRO","clue":"Vehículo con motor y cuatro ruedas para ir por la calle","fact":"El primer carro con motor de gasolina, de 1886, tenía solo tres ruedas.","tier":1},{"w":"COHETE","clue":"Vehículo que sale disparado al espacio echando fuego hacia abajo","fact":"Los cohetes funcionan en el espacio vacío porque empujan contra los gases que lanzan.","tier":2},{"w":"CONSOLA","clue":"Caja que conectas a la tele para jugar videojuegos","fact":"Las primeras consolas de los años setenta solo mostraban rayas y cuadritos.","tier":2},{"w":"ARCADE","clue":"Salón lleno de máquinas de videojuegos que funcionan con monedas","fact":"Muchos juegos clásicos de arcade solo tenían una palanca y uno o dos botones.","tier":2},{"w":"YUNQUE","clue":"Bloque pesado de hierro donde el herrero martilla el metal caliente","fact":"En tu oído hay un huesito llamado yunque porque tiene esa forma.","tier":2},{"w":"TUERCA","clue":"Pieza de metal con hueco en espiral para enroscar un tornillo","fact":"Una tuerca y un tornillo trabajan juntos porque sus espirales encajan.","tier":2},{"w":"CADENA","clue":"Fila de aros de metal unidos, como la de una bici","fact":"La cadena de una bicicleta lleva la fuerza de los pedales a la rueda de atrás.","tier":2},{"w":"PISTÓN","clue":"Pieza que sube y baja dentro de un motor","fact":"En el motor de un carro, cada pistón sube y baja miles de veces por minuto.","tier":2},{"w":"ALAMBRE","clue":"Hilo delgado de metal que se puede doblar","fact":"El alambre se hace estirando metal hasta dejarlo muy delgado.","tier":2},{"w":"ENCHUFE","clue":"Pieza con dos clavijas que metes en la pared para tener electricidad","fact":"En distintos países los enchufes tienen formas diferentes.","tier":2},{"w":"SENSOR","clue":"Aparato que detecta cosas como luz, calor o movimiento","fact":"Las puertas automáticas usan sensores para notar cuando alguien se acerca.","tier":2},{"w":"ESCÁNER","clue":"Máquina que copia una página o una foto a la computadora","fact":"Los escáneres de las tiendas leen las rayas de un código de barras con un rayo láser.","tier":2},{"w":"TECLADO","clue":"Filas de botones con letras que presionas para escribir","fact":"La mayoría de los teclados tienen las letras en el orden QWERTY.","tier":2},{"w":"BOCINA","clue":"Aparato que convierte señales eléctricas en sonido","fact":"Una bocina hace sonar el aire moviendo un cono de papel o plástico muy rápido.","tier":2},{"w":"CÁPSULA","clue":"Nave pequeña que trae astronautas de vuelta a la Tierra con paracaídas","fact":"Muchas cápsulas espaciales caen al mar al terminar su viaje.","tier":2},{"w":"TIMBRE","clue":"Botón de la puerta que suena para avisar que llegaste","fact":"Los primeros timbres eléctricos se inventaron hace casi doscientos años.","tier":2},{"w":"LLANTA","clue":"Anillo de hule que cubre la rueda de un carro","fact":"Las llantas tienen surcos para que se agarren bien al camino.","tier":2},{"w":"VOLANTE","clue":"Rueda que giras para dirigir un carro","fact":"En un carro, el volante hace girar las ruedas de enfrente.","tier":2},{"w":"LANCHA","clue":"Barco pequeño y rápido con motor","fact":"Una lancha rápida se levanta sobre el agua cuando va a mucha velocidad.","tier":2},{"w":"TRINEO","clue":"Vehículo sin ruedas que se desliza sobre la nieve","fact":"Los perros han jalado trineos por el Ártico durante miles de años.","tier":2},{"w":"PATINES","clue":"Botas con ruedas o cuchillas para deslizarse","fact":"Los primeros patines de hielo se hicieron con huesos de animales.","tier":2},{"w":"DÍNAMO","clue":"Máquina que convierte el movimiento giratorio en electricidad","fact":"Algunas luces de bicicleta usan un pequeño dínamo que da energía mientras pedaleas.","tier":2},{"w":"LÁMPARA","clue":"Aparato que da luz en una habitación","fact":"Los antiguos romanos hacían lámparas que quemaban aceite de oliva.","tier":2},{"w":"PÉNDULO","clue":"Peso colgado que se balancea y marca el ritmo de un reloj","fact":"Un péndulo tarda casi lo mismo en cada vaivén, sea grande o pequeño.","tier":2},{"w":"BALANZA","clue":"Aparato con dos platillos para comparar el peso de las cosas","fact":"Las balanzas se usan desde hace miles de años para pesar cosas.","tier":2},{"w":"ESPEJO","clue":"Vidrio brillante donde ves tu reflejo","fact":"Los primeros espejos fueron piedras pulidas, como el vidrio volcánico llamado obsidiana.","tier":2},{"w":"ALETAS","clue":"Piezas de hule que te pones en los pies para nadar rápido","fact":"Los buzos usan aletas porque así sus patadas empujan mucha más agua.","tier":2},{"w":"TALADRO","clue":"Herramienta que gira una broca para hacer agujeros","fact":"Hace mucho tiempo la gente hacía agujeros girando un palo con un arco y una cuerda.","tier":2},{"w":"TOBOGÁN","clue":"Rampa lisa del parque por la que te deslizas","fact":"Un tobogán funciona gracias a la gravedad, que te jala hacia abajo.","tier":2},{"w":"AUTOBÚS","clue":"Vehículo largo y grande que lleva muchos pasajeros por la ciudad","fact":"Los primeros autobuses eran carretas grandes jaladas por caballos.","tier":2},{"w":"COMETA","clue":"Armazón de papel que el viento hace volar, atado a un hilo","fact":"Las cometas se inventaron en China hace más de dos mil años.","tier":2},{"w":"VÁLVULA","clue":"Pieza que abre y cierra para controlar el paso de líquidos","fact":"Tu corazón tiene válvulas que hacen que la sangre vaya en un solo sentido.","tier":2},{"w":"SIRENA","clue":"Aparato que suena fuerte para avisar de una emergencia","fact":"El sonido de la sirena de una ambulancia cambia de tono al pasar junto a ti.","tier":2},{"w":"SATÉLITE","clue":"Aparato que da vueltas alrededor de la Tierra en el espacio","fact":"Algunos satélites toman fotos del clima y otros ayudan a tu celular a ubicarse.","tier":3},{"w":"SUBMARINO","clue":"Barco que viaja bajo el agua","fact":"Un submarino se hunde llenando tanques de agua y sube sacándola con aire.","tier":3},{"w":"TELESCOPIO","clue":"Tubo con lentes para ver planetas y estrellas","fact":"Los telescopios miran al pasado, porque la luz de las estrellas lejanas tarda años en llegar.","tier":3},{"w":"LOCOMOTORA","clue":"Máquina potente que va al frente de un tren jalando vagones","fact":"Las primeras locomotoras quemaban carbón o leña para hervir agua y hacer vapor.","tier":3},{"w":"TELÉGRAFO","clue":"Aparato antiguo que mandaba mensajes con clics por un cable","fact":"Los telegrafistas mandaban palabras con el código Morse, hecho de señales cortas y largas.","tier":3},{"w":"DIRIGIBLE","clue":"Globo gigante alargado, lleno de gas, con motores y hélices","fact":"Los dirigibles flotaban porque estaban llenos de un gas más ligero que el aire.","tier":3},{"w":"SEMÁFORO","clue":"Poste con luces roja, amarilla y verde que ordena el tránsito","fact":"El primer semáforo se instaló en Londres en 1868 y funcionaba con gas.","tier":3},{"w":"LICUADORA","clue":"Aparato de cocina con aspas que mezcla frutas para hacer jugos","fact":"Las aspas de una licuadora pueden girar miles de veces por minuto.","tier":3},{"w":"ASPIRADORA","clue":"Máquina que limpia el piso chupando el polvo","fact":"Una aspiradora baja la presión del aire dentro, así que el aire de afuera entra con la basura.","tier":3},{"w":"MICROONDAS","clue":"Horno de cocina que calienta la comida con ondas invisibles","fact":"El microondas calienta la comida moviendo muy rápido el agua que tiene dentro.","tier":3},{"w":"MONTACARGAS","clue":"Camioncito con dos grandes dientes de metal para levantar cajas pesadas","fact":"Un montacargas tiene la parte de atrás muy pesada para equilibrar la carga, como un sube y baja.","tier":3},{"w":"COSECHADORA","clue":"Máquina enorme de campo que corta y separa los granos","fact":"Antes de las cosechadoras, muchas personas cortaban el trigo a mano.","tier":3},{"w":"MARTILLO","clue":"Herramienta con cabeza de metal para clavar y golpear","fact":"Los martillos más antiguos eran simples piedras atadas a un palo.","tier":3},{"w":"SERRUCHO","clue":"Herramienta con una hoja de dientes para cortar madera","fact":"Algunas sierras tienen diminutos pedacitos de diamante para poder cortar piedra.","tier":3},{"w":"PANTALLA","clue":"Superficie plana donde la tele o la computadora muestran imágenes","fact":"Las pantallas antiguas de tele eran cajas profundas porque usaban grandes tubos de vidrio.","tier":3},{"w":"IMPRESORA","clue":"Máquina que pasa a papel lo que ves en la computadora","fact":"Las impresoras de casa usan gotitas diminutas de tinta para formar letras e imágenes.","tier":3},{"w":"VIDEOJUEGO","clue":"Juego electrónico que se maneja con botones y se ve en pantalla","fact":"Algunos de los primeros videojuegos se hicieron para computadoras enormes que llenaban un cuarto.","tier":3},{"w":"MARCADOR","clue":"Tablero grande del estadio donde se ven las carreras del béisbol","fact":"En algunos estadios viejos todavía se cambian a mano los números del marcador.","tier":3},{"w":"CRONÓMETRO","clue":"Reloj que mide cuánto dura una carrera, hasta décimas de segundo","fact":"Hay cronómetros que miden el tiempo hasta en milésimas de segundo.","tier":3},{"w":"TELEFÉRICO","clue":"Cabina colgada de un cable que sube gente por una montaña","fact":"Algunas ciudades de los Andes usan teleféricos como transporte para subir sus laderas.","tier":3},{"w":"CARRETILLA","clue":"Carrito de una rueda y dos mangos para cargar tierra","fact":"En China se usaban carretillas hace unos dos mil años.","tier":3},{"w":"LINTERNA","clue":"Luz de mano que funciona con pilas y llevas en la oscuridad","fact":"Las primeras linternas llevaban pilas tan débiles que solo daban destellos cortos.","tier":3},{"w":"TRAMPOLÍN","clue":"Tela elástica sobre resortes en la que rebotas","fact":"Los astronautas han entrenado en trampolines para practicar giros y volteretas.","tier":3},{"w":"SALVAVIDAS","clue":"Aro o chaleco que te mantiene a flote en el agua","fact":"Un chaleco salvavidas flota porque su relleno es más ligero que el agua.","tier":3}]}},{"id":"human-body","icon":"🫀","name":{"en":"Human Body","es":"Cuerpo humano"},"words":{"en":[{"w":"HEART","clue":"Muscle that pumps blood around your body","fact":"Your heart beats about 100,000 times every day.","tier":1},{"w":"LUNG","clue":"Spongy bag in your chest that fills with air","fact":"Your left lung is a bit smaller than your right to make room for your heart.","tier":1},{"w":"BONE","clue":"Hard white part of your skeleton","fact":"Bone is living tissue that can heal itself when it breaks.","tier":1},{"w":"SKIN","clue":"Your body's stretchy outer covering","fact":"Your skin is the largest organ of your body.","tier":1},{"w":"BRAIN","clue":"Control center inside your head that thinks and remembers","fact":"Your brain uses about one fifth of your body's energy, even though it is small.","tier":1},{"w":"NOSE","clue":"Face part you smell and breathe with","fact":"Tiny hairs in your nose help trap dust before it reaches your lungs.","tier":1},{"w":"TOOTH","clue":"Hard white chewing part in your mouth","fact":"Tooth enamel is the hardest substance in your whole body.","tier":1},{"w":"KNEE","clue":"Joint in the middle of your leg that bends","fact":"Your kneecap protects the knee joint and helps your leg bend and straighten.","tier":1},{"w":"SKULL","clue":"Bony helmet that protects your brain","fact":"Your skull is made of several bones joined together like a puzzle.","tier":1},{"w":"BLOOD","clue":"Red liquid that your heart pumps through your body","fact":"Blood travels all the way around your body in about a minute.","tier":1},{"w":"SPINE","clue":"Chain of bones running down your back","fact":"Your spine is made of small bones stacked like building blocks.","tier":1},{"w":"PULSE","clue":"Throbbing you can feel in your wrist from the heartbeat","fact":"You can feel your pulse on your wrist or neck, where arteries are near the skin.","tier":1},{"w":"MUSCLE","clue":"Stretchy body part that pulls your bones to make you move","fact":"Your body has more than 600 muscles.","tier":2},{"w":"TONGUE","clue":"Wiggly body part that tastes and helps you talk","fact":"Taste buds sit on bumps on your tongue and get replaced every couple of weeks.","tier":2},{"w":"STOMACH","clue":"Stretchy bag that mixes up the food you swallow","fact":"A coating of mucus protects your stomach from its own strong acid.","tier":2},{"w":"KIDNEY","clue":"Bean-shaped organ that filters your blood","fact":"Your kidneys filter all of your blood many times a day.","tier":2},{"w":"FINGER","clue":"One of the long bendy parts of a hand","fact":"Fingers have no muscles; tendons pulled by muscles in your hand and arm move them.","tier":2},{"w":"BREATHE","clue":"Take air in and out of your lungs","fact":"You breathe in and out about twenty thousand times a day.","tier":2},{"w":"DIGEST","clue":"Break down food so your body can use it","fact":"Digestion starts in your mouth, where saliva begins breaking food down.","tier":2},{"w":"RETINA","clue":"Light-sensing layer at the back of your eye","fact":"Your retina sees the world upside down, and your brain flips the picture.","tier":2},{"w":"HICCUP","clue":"Sudden jump of your diaphragm that makes a \"hic\" sound","fact":"A hiccup happens when your diaphragm twitches and your throat snaps shut.","tier":2},{"w":"SNEEZE","clue":"Sudden burst of air out of your nose and mouth","fact":"A sneeze helps clear dust and germs out of your nose.","tier":2},{"w":"TENDON","clue":"Tough cord that joins a muscle to a bone","fact":"Tendons work like ropes, letting muscles pull on bones to move them.","tier":2},{"w":"EYEBROW","clue":"Curved line of hair above your eye","fact":"Eyebrows help keep sweat and rain from dripping into your eyes.","tier":2},{"w":"SALIVA","clue":"Watery liquid in your mouth that begins digesting food","fact":"Your mouth makes this liquid all day long to help you chew, swallow and taste.","tier":2},{"w":"NEURON","clue":"Tiny nerve cell that sends messages to your brain","fact":"Your brain has billions of neurons, all sending tiny electrical signals.","tier":2},{"w":"SKELETON","clue":"All the bones in your body, put together","fact":"An adult has 206 bones, but babies have about 300 smaller ones that join together.","tier":3},{"w":"SHOULDER","clue":"Joint where your arm meets your body","fact":"The shoulder is one of the most flexible joints in your body.","tier":3},{"w":"INTESTINE","clue":"Long coiled tube where food is absorbed after your stomach","fact":"Your intestines would be about 25 feet long if you stretched them out.","tier":3},{"w":"VERTEBRA","clue":"One of the small bones that stack to make your backbone","fact":"A giraffe has the same number of neck vertebrae as you: seven.","tier":3},{"w":"WINDPIPE","clue":"Tube that carries air from your throat to your lungs","fact":"A flap called the epiglottis covers your windpipe when you swallow food.","tier":3},{"w":"FINGERNAIL","clue":"Hard protective plate at the tip of a finger","fact":"Fingernails grow faster than toenails.","tier":3},{"w":"HEARTBEAT","clue":"The thump you hear when you listen to a chest","fact":"A newborn's heart beats faster than a grown-up's.","tier":3},{"w":"FINGERPRINT","clue":"Swirly pattern on a fingertip that is unique to you","fact":"No two people, not even identical twins, have the same fingerprints.","tier":3},{"w":"BACTERIA","clue":"Tiny one-celled living things; some help digestion, some cause illness","fact":"Trillions of helpful bacteria live in your gut.","tier":3},{"w":"EXERCISE","clue":"Active movement like running to keep your body healthy","fact":"Exercise makes your heart stronger, just like lifting makes arm muscles stronger.","tier":3},{"w":"EAR","clue":"Sound goes into this on each side of your head","fact":"Behind your eardrum are the three smallest bones in your whole body.","tier":1},{"w":"EYE","clue":"Round part of your face that sees colors and shapes","fact":"The picture in your eye lands upside down, and your brain flips it right side up.","tier":1},{"w":"LIP","clue":"Soft pink edge of your mouth","fact":"Lips have very thin skin and lots of nerves, so they feel everything.","tier":1},{"w":"ARM","clue":"Part between your shoulder and hand, used to throw a ball","fact":"Your arm has three long bones: one above the elbow and two below it.","tier":1},{"w":"LEG","clue":"Body part from hip to foot, used for running and kicking","fact":"The thigh bone in your leg is the longest and strongest bone you have.","tier":1},{"w":"FOOT","clue":"Body part at the bottom of your leg that you stand on","fact":"One foot has 26 bones, so your two feet hold about a quarter of all your bones.","tier":1},{"w":"HAND","clue":"Body part at the end of your arm with five fingers","fact":"Your fingertips have so many nerves that they can feel tiny bumps.","tier":1},{"w":"HAIR","clue":"Grows on your head and needs a comb or brush","fact":"Hair grows about half an inch every month.","tier":1},{"w":"NECK","clue":"Body part that holds up your head, above your shoulders","fact":"A giraffe has the same number of neck bones as you: seven.","tier":1},{"w":"CHIN","clue":"Pointy bottom of your face, below your mouth","fact":"Your chin is the front tip of your lower jawbone.","tier":1},{"w":"RIB","clue":"One of the curved bones that shield your heart and lungs","fact":"Most people have 12 pairs of ribs, wrapped around the heart and lungs like a cage.","tier":1},{"w":"THUMB","clue":"The short, wide finger that sticks out to the side","fact":"Your thumb has two bones, while each of your other fingers has three.","tier":1},{"w":"PALM","clue":"The flat inside part of your hand","fact":"Hair does not grow on your palms or on the soles of your feet.","tier":1},{"w":"WRIST","clue":"Joint that bends where your hand meets your arm","fact":"Your wrist has eight small bones that let your hand bend and twist.","tier":1},{"w":"ELBOW","clue":"Joint in the middle of your arm that bends","fact":"Your elbow bends like a door hinge, and pitchers use it to snap a throw.","tier":1},{"w":"ANKLE","clue":"Joint where your foot connects to your leg","fact":"Strong bands called ligaments hold your ankle steady when you run and jump.","tier":1},{"w":"CHEEK","clue":"Soft, round part of your face on each side of your nose","fact":"Muscles in your cheeks help you chew, smile and blow out candles.","tier":1},{"w":"LIVER","clue":"Big organ under your ribs that helps clean your blood","fact":"Your liver is your body's largest organ inside and does hundreds of jobs.","tier":1},{"w":"JAW","clue":"Bone that moves up and down when you chew or talk","fact":"Your lower jaw is the only part of your skull that can open and close.","tier":1},{"w":"SWEAT","clue":"Salty water your skin makes to cool you when you run","fact":"Your skin has millions of tiny sweat glands that help keep you cool.","tier":1},{"w":"YAWN","clue":"Wide open-mouthed breath you take when you are sleepy","fact":"Seeing someone else yawn can make you yawn too, even just reading about it.","tier":1},{"w":"BLINK","clue":"Close and open your eyelids very fast, usually without noticing","fact":"You blink about 15 times every minute without even thinking about it.","tier":1},{"w":"COUGH","clue":"Loud burst of air out of your throat when you are sick","fact":"A cough clears dust and germs out of your airway.","tier":1},{"w":"CELL","clue":"Tiny building block of all living things","fact":"Your body has trillions of cells, and most are too small to see without a microscope.","tier":1},{"w":"VEIN","clue":"Tube that carries blood back to your heart","fact":"Veins look blue through your skin, but your blood is always red.","tier":1},{"w":"IRIS","clue":"Colored ring around the dark center of your eye","fact":"The iris is a tiny muscle that makes your pupil bigger in dim light.","tier":1},{"w":"NERVE","clue":"Thin cable that carries messages between your brain and body","fact":"Some nerve signals travel faster than 200 miles per hour.","tier":1},{"w":"HEEL","clue":"Back of your foot, under your ankle","fact":"Your heel bone is the biggest bone in your foot.","tier":1},{"w":"EYELID","clue":"Skin curtain that closes over your eye","fact":"Your eyelids are the thinnest skin on your whole body.","tier":2},{"w":"EYELASH","clue":"Short hairs on the edge of your lid that catch dust","fact":"Eyelashes stop dust and dirt before it reaches your eye.","tier":2},{"w":"NOSTRIL","clue":"One of the two holes in your nose","fact":"You mostly breathe through one nostril at a time and switch back and forth.","tier":2},{"w":"EARDRUM","clue":"Thin stretched skin inside your ear that shakes with sound","fact":"The eardrum passes sound shaking along to tiny bones just behind it.","tier":2},{"w":"THROAT","clue":"Passage at the back of your mouth that gets sore when sick","fact":"A little flap in your throat closes over your windpipe when you swallow.","tier":2},{"w":"KNUCKLE","clue":"Bumpy joint where a finger meets your hand","fact":"Your knuckles are joints, and they stick out most when you make a fist.","tier":2},{"w":"KNEECAP","clue":"Round bone at the front of the bendy joint in your leg","fact":"Babies are born with soft cartilage there, and the hard bone forms later.","tier":2},{"w":"BICEPS","clue":"Muscle on the front of your upper arm that bulges","fact":"Your biceps and triceps work as a pair: one bends your arm, the other straightens it.","tier":2},{"w":"ENAMEL","clue":"Hard white shell that covers each tooth","fact":"Tooth enamel is the hardest substance in your whole body.","tier":2},{"w":"ARTERY","clue":"Tube that carries blood away from your heart","fact":"Arteries have thick, stretchy walls because blood is pushed through them with force.","tier":2},{"w":"OXYGEN","clue":"Invisible gas in the air that your body needs with every breath","fact":"Your blood carries oxygen from your lungs to every part of your body.","tier":2},{"w":"REFLEX","clue":"Quick automatic movement your body makes without thinking","fact":"In a knee-jerk reflex, your spinal cord sends the message, so it is faster than thinking.","tier":2},{"w":"PELVIS","clue":"Wide bowl-shaped group of bones at your hips","fact":"Your pelvis holds up your spine and connects it to your legs.","tier":2},{"w":"MARROW","clue":"Soft stuff inside your bones that makes new blood cells","fact":"Your marrow builds millions of new red blood cells every second.","tier":2},{"w":"PLASMA","clue":"Pale yellow liquid part of blood that carries the cells","fact":"More than half of your blood is plasma, which is mostly water.","tier":2},{"w":"FOREARM","clue":"Part of your arm between the elbow and wrist","fact":"Your forearm has two bones that twist around each other when you turn your hand.","tier":2},{"w":"BLADDER","clue":"Stretchy bag inside you that stores liquid waste","fact":"A grown-up bladder can hold about two cups of liquid.","tier":2},{"w":"SWALLOW","clue":"Push food or drink from your mouth down toward your stomach","fact":"You can swallow even upside down, because muscles squeeze food along.","tier":2},{"w":"DIMPLE","clue":"Small dent in your cheek when you smile","fact":"Dimples often run in families.","tier":2},{"w":"BRUISE","clue":"Purple-blue mark on your skin after you bump it","fact":"A bruise changes color from purple to green to yellow as it heals.","tier":2},{"w":"SHIVER","clue":"Quick body shaking that warms you up when you are cold","fact":"Shivering is your muscles shaking fast to make heat.","tier":2},{"w":"TONSIL","clue":"Soft lump at the back of your mouth that helps fight germs","fact":"Tonsils help trap germs that come in through your mouth.","tier":2},{"w":"EARLOBE","clue":"Soft squishy bottom of your ear where an earring hangs","fact":"Your earlobe has no bone in it, only skin and soft tissue.","tier":2},{"w":"JAWBONE","clue":"Strong face bone that holds your lower teeth in place","fact":"Your lower jawbone is the strongest bone in your face.","tier":2},{"w":"RIBCAGE","clue":"Bony basket that protects your heart and lungs","fact":"Your ribcage moves up and down a little each time you breathe.","tier":2},{"w":"SPLEEN","clue":"Fist-sized organ on your left side that cleans old blood cells","fact":"Your spleen also helps your body fight germs.","tier":2},{"w":"PROTEIN","clue":"Nutrient in eggs, beans and meat that helps build muscle","fact":"Your body uses protein to build and repair muscles, skin and hair.","tier":2},{"w":"HORMONE","clue":"Chemical messenger in your blood that tells your body to grow","fact":"Hormones travel in your blood and tell parts of your body what to do.","tier":2},{"w":"VITAMIN","clue":"Healthy nutrient found in oranges, carrots and other foods","fact":"Your skin makes vitamin D when sunlight shines on it.","tier":2},{"w":"STRETCH","clue":"Pull your arms and legs long to loosen your muscles","fact":"Stretching gently before sports helps warm up your muscles and joints.","tier":2},{"w":"FRECKLE","clue":"Tiny brown dot on skin that shows up in the sun","fact":"Freckles are spots where skin cells make extra color in the sunshine.","tier":2},{"w":"BLISTER","clue":"Fluid-filled bubble on skin from rubbing, like from new shoes","fact":"The fluid in a blister cushions the skin underneath while it heals.","tier":2},{"w":"FOREHEAD","clue":"Part of your face between your eyebrows and your hair","fact":"Your forehead is the front of your skull, which protects the front of your brain.","tier":3},{"w":"CAPILLARY","clue":"Smallest and thinnest blood tube, thinner than a hair","fact":"Capillaries are so thin that blood cells line up single file to squeeze through.","tier":3},{"w":"CARTILAGE","clue":"Tough, bendy material in your ears and nose, not quite bone","fact":"Sharks have skeletons made of cartilage instead of bone.","tier":3},{"w":"ESOPHAGUS","clue":"Tube between your throat and stomach that food slides down","fact":"Your esophagus squeezes food along in waves, so it works even upside down.","tier":3},{"w":"DIAPHRAGM","clue":"Dome-shaped muscle under your lungs that helps you breathe in","fact":"When your diaphragm jerks suddenly, you get the hiccups.","tier":3},{"w":"PANCREAS","clue":"Organ tucked behind your stomach that makes digestive juices","fact":"Your pancreas also makes insulin, which helps control sugar in your blood.","tier":3},{"w":"ANTIBODY","clue":"Tiny protein your body builds to attack one specific germ","fact":"An antibody fits a particular germ like a key fits a lock.","tier":3},{"w":"LIGAMENT","clue":"Tough band that links one bone to another at a joint","fact":"Ligaments hold your joints together, such as in your knee and ankle.","tier":3},{"w":"PLATELET","clue":"Tiny blood piece that rushes to a cut and helps stop bleeding","fact":"Platelets stick together to plug a cut so you stop bleeding.","tier":3},{"w":"APPENDIX","clue":"Small pouch attached to your large intestine","fact":"Your appendix is only about as long as your finger.","tier":3},{"w":"BACKBONE","clue":"Another word for your spine","fact":"Astronauts can grow up to two inches taller in space as their backbone stretches out.","tier":3},{"w":"CHEEKBONE","clue":"Hard ridge under your eye that gives your face its shape","fact":"Your cheekbones are part of what makes your face look like yours.","tier":3},{"w":"COLLARBONE","clue":"Long thin bone across your upper chest, from neck to shoulder","fact":"Your collarbones act like braces that hold your shoulders out from your chest.","tier":3},{"w":"TAILBONE","clue":"Small bone at the very bottom of your spine","fact":"Your tailbone is a leftover from long-ago ancestors who had tails.","tier":3},{"w":"DIGESTION","clue":"Process of breaking down the food you eat into energy","fact":"Digestion starts in your mouth, where saliva begins breaking food down.","tier":3},{"w":"RESPIRATION","clue":"Breathing in oxygen and breathing out carbon dioxide","fact":"You take well over 15,000 breaths every day without thinking.","tier":3},{"w":"GALLBLADDER","clue":"Small pear-shaped pouch tucked under your liver","fact":"Your gallbladder stores bile, a liquid that helps break up fats in food.","tier":3},{"w":"BLOODSTREAM","clue":"The flowing river of blood that travels all around you","fact":"Your heart can push blood all the way around your body in about a minute.","tier":3},{"w":"TOOTHBRUSH","clue":"Bristly handle you use twice a day to clean your teeth","fact":"Brushing for two minutes, twice a day, helps protect teeth from cavities.","tier":3},{"w":"THUMBNAIL","clue":"Hard plate covering the tip of your thumb","fact":"Your nails are made of keratin, the same stuff as your hair.","tier":3},{"w":"ADRENALINE","clue":"Chemical that makes your heart pound when you are excited","fact":"Adrenaline is made in glands that sit on top of your kidneys.","tier":3},{"w":"ANTIBIOTIC","clue":"Doctor's medicine that fights harmful bacteria","fact":"Antibiotics fight bacteria but do not work on colds, which come from viruses.","tier":3},{"w":"STETHOSCOPE","clue":"Doctor's tool with ear tubes for listening to your heartbeat","fact":"The first stethoscope was a rolled-up paper tube, invented in France in 1816.","tier":3},{"w":"PACEMAKER","clue":"Tiny machine placed in the chest to keep a heartbeat steady","fact":"A pacemaker sends gentle signals to the heart to keep it beating on time.","tier":3}],"es":[{"w":"OJO","clue":"Órgano de tu cara con el que ves","fact":"El ojo ve el mundo al revés, y tu cerebro endereza la imagen.","tier":1},{"w":"OREJA","clue":"Parte a cada lado de tu cabeza que capta sonidos","fact":"Tus orejas están hechas de cartílago, por eso se doblan.","tier":1},{"w":"NARIZ","clue":"Parte de la cara con la que hueles y respiras","fact":"Los pelitos de la nariz atrapan el polvo antes de que llegue a los pulmones.","tier":1},{"w":"BOCA","clue":"Parte de la cara por donde comes y hablas","fact":"Tu boca produce saliva todo el día para ayudarte a masticar y tragar.","tier":1},{"w":"PIEL","clue":"La cubierta flexible de todo tu cuerpo","fact":"La piel es el órgano más grande del cuerpo.","tier":1},{"w":"HUESO","clue":"Parte dura y blanca de tu esqueleto","fact":"El hueso es un tejido vivo y puede repararse solo cuando se rompe.","tier":1},{"w":"MANO","clue":"Tiene cinco dedos y sirve para agarrar cosas","fact":"En cada mano tienes 27 huesos.","tier":1},{"w":"CODO","clue":"Articulación en medio del brazo que se dobla","fact":"El codo funciona como una bisagra y permite doblar el brazo.","tier":1},{"w":"VENA","clue":"Tubito que lleva la sangre de vuelta al corazón","fact":"Muchas venas tienen válvulas diminutas que evitan que la sangre se devuelva.","tier":1},{"w":"DEDO","clue":"Cada una de las partes largas de la mano o del pie","fact":"Los dedos no tienen músculos: los mueven tendones jalados desde la mano y el brazo.","tier":1},{"w":"BRAZO","clue":"Parte del cuerpo entre el hombro y la mano","fact":"Tu brazo tiene tres huesos grandes: el húmero, el radio y el cúbito.","tier":1},{"w":"PULSO","clue":"Latido que sientes con los dedos en la muñeca","fact":"Puedes sentir tu pulso en la muñeca o el cuello, donde las arterias están cerca de la piel.","tier":1},{"w":"CORAZÓN","clue":"Músculo que bombea la sangre por todo tu cuerpo","fact":"Tu corazón late unas 100 000 veces al día.","tier":2},{"w":"PULMÓN","clue":"Bolsa esponjosa en tu pecho que se llena de aire","fact":"El pulmón izquierdo es un poco más pequeño para dejarle espacio al corazón.","tier":2},{"w":"CEREBRO","clue":"Centro de control dentro de tu cabeza, donde piensas y recuerdas","fact":"Tu cerebro usa casi una quinta parte de la energía de tu cuerpo.","tier":2},{"w":"SANGRE","clue":"Líquido rojo que el corazón bombea por tu cuerpo","fact":"La sangre recorre todo tu cuerpo en aproximadamente un minuto.","tier":2},{"w":"DIENTE","clue":"Pieza dura y blanca de la boca para masticar","fact":"El esmalte del diente es la sustancia más dura de tu cuerpo.","tier":2},{"w":"LENGUA","clue":"Parte blanda de la boca que saborea y ayuda a hablar","fact":"Los botones del gusto están en bultitos de la lengua y se renuevan cada dos semanas.","tier":2},{"w":"RODILLA","clue":"Articulación en medio de la pierna que se dobla","fact":"La rótula protege la rodilla y ayuda a doblar y estirar la pierna.","tier":2},{"w":"ESPALDA","clue":"Parte de atrás del cuerpo, entre los hombros y la cintura","fact":"La columna vertebral está formada por huesitos apilados como bloques.","tier":2},{"w":"MÚSCULO","clue":"Parte elástica del cuerpo que jala los huesos para que te muevas","fact":"Tu cuerpo tiene más de 600 músculos.","tier":2},{"w":"NERVIO","clue":"Cable delgado que lleva mensajes entre el cerebro y el cuerpo","fact":"Algunos nervios mandan mensajes al cerebro a más de 100 metros por segundo.","tier":2},{"w":"LATIDO","clue":"Cada golpecito rítmico del corazón","fact":"El corazón de un recién nacido late más rápido que el de un adulto.","tier":2},{"w":"HÍGADO","clue":"Órgano grande del lado derecho que ayuda a limpiar la sangre","fact":"El hígado puede volver a crecer si pierde una parte.","tier":2},{"w":"TOBILLO","clue":"Articulación que une el pie con la pierna","fact":"Cada tobillo está formado por tres huesos que trabajan juntos.","tier":2},{"w":"PESTAÑA","clue":"Cada pelito curvo del borde del párpado","fact":"Las pestañas protegen los ojos del polvo y del sol.","tier":2},{"w":"ESQUELETO","clue":"Todos los huesos de tu cuerpo juntos","fact":"Un adulto tiene 206 huesos, pero un bebé nace con unos 300 huesitos que luego se unen.","tier":3},{"w":"ESTÓMAGO","clue":"Bolsa elástica que mezcla la comida que tragas","fact":"El estómago tiene una capa de moco que lo protege de su propio ácido.","tier":3},{"w":"INTESTINO","clue":"Tubo largo y enrollado donde se absorbe la comida","fact":"Estirados, tus intestinos medirían unos siete metros.","tier":3},{"w":"ESTORNUDO","clue":"Salida repentina y fuerte de aire por la nariz y la boca","fact":"Un estornudo ayuda a sacar polvo y gérmenes de tu nariz.","tier":3},{"w":"COSTILLA","clue":"Hueso curvo del pecho que protege el corazón y los pulmones","fact":"Las personas suelen tener doce pares de costillas.","tier":3},{"w":"GARGANTA","clue":"Zona del cuello por donde pasan el aire y la comida","fact":"Una tapita llamada epiglotis cierra el paso del aire cuando tragas.","tier":3},{"w":"RESPIRAR","clue":"Meter y sacar aire de los pulmones","fact":"Respiras unas veinte mil veces al día sin pensarlo.","tier":3},{"w":"EJERCICIO","clue":"Movimiento activo, como correr, que mantiene el cuerpo sano","fact":"El ejercicio fortalece el corazón, igual que levantar pesas fortalece los músculos.","tier":3},{"w":"MANDÍBULA","clue":"Hueso de abajo de la cara que mueves al masticar","fact":"La mandíbula es el hueso de la cara que más se mueve.","tier":3},{"w":"CIRCULACIÓN","clue":"Recorrido de la sangre por el corazón y los vasos del cuerpo","fact":"Las arterias llevan la sangre desde el corazón y las venas la traen de vuelta.","tier":3},{"w":"PIE","clue":"Parte del cuerpo donde te pones el calcetín y el zapato","fact":"Cada pie tiene 26 huesos, así que entre los dos tienes casi una cuarta parte de tus huesos.","tier":1},{"w":"PELO","clue":"Crece en tu cabeza y lo peinas con un cepillo","fact":"El pelo crece más o menos un centímetro cada mes.","tier":1},{"w":"CARA","clue":"Parte delantera de la cabeza, donde están los ojos y la nariz","fact":"Tu cara tiene decenas de músculos que te permiten sonreír, fruncir el ceño y hacer gestos.","tier":1},{"w":"LABIO","clue":"Borde suave y rosado de tu boca","fact":"Los labios tienen la piel muy delgada y muchos nervios, por eso sienten todo.","tier":1},{"w":"CEJA","clue":"Línea de pelitos encima de cada ojo","fact":"Las cejas ayudan a que el sudor y la lluvia no te caigan en los ojos.","tier":1},{"w":"UÑA","clue":"Capa dura que cubre la punta de cada dedo","fact":"Las uñas están hechas de queratina, la misma sustancia que forma el pelo.","tier":1},{"w":"PECHO","clue":"Parte delantera del cuerpo, entre el cuello y la barriga","fact":"Dentro de tu pecho trabajan sin parar el corazón y los pulmones.","tier":1},{"w":"TALÓN","clue":"Parte de atrás del pie, debajo del tobillo","fact":"El hueso del talón es el más grande de todo el pie.","tier":1},{"w":"SUDOR","clue":"Agua salada que sale de tu piel cuando corres o hace calor","fact":"La piel tiene millones de glándulas diminutas que producen sudor para refrescarte.","tier":1},{"w":"TOS","clue":"Soplido fuerte y repentino que haces cuando te pica la garganta","fact":"Con la tos tu cuerpo limpia el polvo y los microbios de las vías respiratorias.","tier":1},{"w":"SUEÑO","clue":"Lo que tienes cuando cierras los ojos por la noche y descansas","fact":"Mientras duermes, tu cuerpo repara los músculos y tu cerebro ordena lo que aprendiste.","tier":1},{"w":"IRIS","clue":"Anillo de color que rodea la parte negra del ojo","fact":"El iris es un músculo pequeño que agranda o achica la pupila según la luz.","tier":1},{"w":"PALMA","clue":"Parte plana y de adentro de tu mano","fact":"En las palmas de las manos y en las plantas de los pies no crece pelo.","tier":1},{"w":"NUCA","clue":"Parte de atrás del cuello, justo debajo de la cabeza","fact":"En la nuca empieza la columna vertebral, que sale desde la base del cráneo.","tier":1},{"w":"RIÑÓN","clue":"Órgano con forma de frijol que limpia tu sangre","fact":"Tienes dos riñones, y juntos filtran toda tu sangre muchas veces al día.","tier":1},{"w":"BAZO","clue":"Órgano del lado izquierdo que limpia la sangre vieja","fact":"El bazo también ayuda a tu cuerpo a defenderse de los microbios.","tier":1},{"w":"GRIPE","clue":"Enfermedad con fiebre, tos y dolor de cuerpo, común en invierno","fact":"La gripe la causa un virus, y por eso los antibióticos no la curan.","tier":1},{"w":"PECA","clue":"Puntito marrón en la piel que sale con el sol","fact":"Las pecas aparecen cuando ciertas células de la piel producen más color con el sol.","tier":1},{"w":"MUELA","clue":"Diente ancho de atrás que sirve para triturar la comida","fact":"Las muelas tienen la superficie ancha y con bultitos para moler bien los alimentos.","tier":1},{"w":"ENCÍA","clue":"Carne rosada y suave que rodea la base de tus dientes","fact":"Las encías sujetan los dientes y se cuidan cepillándolas con suavidad.","tier":1},{"w":"RISA","clue":"Sonido alegre que haces cuando algo te parece gracioso","fact":"Cuando te ríes, mueves muchos músculos de la cara, el pecho y la barriga.","tier":1},{"w":"OLER","clue":"Usar la nariz para notar el aroma de una flor","fact":"El olfato está muy unido a los recuerdos: un aroma puede recordarte un lugar.","tier":1},{"w":"HIPO","clue":"Saltito repentino del pecho que hace \"hip\" y no puedes controlar","fact":"El hipo ocurre cuando el diafragma, un músculo bajo los pulmones, da una sacudida.","tier":1},{"w":"TOSER","clue":"Soltar aire con fuerza por la garganta cuando estás resfriado","fact":"Toser es un reflejo: tu cuerpo lo hace solo, sin que lo pienses.","tier":1},{"w":"VIRUS","clue":"Microbio tan pequeño que causa resfriados y gripe","fact":"Un virus es mucho más pequeño que una bacteria y solo se multiplica dentro de células vivas.","tier":1},{"w":"SANO","clue":"Que no tiene ninguna enfermedad ni dolor","fact":"Comer frutas, dormir bien y moverte mucho ayudan a mantenerte sano.","tier":1},{"w":"OÍDO","clue":"Sentido y órgano con el que escuchas la música","fact":"Dentro del oído están los tres huesos más pequeños de todo tu cuerpo.","tier":1},{"w":"TIBIA","clue":"Hueso largo de la espinilla, entre la rodilla y el tobillo","fact":"La tibia es el segundo hueso más largo del cuerpo, después del fémur.","tier":1},{"w":"CUELLO","clue":"Parte del cuerpo que une la cabeza con los hombros","fact":"Una jirafa tiene el mismo número de huesos en el cuello que tú: siete.","tier":2},{"w":"PIERNA","clue":"Parte del cuerpo que va de la cadera al pie","fact":"El hueso del muslo, dentro de la pierna, es el más largo y fuerte del cuerpo.","tier":2},{"w":"CADERA","clue":"Zona a cada lado, donde la pierna se une al tronco","fact":"La articulación de la cadera deja que muevas la pierna en casi todas las direcciones.","tier":2},{"w":"MUÑECA","clue":"Articulación que une la mano con el antebrazo","fact":"La muñeca tiene ocho huesitos pequeños que permiten doblar y girar la mano.","tier":2},{"w":"CINTURA","clue":"Parte más delgada del cuerpo, a mitad del tronco","fact":"Tu cintura se dobla fácil porque entre costillas y cadera solo está la columna.","tier":2},{"w":"MEJILLA","clue":"Parte blanda y redonda de la cara, junto a la nariz","fact":"Los músculos de las mejillas te ayudan a masticar, a sonreír y a soplar.","tier":2},{"w":"FRENTE","clue":"Parte de la cara que está encima de las cejas","fact":"La frente es la parte delantera del cráneo y protege la zona frontal del cerebro.","tier":2},{"w":"PUPILA","clue":"Círculo negro en el centro del ojo por donde entra la luz","fact":"La pupila se hace más grande en la oscuridad para dejar entrar más luz.","tier":2},{"w":"PULGAR","clue":"El dedo gordo de la mano que se opone a los demás","fact":"El pulgar tiene dos huesos, mientras que cada uno de los otros dedos tiene tres.","tier":2},{"w":"MEÑIQUE","clue":"El dedo más pequeño de la mano","fact":"El meñique es el dedo más chico, pero tiene tres huesitos como los demás dedos.","tier":2},{"w":"VIENTRE","clue":"Parte del cuerpo donde están el estómago y los intestinos","fact":"Dentro del vientre hay metros y metros de intestino enrollado.","tier":2},{"w":"OMBLIGO","clue":"Hoyito redondo en medio de la barriga","fact":"El ombligo es una cicatriz que queda del cordón que te unía a tu mamá antes de nacer.","tier":2},{"w":"CRÁNEO","clue":"Conjunto de huesos duros que protege el cerebro","fact":"El cráneo de un adulto está formado por 22 huesos unidos entre sí.","tier":2},{"w":"HOMBRO","clue":"Articulación donde el brazo se une al cuerpo","fact":"El hombro se mueve en casi todas las direcciones, por eso un lanzador puede tirar fuerte.","tier":2},{"w":"FIEBRE","clue":"Subida de la temperatura del cuerpo cuando estás enfermo","fact":"La fiebre es una defensa de tu cuerpo: el calor ayuda a combatir los microbios.","tier":2},{"w":"GERMEN","clue":"Ser diminuto, como una bacteria, que puede causar enfermedades","fact":"Lavarte las manos con jabón elimina muchísimos gérmenes que no puedes ver.","tier":2},{"w":"BOSTEZO","clue":"Respiro largo con la boca muy abierta cuando tienes sueño","fact":"Es contagioso: ver a alguien bostezar puede hacerte bostezar a ti también.","tier":2},{"w":"LÁGRIMA","clue":"Gotita salada que sale del ojo cuando lloras","fact":"Las lágrimas también limpian y humedecen tus ojos cada vez que parpadeas.","tier":2},{"w":"CÉLULA","clue":"Pieza diminuta de la que están hechos todos los seres vivos","fact":"Tu cuerpo tiene billones de células, y casi todas son invisibles sin microscopio.","tier":2},{"w":"LLORAR","clue":"Soltar lágrimas cuando estás muy triste o muy contento","fact":"Todos los humanos lloramos, y a veces también lloramos de risa.","tier":2},{"w":"ARTERIA","clue":"Tubo que lleva la sangre desde el corazón al resto del cuerpo","fact":"Las arterias tienen paredes gruesas y elásticas porque la sangre sale del corazón con fuerza.","tier":2},{"w":"TRAGAR","clue":"Pasar la comida de la boca hacia el estómago","fact":"Puedes tragar incluso de cabeza, porque los músculos empujan la comida hacia abajo.","tier":2},{"w":"SALIVA","clue":"Líquido de la boca que humedece la comida cuando masticas","fact":"Produces cerca de un litro de saliva al día, más de lo que imaginas.","tier":2},{"w":"SONRISA","clue":"Gesto de la boca que muestra que estás contento","fact":"Sonreír mueve los músculos de la cara, y es un gesto que se entiende en todo el mundo.","tier":2},{"w":"OXÍGENO","clue":"Gas del aire que tu cuerpo necesita para vivir","fact":"La sangre lleva el oxígeno de los pulmones a todas las partes del cuerpo.","tier":2},{"w":"TÍMPANO","clue":"Membrana delgada dentro del oído que vibra con el sonido","fact":"El tímpano pasa las vibraciones del sonido a tres huesecillos diminutos.","tier":2},{"w":"RÓTULA","clue":"Hueso redondo que protege la parte de adelante de la rodilla","fact":"Los bebés nacen con cartílago blando en lugar de rótula, y el hueso se forma después.","tier":2},{"w":"NUDILLO","clue":"Bultito de cada dedo que se nota al cerrar el puño","fact":"Cada dedo tiene tres articulaciones, pero el pulgar solo tiene dos.","tier":2},{"w":"BÍCEPS","clue":"Músculo del frente del brazo que se infla al doblarlo","fact":"El bíceps y el tríceps trabajan en pareja: uno dobla el brazo y el otro lo estira.","tier":2},{"w":"PÁRPADO","clue":"Pliegue de piel que se cierra sobre el ojo","fact":"Los párpados tienen la piel más delgada de todo el cuerpo.","tier":2},{"w":"ESMALTE","clue":"Capa blanca y dura que cubre cada diente","fact":"El esmalte es la sustancia más dura del cuerpo humano.","tier":2},{"w":"VEJIGA","clue":"Bolsa elástica donde se guarda la orina","fact":"La vejiga de un adulto puede guardar cerca de dos tazas de líquido.","tier":2},{"w":"ESCALOFRÍO","clue":"Temblor repentino del cuerpo que sientes cuando tienes mucho frío","fact":"Los escalofríos son músculos que tiritan rápido para producir calor y calentarte.","tier":3},{"w":"PARPADEO","clue":"Movimiento rápido de abrir y cerrar los ojos","fact":"Parpadeas unas quince veces por minuto sin darte cuenta.","tier":3},{"w":"BARBILLA","clue":"Punta redonda de la cara, debajo de la boca","fact":"La barbilla es la punta delantera del hueso de la mandíbula inferior.","tier":3},{"w":"PANTORRILLA","clue":"Parte carnosa de la pierna, entre la rodilla y el tobillo","fact":"En la pantorrilla está uno de los músculos que usas para saltar y correr.","tier":3},{"w":"ADRENALINA","clue":"Sustancia que hace que tu corazón lata fuerte cuando te emocionas","fact":"La adrenalina se produce en glándulas que están encima de los riñones.","tier":3},{"w":"CARTÍLAGO","clue":"Material firme y flexible de tus orejas y tu nariz","fact":"Los tiburones tienen el esqueleto hecho de cartílago en lugar de hueso.","tier":3},{"w":"AMÍGDALA","clue":"Bultito blando a cada lado del fondo de la garganta","fact":"Las amígdalas ayudan a atrapar microbios que entran por la boca.","tier":3},{"w":"PÁNCREAS","clue":"Órgano detrás del estómago que fabrica jugos para digerir","fact":"El páncreas también produce insulina, que ayuda a controlar el azúcar en la sangre.","tier":3},{"w":"PROTEÍNA","clue":"Nutriente de huevos, pollo y frijoles que forma músculos","fact":"El cuerpo usa las proteínas para construir y reparar músculos, piel y pelo.","tier":3},{"w":"VITAMINA","clue":"Sustancia sana de las frutas y verduras que tu cuerpo necesita","fact":"Tu piel fabrica vitamina D cuando le da el sol.","tier":3},{"w":"CICATRIZ","clue":"Marca que queda en la piel después de que cierra una herida","fact":"Las cicatrices están hechas de una piel un poco distinta, y con el tiempo se van aclarando.","tier":3},{"w":"MARCAPASOS","clue":"Aparato pequeño que ayuda al corazón a latir con ritmo constante","fact":"Un marcapasos envía señales suaves al corazón para que no pierda el ritmo.","tier":3},{"w":"ANTEBRAZO","clue":"Parte del brazo entre el codo y la muñeca","fact":"El antebrazo tiene dos huesos que se cruzan cuando giras la mano.","tier":3},{"w":"CLAVÍCULA","clue":"Hueso largo y delgado que va del cuello al hombro","fact":"Las clavículas funcionan como puntales que mantienen los hombros separados del pecho.","tier":3},{"w":"OMÓPLATO","clue":"Hueso plano y triangular en la parte de arriba de tu espalda","fact":"Los omóplatos se mueven cada vez que subes y bajas los brazos.","tier":3},{"w":"VÉRTEBRA","clue":"Cada uno de los huesitos apilados que forman la columna","fact":"Los niños nacen con unas 33 vértebras, y varias se unen al crecer.","tier":3},{"w":"ANTICUERPO","clue":"Proteína que fabrica tu cuerpo para atacar un microbio concreto","fact":"Un anticuerpo encaja con un microbio como una llave encaja en su cerradura.","tier":3},{"w":"DIGESTIÓN","clue":"Proceso con el que tu cuerpo transforma la comida en energía","fact":"La digestión empieza en la boca, donde la saliva comienza a deshacer la comida.","tier":3},{"w":"RESPIRACIÓN","clue":"Entrada y salida de aire de tus pulmones, una y otra vez","fact":"Respiras más de quince mil veces al día sin pensar en ello.","tier":3},{"w":"MASTICAR","clue":"Moler la comida con los dientes antes de tragarla","fact":"Masticar bien ayuda a que tu estómago digiera mejor la comida.","tier":3},{"w":"CRECIMIENTO","clue":"Proceso por el que tu cuerpo se hace más grande","fact":"Mientras duermes profundo, tu cuerpo produce la hormona que ayuda a crecer.","tier":3},{"w":"EQUILIBRIO","clue":"Capacidad de mantenerte de pie sin caerte, como al andar en bicicleta","fact":"Parte de tu oído interno ayuda a mantener el equilibrio del cuerpo.","tier":3},{"w":"HEMOGLOBINA","clue":"Sustancia roja de la sangre que transporta el oxígeno","fact":"La hemoglobina es la que da el color rojo a tu sangre.","tier":3},{"w":"RADIOGRAFÍA","clue":"Imagen especial que muestra los huesos por dentro","fact":"Con una radiografía el doctor puede ver tus huesos sin abrirte el cuerpo.","tier":3}]}},{"id":"maps-and-geography","icon":"🧭","name":{"en":"Maps and Geography","es":"Mapas y geografía"},"words":{"en":[{"w":"MAP","clue":"Flat picture of places seen from above","fact":"Most maps put north at the top, but that is only a custom.","tier":1},{"w":"ATLAS","clue":"Book full of maps","fact":"The first modern atlas was printed more than 450 years ago.","tier":1},{"w":"GLOBE","clue":"Round model of the whole Earth","fact":"Earth is not a perfect ball; it bulges a little around the middle.","tier":1},{"w":"NORTH","clue":"Direction at the top of most maps","fact":"Polaris, the North Star, stays almost still in the sky while other stars move.","tier":1},{"w":"SOUTH","clue":"Direction opposite of north","fact":"In the southern half of the world, summer happens in December and January.","tier":1},{"w":"EAST","clue":"Direction where the Sun rises","fact":"The Sun rises in the east because Earth spins toward the east.","tier":1},{"w":"WEST","clue":"Direction where the Sun sets","fact":"Sunsets look orange because sunlight passes through more air when the Sun is low.","tier":1},{"w":"POLE","clue":"Either the northernmost or southernmost point of Earth","fact":"The poles get less heat because sunlight hits them at a slant.","tier":1},{"w":"CAPE","clue":"Pointy part of land that sticks out into the sea","fact":"Cape Horn, at the tip of South America, is famous for rough seas.","tier":1},{"w":"RIVER","clue":"Long stream of water that flows toward the sea","fact":"Most rivers begin as tiny streams high in hills or mountains.","tier":1},{"w":"SCALE","clue":"Part of a map that shows how distances are shrunk","fact":"On many maps one inch can stand for many miles of real distance.","tier":1},{"w":"GRID","clue":"Pattern of crossing lines on a map to help find places","fact":"Map grids let you name any place with a letter and a number, like B4.","tier":1},{"w":"LEGEND","clue":"Box on a map that explains the symbols","fact":"A legend is also called a key, because it unlocks what the symbols mean.","tier":2},{"w":"BORDER","clue":"Line that separates one country or state from another","fact":"Some borders follow rivers or mountains, while others are straight lines.","tier":2},{"w":"COUNTRY","clue":"Land with its own flag and borders","fact":"A country can be as big as a continent or as small as a city.","tier":2},{"w":"EQUATOR","clue":"Imaginary line around the middle of Earth","fact":"Ecuador is named for the equator, which runs through the country.","tier":2},{"w":"CAPITAL","clue":"City where a country's government meets","fact":"A country's capital is not always its biggest city.","tier":2},{"w":"STRAIT","clue":"Narrow stretch of water linking two bigger seas","fact":"Some straits are so narrow that you can see across to the other side.","tier":2},{"w":"ARCTIC","clue":"Frozen area around the North Pole","fact":"The Arctic is mostly floating sea ice over an ocean, not land.","tier":2},{"w":"TROPICS","clue":"Warm region near the equator","fact":"The tropics stay warm all year because the Sun is high in the sky.","tier":2},{"w":"TERRAIN","clue":"Shape and features of the land, like hills and valleys","fact":"Hikers check a map to see how steep the terrain will be.","tier":2},{"w":"HORIZON","clue":"Line where the sky seems to meet the land or sea","fact":"On a clear day at the beach, the horizon is about three miles away.","tier":2},{"w":"JOURNEY","clue":"A long trip from one place to another","fact":"Arctic terns fly from the Arctic to Antarctica and back each year.","tier":2},{"w":"VOYAGE","clue":"Long trip by sea or through space","fact":"Sailors long ago steered by the stars on a voyage across the ocean.","tier":2},{"w":"REGION","clue":"Large area that shares features, like a desert or coast","fact":"Ecuador has four natural regions: coast, mountains, Amazon rainforest and the Galápagos.","tier":2},{"w":"ISTHMUS","clue":"Narrow strip of land linking two larger land areas","fact":"The Isthmus of Panama joins North America and South America.","tier":2},{"w":"CONTINENT","clue":"One of Earth's seven huge land areas","fact":"Long ago, all the continents were joined in one giant landmass.","tier":3},{"w":"HEMISPHERE","clue":"Half of Earth, like the northern half or western half","fact":"Ecuador lies right on the equator, so it has land in both hemispheres.","tier":3},{"w":"LATITUDE","clue":"Distance north or south of the equator, measured in degrees","fact":"Lines of latitude run east to west and are parallel to the equator.","tier":3},{"w":"LONGITUDE","clue":"Measurement of how far east or west a place is","fact":"Lines of longitude run from the North Pole to the South Pole.","tier":3},{"w":"PENINSULA","clue":"Land surrounded by water on three sides","fact":"Florida is a peninsula that sticks out into the sea.","tier":3},{"w":"COORDINATE","clue":"Pair of numbers that gives the exact spot of a place","fact":"Coordinates let a ship or a phone find any spot on Earth.","tier":3},{"w":"COASTLINE","clue":"Edge where land meets the sea","fact":"A coastline measures longer when you trace around every tiny bay and rock.","tier":3},{"w":"ELEVATION","clue":"How high a place is above sea level","fact":"Quito sits high in the Andes, about 2,800 meters above sea level.","tier":3},{"w":"NAVIGATION","clue":"Finding your way from one place to another","fact":"Long ago, sailors used stars, and later compasses and maps, for navigation.","tier":3},{"w":"PASSPORT","clue":"Small booklet that lets you travel to other countries","fact":"A passport has a photo and stamps that show where you have traveled.","tier":3},{"w":"LAKE","clue":"Large body of still water with land all around it","fact":"Many lakes were scooped out by giant sheets of ice long ago.","tier":1},{"w":"BAY","clue":"Curved part of a coast where the water bends in toward land","fact":"A bay is often calmer than open ocean because the land shelters it from big waves.","tier":1},{"w":"HILL","clue":"Rounded bump of land, smaller than a mountain","fact":"Hills are often rounded because rain and wind wear them down over millions of years.","tier":1},{"w":"CLIFF","clue":"Steep rock wall at the edge of land, often by the sea","fact":"Ocean waves slowly cut cliffs back, wearing the rock away over many years.","tier":1},{"w":"OCEAN","clue":"Huge salty water that covers most of Earth","fact":"About 71 percent of Earth's surface is covered by ocean.","tier":1},{"w":"COAST","clue":"Long stretch of land where a country meets the sea","fact":"Ports grew up on coasts because boats were once the easiest way to travel.","tier":1},{"w":"BEACH","clue":"Sandy or pebbly strip beside the water where waves roll in","fact":"Beach sand can be tiny bits of rock, coral or shell worn down by waves.","tier":1},{"w":"DELTA","clue":"Triangle of land where a river splits and meets the sea","fact":"Ancient Greeks named the Nile Delta after its shape, like the Greek letter delta.","tier":1},{"w":"REEF","clue":"Colorful underwater ridge made by tiny coral animals","fact":"Reefs cover under one percent of the sea floor yet shelter about a quarter of ocean species.","tier":1},{"w":"CAVE","clue":"Large hollow space inside a hill or under the ground","fact":"Stalactites hang from cave ceilings and grow only a tiny bit each year.","tier":1},{"w":"DUNE","clue":"Hill of sand piled up by the wind","fact":"Dunes slowly shift as wind pushes sand grains up one side and over the top.","tier":1},{"w":"PEAK","clue":"Sharp pointed top of a mountain","fact":"The highest peaks have air so thin that it is hard to breathe.","tier":1},{"w":"RIDGE","clue":"Long narrow line of high ground along the top of hills","fact":"The Mid-Ocean Ridge is a chain of underwater mountains that winds around Earth like a baseball seam.","tier":1},{"w":"CANAL","clue":"Waterway dug by people so boats can travel through the land","fact":"The Panama Canal lets ships cross between two oceans without sailing around South America.","tier":1},{"w":"CITY","clue":"Big place with tall buildings where lots of people live","fact":"Map makers often draw bigger dots for bigger cities.","tier":1},{"w":"TOWN","clue":"Place bigger than a village but smaller than a city","fact":"Many towns grew up where two roads crossed or near a river crossing.","tier":1},{"w":"STATE","clue":"Large part of a country with its own capital, like Texas","fact":"The United States has fifty states, and each one has its own capital city.","tier":1},{"w":"TRAIL","clue":"Narrow path through woods or hills made for hiking","fact":"The Appalachian Trail is a long hiking path that crosses 14 states.","tier":1},{"w":"MILE","clue":"Distance unit on American road signs, about 1.6 kilometers","fact":"Ancient Romans measured a mile as one thousand double steps.","tier":1},{"w":"CHART","clue":"Special map for sailors showing water depths and hidden rocks","fact":"Sailors use charts to steer clear of rocks and shallow spots.","tier":1},{"w":"GULF","clue":"Very large bay, almost surrounded by land","fact":"The Gulf of Mexico touches the coasts of three countries.","tier":1},{"w":"FJORD","clue":"Long narrow arm of the sea between steep cliffs","fact":"Glaciers carved fjords long ago, and then the sea flooded in.","tier":1},{"w":"ATOLL","clue":"Ring of coral islands around a calm lagoon","fact":"Many atolls grew on top of old underwater volcanoes that slowly sank.","tier":1},{"w":"OASIS","clue":"Green spot with water in the middle of a desert","fact":"Desert travelers planned their trips so they could stop at oases for water.","tier":1},{"w":"PLAIN","clue":"Wide, flat stretch of land with very few hills","fact":"Plains are great for farming because flat land often has deep, rich soil.","tier":1},{"w":"PORT","clue":"Place by the sea where ships dock to load and unload","fact":"Giant cranes in ports lift metal shipping containers on and off ships.","tier":1},{"w":"ASIA","clue":"Largest continent, home to China, India and Japan","fact":"Asia covers almost a third of all the land on Earth.","tier":1},{"w":"EARTH","clue":"Our home planet, third from the Sun","fact":"Earth is the only planet known to have liquid water oceans on its surface.","tier":1},{"w":"ISLAND","clue":"Piece of land completely surrounded by water, smaller than a continent","fact":"Some islands are the tops of underwater volcanoes that grew tall enough to poke out.","tier":2},{"w":"DESERT","clue":"Very dry region that gets almost no rain, with sand or rock","fact":"Many dinosaur fossils are found in deserts, where wind wears rock away and uncovers them.","tier":2},{"w":"VALLEY","clue":"Low stretch of land between two hills or mountains","fact":"Rivers and glaciers carve valleys over thousands of years.","tier":2},{"w":"TUNDRA","clue":"Freezing, treeless land near the poles with frozen soil","fact":"Under the tundra's surface the ground stays frozen all year, and that is called permafrost.","tier":2},{"w":"AFRICA","clue":"Second-largest continent, home to lions, zebras and the Nile River","fact":"Africa is home to the Sahara, a giant hot desert.","tier":2},{"w":"EUROPE","clue":"Continent with France, Italy and Spain","fact":"Europe and Asia are joined together as one huge landmass called Eurasia.","tier":2},{"w":"PACIFIC","clue":"Largest ocean on Earth, between Asia and the Americas","fact":"The Pacific covers more area than all of Earth's land put together.","tier":2},{"w":"CANYON","clue":"Very deep, narrow valley with steep rock walls","fact":"The rock layers in the Grand Canyon show millions of years of Earth's history.","tier":2},{"w":"GLACIER","clue":"Huge, slow-moving river of ice","fact":"Over thousands of years, glaciers carve out valleys and lakes as they creep along.","tier":2},{"w":"VOLCANO","clue":"Mountain that can erupt with hot melted rock and ash","fact":"Hot melted rock inside a volcano is called magma, and outside it is called lava.","tier":2},{"w":"HARBOR","clue":"Sheltered place by the sea where boats can safely stay","fact":"A wall of big rocks, called a breakwater, can protect a harbor from waves.","tier":2},{"w":"LAGOON","clue":"Shallow calm seawater almost cut off by a reef or sand","fact":"Many young reef sharks spend their early lives in calm, shallow lagoons.","tier":2},{"w":"SUMMIT","clue":"The very top of a mountain, where climbers hope to stand","fact":"Surveyors often place a metal marker on a summit to record its height.","tier":2},{"w":"PLATEAU","clue":"High, flat stretch of land that rises above its surroundings","fact":"A plateau is flat on top but stands much higher than the land around it.","tier":2},{"w":"MEADOW","clue":"Grassy field full of wildflowers","fact":"Meadows are full of bees and butterflies that carry pollen from flower to flower.","tier":2},{"w":"JUNGLE","clue":"Hot, steamy forest packed with thick vines and tall trees","fact":"Jungles are so thick with plants that very little sunlight reaches the ground.","tier":2},{"w":"FOREST","clue":"Large area of land covered with trees","fact":"About a third of the land on Earth is covered by forest.","tier":2},{"w":"SAVANNA","clue":"Warm grassland with a few scattered trees where zebras roam","fact":"African savannas have a wet season and a dry season, and animals travel to find water.","tier":2},{"w":"PRAIRIE","clue":"Huge flat grassland in the middle of North America","fact":"Millions of bison once roamed the prairies in giant herds.","tier":2},{"w":"GEYSER","clue":"Hot spring that shoots water and steam high into the air","fact":"Underground heat boils the water, and steam pushes it up out of the ground.","tier":2},{"w":"CRATER","clue":"Bowl-shaped hole in the ground, like the many on the Moon","fact":"The Moon is covered with craters made by space rocks crashing into it.","tier":2},{"w":"RAILWAY","clue":"Pair of metal tracks that trains roll along","fact":"Train wheels have a lip on the inside that keeps them on the rails.","tier":2},{"w":"VILLAGE","clue":"Very small community in the countryside","fact":"Many villages were built next to rivers or springs for fresh water.","tier":2},{"w":"COMPASS","clue":"Tool with a needle that always swings to point north","fact":"A compass needle points north because Earth acts like a giant magnet.","tier":2},{"w":"BRIDGE","clue":"Structure that carries a road or train over water or a valley","fact":"Some bridges swing open or lift up so tall boats can pass through.","tier":2},{"w":"STADIUM","clue":"Big open building with rows of seats around a playing field","fact":"No two baseball stadiums have exactly the same outfield walls, so each field is unique.","tier":2},{"w":"RAPIDS","clue":"Fast, bumpy part of a river where water rushes over rocks","fact":"Rafters ride rapids, where a river drops and speeds up over rocks.","tier":2},{"w":"CURRENT","clue":"Stream of seawater that flows through the ocean like a river","fact":"The Gulf Stream is an ocean current that carries warm water across the Atlantic.","tier":2},{"w":"TOURIST","clue":"Visitor who travels to a place for fun and sightseeing","fact":"Maps made for tourists often have little pictures showing famous places.","tier":2},{"w":"SAHARA","clue":"Giant hot desert that stretches across northern Africa","fact":"The Sahara is about as big as the whole United States.","tier":2},{"w":"EVEREST","clue":"Highest mountain above sea level, in the Himalayas","fact":"Fossils of sea creatures have been found near the top of Mount Everest.","tier":2},{"w":"STREAM","clue":"Small body of flowing water, smaller than a river","fact":"Streams join together to form bigger rivers on the way to the sea.","tier":2},{"w":"MOUNTAIN","clue":"Landform much taller and steeper than a hill, with a peak","fact":"Some mountains are still growing taller as huge pieces of Earth's crust push together.","tier":3},{"w":"ATLANTIC","clue":"Ocean that separates North America from Europe","fact":"The Atlantic is getting wider by about an inch or two every year.","tier":3},{"w":"AUSTRALIA","clue":"Continent-country with kangaroos, koalas and the Great Barrier Reef","fact":"Australia is both a country and a continent, and it lies south of the equator.","tier":3},{"w":"ANTARCTICA","clue":"Icy continent around the South Pole","fact":"Antarctica is a desert, because it gets very little snowfall.","tier":3},{"w":"WATERFALL","clue":"River water tumbling off a cliff in a rushing drop","fact":"Over many years, a waterfall wears away rock and slowly moves upstream.","tier":3},{"w":"LIGHTHOUSE","clue":"Tall tower by the sea with a bright light for ships","fact":"Each lighthouse flashes in its own pattern so sailors can tell which one they see.","tier":3},{"w":"SATELLITE","clue":"Machine orbiting Earth that helps make maps and send signals","fact":"GPS satellites help your phone or car know where you are on a map.","tier":3},{"w":"ARCHIPELAGO","clue":"Chain or cluster of many islands close together","fact":"Hawaii is an archipelago made of volcanic islands in the Pacific.","tier":3},{"w":"BOUNDARY","clue":"Line that marks where one place ends and another begins","fact":"Some boundaries follow rivers or mountains, while others are straight lines drawn on maps.","tier":3},{"w":"DIRECTION","clue":"North, south, east or west tells you this","fact":"Many old maps had east at the top instead of north.","tier":3},{"w":"DISTANCE","clue":"How far it is from one place to another","fact":"On a map, one inch can stand for many miles of real land.","tier":3},{"w":"LANDMARK","clue":"Easy-to-spot building or feature that helps you find your way","fact":"Tall towers, bridges and statues are often used as landmarks on maps.","tier":3},{"w":"WILDERNESS","clue":"Wild natural area with no towns, roads or buildings","fact":"In true wilderness, people explore on foot or by canoe because there are no roads.","tier":3},{"w":"EXPEDITION","clue":"Long organized trip to explore or study a faraway place","fact":"Scientists go on expeditions to the ocean floor and to the polar ice.","tier":3},{"w":"DESTINATION","clue":"The place where a trip is headed","fact":"Phone maps ask for your destination, then work out the best route to get there.","tier":3},{"w":"GEOGRAPHY","clue":"School subject about Earth's lands, seas, climates and places","fact":"The word geography comes from Greek words meaning earth and writing.","tier":3},{"w":"MAINLAND","clue":"The big main piece of land, not the small islands nearby","fact":"Hawaii is more than 2,000 miles away from the mainland of North America.","tier":3},{"w":"DOWNTOWN","clue":"The busy central area of a city","fact":"Many downtowns began near a harbor or river where the city first grew.","tier":3},{"w":"MERIDIAN","clue":"Imaginary line running from one pole to the other","fact":"The prime meridian passes through Greenwich, England, and marks zero degrees longitude.","tier":3},{"w":"ALTITUDE","clue":"How high something is above sea level","fact":"Higher altitudes are colder, so tall mountains have snow on top even near the equator.","tier":3},{"w":"RAINFOREST","clue":"Tropical forest with huge trees where it pours almost every day","fact":"The tallest rainforest trees poke up through a leafy roof called the canopy.","tier":3},{"w":"GRASSLAND","clue":"Wide open land covered mostly by grass instead of trees","fact":"Prairies and savannas are both kinds of grassland.","tier":3},{"w":"SKYSCRAPER","clue":"Extremely tall building that seems to scrape the sky","fact":"A strong steel frame lets a skyscraper stand tall without thick walls.","tier":3},{"w":"HIGHLAND","clue":"Region of high, hilly or mountainous land","fact":"Highlands are cooler than nearby lowlands because the air gets colder as you go up.","tier":3}],"es":[{"w":"MAPA","clue":"Dibujo plano que muestra dónde están los lugares","fact":"Casi todos los mapas ponen el norte arriba, pero es solo una costumbre.","tier":1},{"w":"ATLAS","clue":"Libro lleno de mapas","fact":"El primer atlas moderno se imprimió hace más de 450 años.","tier":1},{"w":"NORTE","clue":"Punto cardinal que casi siempre está arriba en los mapas","fact":"La Estrella Polar casi no se mueve en el cielo y siempre indica el norte.","tier":1},{"w":"SUR","clue":"Punto cardinal opuesto al norte","fact":"En la mitad sur del mundo, el verano llega en diciembre y enero.","tier":1},{"w":"ESTE","clue":"Punto cardinal por donde sale el Sol","fact":"El Sol sale por el este porque la Tierra gira hacia el este.","tier":1},{"w":"OESTE","clue":"Punto cardinal por donde se oculta el Sol","fact":"Los atardeceres se ven naranjas porque la luz atraviesa más aire cuando el Sol está bajo.","tier":1},{"w":"POLO","clue":"Cada uno de los dos extremos de la Tierra","fact":"Los polos reciben menos calor porque los rayos del Sol llegan muy inclinados.","tier":1},{"w":"CABO","clue":"Punta de tierra que se adentra en el mar","fact":"El Cabo de Hornos, en la punta de Sudamérica, es famoso por su mar agitado.","tier":1},{"w":"PAÍS","clue":"Territorio con su propio gobierno, bandera y fronteras","fact":"Un país puede ser tan grande como un continente o tan pequeño como una ciudad.","tier":1},{"w":"RUTA","clue":"Camino que sigues para ir de un lugar a otro","fact":"Las aves migratorias repiten cada año la misma ruta por el cielo.","tier":1},{"w":"GOLFO","clue":"Gran entrada de mar rodeada de tierra","fact":"Muchos puertos importantes están en golfos porque el agua allí está más protegida.","tier":1},{"w":"VIAJE","clue":"Ir de un lugar a otro, a veces muy lejos","fact":"Un charrán ártico viaja del Ártico a la Antártida y regresa cada año.","tier":1},{"w":"CIUDAD","clue":"Lugar grande con muchas casas, calles y edificios","fact":"Muchas ciudades antiguas nacieron junto a ríos o puertos porque allí había agua y comercio.","tier":2},{"w":"PUEBLO","clue":"Lugar pequeño con pocas casas y calles","fact":"Muchos pueblos se formaron cerca de ríos o fuentes de agua.","tier":2},{"w":"CAPITAL","clue":"Ciudad donde se reúne el gobierno de un país","fact":"La capital de un país no siempre es su ciudad más grande.","tier":2},{"w":"ECUADOR","clue":"Línea imaginaria que divide la Tierra en dos mitades","fact":"El país Ecuador se llama así porque la línea del ecuador pasa por su territorio.","tier":2},{"w":"TRÓPICO","clue":"Zona cálida de la Tierra cerca del ecuador","fact":"En el trópico hace calor todo el año porque el Sol está alto en el cielo.","tier":2},{"w":"ÁRTICO","clue":"Región helada alrededor del Polo Norte","fact":"El Ártico es hielo flotando sobre un océano, no tierra firme.","tier":2},{"w":"LEYENDA","clue":"Recuadro del mapa que explica el significado de los símbolos","fact":"La leyenda también se llama clave, porque te ayuda a abrir el significado del mapa.","tier":2},{"w":"TERRENO","clue":"Forma de la tierra: colinas, valles y llanuras","fact":"Los excursionistas usan mapas con curvas de nivel para saber qué tan empinado es el terreno.","tier":2},{"w":"REGIÓN","clue":"Zona grande con rasgos propios, como la costa o la selva","fact":"Ecuador tiene cuatro regiones naturales: Costa, Sierra, Amazonía y Galápagos.","tier":2},{"w":"ALTURA","clue":"Qué tan alto está un lugar sobre el nivel del mar","fact":"Quito está a unos 2800 metros de altura, en plena cordillera de los Andes.","tier":2},{"w":"SENDERO","clue":"Caminito angosto para recorrer a pie la naturaleza","fact":"Los senderos tienen señales para que los excursionistas no se pierdan.","tier":2},{"w":"LATITUD","clue":"Distancia al norte o al sur del ecuador, medida en grados","fact":"Las líneas de latitud son paralelas al ecuador y van de este a oeste.","tier":2},{"w":"CAMINO","clue":"Franja de tierra por donde se puede andar","fact":"Los incas construyeron una red de caminos de miles de kilómetros por los Andes.","tier":2},{"w":"NAVEGAR","clue":"Viajar por el agua en un barco","fact":"Hace siglos, los marineros navegaban guiándose por las estrellas.","tier":2},{"w":"CONTINENTE","clue":"Una de las siete grandes masas de tierra de la Tierra","fact":"Hace millones de años todos los continentes estaban unidos en una sola masa de tierra.","tier":3},{"w":"HEMISFERIO","clue":"Mitad de la Tierra, como la del norte o la del sur","fact":"Ecuador está sobre la línea del ecuador, así que tiene territorio en los dos hemisferios.","tier":3},{"w":"LONGITUD","clue":"Medida de qué tan al este o al oeste está un lugar","fact":"Las líneas de longitud van del Polo Norte al Polo Sur.","tier":3},{"w":"COORDENADA","clue":"Par de números que da la posición exacta de un lugar","fact":"Con las coordenadas, un barco o un teléfono puede encontrar cualquier punto de la Tierra.","tier":3},{"w":"FRONTERA","clue":"Línea que separa un país de otro","fact":"Algunas fronteras siguen ríos o montañas, y otras son líneas rectas.","tier":3},{"w":"ESTRECHO","clue":"Franja angosta de mar que une dos mares más grandes","fact":"En algunos estrechos se puede ver la otra orilla a simple vista.","tier":3},{"w":"HORIZONTE","clue":"Línea donde parece que el cielo toca la tierra o el mar","fact":"En un día despejado en la playa, el horizonte está a unos cinco kilómetros.","tier":3},{"w":"PASAPORTE","clue":"Libreta con tu foto que sirve para viajar a otros países","fact":"En un pasaporte se estampan sellos de los países que visitaste.","tier":3},{"w":"EXPLORADOR","clue":"Persona que viaja a lugares poco conocidos para descubrirlos","fact":"Hace mucho, los exploradores dibujaban mapas de los lugares nuevos que encontraban.","tier":3},{"w":"GEOGRAFÍA","clue":"Ciencia que estudia la Tierra, sus paisajes y sus países","fact":"La palabra geografía viene del griego y significa descripción de la Tierra.","tier":3},{"w":"LAGO","clue":"Gran extensión de agua quieta rodeada de tierra","fact":"Muchos lagos se formaron cuando enormes glaciares excavaron el suelo hace miles de años.","tier":1},{"w":"MAR","clue":"Agua salada y profunda donde navegan los barcos","fact":"El agua salada del mar y los océanos forma casi toda el agua del planeta.","tier":1},{"w":"ISLA","clue":"Tierra rodeada de agua por todas partes, más pequeña que un continente","fact":"Algunas islas son la punta de volcanes submarinos que crecieron hasta salir del agua.","tier":1},{"w":"COSTA","clue":"Franja larga de tierra donde un país se encuentra con el mar","fact":"Muchos puertos nacieron en las costas porque los barcos eran la forma más fácil de viajar.","tier":1},{"w":"PLAYA","clue":"Orilla de arena donde llegan las olas y se bañan los turistas","fact":"La arena de las playas puede ser pedacitos de roca, coral o conchas desgastados por las olas.","tier":1},{"w":"CERRO","clue":"Elevación de tierra redondeada, más pequeña que una montaña","fact":"Muchos cerros son redondeados porque la lluvia y el viento los desgastan durante millones de años.","tier":1},{"w":"SELVA","clue":"Bosque cálido y lluvioso con árboles altísimos y muchas lianas","fact":"En la selva del Amazonas crecen miles de tipos distintos de árboles.","tier":1},{"w":"RÍO","clue":"Corriente larga de agua dulce que viaja hacia el mar","fact":"Muchos ríos nacen en las montañas como pequeños arroyos que van creciendo.","tier":1},{"w":"VALLE","clue":"Terreno bajo y ancho entre dos montañas","fact":"Los ríos y los glaciares van tallando los valles durante miles de años.","tier":1},{"w":"CUEVA","clue":"Hueco grande dentro de una montaña o bajo la tierra","fact":"Las estalactitas cuelgan del techo de las cuevas y crecen solo un poquito cada año.","tier":1},{"w":"DUNA","clue":"Colina de arena amontonada por el viento en el desierto","fact":"Las dunas se mueven poco a poco cuando el viento empuja los granos de arena.","tier":1},{"w":"ROCA","clue":"Material duro y pesado del que están hechas las montañas","fact":"Con millones de años, el agua y el viento convierten rocas grandes en arena.","tier":1},{"w":"CANAL","clue":"Vía de agua hecha por personas para que pasen los barcos","fact":"El Canal de Panamá deja que los barcos pasen de un océano a otro sin rodear Sudamérica.","tier":1},{"w":"ASIA","clue":"El continente más grande, donde están China, India y Japón","fact":"Asia ocupa casi una tercera parte de todas las tierras del planeta.","tier":1},{"w":"DELTA","clue":"Tierra triangular donde un río se reparte antes de llegar al mar","fact":"El delta del Nilo se llama así por su forma, parecida a la letra griega delta.","tier":1},{"w":"OASIS","clue":"Lugar con agua y palmeras en medio del desierto","fact":"Los viajeros del desierto planeaban sus rutas para pasar por los oasis y tomar agua.","tier":1},{"w":"LLANO","clue":"Terreno muy plano y extenso, casi sin colinas","fact":"Los llanos son buenos para cultivar porque la tierra plana suele ser profunda y fértil.","tier":1},{"w":"CALLE","clue":"Camino con casas y tiendas a los lados dentro de una ciudad","fact":"Las calles de muchas ciudades forman una cuadrícula, como los cuadritos de un cuaderno.","tier":1},{"w":"MUNDO","clue":"Todo el planeta con todos sus países y sus mares","fact":"En el mundo se hablan miles de idiomas distintos.","tier":1},{"w":"RUMBO","clue":"Dirección que sigue un barco o un avión al viajar","fact":"Los marineros usaban la brújula para mantener el rumbo cuando no veían tierra.","tier":1},{"w":"GLOBO","clue":"Esfera giratoria que muestra todo el planeta con sus países","fact":"Un globo terráqueo muestra la Tierra sin deformar los continentes, algo que un mapa plano no logra.","tier":1},{"w":"MILLA","clue":"Medida de distancia en los letreros de carreteras de Estados Unidos","fact":"Una milla mide un poco más de un kilómetro y medio.","tier":1},{"w":"BAHÍA","clue":"Parte curva de la costa donde el mar entra en la tierra","fact":"Una bahía suele tener el agua más tranquila porque la tierra la protege de las olas grandes.","tier":1},{"w":"ISTMO","clue":"Franja estrecha de tierra entre dos mares que une dos continentes","fact":"El istmo de Panamá une América del Norte con América del Sur.","tier":1},{"w":"ARENA","clue":"Granitos diminutos de roca que forman las playas y los desiertos","fact":"Un puñado de arena contiene miles de granitos, y algunos son restos de conchas y coral.","tier":1},{"w":"FARO","clue":"Torre junto al mar con una luz potente para guiar barcos","fact":"Cada faro destella con su propio patrón para que los marineros sepan cuál están viendo.","tier":1},{"w":"ALDEA","clue":"Grupo muy pequeño de casas en el campo","fact":"Muchas aldeas nacieron junto a ríos o manantiales para tener agua fresca.","tier":1},{"w":"HIELO","clue":"Agua congelada, dura y fría","fact":"El hielo flota en el agua porque es menos denso que el agua líquida.","tier":1},{"w":"ÁFRICA","clue":"El segundo continente más grande, con leones, cebras y el río Nilo","fact":"En África está el Sahara, el desierto cálido más grande del mundo.","tier":2},{"w":"EUROPA","clue":"Continente donde están Francia, Italia y España","fact":"Europa y Asia forman una sola masa de tierra enorme llamada Eurasia.","tier":2},{"w":"AMÉRICA","clue":"Continente donde están México, Brasil y Canadá","fact":"El río Amazonas, que cruza Sudamérica, lleva más agua que cualquier otro río del mundo.","tier":2},{"w":"OCÉANO","clue":"Enorme extensión de agua salada entre los continentes","fact":"El océano cubre cerca del 71 por ciento de la superficie de la Tierra.","tier":2},{"w":"TUNDRA","clue":"Llanura helada y sin árboles cerca de los polos","fact":"Bajo la superficie de la tundra el suelo permanece congelado todo el año.","tier":2},{"w":"GLACIAR","clue":"Enorme río de hielo que avanza muy despacio por una montaña","fact":"Durante miles de años, los glaciares tallan valles y lagos mientras se deslizan.","tier":2},{"w":"VOLCÁN","clue":"Montaña con un cráter que puede lanzar roca derretida y ceniza","fact":"La roca derretida dentro del volcán se llama magma, y cuando sale se llama lava.","tier":2},{"w":"LAGUNA","clue":"Agua tranquila y poco profunda, separada del mar por arena o coral","fact":"Muchos tiburones pequeños crecen en lagunas tranquilas y poco profundas.","tier":2},{"w":"CASCADA","clue":"Agua de un río que cae desde lo alto de una roca","fact":"Con el paso de los años, una cascada va desgastando la roca y retrocede poco a poco.","tier":2},{"w":"ARROYO","clue":"Corriente de agua pequeña y angosta, más chica que un río","fact":"Varios arroyos se juntan para formar ríos más grandes en su camino al mar.","tier":2},{"w":"MESETA","clue":"Terreno alto y plano como una mesa gigante","fact":"Una meseta es plana arriba, pero está mucho más alta que la tierra que la rodea.","tier":2},{"w":"PRADERA","clue":"Terreno extenso cubierto de hierba verde, donde pastan los animales","fact":"Millones de bisontes recorrían antiguamente las praderas de Norteamérica en enormes manadas.","tier":2},{"w":"BOSQUE","clue":"Zona grande de tierra cubierta de árboles","fact":"Más o menos una tercera parte de la tierra firme del planeta está cubierta de bosques.","tier":2},{"w":"SABANA","clue":"Llanura cálida de pasto con pocos árboles, hogar de cebras y leones","fact":"En las sabanas hay temporada de lluvias y de sequía, y los animales viajan buscando agua.","tier":2},{"w":"CRÁTER","clue":"Hueco en forma de tazón, como los que hay en la Luna","fact":"La Luna está llena de cráteres hechos por rocas del espacio que chocaron con ella.","tier":2},{"w":"GÉISER","clue":"Fuente natural que lanza agua caliente y vapor al aire","fact":"El calor bajo la tierra hierve el agua y el vapor la empuja hacia arriba.","tier":2},{"w":"AVENIDA","clue":"Calle muy ancha de una ciudad, con varios carriles","fact":"Las avenidas son más anchas que las calles para dejar pasar a mucho tránsito.","tier":2},{"w":"BRÚJULA","clue":"Instrumento con una aguja que siempre gira hacia el norte","fact":"La aguja de la brújula apunta al norte porque la Tierra funciona como un imán gigante.","tier":2},{"w":"ESTADIO","clue":"Gran edificio con gradas alrededor de un campo para ver partidos","fact":"Cada estadio de béisbol tiene un jardín con medidas distintas, así que no hay dos campos iguales.","tier":2},{"w":"TURISTA","clue":"Visitante que viaja a un lugar para pasear y conocerlo","fact":"Los mapas para turistas suelen mostrar con dibujitos los lugares famosos.","tier":2},{"w":"SAHARA","clue":"Desierto cálido gigantesco que cubre gran parte del norte de África","fact":"El Sahara es casi tan grande como todo Estados Unidos.","tier":2},{"w":"EVEREST","clue":"La montaña más alta sobre el nivel del mar, en el Himalaya","fact":"Cerca de la cima del Everest se han encontrado fósiles de criaturas marinas.","tier":2},{"w":"ATOLÓN","clue":"Anillo de islas de coral que rodea una laguna tranquila","fact":"Muchos atolones se formaron sobre antiguos volcanes submarinos que se hundieron poco a poco.","tier":2},{"w":"FIORDO","clue":"Brazo largo y angosto del mar entre paredes de roca muy altas","fact":"Los glaciares excavaron los fiordos hace mucho tiempo y luego el mar los inundó.","tier":2},{"w":"MONTAÑA","clue":"Elevación enorme de tierra, mucho más alta y empinada que una colina","fact":"Algunas montañas siguen creciendo porque enormes placas de la corteza terrestre se empujan entre sí.","tier":2},{"w":"CUMBRE","clue":"Parte más alta de una montaña, meta de los escaladores","fact":"En las cumbres más altas el aire tiene tan poco oxígeno que los escaladores respiran con dificultad.","tier":2},{"w":"ORILLA","clue":"Borde de un río o del mar donde termina el agua","fact":"Las olas mueven la arena de la orilla y cambian la playa poco a poco.","tier":2},{"w":"PUENTE","clue":"Construcción que cruza un río o un valle","fact":"Algunos puentes se levantan o giran para que puedan pasar los barcos altos.","tier":2},{"w":"RÁPIDOS","clue":"Zona del río donde el agua baja veloz y salpica entre rocas","fact":"Muchas personas practican rafting en los rápidos, donde el río baja de golpe.","tier":2},{"w":"PANTANO","clue":"Terreno blando y lleno de agua estancada, con mucho lodo","fact":"Los pantanos funcionan como esponjas: guardan agua de lluvia y ayudan a evitar inundaciones.","tier":2},{"w":"TIERRA","clue":"Nuestro planeta, el tercero contando desde el Sol","fact":"La Tierra es el único planeta conocido con océanos de agua líquida en su superficie.","tier":2},{"w":"PUERTO","clue":"Lugar junto al mar donde los barcos cargan y descargan","fact":"Las grúas gigantes de los puertos levantan contenedores de metal y los suben a los barcos.","tier":2},{"w":"DESIERTO","clue":"Región muy seca, con arena o rocas, donde casi no llueve","fact":"En desiertos como el de Gobi se han encontrado muchos fósiles de dinosaurios.","tier":3},{"w":"PENÍNSULA","clue":"Tierra con agua por tres lados, unida al continente por el otro","fact":"Italia tiene forma de bota y es una gran península.","tier":3},{"w":"CARRETERA","clue":"Camino ancho y pavimentado por donde viajan autos y camiones entre ciudades","fact":"La Carretera Panamericana une muchos países de América de norte a sur.","tier":3},{"w":"PACÍFICO","clue":"Océano más grande de la Tierra, entre Asia y América","fact":"El Pacífico es tan grande que cubre más superficie que toda la tierra firme junta.","tier":3},{"w":"ATLÁNTICO","clue":"Océano entre América y Europa y África","fact":"El Atlántico se hace más ancho unos dos o tres centímetros cada año.","tier":3},{"w":"AUSTRALIA","clue":"País y continente con canguros, koalas y una enorme barrera de coral","fact":"Australia es a la vez un país y un continente, y está al sur del ecuador.","tier":3},{"w":"ANTÁRTIDA","clue":"Continente cubierto de hielo alrededor del Polo Sur","fact":"La Antártida es un desierto, porque recibe muy poca nieve al año.","tier":3},{"w":"CORDILLERA","clue":"Larga cadena de montañas unidas","fact":"Los Andes, en Sudamérica, forman la cordillera más larga del mundo sobre tierra firme.","tier":3},{"w":"ARRECIFE","clue":"Cresta de coral donde viven peces de colores y tiburones","fact":"Los arrecifes cubren menos del uno por ciento del mar, pero albergan un cuarto de sus especies.","tier":3},{"w":"ALTIPLANO","clue":"Llanura enorme y muy alta entre montañas, como en los Andes","fact":"En el altiplano andino el aire tiene menos oxígeno, así que tu cuerpo trabaja más para respirar.","tier":3},{"w":"BARRANCO","clue":"Hendidura profunda y empinada en la tierra, hecha por el agua","fact":"Cuando llueve fuerte, el agua baja por un barranco y lo va profundizando poco a poco.","tier":3},{"w":"MAPAMUNDI","clue":"Mapa plano que muestra todos los continentes y océanos","fact":"Los primeros mapamundis conocidos se dibujaron hace más de dos mil años.","tier":3},{"w":"TRAVESÍA","clue":"Viaje largo, sobre todo por mar, cruzando un lugar difícil","fact":"Los antiguos navegantes polinesios cruzaron miles de kilómetros de océano guiándose por las estrellas y las olas.","tier":3},{"w":"CORRIENTE","clue":"Agua marina que fluye como un río dentro del océano","fact":"La corriente del Golfo lleva agua cálida a través del océano Atlántico.","tier":3},{"w":"AEROPUERTO","clue":"Lugar con pistas donde los aviones despegan y aterrizan","fact":"En los aeropuertos grandes, las torres de control guían a los aviones con radio y radar.","tier":3},{"w":"RASCACIELOS","clue":"Edificio altísimo que parece rozar las nubes","fact":"Un esqueleto de acero permite que un rascacielos sea muy alto sin paredes gruesas.","tier":3},{"w":"MERIDIANO","clue":"Línea imaginaria que va de polo a polo","fact":"El meridiano de Greenwich, en Inglaterra, marca la longitud cero.","tier":3},{"w":"PARALELO","clue":"Línea imaginaria que rodea la Tierra de este a oeste","fact":"El ecuador es el paralelo más grande: divide la Tierra en dos mitades iguales.","tier":3},{"w":"EXPEDICIÓN","clue":"Viaje organizado para explorar o estudiar un lugar lejano","fact":"Los científicos hacen expediciones al fondo del mar y a los hielos de los polos.","tier":3},{"w":"DISTANCIA","clue":"Cuánto espacio hay de un lugar a otro","fact":"En un mapa, un centímetro puede representar muchos kilómetros reales.","tier":3},{"w":"DIRECCIÓN","clue":"Hacia dónde apunta o se mueve algo, como norte o sur","fact":"Muchos mapas antiguos tenían el este arriba en lugar del norte.","tier":3},{"w":"SATÉLITE","clue":"Máquina que gira alrededor de la Tierra y envía señales e imágenes","fact":"Los satélites del GPS ayudan a tu teléfono a saber dónde estás en un mapa.","tier":3},{"w":"ACANTILADO","clue":"Pared de roca muy alta y empinada junto al mar","fact":"Las olas van desgastando el acantilado lentamente a lo largo de muchos años.","tier":3},{"w":"MANANTIAL","clue":"Lugar donde el agua sale de la tierra por sí sola","fact":"Muchos ríos nacen en un manantial, donde el agua sube desde bajo tierra.","tier":3}]}}]};
